const Map<String, List<String>> kExerciseStepsZhExt = {
  'H0001': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
