  'H1512': ['从四肢着地开始，双手直接放在肩膀下方，膝盖直接放在臀部下方。', '将一条腿向后伸直，保持膝盖弯曲和脚弯曲。', '慢慢地将臀部降低到地面，感觉股四头肌的伸展。', '保持这个姿势20-30秒。', '换腿并在另一侧重复拉伸。'],
  'H0006': ['平躺，膝盖弯曲，双脚平放在地上。', '将双臂伸直至两侧，与地面平行。', '收紧腹肌，将肩膀抬离地面，并将右手伸向右脚跟。', '返回起始位置并在左侧重复，将左手伸向左脚跟。', '继续交替进行所需的重复次数。'],
