  'H2355': ['悬挂在引体向上杆上，双臂完全伸展，膝盖弯曲成 90 度角。', '收紧核心并将膝盖抬向胸部，尽可能靠近肘部。', '慢慢地将双腿放回起始位置。', '重复所需的重复次数。'],
  'H2333': ['悬挂在引体向上杆上，双臂完全伸展，双腿伸直向下。', '启动你的核心并将双腿抬起到你面前，直到它们与地面平行。', '在顶部保持片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
