  'H3204': ['平躺，膝盖弯曲，双脚平放在地上。', '将手臂伸过头顶，保持伸直。', '收紧腹肌，慢慢将上半身抬离地面，向前卷曲直到躯干直立。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
