  'H0012': ['平躺，双腿伸展，双臂放在身体两侧。', '将双手放在臀部下方以获得支撑。', '收紧腹肌，将双腿抬离地面，保持伸直。', '双腿并拢的同时，将它们降低到一侧，直到离地几英寸。', '暂停片刻，然后抬起双腿回到起始位置。', '到另一侧重复该动作。', '继续交替进行所需的重复次数。'],
  'H0013': ['平躺，双腿伸展，双臂放在身体两侧。', '将双手放在臀部下方以获得支撑。', '启动你的核心并将双腿抬离地面，保持伸直。', '抬起双腿，直到它们垂直于地面。', '将双腿放低回到起始位置。', '同时，将双腿向地面放下，保持伸直。', '将双腿抬回到起始位置。', '重复所需的重复次数。'],
  'H0014': ['坐在地上，膝盖弯曲，双脚平放在地板上。', '双手将健身球放在胸前。', '稍微向后倾斜，收紧腹肌并保持背部挺直。', '慢慢地将你的躯干向右扭转，将健身球移向身体的右侧。', '暂停片刻，然后将躯干向左扭转，将健身球移向身体左侧。', '继续交替进行所需的重复次数。'],
