  'H1713': ['脸朝下躺在地上，双腿伸直。', '弯曲左膝，用左手向后抓住左脚或脚踝。', '轻轻地将左脚拉向臀肌，感受左股四头肌的拉伸。', '保持拉伸 20-30 秒，然后放松。', '右腿重复上述动作。'],
  'H1714': ['脸朝下躺在地上，双腿伸直。', '弯曲右膝，用右手向后伸抓住右脚或脚踝。', '轻轻地将右脚或脚踝拉向臀部，感受右大腿前部的拉伸。', '保持拉伸 20-30 秒。', '松开并在另一侧重复。'],
