  'H1712': ['侧躺，双腿伸直并叠放在一起。', '稍微弯曲下面的腿以保持稳定。', '将上脚放在稳定的表面上，例如长凳或台阶上。', '保持上腿伸直，慢慢将其降低到地面，感觉大腿内侧有拉伸感。', '保持拉伸 20-30 秒。', '返回起始位置并在另一侧重复。'],
  'H1758': ['坐在长凳边缘或让某人按住你的脚。', '平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H1432': ['将机器调整至您所需的体重和高度设置。', '面向机器站立，双脚分开与肩同宽。', '正手握住手柄，握距略宽于肩宽。', '启动你的背阔肌和二头肌，并将自己拉向手柄。', '在顶部暂停片刻，挤压背部肌肉。', '慢慢地将自己放回到起始位置。', '重复所需的重复次数。'],
  'H0018': ['双脚分开与肩同宽站立，双手握住毛巾放在脑后。', '保持肘部靠近耳朵，上臂保持静止。', '慢慢向上伸展前臂，在顶部挤压三头肌。', '暂停片刻，然后慢慢将毛巾放回起始位置。', '重复所需的重复次数。'],
  'H0019': ['将机器调整到您想要的重量和高度。', '跪在面向机器的垫子上，双手握住手柄。', '弯曲肘部降低身体，保持背部挺直并靠近机器。', '在底部暂停片刻，然后将自己推回到起始位置。', '重复所需的重复次数。'],
  'H2364': ['将机器调整到您想要的高度，并将膝盖固定在垫子上。', '宽握手柄并保持肘部稍微弯曲。', '弯曲肘部降低身体，直到上臂与地板平行。', '伸展双臂，将自己推回到起始位置。', '重复所需的重复次数。'],
  'H3220': ['双脚分开与肩同宽站立。', '弯曲膝盖并将身体降低至蹲姿。', '爆发性向上跳跃，伸展双腿和手臂。', '在空中时，将双腿分开，并将双臂向两侧伸出。', '双脚分开与肩同宽，轻轻落地，弯曲膝盖以吸收冲击力。', '重复所需的重复次数。'],
  'H3672': ['双脚分开与肩同宽站立。', '右脚向前迈出一步，弯曲膝盖，将身体降低到弓步位置。', '用右脚蹬地，然后回到起始位置。', '用左脚重复该动作，每一步交替双腿。', '继续来回走动，保持稳定的步伐。', '重复所需的持续时间或重复次数。'],
  'H1314': ['将稳定球放在地面上，面朝下躺在上面，臀部放在球上，双脚靠在墙壁或其他稳定的表面上。', '将双手放在脑后或交叉在胸前。', '启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到脚后跟形成一条直线。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H3297': ['首先，用正手握法悬挂在引体向上杆上，双手分开的距离略大于肩宽。', '启动你的核心并将肩胛骨向下拉和向后拉。', '弯曲膝盖并将其向胸部靠拢。', '慢慢抬起双腿，保持伸直，直到身体与地面平行。', '保持这个姿势几秒钟，然后慢慢地将双腿放回起始位置。', '重复所需的重复次数。'],
  'H1405': ['站直，双脚分开与肩同宽。', '将双臂伸直在身前，与地面平行。', '双臂交叉在身体前方，右臂放在左臂上方。', '手指交叉，手掌旋转远离身体。', '慢慢抬起手臂并远离身体，感觉背部和胸部有拉伸感。', '保持拉伸 15-30 秒，然后放松。', '在另一侧重复。'],
  'H1473': ['双脚分开与肩同宽站立。', '稍微弯曲膝盖，向后跳跃，用双脚蹬地。', '脚掌轻轻着地，弯曲膝盖以吸收冲击力。', '重复所需的重复次数。'],
  'H0020': ['将平衡板放在平坦的表面上。', '用一只脚踩在平衡板上，确保其居中。', '慢慢地将体重转移到平衡板上的脚上，保持核心肌群参与。', '在保持该姿势所需的时间内保持平衡和稳定。', '用另一只脚重复该练习。'],
  'H0968': ['双脚分开与肩同宽站立，反手握住弹力带，手掌朝上。', '保持肘部靠近身体两侧，慢慢地将一只手臂向肩膀弯曲，在顶部挤压二头肌。', '将手臂放回起始位置，然后用另一只手臂重复此动作。', '继续交替手臂进行所需的重复次数。'],
  'H0969': ['平躺，双腿伸直，手臂伸过头顶，握住弹力带。', '收紧腹肌，同时将双腿和上半身抬离地面，将双手伸向脚趾。', '当你降低双腿和上半身时，交换双腿的位置，将一条腿交叉在另一条腿上。', '重复该动作，每次重复时交替变换双腿的位置。', '继续进行所需的重复次数。'],
  'H0970': ['将弹力带固定在上拉杆或坚固的锚点上。', '踏上弹力带，手掌背向自己，握住杠铃，双手之间的距离略宽于肩宽。', '双臂完全伸展，保持核心收紧，肩膀向下并向后倾斜。', '将肩胛骨挤压在一起并将肘部向下推向臀部，将身体向上拉向杠铃杆。', '继续拉，直到下巴高于杠铃，然后慢慢降低回到起始位置。', '重复所需的重复次数。'],
  'H0971': ['跪在地板上，双手握住弹力带的手柄，手掌朝下。', '将弹力带放在您面前的地面上，双手分开与肩同宽。', '启动你的核心并缓慢地向前滚动轮子，在保持控制的同时尽可能地伸展你的身体。', '在最远点暂停片刻，然后慢慢地将轮子向膝盖方向滚动，回到起始位置。', '重复所需的重复次数。'],
  'H1254': ['平躺在长凳上，双脚平放在地上，背部紧贴长凳。', '正手握住带子手柄，间距略宽于肩宽。', '充分伸展双臂，将弹力带推离胸部。', '慢慢将弹力带放回到胸部，保持肘部呈 90 度角。', '重复所需的重复次数。'],
  'H0980': ['将带子固定在脚踝高度的坚固锚点上。', '背对锚点站立，双脚与肩同宽。', '向后退一步，在弹力带上产生张力，保持膝盖稍微弯曲。', '铰接臀部并向前倾斜，保持脊柱中立。', '将右腿向后伸直，在顶部挤压臀部。', '将右腿放回原位，然后换左腿重复此动作。', '继续交替双腿达到所需的重复次数。'],
  'H0972': ['平躺，双手放在脑后，膝盖弯曲。', '将脚抬离地面，将右膝盖靠近胸部，同时扭转躯干，将左肘靠近右膝盖。', '伸直右腿，同时将左膝靠近胸部，并扭转躯干，使右肘靠近左膝。', '继续交替扭转运动，就像踩自行车一样，同时在整个运动过程中保持核心参与。', '重复所需的重复次数。'],
  'H0974': ['将弹力带固定在较高的锚点上，例如上拉杆或坚固的横梁。', '面向锚点站立，用反手抓住弹力带，双手与肩同宽。', '后退一步，在弹力带上产生张力，双脚分开与臀部同宽。', '当你将弹力带向下拉向胸部时，收紧你的核心并保持背部挺直，将肩胛骨挤压在一起。', '在动作底部暂停片刻，然后慢慢松开弹力带回到起始位置。', '重复所需的重复次数。'],
  'H0975': ['将一条带子绕在你的上臂上，就在肘部上方。', '采取俯卧撑姿势，双手直接放在肩膀下方，身体从头到脚跟呈一条直线。', '弯曲肘部，将胸部降低到地面，保持肘部靠近身体两侧。', '推动手掌以伸展手臂并返回到起始位置。', '重复所需的重复次数。'],
  'H0976': ['坐在长凳或椅子上，双腿分开，双脚平放在地上。', '用手握住带子的一端，用脚踩在另一端上，同时将脚放在同一侧。', '稍微向前倾，将肘部放在大腿内侧，膝盖上方。', '手掌朝上，慢慢地将手向肩膀弯曲，保持上臂静止。', '在顶部暂停片刻，然后慢慢将手放回起始位置。', '重复所需的重复次数，然后换边。'],
  'H3117': ['将弹力带固定在您上方的固定点上，例如上拉杆或坚固的横梁。', '坐在面向乐队的长凳或椅子上，双脚平放在地上，膝盖弯曲。', '紧紧握住弹力带，手掌朝向您。', '保持背部挺直并启动核心肌群。', '将弹力带向下拉向胸部，将肩胛骨挤压在一起。', '在动作的底部暂停片刻，感受背阔肌的收缩。', '慢慢地将弹力带释放回起始位置，在整个运动过程中保持控制。', '重复所需的重复次数。'],
  'H3116': ['将带子固定在头顶上方坚固的锚点上。', '面向锚点站立，双脚分开与肩同宽。', '反手握住弹力带，双手间距略宽于肩宽。', '后退一步，在弹力带上产生张力，保持手臂完全伸展。', '启动你的核心并将肩胛骨挤压在一起。', '将弹力带向下拉向胸部，用肘部引导。', '在动作的底部暂停片刻，感受背阔肌的收缩。', '慢慢释放带子的张力并返回到起始位置。', '重复所需的重复次数。'],
  'H0977': ['双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝下。', '保持双臂伸直，将弹力带举到身前，直到双臂与地面平行。', '在顶部暂停片刻，然后慢慢将弹力带放回起始位置。', '重复所需的重复次数。'],
  'H0978': ['双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝下。', '保持手臂伸直，慢慢向前举起，直到与地面平行。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H1408': ['仰卧，膝盖弯曲，双脚平放在地上。', '将阻力带放在膝盖上方。', '调动你的臀肌和核心肌肉。', '将脚后跟压入地面，将臀部抬离地板，在顶部挤压臀部。', '在顶部暂停片刻，然后慢慢将臀部放回起始位置。', '重复所需的重复次数。'],
  'H0979': ['将带子固定在腰部高度的坚固锚点上。', '垂直于锚点站立，双脚分开与肩同宽。', '用双手抓住带子手柄并远离锚点以在带子中产生张力。', '将双手放在胸前，保持肘部弯曲并靠近身体。', '调动你的核心并保持稳定的姿势。', '将手臂伸直至前方，将弹力带推离身体。', '保持伸展姿势几秒钟，专注于保持核心紧张。', '慢慢地将双手放回胸前，抵抗弹力带的拉力。', '重复所需的重复次数。'],
  'H0981': ['平躺，双腿伸直，手臂伸过头顶，握住弹力带。', '收紧腹肌，同时抬起双腿和上半身，将双手移向脚部。', '在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。', '重复所需的重复次数。'],
  'H0983': ['将带子固定在头顶上方坚固的锚点上。', '跪下，用一只手握住弹力带，手掌朝下。', '将手臂完全伸过头顶，保持肘部稍微弯曲。', '调动你的背阔肌，将弹力带拉向你的一侧，使你的肘部靠近你的胸腔。', '在底部停顿片刻，然后慢慢释放张力，回到起始位置。', '重复所需的重复次数，然后换边。'],
  'H0985': ['将带子固定在腰部高度的坚固锚点上。', '面向远离锚点的方向跪下，用双手握住弹力带，保持肘部弯曲并靠近身体两侧。', '收紧腹肌，慢慢地将躯干扭向一侧，将双手移向另一侧的臀部。', '暂停片刻，然后慢慢回到起始位置。', '在另一侧重复。', '继续交替进行所需的重复次数。'],
  'H0984': ['仰卧，双腿伸直，将阻力带绕在脚上。', '弯曲膝盖并将其靠近胸部，双脚并拢。', '慢慢向外旋转膝盖，使膝盖彼此远离，同时保持双脚并拢。', '旋转结束时暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H1002': ['平躺，双腿伸直，双脚并拢。', '将带子放在脚弓周围，并用手握住带子的末端。', '收紧腹肌，将双腿抬离地面，直到它们垂直于地板。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H0986': ['双脚分开与肩同宽站立，将弹力带的一端放在脚下。', '握住弹力带的另一端，手臂完全伸过头顶，手掌朝前。', '保持上臂静止，将前臂向肩膀弯曲，挤压二头肌。', '在顶部停顿片刻，然后慢慢将前臂放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0987': ['双脚分开站立，与臀部同宽，将阻力带绕在脚踝上。', '向前伸出一条腿，将脚尖放在长凳上或身后的一步上。', '用一只手握住支撑物以保持平衡。', '弯曲站立的腿，将身体降低到蹲姿，保持膝盖与脚趾在一条直线上。', '推动脚后跟返回到起始位置。', '重复所需的重复次数，然后换腿。'],
  'H0988': ['将带子固定在腰部高度的稳定锚点上。', '面向锚点站立，双脚分开与肩同宽。', '用一只手握住弹力带，手掌朝内，然后后退以在弹力带中产生张力。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '将带子拉向腰部，将肩胛骨挤压在一起。', '在动作的最高点暂停片刻，然后慢慢松开弹力带回到起始位置。', '重复所需的重复次数，然后换边。'],
  'H0989': ['将带子固定在胸部高度的坚固锚点上。', '站立，一侧面向锚点，用一只手抓住带子。', '远离锚点以在带子中产生张力。', '将双脚分开与肩同宽，并稍微弯曲膝盖。', '将握住弹力带的手穿过身体，朝向对侧的肩膀。', '在保持弹力带张力的同时，将手向前推离身体，伸展手臂。', '慢慢回到起始位置并重复所需的重复次数。', '换边并用另一只手重复练习。'],
  'H0990': ['坐在长凳或椅子上，双脚平放在地上，背部挺直。', '用一只手握住弹力带，并将手臂完全伸到身前。', '保持背部挺直，弯曲肘部并将肩胛骨挤压在一起，将弹力带拉向身体。', '同时，将躯干向拉动手臂的一侧扭转。', '在顶部暂停片刻，然后慢慢释放弹力带的张力并返回到起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0991': ['将阻力带连接到地面上坚固的锚点上。', '背对锚点站立，双脚与肩同宽。', '向前迈一步，在弹力带中产生张力，保持膝盖稍微弯曲。', '铰接臀部并将臀部向后推，保持膝盖轻微弯曲。', '降低躯干直到与地面平行，感觉腿筋被拉伸。', '向前推动臀部并挤压臀部以返回起始位置。', '重复所需的重复次数。'],
  'H0992': ['将带子牢固地固定在稳定的锚点上。', '平躺，膝盖弯曲，双脚平放在地上。', '用双手握住弹力带，并将双臂伸向天花板。', '收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H0994': ['坐在长凳或椅子上，双脚平放在地面上。', '正手握住弹力带，手掌朝下，然后将其缠绕在手指上。', '将前臂放在大腿上，手腕悬在边缘上。', '慢慢向上弯曲手腕，挤压前臂。', '在顶部暂停片刻，然后慢慢将手腕放回起始位置。', '重复所需的重复次数。'],
  'H0996': ['坐在椅子或长凳上，背部挺直，双脚平放在地面上。', '在大腿周围、膝盖上方放置一条阻力带。', '保持膝盖弯曲 90 度，双脚分开与肩同宽。', '收紧臀肌，慢慢向外旋转膝盖，克服弹力带的阻力。', '动作结束时暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H1011': ['坐在地上，双腿向前伸展，背部挺直。', '将带子绕在腰上，并用双手握住两端。', '收紧腹肌，慢慢将躯干扭向一侧，保持背部挺直，双脚着地。', '扭转结束时暂停片刻，然后慢慢回到起始位置。', '重复扭转到另一侧。', '继续交替进行所需的重复次数。'],
  'H0997': ['双脚分开与肩同宽站立，将弹力带放在脚下。', '手掌朝前握住弹力带，将双手举至肩高，肘部弯曲。', '将弹力带压过头顶，充分伸展双臂。', '在顶部暂停片刻，然后慢慢将阻力带降低至肩部高度。', '重复所需的重复次数。'],
  'H1018': ['双脚分开与肩同宽站立，将弹力带放在脚下，用手握住两端。', '保持手臂伸直并放松，让弹力带悬挂在大腿前面。', '向上耸肩，尽可能高地举起弹力带，以启动斜方肌。', '保持收缩一会儿，然后慢慢将肩膀放回起始位置。', '重复所需的重复次数。'],
  'H0998': ['双脚分开与肩同宽站立，双手握住弹力带，掌心朝下。', '将手臂伸直至两侧，保持与地面平行。', '慢慢弯曲肘部，将双手放在肩膀上，保持上臂不动。', '暂停片刻，然后慢慢将手臂伸回起始位置。', '重复所需的重复次数。'],
  'H0999': ['双脚分开站立，与臀部同宽，将弹力带绕在左脚掌上。', '如果需要，请抓住一个稳定的物体以保持平衡。', '慢慢地将左脚跟抬离地面，将身体重量转移到脚掌上。', '在顶部暂停片刻，然后慢慢将左脚跟放回起始位置。', '重复所需的重复次数，然后换右腿。'],
  'H1000': ['双脚分开站立，与臀部同宽，将弹力带放在脚掌周围。', '抓住稳定的物体以保持平衡。', '慢慢地将脚跟抬离地面，将身体重量转移到脚掌上。', '在顶部暂停片刻，然后慢慢将脚跟放回起始位置。', '重复所需的重复次数，然后换另一条腿。'],
  'H1001': ['双脚分开站立，与臀部同宽，将阻力带绕在脚踝上。', '右脚向前迈一大步，左脚向后退一小步。', '弯曲膝盖并降低身体，直到右大腿与地面平行，保持左膝盖略高于地面。', '推动右脚跟回到起始位置。', '在另一侧重复。'],
  'H1004': ['双脚分开站立，与肩同宽，弹力带放在膝盖上方。', '保持挺胸、核心收紧，将臀部向后推，弯曲膝盖，形成下蹲姿势。', '确保膝盖位于脚趾上方，并且重量位于脚后跟。', '在底部停顿片刻，然后推动脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H1003': ['将带子固定在腰部高度的坚固锚点上。', '面向锚点站立，双脚分开与肩同宽。', '双手握住弹力带手柄，手掌相对，双臂向前伸展。', '弯曲膝盖并蹲下，保持背部挺直，挺胸。', '从蹲姿开始，将弹力带手柄拉向身体，将肩胛骨挤压在一起。', '在最高点停顿片刻，然后慢慢释放张力，回到起始位置。', '重复所需的重复次数。'],
  'H1005': ['将带子固定在腰部高度的坚固锚点上。', '背对锚点站立，双脚与肩同宽。', '用双手握住弹力带并将其举至胸前，保持肘部弯曲并靠近身体。', '收紧腹肌，慢慢向前挺胸，使胸部靠近膝盖。', '在卷腹的最高点暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H1022': ['双脚分开与肩同宽站立，将弹力带放在脚下。', '双手握住弹力带手柄，手掌相对，双臂向前伸展。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '将弹力带拉向胸部，将肩胛骨挤压在一起。', '在最高点停顿片刻，然后慢慢释放张力，回到起始位置。', '重复所需的重复次数。'],
  'H1007': ['双脚分开与肩同宽站立，将弹力带绕在上背部，穿过胸前。', '用手握住带子的末端，保持肘部弯曲并靠近身体两侧。', '收紧腹肌并将躯干向一侧扭转，将肘部移向另一侧的膝盖。', '暂停片刻，然后回到起始位置。', '在另一侧重复。', '继续交替进行所需的重复次数。'],
  'H1008': ['将一条带子绕在大腿上，就在膝盖上方。', '面向台阶或平台站立，双脚分开与臀部同宽。', '用右脚踩上平台，用脚后跟推动。', '将左腿伸到身后，保持伸直。', '将左脚放回地面。', '重复左脚踩上平台的动作。', '继续交替双腿达到所需的重复次数。'],
  'H1009': ['双脚分开站立，与肩同宽，将弹力带绕在脚踝上。', '用双手将弹力带放在大腿前面，手掌朝向身体。', '保持背部挺直，核心收紧，铰接臀部，慢慢将上半身降低到地面。', '当你降低时，将臀部向后推，并让膝盖稍微弯曲。', '将弹力带降低至地面，感受腿筋的拉伸。', '在底部暂停片刻，然后启动臀肌和腿筋，将上半身抬回到起始位置。', '重复所需的重复次数。'],
  'H1023': ['双脚分开与肩同宽站立，将弹力带绕在大腿上。', '用双手将弹力带放在大腿前面，手掌朝向身体。', '保持背部挺直，膝盖稍微弯曲，铰接臀部并将弹力带降低到地面。', '当你降低弹力带时，感受腿筋的拉伸。', '启动臀肌和腿筋，将身体抬回到起始位置。', '重复所需的重复次数。'],
  'H1010': ['双脚分开与肩同宽站立，将弹力带绕在脚上。', '双手握住弹力带，手掌朝向身体，手臂伸直。', '收紧核心并保持膝盖轻微弯曲。', '慢慢地以臀部为中心向前转动，保持背部挺直，挺胸。', '将弹力带降低至地面，同时保持双腿伸直。', '在底部暂停片刻，然后挤压臀肌和腿筋，回到起始位置。', '重复所需的重复次数。'],
  'H1012': ['双脚分开与肩同宽站立，将弹力带放在脚下。', '将弹力带手柄保持在与肩同高的位置，手掌朝前。', '启动你的核心并将弹力带压过头顶，充分伸展你的手臂。', '当你按压时，将你的躯干扭转到一侧，保持臀部稳定。', '在顶部暂停片刻，然后回到起始位置。', '在另一侧重复按压和扭转。', '继续交替进行所需的重复次数。'],
  'H1369': ['双脚分开与肩同宽站立，并将阻力带放在双脚下方。', '用手握住带子的末端以保持稳定。', '用小腿将脚跟抬离地面，尽可能高。', '在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H1013': ['将弹力带固定在较高的锚点上，例如上拉杆或坚固的横梁。', '面向锚点站立，双脚分开与肩同宽。', '反手握住弹力带，双手间距略宽于肩宽。', '将手臂完全伸过头顶，保持肘部稍微弯曲。', '收紧背阔肌，将弹力带向下拉向胸部，将肩胛骨挤压在一起。', '在动作底部停顿片刻，然后慢慢释放张力，回到起始位置。', '重复所需的重复次数。'],
  'H1014': ['平躺，双腿伸直，手臂伸过头顶，握住弹力带。', '收紧腹肌，同时将双腿和上半身抬离地面，双手伸向脚趾。', '在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。', '重复所需的重复次数。'],
  'H1015': ['双脚分开与肩同宽站立，将弹力带缠绕在胸部高度的坚固物体上。', '用双手握住弹力带并远离锚点，在弹力带中产生张力。', '使自己垂直于锚点，一侧面向弹力带。', '将双臂伸直在身前，保持双手与胸同高。', '收紧核心肌群，将弹力带压离胸部，充分伸展手臂。', '保持该姿势几秒钟，然后慢慢将弹力带拉回到胸部。', '重复所需的重复次数，然后换边。'],
  'H1016': ['坐在长凳或椅子上，双脚平放在地面上。', '双手握住弹力带，手掌朝上，前臂放在大腿上。', '慢慢向上弯曲手腕，挤压前臂。', '在顶部暂停片刻，然后慢慢将手腕放回起始位置。', '重复所需的重复次数。'],
  'H1017': ['双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝内。', '保持双臂伸直，将其向上举至两侧，与身体形成“Y”形。', '在动作的最高点将肩胛骨挤压在一起。', '慢慢地将手臂放回起始位置。', '重复所需的重复次数。'],
  'H0023': ['站直，双脚分开与肩同宽，每只手握住一个杠铃，手掌朝前。', '保持上臂静止，在弯举哑铃时呼气，同时收缩二头肌。', '继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气，慢慢开始将杠铃放回起始位置。', '重复所需的重复次数，交替手臂。'],
  'H2407': ['站直，双脚分开与肩同宽，反手握住杠铃，手掌朝上。', '将上臂靠在手臂冲击波上，保持肘部靠近躯干。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0028': ['双脚分开与肩同宽站立，杠铃放在你面前的地板上。', '弯曲膝盖并以臀部为铰链降低并用正手握住杠铃，双手分开略宽于肩宽。', '通过脚后跟发力，伸展臀部和膝盖，将杠铃抬离地板，使其靠近身体。', '当杠铃到达大腿时，爆发性伸展臀部，耸肩，并将杠铃拉向胸部。', '当杠铃到达胸部高度时，迅速将其降至肩部水平，肘部向前，手掌朝上。', '从接球位置开始，伸展双臂并将杠铃笔直向上推，将杠铃压过头顶。', '将杠铃放回起始位置，然后重复所需的重复次数。'],
  'H0029': ['首先，双脚分开与肩同宽，将杠铃放在上胸部，肘部向前。', '弯曲膝盖并将臀部向后推，降低身体，就像坐在椅子上一样。', '下降时保持挺胸、背部挺直，确保膝盖不超过脚趾。', '继续降低，直到大腿与地面平行，或者尽可能低。', '在底部停顿片刻，然后用脚跟推动站起来，伸展臀部和膝盖。', '重复所需的重复次数。'],
  'H0034': ['躺在倾斜的长凳上，头部低于臀部，双脚固定。', '旋前握住杠铃（手掌背向您），并将手臂伸直至胸部上方。', '有控制地将杠铃降低到头后，保持手臂稍微弯曲。', '暂停片刻，然后收缩背阔肌，将杠铃抬回到起始位置。', '重复所需的重复次数。'],
  'H1255': ['躺在倾斜的长凳上，头部低于臀部，双脚固定。', '旋前握住杠铃（手掌背向自己），双手之间的距离略宽于肩宽。', '将手臂伸至胸部上方，保持肘部轻微弯曲。', '以弧线动作将杠铃降低到头后，感受胸部和肩膀的伸展。', '暂停片刻，然后反向动作将杠铃恢复到起始位置。', '重复所需的重复次数。'],
  'H1370': ['将杠铃放在您面前的地板上。', '站立，脚掌放在杠铃边缘，脚跟悬垂。', '如果需要，请抓住一个稳定的物体以保持平衡。', '尽可能高地抬高脚后跟，用小腿来抬起身体。', '在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H0039': ['首先站立，双脚分开与肩同宽，脚趾稍微向外。', '将杠铃放在胸前，双手与肩同宽，肘部向前。', '当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。', '降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。', '在底部停顿片刻，然后推动脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H0041': ['双脚分开与肩同宽站立，正手握住杠铃于大腿前方。', '保持手臂伸直，向前向上举起杠铃，直至达到肩部水平。', '在顶部停顿片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H1461': ['站立，双脚分开与肩同宽，脚趾稍微向外。', '将杠铃放在上背部，将其放在斜方肌或三角肌后束上。', '当你开始降低身体时，启动你的核心并保持胸部挺直。', '弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。', '降低身体，直到大腿与地面平行或稍低于地面。', '保持膝盖与脚趾对齐，并将重量放在脚后跟上。', '通过脚后跟站起来，伸展臀部和膝盖。', '重复所需的重复次数。'],
  'H1462': ['站立，双脚分开与肩同宽，脚趾稍微向外。', '将杠铃放在上背部，将其放在斜方肌或三角肌后束上。', '当你开始降低身体时，启动你的核心并保持胸部挺直。', '弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。', '降低身体，直到大腿与地面平行或稍低于地面。', '保持膝盖与脚趾对齐，并将重量放在脚后跟上。', '通过脚后跟站起来，伸展臀部和膝盖。', '重复所需的重复次数。'],
  'H1545': ['站立，双脚分开与肩同宽，脚趾稍微外翻。', '将杠铃放在肘部的弯曲处，双手握住杠铃以保持稳定。', '当你将臀部向后降低到蹲姿时，启动你的核心并保持胸部抬起。', '保持膝盖与脚趾对齐，并将重量放在脚后跟上。', '降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。', '通过脚跟发力站起来，在动作的最高点挤压臀部。', '重复所需的重复次数。'],
  'H3562': ['首先坐在长凳边缘，上背部靠在长凳上，双脚平放在地面上，与臀部同宽。', '将杠铃放在臀部上，用双手牢牢握住它。', '锻炼臀肌和核心肌肉，然后用脚后跟将臀部抬离长凳，形成从膝盖到肩膀的一条直线。', '在顶部暂停片刻，挤压臀部。', '慢慢地将臀部放回起始位置。', '重复所需的重复次数。'],
  'H0045': ['平躺在长凳上，双脚平放在地上，背部紧贴长凳。', '正手握住杠铃，握距略宽于肩宽。', '慢慢地将杠铃降低到颈部，保持肘部朝外。', '当杠铃位于颈部上方时，暂停片刻。', '将杠铃推回到起始位置，完全伸展双臂。', '重复所需的重复次数。'],
  'H1436': ['站立，双脚分开与肩同宽，脚趾稍微向外。', '将杠铃放在上背部，放在斜方肌上。', '当你开始蹲下时，启动你的核心并保持胸部挺直，将臀部向后推并弯曲膝盖。', '放低身体，直到大腿与地面平行，或者尽可能低到您能舒服的高度。', '通过脚后跟站起来，伸展臀部和膝盖。', '重复所需的重复次数。'],
  'H1719': ['设置一个 45 度角的上斜凳。', '躺在长凳上，双脚平放在地上。', '紧紧握住杠铃，握距略窄于肩宽。', '松开杠铃并将其缓慢降低至胸部，保持肘部靠近身体。', '当杠铃触及胸部时暂停片刻。', '将杠铃推回到起始位置，完全伸展双臂。', '重复所需的重复次数。'],
  'H0048': ['设置一个 45 度角的上斜凳。', '仰卧在长凳上，反握抓住杠铃，双手距离略宽于肩宽。', '松开杠铃并将其向上胸部降低，保持肘部内收。', '在底部停顿片刻，然后将杠铃推回到起始位置。', '重复所需的重复次数。'],
  'H0049': ['设置一个 45 度角的上斜凳。', '脸朝下躺在长凳上，胸部靠在垫子上，双脚平放在地上。', '正手握住杠铃，握距略宽于肩宽。', '保持背部挺直，核心肌群参与。', '将杠铃拉向胸部，将肩胛骨挤压在一起。', '在顶部停顿片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0050': ['设置一个 45 度角的上斜凳。', '坐在长凳上，背部靠在垫子上，双脚平放在地面上。', '正手握住杠铃，杠铃间距略宽于肩宽。', '将杠铃举至肩膀高度，保持肘部稍微弯曲。', '慢慢地将杠铃举过头顶，充分伸展双臂。', '在顶部停顿片刻，然后慢慢将杠铃放回肩部高度。', '重复所需的重复次数。'],
  'H0051': ['站立，双脚分开与肩同宽，脚趾稍微外翻。', '正手握住杠铃，将其放在身体前部、腰部下方。', '左脚向前迈出，右脚向后迈出，双脚分开与肩同宽。', '弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。', '脚后跟用力，站回起始位置。', '重复该动作，每次重复时交替使用前脚和后脚。'],
  'H0052': ['平躺在长凳上，双脚平放在地上，背部紧贴长凳。', '正手握住杠铃，握距略宽于肩宽。', '将杠铃降低到胸部，保持肘部靠近身体。', '将杠铃推回到起始位置，完全伸展双臂。', '重复所需的重复次数。'],
  'H0053': ['首先，双脚分开与肩同宽站立，将杠铃放在上背部。', '弯曲膝盖并将臀部向后推，将身体降低至蹲姿。', '一旦到达深蹲底部，就从地面跳起向上爆发。', '跳跃时，伸展臀部、膝盖和脚踝，推动脚趾。', '轻轻地回到蹲姿，然后立即重复该动作达到所需的重复次数。'],
  'H1410': ['双脚分开与肩同宽站立，将杠铃放在上背部。', '右脚向一侧迈出一大步，保持左脚踩地。', '弯曲右膝，将身体降低到弓步位置，保持左腿伸直。', '用右脚推出并返回到起始位置。', '在另一侧重复，用左脚迈步。'],
  'H1435': ['双脚分开与肩同宽站立，杠铃放在上背部。', '保持挺胸，核心收紧，弯曲膝盖并向后推臀部，慢慢降低身体。', '继续降低，直到大腿与地面平行或略低于地面。', '暂停片刻，然后用力推动脚后跟，回到起始位置。', '重复所需的重复次数。'],
  'H0055': ['平躺在长凳上，双脚平放在地上，背部紧贴长凳。', '紧紧握住杠铃，双手与肩同宽，手掌朝向脚部。', '将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。', '慢慢地将杠铃降低到胸部，保持肘部靠近身体。', '当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。', '重复所需的重复次数。'],
  'H0056': ['平躺在长凳上，双脚平放在地上，头放在长凳的末端。', '紧握杠铃，双手与肩同宽，掌心向上。', '充分伸展双臂，将杠铃举至胸部上方。', '保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。', '在底部停顿片刻，然后将手臂伸展回起始位置。', '重复所需的重复次数。'],
  'H0057': ['平躺在长凳上，双脚平放在地上，头放在长凳的末端。', '正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。', '保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。', '暂停片刻，然后将手臂伸回到起始位置。', '重复所需的重复次数。'],
  'H0058': ['仰卧在长凳上，双脚平放在地上，膝盖弯曲。', '正手握住杠铃并将其放在臀部上。', '收紧臀部，将臀部抬离长凳，直到身体从膝盖到肩膀形成一条直线。', '在顶部暂停片刻，然后慢慢将臀部放回起始位置。', '重复所需的重复次数。'],
  'H0059': ['坐在牧师长凳上，胸部靠在垫子上，手臂伸出边缘，反手握住杠铃。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续抬高杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0060': ['平躺在长凳上，双脚平放在地上，头放在长凳的末端。', '正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。', '保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。', '当杠铃位于前额上方时暂停片刻，然后将手臂向后伸展至起始位置。', '重复所需的重复次数。'],
  'H0063': ['站立，双脚分开与肩同宽，脚趾稍微向外。', '将杠铃放在上背部，将其放在斜方肌或三角肌后束上。', '收紧核心并保持挺胸，同时弯曲膝盖并向后推臀部，慢慢降低身体。', '继续降低，直到大腿与地面平行或略低于地面。', '暂停片刻，然后用力推动脚后跟，回到起始位置。', '重复所需的重复次数。'],
  'H0064': ['双脚分开与肩同宽站立，膝盖稍微弯曲，用一只手正握握住杠铃。', '臀部向前弯曲，保持背部挺直，头部处于中立位置。', '将杠铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。', '以受控的方式将杠铃降低回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0065': ['仰卧在地板上，膝盖弯曲，双脚平放在地面上。', '用一只手握住杠铃，掌心朝上，将手臂伸直至胸部上方。', '慢慢地将杠铃降低到胸部，保持肘部靠近身体。', '在底部停顿片刻，然后将杠铃推回到起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0066': ['双脚分开与肩同宽站立，一只手握住杠铃，正握。', '保持背部挺直，核心肌群参与。', '臀部弯曲，将杠铃向腿外侧放低，保持手臂伸直，挺胸。', '尽可能降低杠铃，同时保持良好的姿势。', '暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数，然后换边。'],
  'H1411': ['坐在长凳上，双脚平放在地上，前臂放在大腿上，手掌朝下。', '正手握住杠铃，双手与肩同宽。', '弯曲手腕，将杠铃降低到地面，保持前臂静止。', '在底部停顿片刻，然后通过伸展手腕慢慢将杠铃举起。', '重复所需的重复次数。'],
  'H1412': ['坐在长凳上，双脚平放在地面上，反手握住杠铃，手掌朝上。', '将前臂放在长凳上，让手腕悬在长凳边缘。', '保持前臂静止，呼气并尽可能向上弯曲手腕。', '保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H1751': ['将杠铃放在与胸部同高的力量架上。', '面向杠铃站立，将自己置于杠铃下方，双脚分开与肩同宽。', '正手握住杠铃，握距略宽于肩宽。', '将杠铃从架子上提起，并将其保持在胸部正上方，双臂完全伸展。', '将杠铃向胸部方向降低，保持肘部靠近身体。', '当杠铃触及胸部时暂停片刻。', '将杠铃推回到起始位置，完全伸展双臂。', '重复所需的重复次数。'],
  'H0071': ['平躺在垫子上，膝盖弯曲，双脚平放在地上。', '正手握住杠铃，将其放在胸前。', '收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H0073': ['平躺在长凳上，头放在一端，双脚放在地板上。', '握距与肩同宽，握住杠铃，将手臂伸直至胸部上方。', '保持手臂伸直，以受控的方式将杠铃降低到头后，直到感觉到背阔肌被拉伸。', '暂停片刻，然后将杠铃举回起始位置。', '重复所需的重复次数。'],
  'H0022': ['平躺在长凳上，头朝一端，双脚着地。', '旋前握住杠铃（手掌背向您），并将手臂伸直至胸部上方。', '保持手臂伸直，以弧形动作将杠铃降低到脑后，直到感觉到背阔肌有拉伸感。', '暂停片刻，然后反转动作，将杠铃推回到胸部上方的起始位置。', '重复所需的重复次数。'],
  'H0074': ['将杠铃放在膝盖高度的架子上。', '双脚分开与肩同宽站立，脚趾稍微向外。', '弯曲臀部和膝盖，降低身体高度，正手握住杠铃，双手与肩同宽。', '通过伸展臀部和膝盖、向后拉肩膀并在顶部挤压臀部来收紧核心并举起杠铃。', '弯曲臀部和膝盖，将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0075': ['双脚分开与肩同宽站立，正手握住杠铃，手掌朝下。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '将杠铃向两侧举起，保持手臂伸直，直到它们与地面平行。', '在顶部停顿片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0078': ['首先，双脚分开与肩同宽，将杠铃放在上背部。', '右脚向后退一步，用脚掌着地。', '弯曲双膝降低身体，直到左大腿与地面平行。', '推动左脚跟返回到起始位置。', '换另一条腿重复上述步骤。'],
  'H0077': ['双脚分开与肩同宽站立，将杠铃放在上背部。', '右脚向后退一步，用脚掌着地。', '弯曲双膝降低身体，直到左大腿与地面平行。', '推动左脚跟返回到起始位置。', '换另一条腿重复上述步骤。'],
  'H0079': ['坐在长凳上，双脚平放在地上，膝盖弯曲。', '正手握住杠铃，手掌朝下，双手与肩同宽。', '将前臂放在大腿上，让手腕悬在边缘。', '保持前臂静止，呼气并尽可能向上弯曲手腕。', '保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H2187': ['平躺在长凳上，双脚平放在地上，背部紧贴长凳。', '反握抓住杠铃，双手与肩同宽。', '将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。', '慢慢地将杠铃向胸部降低，保持肘部靠近身体。', '当杠铃位于胸部正上方时，暂停片刻。', '将杠铃推回到起始位置，完全伸展双臂。', '重复所需的重复次数。'],
  'H0118': ['站立，双脚分开与肩同宽，膝盖稍微弯曲。', '正手握住杠铃，手掌朝下，双手分开略宽于肩宽。', '臀部向前弯曲，保持背部挺直，挺胸，直到躯干几乎与地板平行。', '将杠铃拉向下胸部，将肩胛骨挤压在一起。', '在顶部停顿片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H1256': ['躺在倾斜的长凳上，双脚固定，头部低于臀部。', '反握抓住杠铃，握距略宽于肩宽。', '松开杠铃，慢慢将其降低到胸部，保持肘部内收。', '在底部停顿片刻，然后将杠铃推回到起始位置。', '重复所需的重复次数。'],
  'H1257': ['设置一个 45 度角的上斜凳。', '躺在长凳上，双脚平放在地上。', '反握抓住杠铃，双手分开略宽于肩宽。', '松开杠铃，慢慢将其降低到胸部，保持肘部内收。', '当杠铃触及胸部时暂停片刻。', '将杠铃推回到起始位置，完全伸展双臂。', '重复所需的重复次数。'],
  'H1317': ['设置一个 45 度角的上斜凳。', '坐在长凳上，面向靠背，胸部靠在靠背上。', '反握（手掌朝下）抓住杠铃，双手距离略宽于肩宽。', '保持背部挺直，核心参与。', '将杠铃拉向上腹部，将肩胛骨挤压在一起。', '在动作的最高点停顿片刻。', '慢慢地将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H1721': ['平躺在长凳上，双脚平放在地上，头放在长凳的末端。', '反握握住杠铃，手掌朝向脸部，双手与肩同宽。', '将手臂伸直越过胸部，保持肘部内收和手腕伸直。', '弯曲肘部，慢慢将杠铃降低到前额，保持上臂静止。', '在底部停顿片刻，然后将手臂伸回起始位置。', '重复所需的重复次数。'],
  'H0081': ['坐在牧师凳上，胸部靠在垫子上，手臂伸直向下，正手握住杠铃。', '保持上臂静止，呼气并向上弯曲杠铃，同时收缩二头肌。', '继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0083': ['首先跪在地板上，将杠铃放在你面前的长凳上。', '正手握住杠铃，握距略宽于肩宽。', '保持核心收紧，背部挺直，慢慢向前滚动杠铃，将手臂伸到身前。', '继续向前滚动杠铃，直到身体完全伸展并且手臂举过头顶。', '在完全伸展的位置暂停片刻，然后慢慢地将杠铃向身体方向滚动，回到起始位置。', '重复所需的重复次数。'],
  'H0086': ['坐在长凳上，背部挺直，双脚平放在地上。', '正手握住杠铃，杠铃间距略宽于肩宽。', '将杠铃从架子上提起，然后将其降至与肩同高，位于头后。', '向上推杠铃，直到手臂完全伸展。', '将杠铃降低回到起始位置。', '重复所需的重复次数。'],
  'H0087': ['坐在长凳上，背部挺直，双脚平放在地上。', '正手握住杠铃，杠铃间距略宽于肩宽。', '将杠铃举至肩膀高度，保持肘部稍微弯曲并指向前方。', '将杠铃推过头顶，充分伸展双臂。', '将杠铃降低回肩部高度，然后重复所需的重复次数。'],
  'H1718': ['坐在长凳上，背部挺直，双脚平放在地上。', '紧紧抓住颈后的杠铃，手掌朝前。', '保持肘部靠近头部，慢慢将杠铃放低至脑后。', '暂停片刻，然后将手臂伸回到起始位置。', '重复所需的重复次数。'],
  'H0090': ['坐在长凳上，双脚平放在地上，上背部放一个杠铃。', '保持背部挺直，挺胸。', '慢慢地向前转动臀部，将躯干降低到地面。', '在底部停顿片刻，然后推动脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H0094': ['坐在平坦的长凳上，双脚平放在地上，膝盖弯曲。', '双手握住杠铃于胸前，保持肘部稍微弯曲。', '启动你的核心，慢慢地将你的躯干扭转到一侧，保持背部挺直。', '扭转结束时暂停片刻，然后慢慢旋转回到起始位置。', '重复扭转到另一侧。', '继续交替进行所需的重复次数。'],
  'H0096': ['双脚分开与肩同宽站立，双手握住杠铃，掌心朝下。', '在整个练习过程中保持背部挺直并保持核心参与。', '慢慢地将你的躯干弯曲到右侧，将杠铃向右膝方向降低。', '暂停片刻，然后回到起始位置。', '在左侧重复该动作。', '继续交替进行所需的重复次数。'],
  'H0098': ['站立，双脚分开比肩宽，脚趾稍微向外。', '将杠铃放在上背部，将其放在斜方肌上。', '当你将身体降低到蹲姿时，收紧你的核心并保持胸部向上，弯曲膝盖和臀部。', '当你下降时，将膝盖向两侧推出，并将体重保持在脚后跟上。', '降低直到大腿与地面平行，然后通过脚后跟推回到起始位置。', '重复所需的重复次数。'],
  'H0097': ['站立，双脚分开比肩宽，脚趾稍微向外。', '将杠铃放在上背部，将其放在肩膀上。', '右脚向一侧迈出一大步，保持左脚踩地。', '弯曲右膝，将身体放低至蹲姿，保持挺胸、背部挺直。', '推动右脚跟回到起始位置。', '在另一侧重复，左脚迈出。', '继续交替进行所需的重复次数。'],
  'H1756': ['站立，双脚分开与臀部同宽，正手握住杠铃在大腿前面。', '将重心转移到左脚上，并将右脚稍微抬离地面。', '臀部向前转动，保持背部挺直，右腿向后伸展以保持平衡。', '将杠铃向地面降低，使其靠近身体，左腿稍微弯曲。', '在底部暂停片刻，然后启动臀肌和腿筋，将躯干抬回到起始位置。', '重复所需的重复次数，然后换边。'],
  'H2799': ['坐在长凳上，背部挺直，将杠铃放在大腿上。', '保持双腿伸直，将一条腿尽可能高地抬起，同时将另一条腿放在地上。', '将抬起的腿放回原位，然后换另一条腿重复上述步骤。', '继续交替双腿达到所需的重复次数。'],
  'H2800': ['坐在长凳上，背部挺直，将杠铃放在大腿上。', '将双手放在长凳两侧以获得支撑。', '保持双腿伸直，将一条腿尽可能抬高，同时保持与地面平行。', '将腿放回原位，然后换另一条腿重复此动作。', '继续交替双腿达到所需的重复次数。'],
  'H0100': ['双脚分开与肩同宽站立，正手握住杠铃于大腿前方。', '稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。', '同时将杠铃举向肩膀，同时稍微离开地面。', '当您到达动作的最高点时，快速反转动作并将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0101': ['站立，双脚分开与肩同宽，脚趾稍微向外。', '将杠铃放在上背部，将其放在斜方肌或三角肌后束上。', '收紧核心肌群，保持挺胸，同时向后和向下降低臀部，就像坐在椅子上一样。', '降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。', '通过脚跟发力站起来，在顶部挤压臀部。', '重复所需的重复次数。'],
  'H2810': ['首先，双脚分开与肩同宽站立，将杠铃放在上背部。', '右脚向前迈出一大步，保持躯干直立。', '弯曲膝盖和臀部，降低身体，直到右大腿与地面平行。', '暂停片刻，然后推动右脚跟回到起始位置。', '左腿向前重复此动作，达到所需的重复次数。'],
  'H0102': ['首先跪在地上，膝盖分开与臀部同宽，脚趾向前。', '将杠铃放在肩膀上，正手握住杠铃，双手分开的距离略大于肩宽。', '收紧核心并保持胸部抬起，同时弯曲膝盖慢慢降低身体，保持背部挺直。', '继续降低，直到大腿与地面平行，或者尽可能低。', '在底部停顿片刻，然后推动脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H2798': ['首先，双脚分开与肩同宽站立，将杠铃放在上背部。', '弯曲膝盖并将臀部向后推，将身体降低至蹲姿。', '向上爆炸，尽可能高地跳离地面。', '双脚轻轻落地，然后立即单腿向后退一步，形成反向弓步。', '降低身体，直到大腿前侧与地面平行，保持背部挺直。', '推动前脚跟以返回到起始位置。', '在另一条腿上重复跳跃和弓步序列。', '继续交替双腿达到所需的重复次数。'],
  'H0103': ['站直，双脚分开与肩同宽，双手握住杠铃于大腿前方。', '启动你的核心肌群，慢慢地将杠铃向地面滚动，保持背部挺直，手臂伸展。', '继续向前滚动杠铃，直到身体完全伸展，双手位于头顶正上方。', '暂停片刻，然后慢慢地将杠铃向大腿方向滚动，保持控制并保持核心参与。', '重复所需的重复次数。'],
  'H0104': ['站直，双脚分开与肩同宽，正手握住杠铃。', '将杠铃放在手背上，手掌朝下，手指指向身体。', '保持上臂静止，呼气并尽可能向上弯曲手腕。', '保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0105': ['双脚分开与肩同宽站立，正手握住杠铃于肩前。', '将杠铃推过头顶，充分伸展双臂。', '将杠铃降低回到起始位置。', '重复所需的重复次数。'],
  'H1456': ['双脚分开与肩同宽站立，正手握住杠铃，双手距离略小于肩宽。', '将杠铃举至肩膀高度，保持肘部靠近身体。', '将杠铃推过头顶，充分伸展双臂。', '将杠铃降低回肩部高度。', '重复所需的重复次数。'],
  'H2414': ['双脚分开与肩同宽站立，一手握住杠铃，掌心朝上。', '将另一只手放在大腿上以获得支撑。', '保持上臂静止，呼气并将重量向上弯向肩膀。', '在顶部暂停片刻，挤压你的二头肌。', '吸气并慢慢将重量放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0107': ['双脚分开与肩同宽站立，正手握住杠铃于大腿前方。', '保持背部挺直并启动核心肌群。', '慢慢地将杠铃举到你面前，保持手臂伸直，手掌朝下。', '继续举起杠铃，直到杠铃略高于肩部水平。', '在顶部停顿片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0108': ['双脚分开与肩同宽站立，将杠铃放在上背部。', '用小腿将脚跟抬离地面，尽可能高。', '在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H0109': ['双脚分开与肩同宽站立，正手握住杠铃。', '将杠铃举过头顶，充分伸展双臂。', '保持上臂靠近头部，弯曲肘部，慢慢将杠铃降低到脑后。', '暂停片刻，然后伸展双臂将杠铃举回起始位置。', '重复所需的重复次数。'],
  'H0110': ['站直，双脚分开与肩同宽，反手握住杠铃，手掌朝上。', '保持肘部靠近躯干，上臂保持静止。', '呼气并弯举杠铃，同时收缩二头肌，使杠铃尽可能靠近肩膀。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0112': ['双脚分开与肩同宽站立，双手握住杠铃于胸前，掌心朝下。', '在整个练习过程中启动你的核心并保持背部挺直。', '慢慢地将躯干向右扭转，以脚和臀部为轴，同时保持下半身稳定。', '扭转结束时暂停片刻，然后慢慢回到起始位置。', '向左侧重复扭转。', '继续交替扭转所需的重复次数。'],
  'H1629': ['双脚分开与肩同宽站立，反握握住杠铃，双手分开比肩宽。', '保持背部挺直，肘部靠近躯干。', '呼气并将杠铃向上弯向肩膀，保持上臂静止。', '在顶部暂停片刻，挤压你的二头肌。', '吸气，慢慢将杠铃放回起始位置，充分伸展双臂。', '重复所需的重复次数。'],
  'H0113': ['站直，双脚分开与肩同宽，正手握住杠铃，双手分开比肩宽。', '让杠铃悬挂在大腿前面，与手掌保持一臂距离，手掌背向身体。', '保持上臂静止，呼气并通过收缩二头肌向上弯曲杠铃。', '继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0115': ['双脚分开与肩同宽站立，膝盖稍微弯曲。', '将杠铃放在上背部，将其放在斜方肌上。', '保持背部挺直，臀部向前转动，将臀部向后推。', '降低躯干直到与地面平行，感觉腿筋被拉伸。', '启动臀肌和腿筋以返回起始位置。', '重复所需的重复次数。'],
  'H0116': ['站立，双脚分开与肩同宽，脚趾指向前方。', '正手握住杠铃，双手分开略宽于肩宽。', '弯曲臀部，将杠铃放低至地面，保持背部挺直，膝盖稍微弯曲。', '降低杠铃，直到感觉到腿筋拉伸。', '启动腿筋和臀肌，将杠铃举回起始位置。', '重复所需的重复次数。'],
  'H3305': ['首先，双脚分开与肩同宽站立，正手握住杠铃，与肩同高。', '弯曲膝盖并将臀部向后推，降低至蹲姿。', '当你到达深蹲底部时，爆发性地通过脚后跟站起来，同时将杠铃压过头顶。', '当你回到深蹲位置时，将杠铃降低到肩膀高度。', '重复所需的重复次数。'],
  'H0120': ['双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。', '让杠铃悬挂在大腿前面，双臂完全伸展。', '保持背部挺直，核心收紧，呼气，将杠铃笔直向上举向下巴，用肘部引导。', '在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0119': ['双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。', '让杠铃悬挂在大腿前面，双臂完全伸展。', '保持背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。', '在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0121': ['双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。', '让杠铃悬挂在大腿前面，双臂完全伸展。', '保持核心收紧，背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。', '在顶部暂停片刻，然后吸气，慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H1258': ['平躺在长凳上，双脚平放在地上，背部紧贴长凳。', '反握宽握杠铃，握距略宽于肩宽。', '将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。', '将杠铃慢慢降低到胸部，保持肘部内收，手腕伸直。', '当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。', '重复所需的重复次数。'],
  'H0123': ['双脚分开与肩同宽站立，正手握住杠铃，双手分开比肩宽。', '让杠铃悬挂在大腿前面，双臂完全伸展。', '保持背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。', '在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0125': ['坐在长凳上，双脚平放在地上，膝盖弯曲。', '反手握住杠铃，手掌朝上，双手与肩同宽。', '将前臂放在大腿上，让手腕悬在边缘。', '慢慢向上弯曲手腕，将杠铃拉向前臂。', '在顶部停顿片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0127': ['站立，双脚分开与肩同宽，脚趾稍微外翻。', '将杠铃放在肘部的弯曲处，双手握住杠铃以保持稳定。', '当你将臀部向后降低到蹲姿时，启动你的核心并保持胸部抬起。', '保持膝盖与脚趾对齐，并将重量放在脚后跟上。', '在深蹲底部暂停片刻，然后用脚后跟恢复到起始位置。', '重复所需的重复次数。'],
  'H3212': ['双脚分开与肩同宽站立，双臂放在身体两侧。', '腰部向前弯曲，保持背部挺直，膝盖稍微弯曲。', '双手向下伸向脚趾，尽可能保持双腿伸直。', '在底部停顿片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H0128': ['站立，双脚分开与肩同宽，膝盖稍微弯曲。', '双手握住绳子的一端，手掌相对。', '将手臂举至肩膀高度，保持肘部稍微弯曲。', '快速抬起和放下每只手臂，开始用绳索产生交替的波浪。', '继续所需的持续时间或重复次数。'],
  'H1259': ['站直，双脚分开与肩同宽。', '将手指交叉放在脑后，肘部朝外。', '慢慢地将肩胛骨挤压在一起，并将胸部向前推。', '保持拉伸 15-30 秒。', '松开拉伸并根据需要重复。'],
  'H1399': ['坐在长凳或椅子的边缘，双手抓住边缘，手指指向前方。', '将臀部滑离长凳，用手支撑体重。', '弯曲肘部降低身体，直到上臂与地板平行。', '伸直手臂，将自己推回起始位置。', '重复所需的重复次数。'],
  'H3639': ['平躺，膝盖弯曲，双脚平放在地上。', '将手臂向两侧伸展，与身体垂直。', '保持膝盖并拢，慢慢地将它们降低到一侧，旨在用膝盖接触地面。', '暂停片刻，然后启动核心并慢慢将膝盖抬回到起始位置。', '到另一侧重复该动作。', '继续交替进行所需的重复次数。'],
  'H1770': ['坐在长凳上，双腿分开，双脚平放在地上。', '一只手握住哑铃，将肘部放在大腿内侧，膝盖上方。', '手掌朝上，将哑铃向肩膀弯曲，同时保持上臂静止。', '在动作的最高点挤压二头肌，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0139': ['悬挂在引体向上杆上，手掌朝向自己，双手与肩同宽。', '启动你的核心并将自己拉向杠铃，专注于使用二头肌来抬起你的身体。', '在最高点暂停片刻，然后慢慢降低回到起始位置。', '重复所需的重复次数。'],
  'H0140': ['悬挂在引体向上杆上，手掌背向自己，双手与肩同宽。', '启动核心肌群，弯曲肘部将自己拉起，使胸部靠近杠铃。', '在动作的最高点暂停，然后慢慢降低回到起始位置。', '重复所需的重复次数。'],
  'H0137': ['首先将双手放在凸起的表面上，例如长凳或双杠上，手掌朝下，手指向前。', '将双腿向前方伸展，脚跟保持在地面上，身体伸直。', '弯曲肘部降低身体，使其靠近身体两侧，直到上臂与地面平行。', '暂停片刻，然后用手掌伸直手臂，将身体抬回到起始位置。', '重复所需的重复次数。'],
  'H3544': ['首先侧躺，双腿伸展并叠放在一起。', '将前臂放在肩膀正下方的地面上，肘部弯曲成 90 度角。', '启动你的核心并将臀部抬离地面，从头到脚形成一条直线。', '保持此位置所需的时间。', '将臀部放回到地面，然后在另一侧重复。'],
  'H1771': ['跪在地上，膝盖分开与臀部同宽。', '将双手放在身前的地面上，与肩同宽，手指指向前方。', '将双腿伸直在身后，用脚趾和双手保持平衡，从头到脚跟形成一条直线。', '弯曲肘部，将上半身向地面降低，保持肘部靠近身体两侧。', '在底部停顿片刻，然后双手用力伸直手臂，回到起始位置。', '重复所需的重复次数。'],
  'H1769': ['侧躺，双腿伸直，用手臂支撑头部。', '将上臂靠在身体两侧，弯曲肘部，将前臂卷向肩膀。', '在顶部暂停片刻，然后慢慢将前臂放回起始位置。', '重复所需的重复次数。'],
  'H3168': ['双脚分开与肩同宽站立，伸直手臂抓住坚固的物体或悬挂训练器。', '将身体降低至蹲姿，保持背部挺直，膝盖位于脚趾后面。', '从蹲姿开始，将身体向上拉向物体或悬挂训练器，将肩胛骨挤压在一起。', '在顶部停顿片刻，然后慢慢将身体放回起始位置。', '重复所需的重复次数。'],
  'H3167': ['双脚分开与肩同宽站立，手掌朝下，将毛巾放在身前。', '弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。', '当你下蹲时，同时将毛巾拉向胸部，将肩胛骨挤压在一起。', '在深蹲底部停顿片刻，然后慢慢回到起始位置，同时伸展双臂。', '重复所需的重复次数。'],
  'H3156': ['双脚分开与肩同宽站立，膝盖稍微弯曲，一只手握住哑铃，握姿中立。', '臀部向前弯曲，保持背部挺直，核心肌群参与。', '将哑铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换边。'],
  'H3158': ['站立，双脚分开与肩同宽，膝盖稍微弯曲。', '腰部向前弯曲，保持背部挺直，核心肌群参与。', '将双臂伸直在身前，紧紧抓住杆或手柄。', '将杠铃或手柄拉向身体，将肩胛骨挤压在一起。', '在动作的最高点停顿片刻，然后慢慢松开并回到起始位置。', '重复所需的重复次数。'],
  'H3162': ['双脚分开与肩同宽站立，膝盖稍微弯曲，一手握住哑铃。', '臀部向前弯曲，保持背部挺直，核心肌群参与。', '让哑铃垂直悬挂在您面前，手臂完全伸展。', '将哑铃向上拉向胸部，保持肘部靠近身体。', '在动作的最高点将肩胛骨挤压在一起。', '将哑铃放回起始位置。', '重复所需的重复次数，然后换边。'],
  'H3161': ['双脚分开与肩同宽站立，膝盖微曲，单手握住毛巾。', '臀部向前弯曲，保持背部挺直，核心肌群参与。', '将毛巾拉向胸部，将肩胛骨挤压在一起。', '在顶部停顿片刻，然后慢慢将毛巾放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H3166': ['站立，双脚分开与肩同宽，膝盖稍微弯曲。', '正手握住杆或手柄，手掌朝下。', '保持背部挺直，核心参与。', '将杠铃或手柄拉向身体，将肩胛骨挤压在一起。', '在动作的最高点停顿片刻。', '慢慢释放并伸展双臂回到起始位置。', '重复所需的重复次数。'],
  'H3165': ['双脚分开与肩同宽站立，双手握住毛巾放在身前。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '将毛巾拉向胸部，将肩胛骨挤压在一起。', '在最高点停顿片刻，然后慢慢释放张力，回到起始位置。', '重复所需的重复次数。'],
  'H0138': ['平躺，双腿伸展，双臂放在身体两侧。', '弯曲膝盖并将其靠近胸部，保持双脚离开地面。', '收紧腹肌，将臀部抬离地面，将膝盖靠近头部。', '在顶部暂停片刻，然后慢慢将臀部放回起始位置。', '重复所需的重复次数。'],
  'H1374': ['站在盒子或平台前，双脚分开与肩同宽。', '弯曲膝盖，跳到盒子上，一只脚轻轻落地，另一只脚悬在盒子边缘。', '将脚踩在盒子上，将自己稳定在盒子上，同时保持另一只脚离开地面。', '保持这个姿势几秒钟，锻炼小腿肌肉以保持平衡。', '将放在盒子上的脚慢慢放下，回到起始位置。', '用另一条腿重复该练习。'],
  'H2466': ['从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。', '启动你的核心并将右脚抬离地面，将右膝移向左肘。', '将右脚放回到起始位置，然后将左脚朝向右肘重复该动作。', '继续交替两侧，以受控的速度移动。', '保持臀部水平，避免臀部抬得太高或下垂得太低。', '在整个练习过程中保持稳定的呼吸模式。', '重复所需的重复次数。'],
  'H0870': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在身体两侧，掌心朝下。', '收紧腹肌，将双腿抬离地面，将膝盖靠近胸部。', '在动作的最高点，挤压腹肌并暂停片刻。', '慢慢地将双腿放回起始位置。', '重复所需的重复次数。'],
  'H1494': ['坐在地板上，双腿伸到身前。', '弯曲膝盖，将脚底并拢，让膝盖向两侧倾斜。', '用手抓住脚踝或脚。', '坐直并拉长脊柱。', '轻轻地将膝盖压向地板，感觉大腿内侧有拉伸感。', '保持这个姿势几个呼吸。', '要放松，请慢慢抬起膝盖并伸展双腿。'],
  'H0148': ['双脚分开与肩同宽站立，并用正手握住绳索机的手柄。', '将双手放在与肩同高的位置，手掌朝前。', '保持核心参与并保持背部挺直。', '向上并向前按下一个手柄，直到您的手臂完全伸展。', '在最高点暂停片刻，然后慢慢将手柄放回起始位置。', '用另一只手臂重复上述步骤。', '双臂交替进行所需的重复次数。'],
  'H0149': ['面对电缆机站立，双脚与肩同宽。', '右手握住电缆手柄，抬起手臂，使上臂与地面平行，肘部弯曲成 90 度角。', '保持上臂静止，前臂向后伸展，完全伸直手臂。', '暂停片刻，然后慢慢回到起始位置。', '用左臂重复此动作。', '继续交替手臂进行所需的重复次数。'],
  'H3235': ['调整缆绳机，使脚踝附件处于最低设置。', '面朝下躺在长凳上，双腿伸直，将脚踝固定装置固定在脚踝上。', '握住长凳的把手以保持稳定。', '保持上半身静止，呼气，弯曲膝盖，将双腿向臀肌方向卷起。', '在动作的最高点暂停片刻，挤压你的腿筋。', '吸气并慢慢降低双腿回到起始位置。', '重复所需的重复次数。'],
  'H0150': ['将电缆滑轮调整至较高位置并安装直杆。', '面向缆绳机坐着，双脚平放在地面上，膝盖稍微弯曲。', '正手握住杠铃，握距略宽于肩宽。', '稍微向后倾斜，挺胸，保持下背部轻微的拱形。', '将杠铃向下拉向胸部，用肘部引导并将肩胛骨挤压在一起。', '在动作底部暂停片刻，然后慢慢地将杠铃返回到起始位置。', '重复所需的重复次数。'],
  'H0151': ['将绳索机调整至胸部高度并安装手柄。', '背对机器站立，双脚与肩同宽。', '正手握住手柄并向前迈一步，以在电缆中产生张力。', '将双脚牢牢放在地面上并启动核心。', '弯曲肘部，将双手置于肩部水平，保持肘部呈 90 度角。', '向前推动手柄，将双臂完全伸展到身前。', '暂停片刻，然后慢慢扭转动作，将双手放回肩部水平。', '重复所需的重复次数。'],
  'H1630': ['将直杆连接到低滑轮电缆机上。', '面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。', '反手握住杠铃，双手与肩同宽。', '在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。', '呼气并将杠铃向上卷向肩膀，收缩二头肌。', '在动作的最高点暂停片刻，挤压你的二头肌。', '吸气，慢慢将杠铃放回起始位置，充分伸展双臂。', '重复所需的重复次数。'],
  'H1631': ['坐在长凳或椅子上，双脚平放在地板上，膝盖稍微弯曲。', '用手握住电缆手柄，并将肘部靠在大腿内侧。', '保持上臂静止，呼气并将电缆手柄向肩膀卷曲，同时收缩二头肌。', '在动作的最高点暂停片刻，然后吸气并慢慢将拉索手柄放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0153': ['将电缆手柄连接到电缆机器两侧与肩同高的位置。', '站在机器中间，双脚分开与肩同宽。', '正手握住手柄并后退以在电缆中产生张力。', '从臀部开始稍微向前倾，保持背部挺直，挺胸。', '将手柄向下拉并穿过身体，将肩胛骨挤压在一起。', '在动作底部暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H0154': ['将 D 形手柄连接到每根低滑轮电缆上，并站在电缆交叉机的中间。', '旋前抓住手柄（手掌朝下），向前迈出一步，双脚分开与肩同宽。', '稍微弯曲膝盖，腰部前倾，保持背部挺直，腹部收紧。', '双臂向两侧伸展，肘部稍微弯曲，呼气并将肩胛骨挤压在一起，同时以反向飞翔动作向后和向上拉动绳索。', '在收缩峰值时停顿片刻，然后吸气，慢慢回到起始位置。', '重复所需的重复次数。'],
  'H0155': ['将电缆滑轮调整至胸部高度。', '站在电缆机的中央，一只脚在另一只脚前面。', '手掌朝下抓住手柄，手臂向两侧伸展。', '向前迈出一步，保持手臂稍微弯曲。', '肘部稍微弯曲，双手并拢放在胸前。', '暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H0157': ['面对电缆机站立，双脚与肩同宽。', '弯曲臀部和膝盖，降低躯干，直到背部与地面平行。', '正手握住电缆手柄，保持手臂伸直，肩膀向后。', '调动臀肌和腿筋来抬起拉索手柄，伸展臀部并站直。', '在顶部暂停片刻，然后慢慢将缆索手柄放回起始位置。', '重复所需的重复次数。'],
  'H0158': ['将拉线机调整至下降位置。', '背对机器站立，双脚与肩同宽。', '握住手柄，手掌朝前，双臂在身前伸直。', '保持肘部轻微弯曲，以受控的动作向两侧张开双臂。', '在完全伸展位置停顿片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H1260': ['将拉线机调整至下降位置。', '背对机器站立，用一只手抓住手柄。', '将背部靠在下斜长凳上，手臂伸直在身前。', '弯曲肘部，将手柄向胸部方向降低，同时保持上臂静止。', '在底部暂停片刻，然后将手柄推回到起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1261': ['将拉线机调整至下降位置。', '坐在面向缆绳机的下降长凳上。', '正手握住手柄并将其置于胸部水平。', '将双脚平放在地面上，并将背部牢牢靠在长凳上。', '呼气并将手柄推离身体，充分伸展双臂。', '动作结束时暂停片刻，挤压胸部肌肉。', '吸气并慢慢地将手柄放回起始位置。', '重复所需的重复次数。'],
  'H0159': ['坐在面向缆绳机的下斜长凳上，双脚牢固地放在脚踏板上。', '用宽的正手握法抓住电缆附件，手掌朝下。', '稍微向后倾斜，保持背部挺直，核心肌群参与。', '将电缆拉向下胸部，将肩胛骨挤压在一起。', '在收缩的峰值处暂停片刻，然后慢慢地将电缆释放回起始位置。', '重复所需的重复次数。'],
  'H1632': ['面向缆绳机站立，双脚与肩同宽。', '用手握住电缆附件，手掌朝上，手臂完全伸展。', '保持上臂静止，呼气并通过收缩二头肌将电缆附件卷曲至肩膀。', '在动作的最高点暂停片刻，挤压你的二头肌。', '吸气并慢慢将电缆附件放回起始位置，充分伸展双臂。', '重复所需的重复次数。'],
  'H0160': ['坐在地板上，双腿伸直，背部挺直。', '将缆绳手柄连接到低滑轮上，并将缆绳机放在您身后。', '正手宽握握住手柄，手掌朝下。', '稍微向后倾斜，保持背部挺直，挺胸。', '将手柄拉向腰部，将肩胛骨挤压在一起。', '在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。', '重复所需的重复次数。'],
  'H0161': ['双脚分开与肩同宽站立，膝盖稍微弯曲。', '正手握住电缆手柄，手掌朝下，双臂在身前完全伸展。', '保持手臂伸直，将电缆手柄抬高至肩部水平。', '在顶部暂停片刻，然后慢慢将缆索手柄放回起始位置。', '重复所需的重复次数。'],
  'H0164': ['双脚分开与肩同宽站立，并用正手握住电缆手柄。', '保持背部挺直，核心肌群参与。', '将电缆手柄举到您面前，保持手臂伸直，手掌朝下。', '继续抬起，直到手臂与地板平行。', '在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。', '重复所需的重复次数。'],
  'H1722': ['将绳子连接到高滑轮上，背对机器站立。', '双手抓住绳子，并将双臂伸过头顶。', '保持肘部靠近头部，上臂保持静止。', '弯曲肘部，慢慢将绳子降低到头后。', '暂停片刻，然后将手臂伸回到起始位置。', '重复所需的重复次数。'],
  'H0167': ['将直杆连接到胸部高度的缆绳机上。', '跪在缆绳机前，用正握方式抓住杠铃，双手与肩同宽。', '坐在脚后跟上，保持背部挺直，核心肌群参与。', '将杠铃拉向上腹部，将肩胛骨挤压在一起。', '在动作的最高点暂停片刻，然后慢慢松开杠铃回到起始位置。', '重复所需的重复次数。'],
  'H0169': ['将长凳调整至 45 度倾斜。', '将电缆手柄连接到高滑轮上。', '坐在长凳上，面向电缆机，双脚平放在地面上。', '正手握住手柄，并将其拉至肩部高度。', '向前和向上推动手柄，直到手臂完全伸展。', '暂停片刻，然后慢慢将手柄放回起始位置。', '重复所需的重复次数。'],
  'H1318': ['以 45 度角设置一个上斜凳，并将绳索手柄连接到低滑轮上。', '坐在长凳上，面向电缆机，双脚平放在地板上，膝盖稍微弯曲。', '正手握住电缆手柄，并将双臂完全伸展到身前。', '从臀部开始向前倾，同时保持背部挺直，核心肌群参与。', '缩回肩胛骨并弯曲肘部，将电缆手柄拉向胸部。', '在动作的最高点挤压背部肌肉，然后慢慢伸展手臂回到起始位置。', '重复所需的重复次数。'],
  'H0170': ['以倾斜角度设置稳定球。', '将电缆手柄连接到电缆机的高滑轮上。', '背对机器坐在稳定球上，双脚牢牢踩在地面上。', '正手握住电缆手柄，手掌朝前。', '稍微向前倾，保持背部挺直，核心参与。', '控制动作，将手臂向两侧伸出，保持肘部轻微弯曲。', '继续这个动作，直到手臂与地面平行。', '暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H0172': ['将直杆连接到高滑轮电缆机上。', '背对机器站立，双脚与肩同宽。', '正手握住杠铃，双手距离略宽于肩宽。', '稍微向前倾并保持背部挺直。', '伸展肘部，将杠铃向下拉向大腿。', '在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。', '重复所需的重复次数。'],
  'H0174': ['面对电缆机站立，双脚与肩同宽。', '用双手握住电缆手柄，使其与胸部齐平，手掌朝下。', '启动你的核心并将你的躯干向右旋转，将电缆拉过你的身体。', '当你旋转时，转动后脚并让臀部自然旋转。', '充分伸展双臂，将绳索手柄翻转到肩膀上来完成动作。', '通过反向运动返回起始位置，将躯干旋转回中心。', '在另一侧重复该动作。', '继续交替进行所需的重复次数。'],
  'H0860': ['面向缆绳机站立，双脚与肩同宽。', '用右手握住电缆手柄并后退以在电缆中产生张力。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '保持上臂靠近身体，肘部弯曲成 90 度角。', '向后伸展前臂，完全伸直手臂。', '暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数，然后换边。'],
  'H3697': ['将绳索手柄连接到低电缆滑轮上，面向机器跪下。', '以中立握法（手掌相对）抓住绳子，并将双臂完全伸展到身前。', '保持背部挺直，核心收紧，通过收缩肩胛骨将绳子拉向身体。', '在动作结束时将肩胛骨挤压在一起并保持短暂的停顿。', '慢慢释放张力并回到起始位置。', '重复所需的重复次数。'],
  'H0176': ['将绳索手柄连接到高滑轮上，面向绳索机跪下。', '以中立握法（手掌相对）抓住绳子，并将双手放在头的两侧。', '在整个练习过程中，保持肘部靠近头部，上臂保持静止。', '通过收缩三头肌来伸展前臂，直到手臂完全伸展。', '暂停片刻，然后弯曲肘部慢慢回到起始位置。', '重复所需的重复次数。'],
  'H2330': ['坐在高位下拉机上，膝盖位于护垫下方。', '正手握住电缆杆，握距略宽于肩宽。', '稍微向后倾斜，挺胸，保持下背部轻微的拱形。', '将杠铃向下拉至上胸部，将肩胛骨挤压在一起。', '在动作底部暂停片刻，然后慢慢松开杠铃回到起始位置。', '重复所需的重复次数。'],
  'H0177': ['将绳索附件连接到电缆机的高位置。', '面向机器站立，双脚分开与肩同宽。', '正手握住绳子，手掌相对。', '保持背部挺直并稍微向后倾斜。', '将绳子向下拉向身体两侧，将肩胛骨挤压在一起。', '在动作的底部停顿片刻。', '慢慢释放张力，让绳子回到起始位置。', '重复所需的重复次数。'],
  'H2616': ['坐在电缆下拉机上，用正手抓住 V 形杆附件。', '调整护膝，使大腿固定在其下方。', '保持背部挺直并稍微向后倾斜。', '将 V 形杆向下拉至上胸部，同时保持肘部靠近身体。', '在动作底部挤压背部肌肉。', '慢慢地将 v 形杆返回到起始位置，然后重复所需的重复次数。'],
  'H0179': ['将手柄连接到缆绳机的低滑轮上，并选择合适的重量。', '站在机器中间，双脚分开与肩同宽，膝盖稍微弯曲。', '正手握住手柄，将手臂向两侧伸展，肘部保持轻微弯曲。', '保持控制，以扫过的动作缓慢地将手臂向前伸，交叉在身体前面。', '在运动的最高点暂停片刻，感受胸部肌肉的拉伸。', '反转动作，慢慢将手臂恢复到起始位置，始终保持胸部肌肉紧张。', '重复所需的重复次数。'],
  'H0180': ['坐在机器上，双脚平放在脚踏板上，膝盖稍微弯曲。', '正手握住手柄，手掌朝下。', '保持背部挺直，稍微向前倾斜，肘部保持轻微弯曲。', '将手柄拉向身体，将肩胛骨挤压在一起。', '在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。', '重复所需的重复次数。'],
  'H0184': ['将绳子连接到缆绳机上，并将滑轮设置在最高位置。', '躺在长凳上，头朝向电缆机。', '双手握住绳子，将双臂伸直至胸部上方。', '保持双臂伸直，在保持控制的同时慢慢将绳子放到脑后。', '在底部停顿片刻，然后慢慢将绳子拉回起始位置。', '重复所需的重复次数。'],
  'H0185': ['将手柄连接到电缆上，平放在长凳上，双脚平放在地面上。', '手掌相对，握住手柄，双臂伸直至胸部上方。', '保持肘部轻微弯曲，将手臂以宽弧线向两侧放低，直到感觉到胸部有拉伸感。', '暂停片刻，然后挤压胸部肌肉，使手臂回到起始位置。', '重复所需的重复次数。'],
  'H0186': ['将绳索手柄连接到低滑轮电缆机器上。', '面朝上躺在平坦的长凳上，头朝向电缆机。', '双手抓住绳柄，掌心相对，将双臂伸直至胸前。', '保持上臂静止，弯曲肘部，慢慢将绳索手柄放低至前额。', '在底部停顿片刻，然后将手臂伸回起始位置。', '重复所需的重复次数。'],
  'H0188': ['将电缆连接到电缆机两侧胸部高度处。', '站在机器的中央，一只脚稍微在另一只脚前面。', '正手握住手柄，并将手臂向两侧伸展。', '保持肘部轻微弯曲并保持轻微前倾。', '收紧胸部肌肉，并以扫过的动作将手臂向前伸。', '在中心停顿片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H0189': ['面向缆绳机站立，双脚与肩同宽。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '用一只手抓住电缆手柄，手掌朝内，然后完全伸展手臂。', '将电缆手柄拉向身体，保持肘部靠近身体一侧，直到手到达下胸部。', '暂停片刻，然后慢慢将手臂伸回起始位置。', '重复所需的重复次数，然后换边。'],
  'H0190': ['面对电缆机站立，双脚与肩同宽。', '反手握住电缆手柄，手掌朝上。', '保持肘部靠近身体两侧，慢慢地将前臂向上卷向肩膀。', '在顶部暂停片刻，然后慢慢将前臂放回起始位置。', '重复所需的重复次数。'],
  'H1262': ['将 D 形手柄连接到低滑轮绳索机器上，并将长凳设置为下降角度。', '躺在长凳上，头朝向机器，用右手抓住手柄。', '将手臂伸直至胸部上方，保持肘部轻微弯曲。', '控制动作，将手臂向一侧放低，直到手与肩膀在一条直线上。', '暂停片刻，然后反转动作并将手臂恢复到起始位置。', '重复所需的重复次数，然后切换到左臂并重复练习。'],
  'H1263': ['坐在健身球上，双脚平放在地上，背部挺直。', '一只手握住电缆手柄，并将手臂向一侧伸出，与地面平行。', '保持肘部稍微弯曲，手掌朝前。', '慢慢地将手臂放在身体上，挤压胸部肌肉。', '动作结束时暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数，然后换边。'],
  'H1264': ['坐在健身球上，双脚平放在地面上，背部靠在倾斜的长凳上。', '一只手握住电缆手柄，手臂伸展，手掌朝内。', '保持肘部轻微弯曲，慢慢地将手臂向一侧放低，直到手与肩膀在一条直线上。', '暂停片刻，然后挤压胸部肌肉，使手臂回到起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1265': ['将拉索机调整至低滑轮位置。', '坐在倾斜的长凳上，背对缆绳机。', '用一只手抓住手柄并将其举至肩膀高度。', '将双脚牢牢放在地面上并保持稳定的位置。', '向前和向上按下手柄，充分伸展手臂。', '在最高点暂停片刻，然后慢慢将手柄放回起始位置。', '重复所需的重复次数，然后换边。'],
  'H1266': ['坐在健身球上，双脚平放在地上，背部靠在倾斜的长凳上。', '一只手握住电缆手柄，将手臂呈 90 度角，肘部弯曲。', '向前和向上按下电缆手柄，完全伸展手臂。', '在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0191': ['双脚分开与肩同宽站立，面向缆绳机。', '用一只手抓住手柄并向后退一步以在电缆上产生张力。', '腰部向前弯曲，保持背部挺直，核心肌群参与。', '将手臂向侧面伸展，与地面平行，肘部稍微弯曲。', '慢慢地将手臂放回起始位置，在整个运动过程中保持控制。', '重复所需的重复次数，然后换边。'],
  'H0192': ['双脚分开与肩同宽站立，面向绳索机。', '用一只手握住电缆手柄，手掌朝下，站得离机器足够远，以便电缆上有张力。', '保持手臂伸直，慢慢向一侧举起，直到与地面平行。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数，然后换边。'],
  'H1633': ['调整绳索机，使牧师弯举垫处于胸部高度。', '面对电缆机站立，双脚与肩同宽。', '用手握住电缆手柄，并将上臂靠在牧师弯举垫上。', '保持背部挺直，核心肌群参与。', '慢慢地将电缆手柄卷向肩膀，保持上臂靠在垫子上。', '在动作的最高点暂停片刻，挤压你的二头肌。', '慢慢地将电缆手柄放回起始位置。', '重复所需的重复次数。', '交换手臂并重复练习。'],
  'H1267': ['坐在健身球上，双脚平放在地上，背部挺直。', '一只手握住电缆手柄，将手臂置于胸部高度，肘部弯曲。', '将另一只手放在臀部上以保持稳定。', '向前按电缆手柄，完全伸展手臂。', '暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数，然后换臂。'],
  'H3563': ['将单个手柄连接到高滑轮电缆机上。', '面向机器站立，双脚分开与肩同宽。', '正手握住手柄并完全伸展手臂。', '保持背部挺直，核心肌群参与。', '将手柄向一侧拉，同时保持肘部靠近身体。', '在动作底部暂停片刻，挤压背阔肌。', '慢慢松开手柄回到起始位置。', '重复所需的重复次数。', '换边并用另一只手臂重复练习。'],
  'H1635': ['调整拉索机，使滑轮处于最低位置。', '面对电缆机站立，双脚与肩同宽。', '用反手抓住电缆手柄，并将上臂靠在牧师凳垫上。', '在整个练习过程中保持背部挺直，核心肌群参与其中。', '慢慢地将前臂向二头肌方向卷曲，保持上臂固定在垫子上。', '在动作的最高点暂停片刻，挤压你的二头肌。', '慢慢地将电缆手柄放回起始位置。', '重复所需的重复次数。', '交换手臂并重复练习。'],
  'H0193': ['将手柄连接到腰部高度的缆绳机上。', '面向电缆机跪下，用一只手抓住手柄。', '保持背部挺直，核心肌群参与。', '将手柄拉向胸部，将肩胛骨挤压在一起。', '在动作的最高点停顿片刻。', '慢慢松开手柄回到起始位置。', '重复所需的重复次数。', '换边并用另一只手臂重复练习。'],
  'H1723': ['面向缆绳机站立，并在胸部高度处安装直杆附件。', '正手握住杠铃，然后后退以在绳索上产生张力。', '将双脚分开与肩同宽，并稍微弯曲膝盖。', '在整个练习过程中保持背部挺直并保持核心参与。', '首先，手臂完全伸展并垂直于地板。', '保持上臂静止，呼气并将杠铃向下推，直到手臂完全伸展。', '暂停片刻，然后吸气，慢慢回到起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1636': ['将直杆连接到高滑轮电缆机上。', '面向机器站立，双脚分开与肩同宽。', '反手握住杠铃，双手与肩同宽。', '保持肘部靠近身体两侧，上臂保持静止。', '呼气并将杠铃向下卷向前额，保持上臂静止。', '在动作底部暂停片刻，挤压二头肌。', '吸气，慢慢地将杠铃返回到起始位置，充分伸展双臂。', '重复所需的重复次数。'],
  'H1637': ['坐在健身球上，用反手握住电缆手柄。', '将手臂完全伸过头顶，保持肘部靠近耳朵。', '慢慢地将电缆朝前额卷曲，保持上臂静止。', '在动作底部暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H1319': ['将手柄连接到腰部高度的缆绳机上。', '面向机器站立，双脚分开与肩同宽。', '正手握住手柄，手掌朝下。', '向后退一步，在绳索上产生张力，保持背部挺直，膝盖稍微弯曲。', '将手柄拉向身体，同时将手掌旋转至向上。', '在动作结束时将肩胛骨挤压在一起。', '慢慢松开手柄回到起始位置。', '重复所需的重复次数。'],
  'H1268': ['坐在健身球上，双脚平放在地上，膝盖呈 90 度角。', '将电缆手柄保持在胸部高度，手掌朝下，肘部弯曲。', '收紧核心并向前按压缆索手柄，直到手臂完全伸展。', '暂停片刻，然后慢慢释放张力，并将电缆手柄拉回起始位置。', '重复所需的重复次数。'],
  'H0197': ['调整座椅高度，使大腿与地面平行，双脚平放在地板上。', '正手握住背阔肌杠铃，握距略宽于肩宽。', '坐下来，稍微向后倾斜，保持挺胸、背部挺直。', '将杠铃向下拉向胸部，将肩胛骨挤压在一起。', '在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。', '重复所需的重复次数。'],
  'H1638': ['在最高设置下将直杆连接到电缆机上。', '面向机器站立，双脚分开与肩同宽。', '反手握住杠铃，双手与肩同宽。', '保持肘部靠近身体两侧，上臂保持静止。', '呼气，慢慢将杠铃向大腿方向卷曲，保持手腕伸直。', '在动作底部暂停片刻，挤压二头肌。', '吸气，慢慢地将杠铃返回到起始位置，充分伸展双臂。', '重复所需的重复次数。'],
  'H0199': ['将直杆连接到高滑轮电缆机上。', '面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。', '正手握住杠铃，保持手臂伸直，手掌朝下。', '呼气时，收紧核心并保持背部挺直，并将杠铃向下推向大腿。', '在底部暂停片刻，然后一边吸气，一边慢慢地将杠铃返回到起始位置。', '重复所需的重复次数。'],
  'H0200': ['将绳索附件连接到缆绳机上的高滑轮上。', '面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。', '正手握住绳子，手掌相对。', '在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。', '呼气并伸展肘部将绳子向下推，直到手臂完全伸展。', '暂停片刻，然后吸气，并让肘部弯曲，慢慢回到起始位置。', '重复所需的重复次数。'],
  'H0202': ['将马镫手柄连接到低电缆滑轮上，面向机器站立。', '左手抓住手柄，右脚后退一步，身体保持一个轻微的角度。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。', '左臂伸展，手掌朝下，通过缩回肩胛骨将手柄拉向胸部。', '在动作的最高点暂停片刻，挤压肩胛骨。', '慢慢地将手柄释放回起始位置，然后重复所需的重复次数。', '换边并用右臂重复练习。'],
  'H0203': ['将绳索手柄连接到低滑轮电缆机器上。', '面向机器站立，双脚分开与肩同宽。', '正手握住绳索手柄，手掌相对。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '保持肘部稍微弯曲，将绳子拉向胸部，将肩胛骨挤压在一起。', '在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。', '重复所需的重复次数。'],
  'H0204': ['将手柄连接到低滑轮电缆机器上，并背对机器站立。', '正手握住手柄，并将双臂伸直至身前。', '保持肘部不动，将手柄拉回身体，在动作结束时挤压三头肌。', '慢慢地将手柄返回到起始位置，然后重复所需的重复次数。'],
  'H0205': ['调整拉索机，使滑轮处于最高位置。', '面向机器坐着，双脚平放在地面上，膝盖稍微弯曲。', '正手握住电缆附件，双手之间的距离略大于肩宽。', '稍微向后倾斜，保持背部挺直，挺胸。', '将电缆附件向下拉向胸部，将肩胛骨挤压在一起。', '在动作底部停顿片刻，然后慢慢松开绳索回到起始位置。', '重复所需的重复次数。'],
  'H0873': ['将电缆连接到低滑轮上，然后面朝上躺在垫子上。', '用双手握住电缆，并将双臂伸向天花板。', '弯曲膝盖并抬起双腿，使大腿靠近胸部。', '在保持上半身稳定的同时，将骨盆向胸部弯曲，将臀部抬离垫子。', '在顶部暂停片刻，然后慢慢将臀部放回起始位置。', '重复所需的重复次数。'],
  'H0206': ['将直杆连接到低滑轮电缆机上。', '面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。', '反手握住杠铃，双手与肩同宽。', '在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。', '呼气并将杠铃向上卷向肩膀，收缩二头肌。', '在顶部暂停片刻，挤压你的二头肌。', '吸气，慢慢将杠铃放回起始位置，充分伸展双臂。', '重复所需的重复次数。'],
  'H2406': ['在最高设置下将直杆连接到电缆机上。', '面对电缆机站立，双脚与肩同宽。', '反手握住杠铃，手掌朝上，双手与肩同宽。', '在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。', '启动你的三头肌，慢慢地向下推杠铃，直到你的手臂完全伸展。', '在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。', '重复所需的重复次数。'],
  'H1413': ['面向缆绳机站立，双脚与肩同宽。', '反手握住电缆手柄，手掌朝下。', '保持肘部靠近身体两侧，慢慢地将前臂向上卷向肩膀。', '在顶部暂停片刻，然后慢慢将前臂放回起始位置。', '重复所需的重复次数。'],
  'H0209': ['调整绳索机，使牧师弯举垫处于胸部高度。', '坐在牧师弯举凳上，将上臂放在垫子上，手掌朝下，肘部完全伸展。', '反手抓住电缆手柄，距离与肩同宽。', '保持上臂静止，呼气并将手柄向肩膀卷曲，收缩二头肌。', '在动作的最高点暂停片刻，挤压你的二头肌。', '吸气，慢慢将手柄放回起始位置，充分伸展肘部。', '重复所需的重复次数。'],
  'H0210': ['将电缆连接到低滑轮上，然后坐在面向电缆机的长凳上。', '正手握住电缆手柄，手掌朝下。', '将前臂放在大腿上，手腕悬在边缘上。', '保持前臂静止，呼气并尽可能向上弯曲手腕。', '在顶部暂停片刻，然后吸气并慢慢将手腕放回起始位置。', '重复所需的重复次数。'],
  'H0207': ['将直杆连接到高滑轮电缆机上。', '面向机器站立，双脚分开与肩同宽。', '反手握住杠铃，手掌朝上，双手与肩同宽。', '在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。', '使用三头肌，将杠铃向下推，直到手臂完全伸展并且三头肌收缩。', '暂停片刻，然后慢慢地将杠铃返回到起始位置。', '重复所需的重复次数。'],
  'H0208': ['坐在面向电缆机的座位上，双脚平放在地板上。', '用手握住电缆附件，手掌朝上，双手与肩同宽。', '保持背部挺直，并从臀部稍微向前倾斜。', '通过缩回肩胛骨并挤压背部肌肉，将电缆拉向躯干。', '在收缩的峰值处暂停片刻，然后慢慢地将电缆释放回起始位置。', '重复所需的重复次数。'],
  'H1320': ['坐在划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。', '正手握住缆绳，手掌相对。', '稍微向后倾斜，保持背部挺直，核心肌群参与。', '将缆绳拉向胸部，将肩胛骨挤压在一起。', '在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。', '重复所需的重复次数。'],
  'H1321': ['坐在面向电缆机的高架座椅上。', '正手握住缆绳手柄，手掌相对。', '保持背部挺直并稍微向后倾斜，保持膝盖轻微弯曲。', '通过缩回肩胛骨并挤压背部肌肉，将电缆拉向您的身体。', '在完全收缩的位置暂停片刻。', '慢慢释放压力并将手臂伸回到起始位置。', '重复所需的重复次数。'],
  'H1322': ['以 45 度角设置上斜凳，并将绳索机连接到低滑轮上。', '将绳索手柄连接到缆绳机上，然后坐在面向机器的倾斜长凳上。', '正手抓住绳索把手，身体前倾，保持背部挺直。', '充分伸展双臂，将绳子拉向上胸部，同时保持肘部靠近身体。', '在动作结束时将肩胛骨挤压在一起。', '慢慢释放张力并回到起始位置。', '重复所需的重复次数。'],
  'H1639': ['将绳索附件连接到低滑轮缆绳机上。', '面向机器站立，双脚分开与肩同宽。', '以中立握法（手掌相对）抓住绳子。', '将上臂靠在牧师凳垫上，保持肘部稍微弯曲。', '保持上臂静止，呼气并通过收缩二头肌将绳子卷向肩膀。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气，慢慢将绳子放回起始位置。', '重复所需的重复次数。'],
  'H1724': ['将绳子连接到高滑轮上并相应地调整重量。', '背对滑轮机站立，双脚与肩同宽。', '双手抓住绳子，掌心朝下，双手举过头顶。', '保持上臂靠近头部并垂直于地板。', '弯曲肘部，慢慢将绳子降低到头后。', '暂停片刻，然后将手臂伸回到起始位置。', '重复所需的重复次数。'],
  'H1725': ['将绳子连接到高滑轮上，并将倾斜长凳调整到舒适的角度。', '背对滑轮站立，双脚与肩同宽。', '正手抓住绳子，并将双臂伸直过头顶。', '在整个练习过程中，保持肘部靠近头部，上臂保持静止。', '弯曲肘部，直到前臂接触二头肌，将绳子降低到头后。', '暂停片刻，然后将手臂伸回到起始位置。', '重复所需的重复次数。'],
  'H1726': ['将绳子连接到缆绳机上并将其设置到最低位置。', '面朝上躺在地板上，头朝向电缆机。', '双手握住绳子，掌心相对，双臂伸直向上伸向天花板。', '保持上臂静止，慢慢地将绳子放低到前额，弯曲肘部。', '暂停片刻，然后将手臂伸回到起始位置。', '重复所需的重复次数。'],
  'H1640': ['将绳索手柄连接到低滑轮电缆机器上。', '面向机器站立，双脚分开与肩同宽。', '反手握住绳索手柄，手掌朝上。', '将上臂靠在牧师凳垫上，保持肘部稍微弯曲。', '在整个练习过程中保持背部挺直，核心肌群参与其中。', '慢慢地将绳索手柄卷向肩膀，保持上臂静止。', '在动作的最高点挤压二头肌，然后慢慢将绳柄放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1323': ['坐在划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。', '正手握住缆绳，手掌相对。', '保持背部挺直，稍微向前倾斜，肘部保持轻微弯曲。', '将缆绳拉向身体，将肩胛骨挤压在一起。', '在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。', '重复所需的重复次数。'],
  'H0211': ['坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。', '双手握住电缆手柄，并将双臂伸直至前方。', '稍微向后倾斜，同时保持背部挺直并且核心参与。', '将躯干向右扭转，将电缆手柄拉向右臀部。', '暂停片刻，然后将躯干向左扭转，将电缆手柄拉向左臀部。', '继续交替扭转所需的重复次数。'],
  'H2144': ['将座椅高度和电缆手柄调整至舒适的位置。', '坐在长凳上，背部挺直，双脚平放在地板上。', '正手握住电缆手柄，与肩同高。', '向前推动手柄并使其远离身体，充分伸展双臂。', '暂停片刻，然后慢慢将手柄放回起始位置。', '重复所需的重复次数。'],
  'H0212': ['坐在缆绳机上，双脚平放在地面上，膝盖弯曲。', '用双手握住电缆手柄并将其放在脑后。', '收紧腹肌，慢慢向前弯曲上半身，使胸部靠近膝盖。', '在顶部停顿片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H1641': ['坐在缆绳机上，双脚平放在地面上，背部挺直。', '反手抓住电缆附件，手掌朝上，双臂完全伸展。', '保持上臂静止，呼气并将电缆附件卷向肩膀，收缩二头肌。', '在动作的最高点暂停片刻，挤压你的二头肌。', '吸气并慢慢将电缆附件放回起始位置，充分伸展双臂。', '重复所需的重复次数。'],
  'H0213': ['坐在缆绳机上，双脚平放在地板上，膝盖稍微弯曲。', '正手握住 V 形杆附件，手掌相对，双手与肩同宽。', '保持背部挺直，并从臀部稍微向前倾斜。', '通过收缩肩胛骨并挤压背部肌肉，将 V 形杆拉向躯干。', '在收缩的顶峰停顿片刻，然后慢慢释放张力，回到起始位置。', '重复所需的重复次数。'],
  'H0214': ['坐在长凳上，面对缆绳机，双脚平放在地面上，膝盖稍微弯曲。', '用一只手抓住手柄，并将手臂完全伸展到身前。', '将手柄拉向身体，缩回肩胛骨并保持肘部靠近身体两侧。', '在动作的最高点暂停片刻，挤压背部肌肉。', '慢慢松开手柄回到起始位置。', '用另一只手臂重复上述步骤。', '双臂交替进行所需的重复次数。'],
  'H1642': ['坐在长凳上，双脚平放在地板上，背部挺直。', '用一只手握住电缆手柄，并将肘部放在大腿内侧、膝盖上方。', '呼气时，保持上臂静止并将电缆手柄向肩膀卷曲。', '在动作的最高点暂停片刻，挤压你的二头肌。', '吸气时慢慢将电缆手柄放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1643': ['坐在长凳上，面向电缆机，双脚平放在地面上。', '用手握住电缆附件，手掌朝上，双手与肩同宽。', '保持上臂不动，肘部靠近身体两侧。', '呼气并将电缆附件卷向肩膀，收缩二头肌。', '在动作的最高点暂停片刻，挤压你的二头肌。', '吸气并慢慢将电缆附件放回起始位置，充分伸展双臂。', '重复所需的重复次数。'],
  'H0215': ['坐在长凳上，面向电缆机，双脚平放在地面上。', '正手握住电缆手柄，并将双臂伸直至前方。', '保持手臂伸直，慢慢向两侧举起，直到与地板平行。', '在顶部停顿片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H0216': ['坐在长凳或椅子上，面向电缆机，双脚平放在地面上。', '握住电缆手柄，手臂在身前伸直，与地面平行。', '保持肘部稍微弯曲，肩胛骨向后和向下拉。', '慢慢向内旋转手臂，将电缆手柄拉向身体中心。', '动作结束时暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数，然后换臂。'],
  'H2399': ['坐在缆绳机上，双脚平放在地面上，膝盖稍微弯曲。', '双手握住电缆手柄，并将双臂伸直至身前。', '保持核心参与，慢慢地将躯干旋转到一侧，将电缆拉过身体。', '在动作范围结束时暂停片刻，然后慢慢旋转回到起始位置。', '在另一侧重复。', '继续交替进行所需的重复次数。'],
  'H0218': ['坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。', '正手宽握握住手柄，手掌朝下。', '保持背部挺直，并从臀部稍微向前倾斜。', '将手柄拉向下胸部，将肩胛骨挤压在一起。', '在收缩高峰时暂停片刻。', '慢慢松开手柄回到起始位置，充分伸展双臂。', '重复所需的重复次数。'],
  'H0219': ['调整绳索机，使手柄位于肩部高度。', '背对机器站立，双脚与肩同宽。', '正手握住手柄，将其提升至肩部水平，肘部弯曲并指向外侧。', '向上按压手柄，直到手臂完全伸过头顶。', '在顶部暂停片刻，然后慢慢将手柄放回至肩部水平。', '重复所需的重复次数。'],
  'H0222': ['双脚分开与肩同宽站立，用一只手抓住电缆手柄。', '保持背部挺直，核心肌群参与。', '腰部慢慢向侧面弯曲，将电缆手柄向膝盖方向降低。', '暂停片刻，然后回到起始位置。', '在另一侧重复。', '交替进行所需的重复次数。'],
  'H0221': ['双脚分开与肩同宽站立，一只手握住电缆手柄。', '将另一只手放在臀部上。', '启动你的核心，慢慢向握住电缆的手侧弯，保持背部挺直。', '在动作底部暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数，然后换边。'],
  'H0223': ['将电缆手柄连接到低滑轮上并站在机器旁边。', '用距离机器最远的手抓住手柄，并将另一只手放在臀部上。', '双脚分开与肩同宽，膝盖稍微弯曲。', '收紧腹肌，腰部向侧面弯曲，将肘部向下拉向臀部。', '在底部停顿片刻，然后慢慢回到起始位置。', '重复所需的重复次数，然后换边。'],
  'H1717': ['将绳子连接到腰部高度的缆绳机上。', '面对电缆机站立，双脚与肩同宽。', '弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。', '正手握住绳子，双手与肩同宽。', '收紧核心并将绳子拉向身体，将肩胛骨挤压在一起。', '保持肘部靠近身体并继续拉，直到双手到达胸部。', '在动作的最高点停顿片刻，然后慢慢松开绳子，并将手臂伸回到起始位置。', '重复所需的重复次数。'],
  'H1644': ['将电缆手柄连接到电缆机器上的最低设置。', '面向机器站立，双脚分开与肩同宽。', '反手握住电缆手柄，手掌朝上，手臂完全伸展。', '将身体降低至蹲姿，保持背部挺直，膝盖位于脚趾后面。', '当你蹲下时，将电缆手柄卷向肩膀，保持肘部靠近身体两侧。', '在弯举的顶部暂停片刻，挤压二头肌。', '慢慢地将电缆手柄放回起始位置，完全伸展双臂。', '重复所需的重复次数。'],
  'H0224': ['面向缆绳机站立，双脚与肩同宽。', '正手握住电缆手柄，手掌朝下。', '保持手臂伸直，肘部靠近身体两侧。', '慢慢向上弯曲手腕，将电缆手柄拉向身体。', '在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。', '重复所需的重复次数。'],
  'H1375': ['面向缆绳机站立，双脚与肩同宽。', '握住电缆机手柄或将电缆脚踝带固定在脚踝上。', '尽可能高地伸展脚踝，将脚后跟抬离地面。', '在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H0225': ['将 D 形手柄安装到缆绳机两侧与肩同高的位置。', '站在缆绳机的中间，双脚分开与肩同宽。', '正手握住手柄，并将手臂向两侧伸展，手掌朝前。', '在整个练习过程中保持肘部轻微弯曲并保持背部挺直。', '当您将手柄拉向身体前方时，收紧肩部肌肉并将肩胛骨挤压在一起。', '在动作的最高点停顿片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H0226': ['将电缆手柄连接到高滑轮上，并背对机器站立。', '双手握住手柄并将其放在脑后，保持肘部弯曲。', '双脚分开与肩同宽站立，膝盖稍微弯曲。', '保持腹肌收紧，呼气，将躯干压向膝盖，将肘部拉向大腿。', '在动作底部暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H0874': ['将一根绳子连接到胸部高度的缆绳机上。', '背对机器站立，双脚与肩同宽。', '双手握住绳子并将其放在脑后，保持肘部弯曲。', '收紧腹肌，慢慢向前挤压躯干，使肘部靠近膝盖。', '在卷腹的最高点暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H0227': ['将手柄连接到胸部高度的电缆上。', '双脚分开与肩同宽站立，背对缆绳机。', '正手握住手柄，手掌朝前。', '稍微向前一步以在缆绳中产生张力。', '在整个练习过程中保持核心参与并保持背部挺直。', '肘部稍微弯曲，慢慢地将双臂向前并拢在胸前。', '在运动的最高点挤压胸部肌肉。', '慢慢扭转动作，将手臂恢复到起始位置。', '重复所需的重复次数。'],
  'H0229': ['面向缆绳机站立，双脚与肩同宽。', '反手握住电缆手柄，手掌朝上。', '保持肘部靠近身体两侧，上臂保持静止。', '呼气并将绳索手柄卷向肩膀，收缩二头肌。', '在动作的最高点暂停片刻，挤压你的二头肌。', '吸气并缓慢地将电缆手柄放回起始位置。', '重复所需的重复次数。'],
  'H0230': ['面对电缆机站立，双脚与肩同宽。', '双手握住电缆手柄并将其置于腰部高度。', '在整个练习过程中启动核心并保持背部挺直。', '保持手臂伸直，呼气并将电缆手柄向另一侧的肩膀向上提起，同时旋转躯干。', '在顶部暂停片刻，然后吸气并慢慢将拉索手柄放回起始位置。', '重复所需的重复次数，然后换边。'],
  'H0231': ['双脚分开与肩同宽站立，面向绳索机。', '用右手握住电缆手柄，掌心朝下，调整手臂位置，使其完全伸展并与地面平行。', '保持肘部静止并靠近身体。', '慢慢弯曲肘部，将电缆手柄向脑后降低。', '在动作底部停顿片刻，然后将手臂伸回起始位置。', '重复所需的重复次数，然后换边并用左臂进行练习。'],
  'H1376': ['面向缆绳机站立，双脚与肩同宽。', '抓住电缆机以获得支撑。', '将一条腿抬离地面并用另一条腿保持平衡。', '慢慢地将脚跟抬离地面，将身体抬起到脚趾上。', '在顶部暂停片刻，然后慢慢将脚跟放回起始位置。', '重复所需的重复次数，然后换腿。'],
  'H0232': ['将绳索连接到最高设置的缆绳机上。', '面向机器站立，双脚分开与肩同宽。', '正手握住绳子，手掌朝下。', '在整个练习过程中保持背部挺直并保持核心参与。', '将绳子向下拉向大腿，挤压二头肌。', '在底部停顿片刻，然后慢慢地将绳子放回原位。', '重复所需的重复次数。'],
  'H0233': ['面向缆绳机站立，双脚与肩同宽。', '用双手握住电缆附件，手掌相对，然后后退以在电缆中产生张力。', '保持背部挺直，核心肌群参与。', '将电缆拉向您的身体，将肩胛骨挤压在一起。', '在运动的最高点停顿片刻，然后慢慢松开绳索回到起始位置。', '重复所需的重复次数。'],
  'H1727': ['背对缆绳机站立，双脚与肩同宽。', '用手握住电缆手柄，并将手臂伸过头顶，保持肘部靠近头部。', '保持上臂静止，弯曲肘部，慢慢将电缆手柄降低到脑后。', '在底部停顿片刻，然后将手臂伸回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0234': ['面对电缆机站立，双脚与肩同宽。', '正手握住 V 形杆附件，手掌朝下。', '保持背部挺直，核心肌群参与。', '将 V 形杆拉向身体，将肩胛骨挤压在一起。', '在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。', '重复所需的重复次数。'],
  'H0235': ['双脚分开与肩同宽站立，膝盖稍微弯曲。', '将手臂伸向前方，与地面平行，握住电缆手柄。', '保持肘部稍微弯曲，肩胛骨向后拉。', '慢慢地向外旋转手臂，远离身体，同时保持肘部处于同一位置。', '动作结束时暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H0236': ['将 V 形杆附件连接到胸部高度的缆绳机上。', '面对电缆机站立，双脚与肩同宽。', '正手握住 V 形杆，手掌朝下。', '后退一步以在电缆中产生张力。', '在整个练习过程中保持背部挺直并保持核心参与。', '缩回肩胛骨并弯曲肘部，将 V 形杆拉向躯干。', '当你拉的时候，将你的躯干扭转到一侧，将肩胛骨挤压在一起。', '在动作的最高点暂停片刻，感受上背部的收缩。', '慢慢释放紧张并回到起始位置，松开躯干。', '重复该动作达到所需的重复次数，每次重复交替扭转方向。'],
  'H1269': ['站在缆绳机中间，双脚分开与肩同宽。', '手掌朝下握住电缆手柄，手臂伸直至两侧。', '保持双臂伸直，将双手放在身体前面，相互交叉。', '暂停片刻，然后慢慢回到起始位置，保持双臂伸展。', '重复所需的重复次数。'],
  'H0238': ['将直杆连接到缆绳机的高滑轮上。', '面向机器站立，双脚分开与肩同宽。', '正手握住杠铃，保持手臂伸直，手掌朝下。', '收紧背阔肌并将杠铃向下拉向大腿，在整个运动过程中保持手臂伸直。', '在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。', '重复所需的重复次数。'],
  'H0237': ['将绳索连接到最高设置的缆绳机上。', '面向机器站立，双脚分开与肩同宽。', '双手抓住绳子，掌心朝下。', '将手臂完全伸展到身前，保持肘部稍微弯曲。', '收紧背阔肌，慢慢地将绳子向下拉向大腿，保持手臂伸直。', '在底部停顿片刻，然后慢慢释放张力，回到起始位置。', '重复所需的重复次数。'],
  'H0239': ['坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。', '正手握住电缆手柄，手掌朝下。', '保持背部挺直，并从臀部稍微向前倾斜。', '将电缆手柄拉向身体，将肩胛骨挤压在一起。', '在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。', '重复所需的重复次数。'],
  'H0240': ['将 D 形手柄连接到低滑轮缆绳机上，并面朝下躺在平凳上。', '每只手握住 D 形手柄，手掌朝下，并将双臂伸直至前方。', '保持手臂伸直，将它们向两侧举起，直到与地板平行。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H2464': ['将电缆手柄连接到低滑轮上，面向机器坐着，双脚平放在地板上。', '用右手抓住手柄，完全伸展手臂，保持肘部轻微弯曲。', '从臀部开始向前倾斜，保持背部挺直并收紧腹肌。', '缩回肩胛骨并弯曲肘部，将手柄拉向躯干，保持手臂靠近身体。', '在动作的最高点挤压背部肌肉，然后慢慢回到起始位置。', '重复所需的重复次数，然后换边并用左臂执行。'],
  'H0241': ['在最高设置下将 V 形杆附件连接到电缆机上。', '面对电缆机站立，双脚与肩同宽。', '正手握住 V 形杆，手掌朝下，双手与肩同宽。', '在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。', '收紧三头肌并呼气，同时向下推 V 形杆，直到手臂完全伸展。', '在动作的底部暂停片刻，挤压你的三头肌。', '吸气，同时缓慢地将 V 形杆返回到起始位置，保持控制。', '重复所需的重复次数。'],
  'H2405': ['在最高设置下将 V 形杆附件连接到电缆机上。', '面对电缆机站立，双脚与肩同宽。', '正手握住 V 形杆，手掌朝下，双手与肩同宽。', '在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。', '收紧三头肌并呼气，同时向下推 V 形杆，直到手臂完全伸展。', '在动作的底部暂停片刻，挤压你的三头肌。', '吸气，同时缓慢地将 V 形杆返回到起始位置，保持控制。', '重复所需的重复次数。'],
  'H0242': ['将电缆连接到低滑轮上，然后面朝上躺在垫子上。', '用双手握住电缆并将双臂伸直至胸部上方。', '弯曲膝盖并抬起双腿，使膝盖靠近胸部。', '同时，将骨盆向胸部弯曲，将臀部抬离地面。', '在顶部暂停片刻，然后慢慢降低双腿和臀部回到起始位置。', '重复所需的重复次数。'],
  'H0243': ['双脚分开与肩同宽站立，面向绳索机。', '双手握住电缆手柄于胸前，保持双臂略微弯曲。', '启动你的核心并将你的躯干向右扭转，将电缆拉过你的身体。', '动作结束时暂停片刻，感受腹肌和斜肌的收缩。', '缓慢返回起始位置，抵抗绳索的拉力。', '向左侧重复该动作。', '继续交替进行所需的重复次数。'],
  'H0862': ['双脚分开与肩同宽站立，面向绳索机。', '双手握住电缆手柄于胸前，保持双臂略微弯曲。', '启动你的核心并慢慢地将你的躯干旋转到一侧，保持你的臀部和腿部稳定。', '旋转结束时暂停片刻，然后慢慢回到起始位置。', '向另一侧重复旋转。', '继续交替进行所需的重复次数。'],
  'H0244': ['将电缆手柄连接到低滑轮上并面向机器站立。', '用左手抓住手柄，离开机器，完全伸展手臂。', '双脚分开与肩同宽，膝盖稍微弯曲。', '在整个练习过程中保持背部挺直，核心肌群参与其中。', '将手柄拉向您的身体，同时将您的躯干向右旋转。', '动作结束时挤压背部肌肉。', '慢慢回到起始位置，保持绳索的张力。', '重复所需的重复次数，然后换边并用右手执行。'],
  'H1645': ['坐在倾斜的长凳上，背部靠在垫子上，双脚平放在地面上。', '反手握住电缆手柄，手掌朝上，手臂完全伸展。', '保持上臂静止，呼气并将手柄向肩膀弯曲，同时收缩二头肌。', '在动作的最高点暂停片刻，挤压你的二头肌。', '吸气，慢慢将手柄放回起始位置，充分伸展双臂。', '重复所需的重复次数。'],
  'H1728': ['站立，双脚分开与肩同宽，膝盖稍微弯曲。', '双手握住电缆手柄，手掌朝内，手臂弯曲成 90 度角。', '保持上臂静止，向后伸展前臂，直到手臂完全伸展。', '暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H0245': ['调整缆绳机，使下拉杆位于您头部上方的高度。', '坐在座椅上，用反手抓住下拉杆，双手分开的距离略大于肩宽。', '保持背部挺直并稍微向后倾斜。', '将杠铃向下拉向胸部，将肩胛骨挤压在一起。', '在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。', '重复所需的重复次数。'],
  'H1270': ['将手柄连接到胸部高度的电缆上。', '站在绳索机的中央，一只脚稍微在另一只脚前面。', '手掌朝下抓住手柄，手臂向两侧伸展。', '保持肘部轻微弯曲并启动核心肌群。', '将电缆在胸前拉到一起，使它们相互交叉。', '在运动的最高点挤压胸部肌肉。', '慢慢地将电缆释放回起始位置。', '重复所需的重复次数。'],
  'H1324': ['将直杆连接到胸部高度的缆绳机上。', '面向机器站立，双脚分开与肩同宽。', '正手握住杠铃，双手距离略宽于肩宽。', '保持背部挺直，核心肌群参与。', '将杠铃拉向上胸部，将肩胛骨挤压在一起。', '在动作的最高点停顿片刻。', '慢慢地将杠铃释放回起始位置。', '重复所需的重复次数。'],
  'H1325': ['调整缆绳机，使下拉杆位于您头部上方的高度。', '坐在座椅上，用宽的正手握法抓住下拉杆。', '稍微向后倾斜时，保持背部挺直，挺胸。', '将杠铃向下拉至上胸部，将肩胛骨挤压在一起。', '在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。', '重复所需的重复次数。'],
  'H0247': ['将直杆连接到低滑轮电缆机上。', '面向机器站立，双脚分开与肩同宽。', '反手握住杠铃，手掌朝上，双手与肩同宽。', '将前臂放在长凳或垫子上，手腕悬在边缘上。', '保持前臂静止，呼气并尽可能向上弯曲手腕。', '在顶部暂停片刻，然后吸气并慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H1407': ['面向墙壁站立，双脚分开与臀部同宽。', '将双手靠在墙上，与肩同高。', '一只脚向后退一步，脚跟保持在地面上，腿伸直。', '稍微弯曲前膝盖并向前倾斜，感觉小腿有拉伸感。', '保持拉伸 20-30 秒。', '换腿并重复拉伸。'],
  'H1377': ['面向墙壁站立，双脚分开与臀部同宽。', '将双手靠在墙上，与肩同高。', '右脚向后退一步，保持脚后跟着地，腿伸直。', '弯曲左膝并向前倾斜，保持后腿伸直，脚后跟着地。', '保持拉伸 20-30 秒。', '换腿并重复拉伸。'],
  'H1378': ['面向墙壁或坚固物体站立，双脚分开与臀部同宽。', '双手握住绳子的两端，将绳子的中间放在右脚掌周围。', '左脚向后退一步，脚跟保持在地面上，腿伸直。', '身体前倾，保持背部挺直，轻轻拉动绳子以伸展小腿。', '保持拉伸 20-30 秒，然后放松。', '在另一条腿上重复。'],
  'H0248': ['在地板上放一个杠铃，脸朝下躺在长凳上，胸部刚好离开边缘。', '向下伸手，正手抓住杠铃，距离略宽于肩宽。', '双腿伸直，双脚着地，伸展双臂，将杠铃提离地面。', '将杠铃拉向胸部，将肩胛骨挤压在一起。', '将杠铃放回起始位置，然后重复所需的重复次数。'],
  'H2963': ['坐在船长椅上，背部靠在靠背上，前臂放在扶手垫上。', '保持上半身稳定，背部挺直。', '收紧腹肌并将双腿抬起到身前，保持伸直。', '继续抬起，直到双腿与地面平行或达到您可以舒适地达到的高度。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H1548': ['坐在椅子边缘，背部挺直，双脚平放在地面上。', '将一只腿伸直在身前，脚跟保持在地面上。', '稍微向前倾，感受股四头肌的拉伸。', '保持这个姿势20-30秒。', '换腿并重复拉伸。'],
  'H1271': ['站直，双脚分开与肩同宽。', '将双臂伸直至前方，与肩同高。', '双臂交叉在身体前方，右臂放在左臂上方。', '手指交叉并将手掌压在一起。', '轻轻地将肩胛骨挤压在一起，然后将双手向前推，感觉胸部和肩膀前部有拉伸感。', '保持拉伸 20-30 秒，然后放松。', '重复所需的重复次数。'],
  'H1430': ['将倾斜杆调整到您可以舒适地握住它们的高度。', '站在杠铃之间，将双手放在每个杠铃上，距离略宽于肩宽。', '跳起来并伸直双臂，将体重支撑在杠上。', '弯曲膝盖并将脚踝交叉在身后。', '弯曲肘部降低身体，保持胸部向上，肩膀向下。', '继续降低，直到肩膀低于肘部或直到您感到胸部有拉伸感。', '推动手掌并伸展肘部，将身体抬回到起始位置。', '重复所需的重复次数。'],
  'H2462': ['手掌朝下，双臂完全伸展，抓住双杠。', '弯曲膝盖并交叉脚踝。', '弯曲手臂，降低身体，直到肩膀低于肘部。', '伸直手臂，将自己推回起始位置。', '重复所需的重复次数。'],
  'H1272': ['坐在稳定球上，双脚平放在地面上，背部挺直。', '双手握住健身球，并将双臂伸直至身前。', '慢慢地将健身球移向胸部，感受胸部肌肉的拉伸。', '保持伸展几秒钟，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H3216': ['从高平板支撑位置开始，双手分开略宽于肩宽，身体呈一条直线。', '弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。', '当你降低身体时，用右手拍打胸部。', '将自己推回到起始位置。', '重复这个动作，这次用左手敲击胸部。', '继续交替进行所需的重复次数。'],
  'H0253': ['用狭窄的平行握距悬挂在引体向上杆上，手掌朝向您。', '收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。', '继续拉，直到下巴位于杠铃上方。', '在顶部停顿片刻，然后慢慢将身体放回起始位置。', '重复所需的重复次数。'],
  'H0257': ['双脚分开与肩同宽站立，双手放在臀部。', '稍微弯曲膝盖，将脚跟抬离地面，用脚掌保持平衡。', '保持膝盖弯曲，先顺时针旋转膝盖，然后逆时针旋转膝盖。', '执行所需的重复运动次数。'],
  'H0258': ['从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。', '弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。', '当你下降时，将你的身体向左旋转，将你的左臂伸直到侧面。', '向上推回到起始位置，同时将身体旋转到中心。', '重复俯卧撑，这次将身体向右旋转，并将右臂向侧面伸出。', '每次重复时继续交替进行。'],
  'H1327': ['抓住引体向上杆，手掌朝向自己，双手与肩同宽。', '悬挂在杠上，双臂完全伸展，双脚离开地面。', '收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。', '继续拉，直到下巴位于杠铃上方。', '在顶部停顿片刻，然后慢慢将身体放回起始位置。', '重复所需的重复次数。'],
  'H2398': ['首先双手和膝盖着地，双手与肩同宽，膝盖与臀部同宽。', '弯曲肘部，将上身压向地面，使其靠近身体两侧。', '当你的胸部刚好高于地面时，暂停片刻。', '推动手掌以伸直手臂并返回到起始位置。', '重复所需的重复次数。'],
  'H0260': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H1468': ['首先坐在地上，膝盖弯曲，双脚平放在地板上。', '将双手放在身后，手指指向脚部，并将臀部抬离地面。', '将一条腿伸直到您面前，同时将另一只手伸向脚趾。', '返回起始位置并在另一侧重复。', '继续交替进行所需的重复次数。'],
  'H0267': ['平躺，膝盖弯曲，双脚平放在地上。', '将双臂伸直至头顶上方。', '收紧腹肌，将上半身抬离地面，向前向膝盖弯曲。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H0271': ['坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。', '仰卧在球上，直到下背部得到支撑并且上半身与地板平行。', '将双手放在脑后或放在胸前。', '收紧腹肌，将上身抬向膝盖，躯干向前卷曲。', '在动作的最高点暂停片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H0272': ['坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。', '仰卧在球上，直到下背部得到支撑并且上半身与地板平行。', '将双手放在脑后或交叉放在胸前。', '收紧腹肌，将上半身抬离球，将肩膀向臀部弯曲。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H3016': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H3769': ['双脚分开与肩同宽站立。', '右脚向斜后方跨出一步，跨过身体，交叉在左腿后面。', '弯曲双膝，就像行屈膝礼一样，将身体降低到地面。', '保持躯干直立，将体重放在前脚上。', '推动前脚返回起始位置。', '在另一侧重复，用左脚斜向后方跨过身体。'],
  'H2331': ['调整座椅高度并将自己放在自行车交叉训练机上。', '将脚放在踏板上并抓住车把。', '开始以平稳且受控的动作踩踏。', '保持稳定的步伐并根据需要增加阻力。', '继续踩踏您的有氧运动所需的持续时间。'],
  'H0277': ['躺在倾斜的长凳上，双脚固定，膝盖弯曲成 90 度角。', '将双手放在脑后或放在胸前。', '收紧腹肌，将上半身抬向膝盖，卷曲躯干。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H0282': ['躺在倾斜的长凳上，双脚固定，膝盖弯曲。', '将双手放在脑后或放在胸前。', '收紧腹肌，将上半身抬离长凳，向前向膝盖弯曲。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H1274': ['从高平板支撑位置开始，双手分开略宽于肩宽，身体呈一条直线。', '弯曲肘部，使胸部靠近地面，使胸部靠近地面。', '推动手掌以伸展手臂并返回到起始位置。', '重复所需的重复次数。'],
  'H0283': ['从高位平板支撑开始，双手并拢，拇指和食指形成菱形。', '让你的身体从头到脚保持一条直线，锻炼你的核心和臀部。', '将胸部降低至双手形成的菱形，保持肘部靠近身体。', '在底部暂停片刻，然后将自己推回到起始位置。', '重复所需的重复次数。'],
  'H1275': ['从高平板支撑位置开始，双手分开略宽于肩宽。', '将胸部压向地面，保持肘部靠近身体。', '当你的胸部刚好高于地面时，迅速将膝盖放在地上。', '伸展双臂，将自己推回到起始位置。', '重复所需的重复次数。'],
  'H0285': ['站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数，交替手臂。'],
  'H2403': ['站直，双脚分开与肩同宽，双手各握一个哑铃，手掌朝前。', '将手臂冲击波放在上臂上，确保牢固贴合。', '保持上臂静止，呼气并将一只哑铃向上弯向肩膀，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气，慢慢将哑铃放回起始位置。', '用另一只手臂重复该动作。', '继续交替手臂进行所需的重复次数。'],
  'H1648': ['坐在长凳上，双手各握一个哑铃，手掌朝向躯干，手臂向下伸展。', '保持背部挺直，肘部靠近躯干。', '呼气，将右手的哑铃向肩膀弯曲，保持上臂静止。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '暂停片刻，然后吸气，慢慢将哑铃放回起始位置。', '用左臂重复该动作。', '继续交替手臂进行所需的重复次数。'],
  'H0286': ['双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高。', '将一个哑铃推过头顶，同时将另一个哑铃保持在与肩同高的位置。', '将按下的哑铃放回肩部高度，同时将另一个哑铃压过头顶。', '继续交替进行所需的重复次数。'],
  'H0287': ['坐在有背部支撑的长凳上，双手各握一个哑铃，与肩同高，手掌朝向身体，肘部弯曲。', '向上推哑铃，直到手臂完全伸展，手掌朝前。', '抬起时旋转手腕，使手掌在动作的最高点朝前。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0288': ['平躺在长凳上，头放在一端，双脚牢牢踩在地上。', '双手握住哑铃，将手臂伸直至胸部上方。', '保持手臂伸直，以弧线动作慢慢将哑铃降低到脑后。', '在底部停顿片刻，然后将哑铃举回到起始位置。', '重复所需的重复次数。'],
  'H0290': ['坐在长凳上，每只手各拿一个哑铃，放在大腿上。', '向后倾斜，将哑铃放在胸部两侧，手掌朝前。', '向上推哑铃，直到手臂完全伸展。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1651': ['双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。', '右脚向前迈出一步，弯曲右膝，将身体降低至弓步位置。', '当你向前弓步时，将哑铃向上弯向肩膀，保持肘部靠近身体。', '在弓步底部，将躯干向右旋转，就像打保龄球一样。', '反转动作，右脚向后退一步，回到起始位置，同时放下哑铃。', '重复弓步和弯举动作，这次将躯干向左旋转。', '继续交替进行所需的重复次数。'],
  'H1653': ['双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。', '将一条腿伸到身后，用脚趾保持平衡。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数，然后换腿并重复。'],
  'H2401': ['站直，双手各持一个哑铃，手掌朝前。', '保持肘部靠近躯干，上臂保持静止。', '呼气并弯举哑铃，同时收缩二头肌。', '继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1654': ['站直，双手各握一个哑铃，手掌朝下，双臂完全伸展。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1655': ['双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。', '保持背部挺直，肘部靠近身体两侧，呼气并将哑铃向上弯向肩膀。', '在顶部暂停片刻，挤压你的二头肌。', '吸气并慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1656': ['坐在博苏球上，双脚平放在地上，膝盖弯曲成 90 度角。', '每只手握住一个哑铃，手掌朝前，双臂在身体两侧完全向下伸展。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1201': ['从站立位置开始，双脚分开与肩同宽，每只手各拿一个哑铃。', '将身体降低至蹲姿，将哑铃放在您面前的地面上。', '将双脚踢回到俯卧撑位置，保持身体呈一条直线。', '进行俯卧撑，弯曲肘部并将胸部降低到地面。', '将脚向后跳向双手，以蹲姿着地。', '爆发性地站起来，将哑铃从地上举起，放到肩膀上。', '将哑铃举过头顶，充分伸展手臂。', '将哑铃放回到肩膀上，然后重复整个序列，达到所需的重复次数。'],
  'H0295': ['双脚分开与肩同宽站立，双手各握一个哑铃，正握。', '弯曲膝盖，降低臀部至下蹲位置，保持背部挺直，挺胸。', '爆发性地伸展臀部和膝盖，通过脚后跟跳离地面。', '当你跳跃时，耸肩并将哑铃拉向你的肩膀，保持它们靠近你的身体。', '在与肩同高的位置抓住哑铃，肘部向前，手掌朝上。', '通过反向运动将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0298': ['站直，双手各持一个哑铃，手掌朝向身体。', '保持肘部靠近躯干，上臂保持静止。', '呼气并弯举哑铃，同时收缩二头肌，将哑铃穿过身体拉向对侧的肩膀。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1657': ['站直，双手各持一个哑铃，手掌朝向身体。', '保持肘部靠近躯干，上臂保持静止。', '呼气并弯举哑铃，同时收缩二头肌，使哑铃尽可能靠近另一侧的肩膀。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0299': ['双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝下。', '保持核心收紧，肘部稍微弯曲，将哑铃向上举过头顶，直到手臂完全伸展。', '旋转手腕，使手掌朝前。', '慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。', '重复所需的重复次数。'],
  'H2136': ['双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝下。', '保持核心收紧，背部挺直，将哑铃垂直推过头顶，直到手臂完全伸展。', '旋转手腕，使手掌朝前。', '将哑铃放回至肩膀高度，将手腕旋转回起始位置。', '重复所需的重复次数。'],
  'H0300': ['双脚分开与肩同宽站立，脚趾指向前方。', '双手各握一个哑铃，手掌朝向身体，手臂向下伸展。', '弯曲臀部和膝盖，将哑铃向地面降低，同时保持背部挺直。', '脚跟用力，伸展臀部和膝盖，将哑铃举回起始位置。', '重复所需的重复次数。'],
  'H0303': ['躺在倾斜的长凳上，双脚固定，头部低于臀部。', '双手各握一个哑铃，手掌相对，双臂伸至胸部上方。', '将哑铃降低到胸部两侧，保持肘部稍微弯曲。', '将哑铃推回到起始位置，充分伸展手臂。', '重复所需的重复次数。'],
  'H1276': ['躺在斜凳上，一只手拿着哑铃，将其放在大腿上。', '用大腿帮助举起哑铃，将其举至与肩同宽，手掌朝向躯干。', '旋转手腕，使手掌朝前。', '吸气时，将哑铃慢慢降低到一侧，直到感觉到胸部有拉伸感。', '呼气并使用胸部肌肉将哑铃拉回到起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1617': ['躺在下斜长凳上，一只手握住哑铃，放在胸前。', '将手臂伸直向上，保持肘部稍微弯曲。', '将哑铃向肩膀方向降低，保持肘部靠近身体。', '将哑铃推回到起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0305': ['设置一个 45 度角的下斜凳。', '脸朝下躺在长凳上，胸部和腹部靠在长凳上。', '每只手握住一个哑铃，双臂完全伸向地板。', '保持手臂伸直，将肩膀尽可能高地抬向耳朵。', '保持收缩一会儿，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0304': ['设置一个 45 度角的下斜凳。', '脸朝下躺在长凳上，胸部和腹部靠在长凳上。', '每只手握住一个哑铃，手掌相对，双臂完全伸展。', '保持手臂伸直，尽可能高地抬高肩膀，同时将肩胛骨挤压在一起。', '保持收缩短暂停顿，然后将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0307': ['躺在倾斜的长凳上，头部低于臀部。', '双手各握一个哑铃，手掌相对，双臂伸直越过胸部。', '将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。', '当你降低哑铃时，扭转手腕，使手掌在动作底部朝前。', '反转动作，将哑铃拉回到起始位置，在顶部挤压胸部肌肉。', '重复所需的重复次数。'],
  'H1437': ['坐在长凳或椅子上，双脚平放在地上，背部挺直。', '一只手握住哑铃，反手握住，将前臂放在大腿上，手掌朝上。', '让哑铃向下滚动到指尖，然后弯曲手指将其卷起。', '重复所需的重复次数，然后换另一只手。'],
  'H1277': ['坐在健身球上，每只手各握一个哑铃。', '双脚向前走，身体向下滚动，直到头部、颈部和上背部得到球的支撑。', '将双臂伸直至胸部上方，手掌相对。', '稍微弯曲肘部，将手臂以宽弧线向两侧放低，直到感觉到胸部有拉伸感。', '暂停片刻，然后反向运动并挤压胸部肌肉，同时将​​哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1732': ['双脚分开与肩同宽站立，每只手各握一个哑铃。', '右脚向前迈出一步，将身体降低至弓步位置。', '保持背部挺直，挺胸。', '将手臂伸直过头顶，保持肘部靠近耳朵。', '弯曲肘部，将哑铃降低到脑后。', '暂停片刻，然后伸直手臂回到起始位置。', '重复该动作达到所需的重复次数，然后换腿并重复。'],
  'H0309': ['双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向大腿。', '保持背部挺直并启动核心肌群。', '慢慢举起你面前的哑铃，手臂伸直，直到与肩齐平。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0311': ['双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。', '保持背部挺直并启动核心肌群。', '将手臂向两侧举起，肘部保持轻微弯曲，直到与地面平行。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H1659': ['坐在健身球上，双脚平放在地上，背部挺直。', '每只手握住一个哑铃，手掌朝向身体，双臂完全伸展。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0312': ['站直，双手各持一个哑铃，手掌朝向躯干。', '保持肘部靠近躯干，并旋转手掌，直到手掌朝前。', '这将是您的起始位置。', '现在，保持上臂静止，呼气并卷曲哑铃，同时收缩二头肌。', '继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '然后，吸气并慢慢开始将哑铃放回起始位置。', '重复建议的重复次数。'],
  'H2402': ['站直，双手各持一个哑铃，手掌朝向躯干。', '保持肘部靠近躯干，并旋转手掌，直到手掌朝前。', '这将是您的起始位置。', '现在，保持上臂不动，呼气并卷曲哑铃，同时收缩二头肌。', '继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '然后，吸气并慢慢开始将哑铃放回起始位置。', '重复建议的重复次数。'],
  'H1664': ['站直，双手各持一个哑铃，手掌朝前。', '保持上臂静止，将哑铃尽可能高地卷起，同时收缩二头肌。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H3545': ['坐在上斜凳上，每只手各拿一个哑铃，放在大腿上。', '向后靠在长凳上，用大腿帮助将哑铃举至肩高，手掌朝前。', '到达肩膀高度后，旋转手腕，使手掌朝前。', '用胸部和肩膀将哑铃向上推，充分伸展手臂。', '将哑铃放回起始位置，保持肘部稍微弯曲。', '重复所需的重复次数，交替手臂。'],
  'H0315': ['坐在上斜凳上，双手各握一个哑铃，手掌朝前，双臂完全伸展。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0316': ['设置一个 45 度角的上斜凳。', '坐在长凳上，背部靠在垫子上，双脚平放在地面上。', '双手各握一个哑铃，正手握握，手掌朝前。', '首先，双臂完全伸展，垂直于地面。', '慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。', '在底部暂停片刻，然后将哑铃推回到起始位置。', '重复所需的重复次数。'],
  'H0318': ['将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心向前。', '将上臂放在上斜凳上，让肘部下垂，充分伸展手臂。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0317': ['坐在上斜凳上，双手各握一个哑铃，手掌朝前，双臂完全伸展。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0319': ['将上斜凳设置为 45 度角。', '坐在长凳上，双手各握一个哑铃，手掌相对。', '仰卧在长凳上，将哑铃推至起始位置，位于胸部正上方。', '将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。', '暂停片刻，然后挤压胸部肌肉，将哑铃拉回起始位置。', '重复所需的重复次数。'],
  'H1278': ['设置一个 45 度角的上斜凳。', '坐在健身球上，向前滚动，直到上背部靠在倾斜的长凳上。', '双手各握一个哑铃，手掌相对，双臂伸至胸部上方。', '将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。', '暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。', '重复所需的重复次数。'],
  'H0320': ['坐在上斜凳上，每只手各握一个哑铃，手掌朝向躯干，手臂完全伸展。', '背部靠在长凳上，双脚平放在地板上。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0321': ['将上斜凳设置成 45 度角，坐在上面，双手各握一个哑铃，放在大腿上。', '仰卧在长凳上，将哑铃置于与肩同高的位置，手掌相对。', '将哑铃向上推离身体，直到手臂完全伸展。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1618': ['坐在健身球上，双手各握一个哑铃，手掌相对。', '双脚向前走，身体沿着球滚动，直到头部、颈部和上背部得到球的支撑。', '将哑铃保持在与肩同高的位置，肘部弯曲并指向两侧。', '将哑铃向上并稍微向内推，保持手掌相对。', '充分伸展双臂，在动作的最高点挤压三头肌。', '慢慢地将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0322': ['坐在上斜凳上，双手各握一个哑铃，手掌相对。', '将上臂放在长凳上，让肘部下垂，手掌朝前。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1279': ['将倾斜凳调整至 30-45 度角。', '坐在长凳上，一只手拿着哑铃，将其放在大腿上。', '向后躺在长凳上，双脚平放在地面上。', '握住哑铃，手臂伸直越过胸部。', '将哑铃以宽弧线向一侧放低，保持肘部轻微弯曲。', '当手臂与地面平行时暂停，然后反向运动，使哑铃回到起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1280': ['坐在健身球上，一只手拿着哑铃。', '双脚向前走，身体向下滚动，直到头部、颈部和上背部得到球的支撑。', '握住哑铃，手臂伸直越过胸部，手掌朝内。', '慢慢地将哑铃向一侧放低，保持肘部轻微弯曲。', '当手臂与地面平行时暂停片刻。', '启动胸部肌肉，将哑铃拉回到起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1619': ['坐在上斜凳上，一只手拿着哑铃，放在大腿上。', '向后靠在长凳上，用大腿帮助将哑铃举至肩膀高度。', '旋转手腕，使手掌朝内，朝向身体。', '将哑铃向上推离身体，完全伸展手臂。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1620': ['坐在健身球上，一只手拿着哑铃。', '双脚向前走，身体向下滚动，直到头部、颈部和上背部得到球的支撑。', '握住哑铃，手掌朝内，肘部弯曲成 90 度角。', '将哑铃向上推向天花板，伸直手臂。', '将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0323': ['坐在上斜凳上，一只手拿着哑铃，将其放在大腿上。', '身体前倾，将上臂靠在大腿内侧。', '将哑铃举到一侧，保持手臂稍微弯曲，手掌朝下。', '继续抬起，直到手臂与地板平行。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H1281': ['坐在上斜凳上，一只手拿着哑铃，放在大腿上。', '仰卧在长凳上，将哑铃置于与肩同高的位置，手掌朝前。', '将哑铃向上并稍微向内推，充分伸展手臂。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H1282': ['坐在健身球上，一只手拿着哑铃，双脚平放在地上。', '慢慢地向前移动你的脚，滚动球，直到你的头、脖子和上背部得到球的支撑。', '将哑铃握在与肩同高的位置，手掌朝前。', '向上推哑铃，直到手臂完全伸展。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0324': ['设置一个 45 度角的上斜凳。', '坐在长凳上，双手各握一个哑铃，手掌相对。', '将双脚牢牢踩在地面上，并保持背部挺直靠在长凳上。', '从与肩同高的哑铃开始，肘部弯曲，手掌相对。', '将哑铃向上推离身体，充分伸展手臂。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1283': ['坐在健身球上，每只手各握一个哑铃，手掌朝前。', '双脚慢慢向前移动，身体沿着球滚动，直到头部、颈部和上背部得到球的支撑。', '将哑铃保持在与肩同高的位置，肘部弯曲并指向两侧。', '向上推哑铃，充分伸展手臂。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0325': ['坐在上斜凳上，每只手各拿一个哑铃，放在大腿上。', '向后靠在长凳上，将哑铃举至肩高，手掌朝前。', '背部靠在长凳上，呼气并将哑铃举过头顶，充分伸展双臂。', '在顶部停顿片刻，然后吸气，慢慢将哑铃放回肩部高度。', '重复所需的重复次数。'],
  'H0326': ['设置一个 45 度角的上斜凳。', '坐在长凳上，胸部靠在靠背上，双手各握一个哑铃。', '双臂伸直向下，手掌相对。', '保持肘部轻微弯曲，将手臂向两侧抬起，直到与地面平行。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H0328': ['将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心朝下。', '将哑铃放在大腿上，然后靠在长凳上。', '用大腿帮助将哑铃举至肩膀高度，然后旋转手腕，使手掌朝前。', '呼气，慢慢将哑铃举过头顶，保持肘部轻微弯曲。', '在顶部停顿片刻，然后吸气，慢慢将哑铃放回肩部高度。', '重复所需的重复次数。'],
  'H0329': ['将上斜凳设置为 45 度角，坐在上面，双手各握一个哑铃。', '将双脚平放在地面上，让双臂笔直下垂，手掌朝向身体。', '保持手臂伸直，耸肩，尽可能高地靠近耳朵。', '保持收缩一会儿，然后慢慢将肩膀放回起始位置。', '重复所需的重复次数。'],
  'H3542': ['将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心向内。', '向前倾斜，让手臂笔直向下垂，垂直于地板。', '保持手臂伸直，将它们向两侧举起，直到与地板平行，与身体形成“T”形。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H0330': ['坐在上斜凳上，双手各握一个哑铃，掌心向内。', '将手臂完全伸过头顶，保持肘部靠近头部。', '弯曲肘部，将哑铃降低到头后，保持上臂静止。', '暂停片刻，然后伸展双臂将哑铃举回起始位置。', '重复所需的重复次数。'],
  'H0331': ['将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心相对。', '仰卧在长凳上，将哑铃推至起始位置，位于胸部正上方，双臂伸展。', '将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。', '放下哑铃时，旋转手腕，使手掌在动作底部朝前。', '反转动作，将哑铃拉回起始位置，在顶部将胸部肌肉挤压在一起。', '重复所需的重复次数。'],
  'H1733': ['坐在上斜凳上，每只手各拿一个哑铃，放在大腿上。', '慢慢地躺在长凳上，保持哑铃靠近胸部。', '完全躺下后，将手臂伸向天花板，保持肘部稍微弯曲。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0332': ['双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。', '将双臂向两侧举起，直至与地面平行，与身体形成T字形。', '暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H0333': ['双脚分开与肩同宽站立，每只手各握一个哑铃。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '将上臂靠近身体两侧，肘部弯曲成 90 度角。', '将手臂向后伸直，在动作的最高点挤压三头肌。', '暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1734': ['坐在健身球上，双脚平放在地上，背部挺直。', '双手各握一个哑铃，掌心向内，手臂弯曲成 90 度角。', '将手臂向后伸直，在动作的最高点挤压三头肌。', '暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1660': ['跪在地板上，面前放一个健身球。', '将肘部放在健身球上，双手各握一个哑铃，手掌朝上。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0335': ['双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。', '保持背部挺直并启动核心肌群。', '将手臂向两侧举起，直到与地面平行，保持肘部稍微弯曲。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '接下来，将手臂举到身前，直到它们与地面平行，再次保持肘部稍微弯曲。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H1658': ['双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。', '右脚向前迈出一步，将身体降低至弓步位置。你的右膝应该弯曲成 90 度角，左膝应该悬停在地面上方。', '当你向前弓步时，同时将哑铃向肩膀弯曲，保持肘部靠近身体。', '在弓步底部停顿片刻，然后通过右脚跟推动回到起始位置，将哑铃放回身体两侧。', '在另一侧重复弓步和二头肌弯举，左脚向前迈出。', '继续交替进行所需的重复次数。'],
  'H0337': ['平躺在长凳上，双脚平放在地上，头放在长凳的末端。', '双手握住哑铃，双臂伸直至胸部上方，手掌相对。', '保持上臂静止，将哑铃在头后呈弧形缓慢降低，直到前臂与地面平行。', '暂停片刻，然后收缩三头肌，将哑铃带回起始位置。', '重复所需的重复次数。'],
  'H1729': ['平躺在长凳上，双手各握一个哑铃，手掌相对。', '将手臂伸直越过胸部，保持肘部轻微弯曲。', '将一个哑铃朝头部方向放下，肘部弯曲，同时保持另一只手臂伸展。', '在底部停顿片刻，然后将哑铃举回到起始位置。', '用另一只手臂重复上述动作，交替进行所需的重复次数。'],
  'H0338': ['平躺在长凳上，双手各握一个哑铃，手掌相对，双臂伸直越过胸部。', '弯曲肘部，将哑铃向肩膀方向降低，保持上臂静止。', '在底部暂停片刻，然后伸展肘部将哑铃推回到起始位置。', '重复所需的重复次数。'],
  'H0863': ['侧躺在平坦的长凳上，上臂靠在身体两侧，肘部弯曲 90 度。', '手中握住哑铃，手掌朝下。', '保持上臂靠在身体两侧，尽可能缓慢地向上旋转前臂。', '在顶部暂停片刻，然后慢慢将前臂放回起始位置。', '重复所需的重复次数，然后换边。'],
  'H0339': ['平躺，双腿伸直，将哑铃放在下腹部。', '弯曲膝盖，将哑铃拉向臀部，保持双脚平放在地面上。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0340': ['平躺在长凳上，双手各握一个哑铃，手掌相对，双臂伸直向上。', '将哑铃放低至胸部两侧，保持肘部呈 90 度角。', '将哑铃推回到起始位置，充分伸展手臂。', '重复所需的重复次数。'],
  'H2470': ['脸朝下躺在地板上，双手各握一个哑铃，手掌相对。', '将手臂伸直在身前，保持肘部轻微弯曲。', '调动肩部肌肉，将手臂向上并向两侧抬起，将肩胛骨挤压在一起。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H0341': ['脸朝下躺在平坦的长凳上，一只手握住哑铃，手掌朝内。', '将手臂笔直向下伸向地板，保持靠近身体。', '向上和向后举起手臂，将肩胛骨挤压向脊柱。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0343': ['平躺在长凳上，一只手拿着哑铃，双脚平放在地上。', '将哑铃举至肩部水平，手掌朝前。', '向上推哑铃，直到手臂完全伸展。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0342': ['平躺在长凳上，背部支撑，双脚平放在地面上。', '一只手握住哑铃，手掌朝向脚部。', '将手臂伸向天花板，保持肘部稍微弯曲。', '慢慢地将哑铃向胸部方向降低，保持肘部靠近身体。', '在底部暂停片刻，然后将哑铃推回到起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0344': ['平躺在长凳上，背部和头部得到支撑，双脚平放在地面上。', '一只手握住哑铃，手掌朝下，将手臂伸直至肩膀上方。', '保持上臂静止，弯曲肘部，慢慢将哑铃降低到脑后。', '在底部停顿片刻，然后将手臂伸回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0345': ['脸朝下躺在平坦的长凳上，一只手拿着哑铃，垂向地板。', '保持手臂伸直，将哑铃举到一侧，远离身体。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0346': ['平躺在长凳上，背部和头部得到支撑，双脚平放在地面上。', '一只手握住哑铃，反握，将手臂伸直至肩膀上方。', '保持上臂静止，弯曲肘部，慢慢将哑铃降低到脑后。', '在底部停顿片刻，然后将手臂伸回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0347': ['平躺在长凳上，胸部朝下，双臂伸直向下，每只手各握一个哑铃。', '旋转手掌，使手掌朝上。', '保持上臂静止，呼气并弯曲哑铃，同时将手掌旋转至面朝下。', '吸气并慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H2705': ['平躺在地板上，脸朝下，双臂伸直在身前，每只手各握一个哑铃。', '旋转手掌，使其朝下朝向地板。', '保持手臂伸直，收缩前臂将哑铃提离地板。', '继续举起，直到前臂完全收缩并且哑铃与肩部齐平。', '保持一会儿，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1284': ['坐在健身球上，向前滚动，直到上背部靠在球上。', '双手握住哑铃，将手臂伸直至胸部上方。', '慢慢地将哑铃放到脑后，同时保持手臂伸直。', '暂停片刻，然后将哑铃举回到起始位置。', '重复所需的重复次数。'],
  'H1328': ['脸朝下躺在平坦的长凳上，每只手各握一个哑铃，手掌朝内。', '将手臂伸直向下伸向地板，肘部保持轻微弯曲。', '调动背部肌肉，将哑铃举向胸部，将肩胛骨挤压在一起。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0348': ['脸朝下躺在平坦的长凳上，双手各握一个哑铃，手掌相对。', '将手臂伸直向下伸向地板，肘部保持轻微弯曲。', '调动肩部肌肉，将手臂向两侧抬起，直到与地板平行。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H1735': ['平躺在长凳上，一只手拿着哑铃，手臂完全伸展到胸部上方。', '以受控的方式将哑铃降低到前额，保持上臂静止。', '在动作底部短暂暂停，然后将手臂伸展回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0349': ['平躺在长凳上，双脚平放在地上。', '每只手握住一个哑铃，手掌朝上，双臂完全伸展。', '保持上臂不动，收缩前臂，将哑铃向肩膀方向卷曲。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H2706': ['仰卧在地板上，双腿伸直，双臂放在身体两侧，每只手各握一个哑铃。', '将手掌旋转至向上，保持肘部靠近身体两侧。', '慢慢地将哑铃向肩膀弯曲，挤压前臂。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1661': ['平躺在长凳上，背部和头部得到支撑，双脚平放在地面上。', '每只手握住一个哑铃，手掌朝上，双臂完全伸展。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0350': ['平躺在长凳上，双手各握一个哑铃，手掌朝上，双臂完全伸展。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1662': ['平躺在长凳上，双手各握一个哑铃，手掌朝上，双臂完全伸展。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0352': ['平躺在长凳上，双脚平放在地上，背部紧贴长凳。', '每只手握一个哑铃，中立握法（手掌相对），双臂伸直越过胸部。', '慢慢地将哑铃降低到胸部，保持肘部靠近身体。', '在底部停顿片刻，然后将哑铃推回起始位置，完全伸展手臂。', '重复所需的重复次数。'],
  'H1285': ['坐在平坦的长凳上，一只手拿着哑铃，将其放在大腿上方。', '向后躺在长凳上，将哑铃压在大腿上。', '用空着的那只手帮助将哑铃举至起始位置。', '将哑铃握在肩膀正上方，手臂伸展，手掌朝内。', '将哑铃以宽弧线向一侧放低，保持肘部轻微弯曲。', '当手臂与地面平行时暂停，然后反向运动并将哑铃带回起始位置。', '重复所需的重复次数，然后换臂重复。'],
  'H0292': ['双脚分开与肩同宽站立，一手握住哑铃，手掌朝向身体。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。', '让哑铃垂直垂向地板，手臂完全伸展。', '将哑铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换边。'],
  'H1286': ['坐在健身球上，一只手拿着哑铃，双脚平放在地上。', '双脚向前走，滚动球，直到你的上背部受到球的支撑，并且你的头、脖子和肩膀离开球。', '将手臂伸直，将哑铃举至胸部上方，手掌朝内。', '慢慢地将哑铃向一侧放低，保持肘部轻微弯曲。', '当手臂与地面平行时暂停片刻。', '启动胸部肌肉，将哑铃拉回到起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0353': ['坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。', '一只手握住哑铃，手掌朝上，手臂向下伸向地板。', '将肘部放在大腿内侧、膝盖上方。', '保持上臂静止，呼气并将哑铃向上弯向肩膀，同时收缩二头肌。', '在动作的最高点停顿片刻，然后吸气，慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂重复。'],
  'H1287': ['躺在下斜长凳上，一只手握住哑铃，放在胸前。', '将双脚平放在地面上，并将背部压在长凳上。', '伸展手臂，将哑铃推向天花板，充分伸展肘部。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H1288': ['坐在健身球上，一只手拿着哑铃，双脚平放在地上。', '双脚向前走，身体向下滚动，直到上背部靠在健身球上。', '将手臂伸直，将哑铃举至胸部上方，手掌朝内。', '慢慢地将哑铃向一侧放低，保持肘部轻微弯曲。', '暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1736': ['坐在健身球上，双脚平放在地上，背部挺直。', '一只手握住哑铃，手掌朝上，肘部弯曲成 90 度角。', '将手臂伸向天花板，保持肘部不动。', '慢慢地将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1663': ['坐在牧师凳上，一只手拿着哑铃，上臂放在垫子上。', '以中立握法握住哑铃（手掌朝向身体）。', '保持上臂静止，呼气并将哑铃向上弯向肩膀。', '在顶部暂停片刻，挤压你的二头肌。', '吸气，慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1621': ['坐在健身球上，双脚平放在地上，背部挺直。', '一只手握住哑铃，掌心向内，肘部弯曲成 90 度角。', '将另一只手放在臀部上以保持稳定。', '向上推哑铃，充分伸展手臂。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1289': ['将上斜凳调整至 45 度角。', '坐在长凳上，背部靠在垫子上，双脚平放在地面上。', '一只手握住哑铃，正手握住，将其放在肩膀上。', '将哑铃向上推离身体，完全伸展手臂。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0354': ['双脚分开与肩同宽站立，右手握住哑铃。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '将右肘举至身体一侧，保持弯曲 90 度角。', '将右臂向后伸直，在动作的最高点挤压三头肌。', '慢慢地将哑铃放回起始位置。', '重复所需的重复次数，然后换边。'],
  'H0355': ['双脚分开与肩同宽站立，一手握住哑铃，手掌朝向身体。', '在整个练习过程中保持背部挺直，核心肌群参与其中。', '将哑铃举至一侧，保持手臂伸直，手掌朝下。', '继续抬起，直到手臂与地面平行。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0356': ['双脚分开与肩同宽站立，一手握住哑铃，手掌朝向身体。', '将另一只手放在稳定的表面（例如长凳或墙壁）上以获得支撑。', '保持背部挺直并启动核心肌群。', '将哑铃向一侧举起，保持手臂伸直，手掌朝下。', '继续抬起，直到手臂与地面平行。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换边。'],
  'H1290': ['坐在健身球上，双脚平放在地上，膝盖弯曲成 90 度角。', '一只手握住哑铃，将其置于与肩同高的位置，肘部弯曲，手掌朝前。', '慢慢向上推哑铃，直到手臂完全伸展，同时保持核心收紧并在健身球上保持平衡。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H1665': ['脸朝下躺在平坦的长凳上，一只手握住哑铃，掌心朝下。', '完全伸展你的手臂，让它垂直垂向地板。', '保持上臂静止，通过收缩二头肌将哑铃向上卷曲至肩膀。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1666': ['面朝下躺在平坦的长凳上，一只手拿着哑铃，手掌面向身体，手臂完全伸展。', '保持上臂静止，将哑铃向肩膀弯曲，收缩二头肌。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1291': ['坐在健身球上，双脚平放在地上，膝盖弯曲成 90 度角。', '用一只手握住哑铃，将手臂伸直至胸部上方。', '慢慢地将哑铃放到脑后，同时保持手臂伸直。', '暂停片刻，然后将哑铃举回到起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0358': ['坐在长凳或椅子上，双脚平放在地面上。', '一只手握住哑铃，正手握住，手掌朝下。', '将前臂放在大腿上，手腕悬在边缘。', '弯曲手腕，慢慢地将哑铃降低到地面。', '在底部停顿片刻，然后慢慢地将手腕向上卷向身体。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0359': ['坐在长凳上，双脚平放在地上，背部挺直。', '一只手握住哑铃，手掌朝内。', '身体前倾，将空着的手放在长凳上以获得支撑。', '保持手臂稍微弯曲并将其向侧面抬起，直到与地面平行。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1622': ['坐在平坦的长凳上，一只手拿着哑铃，手掌朝向身体。', '将双脚平放在地面上，并保持背部挺直。', '将哑铃举至肩膀高度，保持肘部靠近身体。', '向上推哑铃，直到手臂完全伸展。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H1414': ['坐在牧师凳上，胸部靠在垫子上，手臂伸出长凳边缘，反握哑铃。', '慢慢降低哑铃，直到手臂完全伸展。', '将哑铃向后弯向肩膀，保持上臂静止。', '在动作的最高点挤压二头肌，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1667': ['站直，一只手握住哑铃，手掌朝下，手臂完全伸展。', '保持上臂静止，弯曲肘部，将哑铃向肩膀方向卷曲。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1668': ['坐在健身球上，双脚平放在地上，背部挺直。', '一只手握住哑铃，手掌朝上，手臂完全伸展。', '保持上臂静止，通过收缩二头肌将哑铃向肩膀弯曲。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1669': ['坐在长凳上，背部挺直，双脚平放在地上。', '一只手握住哑铃，保持中立握姿（手掌相对）。', '将肘部放在大腿内侧、膝盖上方。', '保持上臂静止，呼气并将哑铃向上弯向肩膀。', '在顶部暂停片刻，挤压你的二头肌。', '吸气，慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1415': ['坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝上。', '将前臂放在大腿上，让手腕悬在边缘。', '保持前臂静止，尽可能向上弯曲手腕。', '在顶部暂停片刻，然后慢慢将手腕放回起始位置。', '重复所需的重复次数，然后换另一只手。'],
  'H0361': ['双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝前。', '向上推哑铃，直到手臂完全伸过头顶。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0360': ['双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝前。', '启动核心肌群，将哑铃垂直推过头顶，充分伸展手臂。', '在顶部停顿片刻，然后慢慢将哑铃放回肩部水平。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H3888': ['双脚分开与肩同宽站立，一只手握住哑铃，正握。', '稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。', '将哑铃向地面放低，使其靠近身体。', '爆发性伸展臀部、膝盖和脚踝，将哑铃沿直线向上推。', '当哑铃到达肩膀高度时，快速旋转你的手并将其击打过头顶，充分伸展你的手臂。', '将哑铃举过头顶，膝盖和臀部稍微弯曲。', '以受控的方式将哑铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H1670': ['站直，一手握哑铃，手掌朝前，手臂完全伸展。', '保持上臂静止，呼气并向上弯曲重量，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气，慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1671': ['站直，双手各持一个哑铃，手掌朝向躯干。', '保持肘部靠近躯干，上臂保持静止。', '呼气并弯举哑铃，同时收缩二头肌。', '继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0362': ['坐在长凳上，背部挺直，双脚平放在地上。', '一手握住哑铃，另一只手放在长凳上以获得支撑。', '将哑铃举过头顶，保持上臂靠近头部，肘部向前。', '弯曲肘部，将哑铃降低到头后，保持上臂静止。', '将手臂向后伸展至起始位置，完全伸直肘部。', '重复所需的重复次数，然后换臂。'],
  'H0363': ['双脚分开与肩同宽站立，一只手握住哑铃，正握。', '让哑铃悬挂在大腿前面，与手臂保持一定距离，手掌朝向身体。', '保持背部挺直，核心收紧，呼气，将哑铃笔直向上举至下巴，用肘部引导。', '在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0364': ['坐在长凳或椅子上，双脚平放在地面上。', '一只手握住哑铃，反握，将前臂放在大腿上。', '让你的手腕伸展，让哑铃向你的手指方向滚动。', '慢慢地向后弯曲手腕，将哑铃拉向前臂。', '重复所需的重复次数，然后换另一只手。'],
  'H1672': ['坐在牧师弯举凳上，单手握哑铃，反握。', '将上臂放在牧师凳垫上，让手臂完全伸展。', '将哑铃向上弯向肩膀，保持上臂静止。', '在卷曲的顶部，旋转手腕，使手掌朝上。', '慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1292': ['坐在健身球上，双手各握一个哑铃，手掌相对。', '将一只脚放在地面上，并将另一条腿伸直到您面前。', '稍微向前倾，将手臂向两侧伸出，保持肘部轻微弯曲。', '慢慢地将哑铃向两侧放低，感觉胸部有拉伸感。', '在底部暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。', '重复所需的重复次数，然后换腿并重复。'],
  'H0365': ['坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。', '将前臂放在长凳上，让手腕悬在长凳边缘。', '保持上臂静止，呼气并将哑铃向上弯向肩膀。', '在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0366': ['坐在长凳上，一只手拿着哑铃，手臂伸过长凳，手掌朝上。', '保持上臂静止，将哑铃向肩膀弯曲，使手腕保持在中立位置。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1441': ['坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝下。', '将前臂放在长凳上，手腕悬在长凳边缘。', '慢慢向上弯曲手腕，将哑铃拉向前臂。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0367': ['坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝下。', '将前臂放在长凳上，手腕悬在长凳边缘。', '慢慢向上弯曲手腕，将哑铃拉向前臂。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0368': ['坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝下。', '将前臂放在长凳上，让手腕悬在长凳边缘。', '慢慢向上弯曲手腕，将哑铃拉向身体。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0369': ['坐在长凳上，前臂放在长凳上，手掌朝上，每只手各握一个哑铃。', '让手腕悬在长凳边缘。', '慢慢向上弯曲手腕，在动作的最高点挤压前臂。', '暂停片刻，然后慢慢将手腕放回起始位置。', '重复所需的重复次数。'],
  'H1329': ['双脚分开与肩同宽站立，双手各握一个哑铃，正握。', '臀部向前弯曲，保持背部挺直，膝盖稍微弯曲。', '让你的手臂笔直下垂，手掌朝向身体。', '收紧核心肌群，将哑铃拉向胸部，保持肘部靠近身体。', '当你向上拉哑铃时，旋转手掌，使其背向身体。', '在动作的最高点将肩胛骨挤压在一起。', '慢慢地将哑铃放回起始位置，将手掌旋转回起始位置。', '重复所需的重复次数。'],
  'H1623': ['设置一个 45 度角的上斜凳。', '坐在长凳上，背部靠在靠背上，双脚平放在地上。', '双手各握一个哑铃，正手握握，手掌朝内。', '将手臂伸直至胸部上方，保持肘部轻微弯曲。', '将哑铃慢慢向肩膀方向降低，保持肘部靠近身体。', '在底部暂停片刻，然后将哑铃推回到起始位置。', '重复所需的重复次数。'],
  'H0370': ['站直，双手各持一个哑铃，手掌朝向躯干。', '保持肘部靠近躯干，并旋转手掌，直到手掌朝前。', '这将是您的起始位置。', '现在，保持上臂静止，呼气并卷曲哑铃，同时收缩二头肌。', '继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '然后，吸气并慢慢开始将哑铃放回起始位置。', '重复建议的重复次数。'],
  'H0371': ['双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。', '弯曲膝盖并将臀部向后推，将身体降低至蹲姿。', '当你到达深蹲底部时，向上爆发，跳离地面。', '在空中时，快速改变双脚的位置，落地时另一只脚向前。', '立即将身体放回蹲姿，然后重复跳跃，再次换脚。', '每次跳跃时继续交替双脚的位置，达到所需的重复次数。'],
  'H1673': ['坐在健身球上，双脚平放在地上，背部挺直。', '一只手握住哑铃，反握，将肘部放在健身球上。', '保持上臂静止，呼气并将哑铃向上弯向肩膀。', '在最高点停顿片刻，然后吸气，慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1293': ['坐在健身球上，双脚平放在地上，双手各握哑铃，放在大腿上。', '慢慢地向前移动双脚，滚动健身球，直到下背部受到球的支撑并且膝盖呈 90 度角。', '将哑铃举至肩高，手掌朝前。', '向上推哑铃，直到手臂完全伸展。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0373': ['坐在长凳或椅子上，背部挺直，双脚平放在地面上。', '双手握住哑铃，掌心朝下，双臂伸直举过头顶。', '保持上臂靠近头部，肘部向前，弯曲肘部，慢慢将哑铃降低到脑后。', '暂停片刻，然后将手臂伸回到起始位置。', '重复所需的重复次数。'],
  'H0374': ['将长凳调整至 45 度倾斜。', '脸朝下躺在长凳上，胸部和腹部靠在长凳上。', '每只手握住一个哑铃，手掌朝下，双臂完全伸展。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1674': ['将长凳调整至 45 度倾斜。', '脸朝下躺在长凳上，双手各握一个哑铃，手掌相对。', '让你的手臂垂直垂向地板，保持肘部稍微弯曲。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1294': ['坐在健身球上，双脚平放在地面上，哑铃放在大腿上。', '慢慢地向前移动你的脚，将健身球沿着你的背部滚动，直到你的头部、颈部和上背部得到球的支撑。', '双手握住哑铃，将手臂伸直至胸部上方，肘部保持轻微弯曲。', '将哑铃放在脑后，保持手臂伸直并保持控制。', '暂停片刻，然后将哑铃举回到起始位置。', '在保持双臂伸展的同时，将臀部抬离地面，挤压臀肌并启动核心肌群。', '将臀部放低至起始位置。', '重复所需的重复次数。'],
  'H1295': ['坐在健身球上，双手握住哑铃，置于胸前，双臂伸展。', '慢慢地将哑铃放到脑后，同时保持手臂伸直。', '暂停片刻，然后将哑铃举回到起始位置。', '重复所需的重复次数。'],
  'H1700': ['双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高。', '稍微弯曲膝盖，身体下沉，然后爆发性伸展双腿，将哑铃压过头顶。', '在动作的最高点锁定手臂，然后将哑铃放回肩部水平。', '重复所需的重复次数。'],
  'H0376': ['双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。', '保持背部挺直并启动核心肌群。', '将手臂向两侧抬起，直到与地板平行，保持肘部稍微弯曲。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H2292': ['双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H0377': ['站立，双脚分开与肩同宽，膝盖稍微弯曲。', '每只手握住一个哑铃，手掌朝向身体。', '腰部向前弯曲，保持背部挺直，核心肌群参与。', '将手臂伸直向下伸向地板，肘部稍微弯曲。', '将哑铃向两侧举起，将肩胛骨挤压在一起。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0378': ['双脚分开与肩同宽站立，每只手各握一个哑铃。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '将双臂笔直向下伸向地面，手掌相对。', '保持肘部轻微弯曲，将手臂向两侧抬起，并将肩胛骨挤压在一起。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H0379': ['双脚分开与肩同宽站立，每只手各握一个哑铃。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '将手臂向两侧举起，肘部保持轻微弯曲，直到与地面平行。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H0381': ['双脚分开与肩同宽站立，每只手各握一个哑铃。', '右脚向后退一步，将身体降低至弓步位置。', '弯曲左膝并降低身体，直到左大腿与地面平行。', '暂停片刻，然后推动左脚跟回到起始位置。', '在另一侧重复，左脚向后退一步。'],
  'H0382': ['站直，双手各握一个哑铃，手掌朝下，双臂完全伸展。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1624': ['平躺在长凳上，双脚平放在地上，膝盖弯曲。', '双手各握一个哑铃，正手握住，手掌朝向脚部。', '将手臂伸直向上伸向天花板，保持肘部轻微弯曲。', '慢慢地将哑铃降低到胸部，让肘部向两侧张开。', '在底部暂停片刻，然后将哑铃推回到起始位置。', '重复所需的重复次数。'],
  'H0383': ['双脚分开与肩同宽站立，每只手各握一个哑铃。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '将双臂伸直在身前，手掌相对。', '保持肘部轻微弯曲，将手臂向两侧抬起，直到与地面平行。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H1330': ['设置一个 45 度角的上斜凳。', '将哑铃放在长凳旁边的地板上。', '面对长凳站立，双脚分开与肩同宽。', '弯曲腰部，将左膝和左手放在长凳上以获得支撑。', '用右手反握（手掌朝下）拿起哑铃。', '保持背部挺直，核心肌群参与。', '将哑铃向上拉向胸部，保持肘部靠近身体。', '在动作的最高点挤压背部肌肉。', '以受控的方式将哑铃放回起始位置。', '重复所需的重复次数。', '换边并用左臂重复练习。'],
  'H1331': ['设置一个 45 度角的上斜凳。', '坐在长凳上，胸部靠在靠背上，双脚平放在地上。', '双手各握一个哑铃，反握。', '身体前倾，双臂伸直下垂，完全伸展。', '将哑铃拉向胸部，将肩胛骨挤压在一起。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H2327': ['站立，双脚分开与肩同宽，膝盖稍微弯曲。', '双手各握一个哑铃，正手握握，手掌朝向身体。', '腰部向前弯曲，保持背部挺直，核心肌群参与。', '让你的手臂伸直垂下，完全伸展，肘部稍微弯曲。', '将哑铃拉向胸部，将肩胛骨挤压在一起。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0384': ['坐在牧师凳上，上臂放在垫子上，胸部靠在支撑物上。', '每只手握住一个哑铃，反握，手掌朝上。', '保持上臂静止，呼气并弯曲哑铃，同时收缩二头肌。', '继续弯举哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1675': ['站直，双手各握一个哑铃，手掌朝向身体，双臂完全伸展。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0385': ['坐在长凳或椅子上，双脚平放在地面上。', '双手各握一个哑铃，正手握握，手掌朝下。', '将前臂放在大腿上，让手腕悬在边缘。', '慢慢向上弯曲手腕，将哑铃拉向身体。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0386': ['双脚分开与肩同宽站立，双手各握一个哑铃，掌心向内。', '稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。', '将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。', '旋转手臂，使手掌朝下。', '慢慢地将手臂放回起始位置。', '重复所需的重复次数。'],
  'H2397': ['坐在长凳上，双手各握一个哑铃，手掌朝前。', '将哑铃举至肩部高度，肘部弯曲，手掌朝前。', '向上推哑铃，直到手臂完全伸展。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0387': ['坐在长凳上，背部挺直，双脚平放在地上。', '每只手握住一个哑铃，手掌朝向身体，手臂向下伸展到身体两侧。', '保持双臂伸直，将一只哑铃举至身前，直至其与地面平行。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '用另一只手臂重复上述步骤。', '双臂交替进行所需的重复次数。'],
  'H1676': ['坐在健身球上，双脚平放在地上，背部挺直。', '每只手握住一个哑铃，手掌朝向身体，双臂完全伸展。', '保持上臂静止，呼气并将一只哑铃向上弯向肩膀，同时保持手掌朝向身体。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气，慢慢将哑铃放回起始位置。', '用另一只手臂重复该动作。', '继续交替手臂进行所需的重复次数。'],
  'H0388': ['坐在长凳上，双手各握一个哑铃，手掌朝前。', '将哑铃举至肩部高度，肘部弯曲，手掌朝前。', '将一只哑铃举过头顶，完全伸展手臂。', '将哑铃放回至肩膀高度。', '用另一只手臂重复上述步骤。', '继续交替手臂进行所需的重复次数。'],
  'H3546': ['坐在长凳上，背部挺直，双脚平放在地上。', '双手各握一个哑铃，掌心向内，将哑铃举至肩高。', '将一个哑铃举过头顶，同时将另一个哑铃保持在与肩同高的位置。', '将举起的哑铃放回肩高，同时将另一个哑铃推过头顶。', '继续交替手臂进行所需的重复次数。'],
  'H0389': ['坐在长凳上，背部挺直，双脚平放在地上。', '双手握住哑铃，将手臂伸直至头顶上方。', '慢慢地将哑铃放到脑后，保持肘部靠近耳朵。', '暂停片刻，然后将哑铃举回到起始位置。', '重复所需的重复次数。'],
  'H2317': ['坐在长凳上，背部挺直，双脚平放在地上。', '双手各握一个哑铃，手掌朝向身体，手臂弯曲成 90 度角。', '保持肘部弯曲，将手臂向两侧抬起，直到与地面平行。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H1730': ['坐在长凳上，双手各握一个哑铃，手掌朝内。', '腰部向前弯曲，保持背部挺直并与地面平行。', '将一只手臂向后伸直，保持靠近身体，直到手臂完全伸展。', '暂停片刻，然后慢慢将哑铃放回起始位置。', '用另一只手臂重复上述步骤。', '继续交替手臂进行所需的重复次数。'],
  'H1737': ['坐在长凳上，双脚平放在地上，每只手各握一个哑铃。', '腰部向前弯曲，保持背部挺直，头部抬起。', '将手臂向后伸直，保持肘部靠近头部。', '暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1677': ['坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。', '保持背部挺直，肘部靠近躯干。', '呼气并将哑铃向上弯向肩膀，收缩二头肌。', '在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0390': ['坐在稳定球上，双脚平放在地面上，背部挺直。', '每只手握住一个哑铃，手掌朝前，双臂完全伸展。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H3547': ['坐在长凳上，背部挺直，双脚平放在地上。', '每只手握住一个哑铃，手掌朝前，双臂完全伸展。', '保持肘部靠近身体两侧，将哑铃向上弯向肩膀。', '前臂垂直后，旋转手腕，使手掌朝前。', '将哑铃推过头顶，直到手臂完全伸展。', '通过反向运动将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1379': ['坐在长凳或椅子上，双脚平放在地面上，并将哑铃放在大腿上。', '将脚掌放在升高的表面（例如台阶或木块）上，脚跟悬在边缘外。', '握住哑铃以保持稳定。', '尽可能高地抬高脚后跟，将身体重量转移到脚掌上。', '在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H0391': ['坐在长凳上，双脚平放在地面上，每只手各握一个哑铃，手掌朝前。', '保持背部挺直，肘部靠近躯干。', '呼气并将哑铃向上弯向肩膀，收缩二头肌。', '在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0392': ['坐在长凳上，双脚平放在地上，每只手各拿一个哑铃，放在大腿上。', '保持背部挺直，核心参与。', '将哑铃举到身前，手掌朝下，直到与肩同高。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1678': ['坐在长凳上，双手各握一个哑铃，手掌朝向躯干，手臂伸直向下。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0393': ['坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。', '将上臂放在大腿上，让哑铃垂下。', '保持上臂不动，通过收缩二头肌将哑铃向肩膀方向卷曲。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0394': ['坐在长凳上，双脚平放在地上，每只手各握一个哑铃。', '稍微弯曲膝盖，从臀部向前倾斜，保持背部挺直。', '将上臂靠近身体两侧，并保持肘部弯曲成 90 度角。', '将手臂向后伸直，在动作的最高点挤压三头肌。', '暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0396': ['坐在长凳上，双脚平放在地上，每只手各拿一个哑铃，放在大腿上。', '保持背部挺直，核心参与。', '将哑铃举至身体两侧，肘部稍微弯曲，直到手臂与地面平行。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0395': ['坐在长凳上，双脚平放在地上，每只手各拿一个哑铃，放在大腿上。', '保持背部挺直，核心参与。', '将哑铃举至身体两侧，肘部稍微弯曲，直到手臂与地面平行。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0397': ['坐在长凳上，双脚平放在地上，双手各握一个哑铃，手掌相对。', '将前臂放在大腿上，让哑铃垂下。', '保持手腕处于中立位置，将哑铃向上弯向肩膀。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1679': ['坐在健身球上，双脚平放在地上，背部挺直。', '一只手握住哑铃，手掌朝上，手臂完全伸展。', '将另一只手放在臀部上以保持稳定。', '慢慢地将哑铃向肩膀弯曲，保持上臂静止。', '在动作的最高点暂停片刻，挤压你的二头肌。', '慢慢地将哑铃放回起始位置。', '重复所需的重复次数。', '交换手臂并重复练习。'],
  'H0398': ['坐在长凳上，双脚平放在地上，一手握住哑铃。', '将躯干的腰部向前弯曲，保持背部挺直并与地面平行。', '将手臂向后伸直，保持肘部靠近身体。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0399': ['坐在长凳上，背部挺直，一只手握住哑铃，将其放在大腿上。', '将哑铃举至肩膀高度，保持肘部靠近身体。', '向外旋转前臂，远离身体，同时保持上臂静止。', '在顶部停顿片刻，然后慢慢旋转前臂回到起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H1380': ['坐在长凳或椅子上，双脚平放在地面上，并将哑铃放在大腿上。', '将一只脚放在凸起的表面上，例如台阶或木块，脚跟悬在边缘之外。', '用锤式握法握住哑铃，这意味着您的手掌相对，手指缠绕在手柄上。', '保持核心收紧，背部挺直，通过脚掌推动，将脚后跟慢慢抬高，尽可能高。', '在顶部暂停片刻，然后慢慢将脚跟放回起始位置。', '重复所需的重复次数，然后换另一条腿。'],
  'H1381': ['坐在长凳或椅子上，背部挺直，双脚平放在地面上。', '一只手握住哑铃，将其放在大腿上方，掌心朝上。', '将一条腿抬离地面并将其延伸到您面前，保持膝盖稍微弯曲。', '通过脚掌推动，尽可能高地抬起脚后跟。', '在顶部停顿片刻，然后慢慢降低脚跟。', '重复所需的重复次数，然后换腿并重复。'],
  'H0401': ['坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。', '将前臂放在大腿上，让手腕悬在边缘。', '慢慢向上弯曲手腕，在动作的最高点挤压前臂。', '暂停片刻，然后将手腕放回起始位置。', '重复所需的重复次数。'],
  'H0402': ['坐在牧师弯举凳上，双脚平放在地板上。', '一只手握住哑铃，反手握住，将上臂靠在讲道垫上。', '保持上臂静止，呼气并将哑铃向上弯向肩膀。', '在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0403': ['坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝上。', '将肘部放在大腿内侧、膝盖上方。', '保持上臂静止，呼气并将哑铃向肩膀弯曲。', '在顶部暂停片刻，挤压你的二头肌。', '吸气，慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1738': ['坐在长凳上，背部挺直，双脚平放在地上。', '反手握住哑铃，将手臂伸直至头顶。', '弯曲肘部，将哑铃降低到头后，保持上臂静止。', '暂停片刻，然后将手臂伸回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0405': ['坐在长凳上，每只手各拿一个哑铃，放在大腿上。', '将哑铃举至肩高，手掌朝前。', '向上推哑铃，直到手臂完全伸过头顶。', '在顶部停顿片刻，然后慢慢将哑铃放回肩部高度。', '重复所需的重复次数。'],
  'H0404': ['坐在长凳上，双手各握一个哑铃，掌心向内。', '将哑铃举至肩高，肘部弯曲，手掌朝前。', '向上推哑铃，直到手臂完全伸过头顶。', '在顶部停顿片刻，然后慢慢将哑铃放回肩部高度。', '重复所需的重复次数。'],
  'H2188': ['坐在长凳上，背部挺直，双脚平放在地上。', '双手握住哑铃，双臂伸直举过头顶。', '弯曲肘部，将哑铃放在脑后，保持上臂靠近耳朵。', '暂停片刻，然后伸直手臂，回到起始位置。', '重复所需的重复次数。'],
  'H0408': ['侧躺，双腿伸直，用手臂支撑头部。', '用你的上手握住哑铃，手掌朝下。', '保持手臂伸直，将哑铃举至肩膀高度。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换边。'],
  'H3664': ['首先侧躺，双腿伸展并叠放在一起。', '将前臂放在肩膀正下方的地面上，保持肘部弯曲成 90 度角。', '用你的上手握住哑铃，手臂垂直向下伸向地面。', '收紧核心并将臀部抬离地面，从头部到脚后跟形成一条直线。', '在保持侧平板支撑位置的同时，将哑铃向天花板方向举起，将肩胛骨挤压在一起。', '将哑铃放回起始位置。', '重复所需的重复次数，然后换边。'],
  'H3548': ['站直，双脚分开与肩同宽，一手握住哑铃。', '将哑铃举过头顶，充分伸展手臂。', '向前行走时，启动核心肌群并保持背部挺直，将哑铃举过头顶。', '继续步行所需的距离或时间。', '交换双手并重复练习。'],
  'H1757': ['双脚分开与臀部同宽站立，右手握住哑铃。', '将体重转移到左腿上，并将右脚稍微抬离地面。', '保持背部挺直，臀部向前转动，将哑铃放低至地面。', '同时，将右腿伸直在身后，保持左膝轻微弯曲。', '降低哑铃，直到躯干和右腿与地面平行。', '暂停片刻，然后收紧臀肌和腿筋，回到起始位置。', '重复所需的重复次数，然后换边。'],
  'H2805': ['双脚分开与臀部同宽站立，右手握住哑铃。', '将左脚放在身后的台阶或高架表面上。', '保持背部挺直，核心收紧，髋部向前转动，将哑铃放低至地面。', '当你放下哑铃时，同时将左腿抬起到身后，从头到脚跟保持一条直线。', '降低哑铃，直到感觉到右腿筋拉伸，然后回到起始位置。', '重复所需的重复次数，然后换边。'],
  'H0411': ['双脚分开与肩同宽站立，每只手各握一个哑铃。', '向前伸展一条腿，并在整个练习过程中保持其离开地面。', '弯曲站立的腿并降低身体，就像坐回椅子上一样。', '保持挺胸、背部挺直。', '在底部停顿片刻，然后用脚跟推动回到起始位置。', '重复所需的重复次数，然后换腿。'],
  'H3560': ['站直，双手各持一个哑铃，手掌朝向身体。', '保持肘部靠近躯干，背部挺直。', '呼气，将右手的哑铃向肩膀弯曲，保持上臂静止。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '吸气，慢慢将哑铃放回起始位置。', '用左手重复卷发动作。', '左手完成弯举后，呼气，将右手的哑铃压过头顶。', '完全伸展手臂并在顶部保持片刻。', '吸气，慢慢将哑铃放回起始位置。', '用左手重复按压。', '继续交替进行弯举和推举，达到所需的重复次数。'],
  'H0414': ['双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝前。', '将一只哑铃举过头顶，完全伸展手臂。', '将哑铃放低至肩部水平。', '用另一只手臂重复上述步骤。', '继续交替手臂进行所需的重复次数。'],
  'H0415': ['双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。', '保持背部挺直，核心肌群参与。', '将一个哑铃举到一侧，保持手臂伸直，手掌朝下。', '继续抬起，直到手臂与地面平行。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '用另一只手臂重复上述步骤。', '双臂交替进行所需的重复次数。'],
  'H1739': ['双脚分开与肩同宽站立，每只手各握一个哑铃。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '双臂向后伸直，保持肘部靠近身体。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '用另一只手臂重复上述动作，每次重复时交替进行。'],
  'H2143': ['双脚分开与肩同宽站立，每只手各握一个哑铃。', '将手臂伸直至两侧，与肩同高，手掌朝下。', '保持手臂伸直，慢慢地以圆周运动旋转手臂，将哑铃放在身体前面，然后举过头顶。', '继续圆周运动，将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H1740': ['双脚分开与肩同宽站立，一只手握住哑铃。', '腰部向前弯曲，保持背部挺直并与地面平行。', '将手臂向后伸直，保持肘部靠近身体。', '慢慢地将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1741': ['双脚分开与肩同宽站立，每只手各握一个哑铃。', '腰部向前弯曲，保持背部挺直，膝盖稍微弯曲。', '双臂向后伸直，保持肘部靠近身体。', '慢慢地将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0416': ['站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0417': ['双脚分开与肩同宽站立，每只手各握一个哑铃。', '用小腿将脚跟抬离地面，尽可能高。', '在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H0418': ['双脚分开与肩同宽站立，一手握住哑铃，手臂完全伸展，手掌朝内。', '将另一只手放在大腿上以获得支撑。', '保持上臂静止，呼气，通过收缩二头肌将哑铃向肩膀弯曲。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气，慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0419': ['双脚分开与肩同宽站立，双手各握一个哑铃，正握。', '保持双臂伸直，将哑铃举至身前，举过头顶。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H2321': ['站直，双手各持一个哑铃，手掌朝向躯干。', '保持肘部靠近躯干，并旋转手掌，直到手掌朝前。', '保持上臂不动，弯曲哑铃，同时收缩二头肌。', '继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气时慢慢开始将哑铃放回起始位置。', '重复建议的重复次数。'],
  'H0420': ['双脚分开与肩同宽站立，每只手各握一个哑铃。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '将手臂向后伸直，在动作的最高点挤压三头肌。', '暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0421': ['站直，双脚分开与肩同宽，一手握住哑铃，掌心朝上。', '将空着的手放在大腿上以获得支撑。', '保持上臂静止，呼气，通过收缩二头肌将哑铃向肩膀弯曲。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气，慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0422': ['双脚分开与肩同宽站立，一手握住哑铃，手掌朝前。', '将另一只手放在倾斜的长凳上以获得支撑。', '保持上臂静止，呼气，通过收缩二头肌将哑铃向肩膀弯曲。', '在最高点停顿片刻，然后吸气，慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H0423': ['双脚分开与肩同宽站立，一只手握住哑铃。', '将哑铃举过头顶，充分伸展手臂。', '保持上臂靠近头部并垂直于地面。', '慢慢地将哑铃放到脑后，弯曲肘部。', '暂停片刻，然后将哑铃举回到起始位置。', '重复所需的重复次数。'],
  'H0424': ['双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝内。', '启动你的核心并保持背部挺直。', '向上推哑铃，直到手臂完全伸展。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0425': ['站直，双脚分开与肩同宽，一只手握住哑铃，正握。', '保持手臂完全伸展并靠近身体，手掌朝下。', '慢慢地将哑铃向上弯向肩膀，保持上臂静止。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0427': ['双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝内。', '保持核心收紧，背部挺直，向上推哑铃，直到手臂完全伸过头顶。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0428': ['站直，双脚分开与肩同宽，每只手各握一个哑铃，手掌朝前。', '将上臂后部靠在牧师凳或上斜凳上，肘部稍微弯曲。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0429': ['站直，双脚分开与肩同宽，双手各握一个哑铃，手掌朝向身体。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H2293': ['站直，双手各持一个哑铃，手掌朝前。', '将上臂靠在牧师凳上，并保持肘部稍微弯曲。', '将哑铃向上弯向肩膀，同时保持上臂静止。', '在动作的最高点，旋转手腕，使手掌朝下。', '慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。', '重复所需的重复次数。'],
  'H1684': ['站在台阶或平台前，每只手各握一个哑铃，手掌朝向身体。', '将右脚放在台阶上，确保整个脚与表面接触。', '启动核心并推动右脚跟，将身体抬起到台阶上，将左膝抬向胸部。', '在动作的最高点，弯曲肘部并将哑铃拉向肩膀，进行二头肌弯举。', '将哑铃放回原处，同时将左脚放回地面。', '在另一侧重复该动作，左脚向上并弯举哑铃。', '继续交替进行所需的重复次数。'],
  'H2796': ['站在台阶或平台前，每只手各持一个哑铃，手掌朝向身体两侧。', '将右脚放在台阶上，确保整个脚都踩在台阶上。', '推动右脚跟，将身体抬起到台阶上，同时将左脚抬起。', '双脚踩在台阶上后，将左脚放回起始位置，并将右脚保持在台阶上。', '重复该动作，每次交替使用哪只脚。', '继续进行所需的重复次数。'],
  'H2812': ['站在长凳或台阶前，每只手各握一个哑铃，手掌朝向身体。', '将右脚放在长凳或台阶上，确保整个脚与表面接触。', '走到长凳上或用右脚踩上，用脚跟推动身体抬起。', '当你向上迈步时，同时将左膝抬向胸部。', '在动作的最高点暂停，然后慢慢将左脚放回地面，同时将右脚放在长凳或台阶上。', '将左脚放在长凳或台阶上，重复该动作。', '继续交替左右脚，达到所需的重复次数。'],
  'H0432': ['双脚分开与肩同宽站立，双手各握一个哑铃，正握。', '保持背部挺直，核心收紧，铰接臀部并将哑铃向地面降低，让膝盖稍微弯曲。', '降低哑铃，直到感觉到腿筋拉伸，然后挤压臀肌并通过脚后跟推回到起始位置。', '重复所需的重复次数。'],
  'H0433': ['平躺在长凳上，头朝一端，双脚牢牢踩在地上。', '双手握住哑铃，将手臂伸直至胸部上方。', '保持手臂伸直，以弧线动作慢慢将哑铃降低到脑后。', '暂停片刻，然后将哑铃举回到起始位置。', '重复所需的重复次数。'],
  'H0434': ['双脚分开与肩同宽站立，双手各握一个哑铃，正握。', '保持背部挺直，核心收紧，以臀部为铰链，将哑铃向地面降低，让躯干向前倾斜。', '继续降低哑铃，直到感觉到腿筋拉伸，保持膝盖稍微弯曲。', '在底部暂停片刻，然后启动臀肌和腿筋，将躯干抬回到起始位置。', '重复所需的重复次数。'],
  'H2808': ['站立，双脚分开比肩宽，脚趾朝外。', '双手握住哑铃置于身体前方，双臂伸展。', '弯曲膝盖，将臀部放低至下蹲位置，保持背部挺直。', '将哑铃放在两腿之间，保持手臂伸直。', '通过脚后跟发力，向前伸展臀部，将哑铃向上拉至身体前方。', '在动作的最高点挤压臀部，然后将哑铃放回双腿之间。', '重复所需的重复次数。'],
  'H2803': ['双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。', '保持挺胸，核心收紧，弯曲膝盖并向后推臀部，慢慢降低身体。', '继续降低，直到大腿与地面平行，或者尽可能低。', '在底部停顿片刻，然后推动脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H1742': ['双脚分开与肩同宽站立，右手握住哑铃。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '将右肘举至身体一侧，保持弯曲 90 度角。', '将右臂向后伸直，挤压三头肌。', '暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数，然后换边。'],
  'H1743': ['平躺在长凳上，双脚平放在地上，背部紧贴长凳。', '双手各握一个哑铃，正手握握，手掌背向自己。', '将手臂伸直越过胸部，保持肘部轻微弯曲。', '将哑铃向胸部方向降低，保持肘部靠近身体。', '放下哑铃时，扭转手腕，使手掌在动作底部面向自己。', '在底部暂停片刻，然后通过将哑铃推回到起始位置来反转动作。', '当你向上推哑铃时，将手腕扭转回起始位置，手掌背向自己。', '重复所需的重复次数。'],
  'H1765': ['双脚分开与肩同宽站立，双手各握一个哑铃，正握。', '让哑铃悬挂在大腿前面，双臂完全伸展，手掌面向身体。', '保持背部挺直，核心收紧，呼气，将哑铃笔直向上举至下巴，用肘部引导。', '继续举起哑铃，直到哑铃与肩同高，肘部指向两侧。', '在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0864': ['双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。', '将手臂向两侧抬起，直到与地面平行，保持肘部稍微弯曲。', '向外旋转手臂，将哑铃举向头部，同时保持肘部处于同一位置。', '在最高点暂停片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H5201': ['站直，双手各持一个哑铃，手掌朝前。', '保持上臂靠近身体，肘部内收。', '慢慢地将哑铃向上弯向肩膀，保持手腕伸直。', '在顶部停顿片刻，然后慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0438': ['坐在长凳上，双手各握一个哑铃，手掌朝前。', '将哑铃举至肩高，肘部弯曲，手掌朝前。', '向上推哑铃，直到手臂完全伸过头顶。', '将哑铃放低至肩部高度。', '重复所需的重复次数。'],
  'H0439': ['站直，双手各持一个哑铃，手掌朝向身体。', '保持肘部靠近躯干，并旋转手掌以面向前方。', '将哑铃举至肩膀处，同时保持上臂静止。', '在动作的最高点，旋转手腕，使手掌背向身体。', '慢慢地将哑铃放回起始位置，将手掌旋转回面向身体。', '重复所需的重复次数。'],
  'H2294': ['坐在牧师凳上，双手各持一个哑铃，手掌朝上，肘部放在垫子上。', '将哑铃向上弯向肩膀，保持上臂静止，手掌朝上。', '在弯举的顶部，旋转手腕，使手掌朝下。', '慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。', '重复所需的重复次数。'],
  'H2189': ['坐在长凳上，背部挺直，双脚平放在地上。', '双手握住哑铃，正握，将其举过头顶。', '弯曲肘部，将哑铃放在脑后，保持上臂靠近耳朵。', '伸展双臂，将哑铃举回到起始位置。', '重复所需的重复次数。'],
  'H1167': ['站直，双脚分开与肩同宽。', '将双臂伸直至两侧，与地面平行。', '慢慢地将双臂向前伸，交叉在身体前面。', '感受胸部肌肉的伸展。', '保持拉伸 10-30 秒。', '返回起始位置并重复所需的重复次数。'],
  'H3287': ['坐在长凳或椅子的边缘，双手抓住臀部旁边的边缘。', '将臀部向前滑离长凳，伸直双腿，保持脚后跟着地。', '弯曲肘部，将身体放低至地面，保持背部靠近长凳。', '在底部停顿片刻，然后双手用力伸直手臂，将身体抬回到起始位置。', '重复所需的重复次数。'],
  'H1772': ['首先，脸朝下躺在地上，双腿伸展，双手直接放在肩膀下方。', '收紧核心并用手掌按压，将上半身抬离地面，保持肘部靠近身体两侧。', '在顶部暂停片刻，挤压上背部肌肉。', '慢慢地将身体放回起始位置。', '重复所需的重复次数。'],
  'H0443': ['首先平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，将上半身抬离地面，将右肘靠近左膝盖。', '同时，将左膝移向右肘，形成扭转动作。', '在顶部停顿片刻，然后慢慢降低上半身并将双腿伸展回到起始位置。', '重复该动作，这次将左肘移向右膝，将右膝移向左肘。', '继续交替进行所需的重复次数。'],
  'H3292': ['双脚分开与肩同宽站立，膝盖稍微弯曲。', '将双手放在臀部或交叉放在胸前。', '保持背部挺直，腰部慢慢向前弯曲，将上半身向地面降低。', '在底部停顿片刻，然后慢慢抬起上半身回到起始位置。', '重复所需的重复次数。'],
  'H1332': ['坐在稳定球上，双脚平放在地面上，背部挺直。', '双手各握一个哑铃，手掌朝内，双臂在身体两侧向下伸展。', '启动你的核心，慢慢地将一只手臂向肩膀抬起，保持肘部稍微弯曲。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '用另一只手臂重复该动作。', '继续交替手臂进行所需的重复次数。'],
  'H1333': ['将稳定球放在地上，面朝下躺在上面，臀部放在球上，双脚靠在墙上以保持稳定。', '将双臂伸直在身前，手掌朝下。', '启动你的核心，慢慢地将上半身抬离球，保持背部挺直，颈部与脊柱成一直线。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H1334': ['将稳定球放在地上，面朝下躺在上面，臀部放在球上。', '将脚靠在墙壁或其他稳定的表面上以获得支撑。', '双臂交叉于脑后，双手触碰后脑勺。', '启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到臀部形成一条直线。', '在动作的最高点暂停片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H1335': ['将稳定球放在地上，面朝下躺在上面，臀部放在球上，双脚靠在墙上以保持稳定。', '将双手放在脑后或交叉在胸前。', '启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到脚后跟形成一条直线。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H1336': ['首先，面朝下躺在稳定球上，臀部放在球上，双脚牢牢踩在地面上。', '将双手放在脑后或交叉放在胸前。', '启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到脚后跟形成一条直线。', '在顶部停顿片刻，然后慢慢将躯干旋转到一侧，保持臀部和腿部稳定。', '返回中心并重复旋转到另一侧。', '将上半身放低至起始位置，然后重复所需的重复次数。'],
  'H1744': ['坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。', '将双手放在臀部旁边的球上，手指指向前方。', '启动你的三头肌并用力推动你的身体，将你的身体抬离球，伸直你的手臂。', '弯曲肘部，将身体放低，使其靠近身体两侧。', '重复所需的重复次数。'],
  'H1559': ['将稳定球放在地上并跪在其前面。', '将右脚放在稳定球上，膝盖弯曲成 90 度角。', '将左腿伸到身后，保持伸直。', '身体前倾，将臀部推向稳定球，直到感觉到右髋屈肌有拉伸感。', '保持拉伸 20-30 秒，然后换边重复。'],
  'H1338': ['坐在稳定球上，双脚平放在地面上，背部挺直。', '用双手握住稳定球，将其抱在靠近胸部的位置。', '启动你的核心肌肉，慢慢向后倾斜，保持背部挺直，双脚踩在地上。', '继续向后倾斜，直到感觉到背部肌肉伸展。', '保持该姿势几秒钟，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H1339': ['坐在稳定球上，双脚平放在地面上，背部挺直。', '一只手握住哑铃，然后将手臂伸直至头顶。', '慢慢地向另一侧倾斜，感受背阔肌的拉伸。', '保持伸展动作 20-30 秒，然后回到起始位置。', '在另一侧重复。'],
  'H1341': ['坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。', '慢慢地向前移动你的脚，将球沿着你的背部滚动，直到你的下背部靠在球上。', '将双手放在脑后或交叉放在胸前。', '启动你的核心，慢慢地将你的上半身降低到地面，让你的下背部伸展到球上方。', '保持伸展几秒钟，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H1342': ['侧躺，双腿伸展，头部由稳定球支撑。', '将上臂放在球上以保持稳定性。', '将上臂举过头顶，让躯干稍微旋转。', '感受身体一侧背阔肌的拉伸。', '保持拉伸 20-30 秒，然后换边重复。'],
  'H1382': ['背靠墙站立，将健身球放在下背部和墙壁之间。', '双脚分开与肩同宽，脚趾指向前方。', '每只手握住一个哑铃，双臂伸向身体两侧。', '将脚跟抬离地面，将身体重量转移到脚掌上。', '在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H3241': ['面向墙壁站立，双脚分开与肩同宽。', '在墙壁和下背部之间放置一个健身球。', '每只手握住一个哑铃，双臂伸向身体两侧。', '将网球放在脚踝之间。', '将脚后跟抬离地面，将身体抬起到脚趾上。', '在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H3240': ['背靠墙站立，将健身球放在下背部和墙壁之间。', '将双脚分开与肩同宽，并稍微位于您的前方。', '每只手握住一个哑铃，双臂伸向身体两侧。', '将网球放在膝盖之间。', '将脚后跟抬离地面，将身体抬起到脚趾上。', '在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H1416': ['面朝下躺在稳定球上，臀部放在球上，双腿伸直在身后。', '将双手放在身前的地面上以获得支撑。', '调动你的臀肌和核心肌肉来稳定你的身体。', '慢慢地将一条腿抬离地面，保持笔直并与地板平行。', '向外旋转腿部，远离身体，同时保持臀部和上半身稳定。', '旋转结束时暂停片刻，然后慢慢地将腿放回起始位置。', '用另一条腿重复旋转。', '继续交替双腿达到所需的重复次数。'],
  'H1417': ['首先仰卧，双腿伸展，脚跟放在稳定球上。', '将手臂放在身体两侧以保持稳定。', '调动臀肌和核心肌肉，将臀部抬离地面，从肩膀到脚后跟形成一条直线。', '弯曲右膝并将其靠近胸部，保持左腿伸展，脚部弯曲。', '将右腿斜踢过身体，完全伸展并拉动腿筋。', '慢慢地将右腿返回到起始位置，保持控制和稳定性。', '用左腿重复该动作，交替进行所需的重复次数。'],
  'H1296': ['从俯卧撑位置开始，双手放在地板上，小腿放在稳定球上。', '收紧核心肌群，将臀部抬向天花板，将球滚向双手。', '保持双腿伸直，身体呈屈体姿势，形成倒V字形。', '弯曲肘部，将上半身降低到地板上，保持头部与双手在一条直线上。', '用手推动并伸展双臂以返回到起始位置。', '重复所需的重复次数。'],
  'H1343': ['面朝下躺在垫子上，双腿伸展，脚趾放在稳定球上。', '将双手放在地上，与肩同宽，锻炼核心肌肉。', '保持双腿伸直，慢慢将它们抬离地面，用下背部和臀部将它们尽可能抬高。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H1560': ['坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。', '慢慢地向前滚动球，双脚向外走，直到上背部靠在球上，双腿在身前伸直。', '将双手放在臀部上以获得支撑。', '启动你的核心，慢慢地将上半身降低到地面，保持背部挺直，胸部抬起。', '当您感觉到腿筋拉伸时停止，并保持该姿势 20-30 秒。', '通过推动脚后跟并使用腿筋将自己拉回来，慢慢回到起始位置。', '重复所需的重复次数。'],
  'H1745': ['坐在稳定球上，双脚平放在地面上，背部挺直。', '一只手握住哑铃，将手臂伸直至头顶上方。', '弯曲肘部，将哑铃放在脑后，保持上臂靠近耳朵。', '保持伸展几秒钟，然后回到起始位置。', '用另一只手臂重复上述步骤。'],
  'H1746': ['坐在健身球上，双脚平放在地上，膝盖弯曲成 90 度角。', '双手握住哑铃，双臂伸直向天花板方向伸展。', '慢慢地将哑铃放到脑后，保持肘部靠近耳朵。', '暂停片刻，然后将哑铃举回到起始位置。', '重复所需的重复次数。'],
  'H1747': ['坐在健身球上，正手握住 EZ 杠铃。', '向上伸展双臂，保持肘部靠近头部。', '弯曲肘部，慢慢将杠铃降低到脑后。', '暂停片刻，然后将手臂伸回到起始位置。', '重复所需的重复次数。'],
  'H3010': ['平躺在长凳上，头放在一端，双脚放在地板上。', '旋前握住 EZ 杠铃（手掌背向您），双手与肩同宽。', '将手臂伸直至胸部上方，保持肘部轻微弯曲。', '以弧线动作将杠铃降低到头后，保持肘部轻微弯曲。', '暂停片刻，然后通过反向弧线运动将杠铃返回到起始位置。', '重复所需的重复次数。'],
  'H1748': ['平躺在长凳上，双脚平放在地上，头放在长凳的末端。', '紧紧握住 ez 杠铃，手掌朝上，将手臂伸直至胸部上方。', '保持上臂静止，弯曲肘部，慢慢将杠铃降低到脑后。', '暂停片刻，然后将手臂伸回到起始位置。', '重复所需的重复次数。'],
  'H1344': ['站立，双脚分开与肩同宽，膝盖稍微弯曲。', '反手握住 ez 杠铃，手掌朝上，双手与肩同宽。', '臀部向前弯曲，保持背部挺直，挺胸，直到躯干几乎与地板平行。', '将 ez 杠铃拉向下胸部，将肩胛骨挤压在一起。', '在顶部暂停片刻，然后慢慢将 ez 杠铃放回起始位置。', '重复所需的重复次数。'],
  'H1682': ['坐在长凳上，双脚平放在地面上，反手握住 EZ 杠铃。', '将肘部放在大腿内侧、膝盖上方。', '将杠铃向上弯向肩膀，同时保持上臂静止。', '在动作的最高点挤压二头肌，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H1749': ['双脚分开与肩同宽站立，正手握住杠铃。', '将杠铃举过头顶，充分伸展双臂。', '保持上臂靠近头部，弯曲肘部，慢慢将杠铃降低到脑后。', '暂停片刻，然后将手臂伸回到起始位置。', '重复所需的重复次数。'],
  'H0445': ['首先，双脚分开与肩同宽站立，并用正手握住杠铃。', '将杠铃举至肩膀高度，保持肘部稍微弯曲，手掌朝前。', '将杠铃推过头顶，充分伸展双臂。', '将杠铃降低回肩部高度，然后重复所需的重复次数。'],
  'H1627': ['坐在牧师弯举凳上，将上臂放在垫子上，反手握住 ez 杠铃。', '将三头肌放在垫子上，充分伸展手臂，保持背部挺直。', '慢慢地将杠铃向肩膀弯曲，收缩二头肌。', '在顶部暂停片刻，挤压你的二头肌。', '将杠铃放回起始位置，充分伸展双臂。', '重复所需的重复次数。'],
  'H0446': ['站直，双脚分开与肩同宽，反手握住杠铃，双手分开与肩同宽。', '在整个运动过程中，保持肘部靠近躯干，上臂保持静止。', '将杠铃向上弯向肩膀，收缩二头肌。', '在顶部停顿片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0447': ['站直，双脚分开与肩同宽，反手握住 ez 杠铃，手掌朝上。', '在整个运动过程中，保持肘部靠近躯干，上臂保持静止。', '当你将杠铃向肩膀方向卷曲时呼气，收缩二头肌。', '在顶部暂停片刻，然后吸气，慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0448': ['躺在倾斜的长凳上，头低于脚。', '紧紧抓住 ez 杠铃，手掌相对。', '将手臂伸直至胸部上方，保持肘部靠近身体。', '弯曲肘部，将杠铃降低到前额。', '暂停片刻，然后将杠铃推回到起始位置。', '重复所需的重复次数。'],
  'H2186': ['躺在倾斜的长凳上，头低于脚，双脚固定。', '正手握住 ez 杠铃，双手与肩同宽。', '充分伸展双臂，保持肘部靠近头部。', '将杠铃慢慢降低到前额，弯曲肘部。', '暂停片刻，然后将手臂伸回到起始位置。', '重复所需的重复次数。'],
  'H0449': ['设置一个 45 度角的上斜凳。', '坐在长凳上，背部靠在垫子上，正手握住 ez 杠铃。', '将手臂完全伸过头顶，保持肘部靠近头部。', '弯曲肘部，将杠铃降低到头后，保持上臂静止。', '暂停片刻，然后将手臂伸回到起始位置。', '重复所需的重复次数。'],
  'H0450': ['平躺在长凳上，双脚平放在地上，背部紧贴长凳。', '正手握住杠铃，握距略宽于肩宽。', '将杠铃降低到胸部，保持肘部靠近身体。', '将杠铃推回到起始位置，完全伸展双臂。', '重复所需的重复次数。'],
  'H0451': ['站直，双脚分开与肩同宽，反手握住 ez 杠铃。', '在整个练习过程中，保持肘部靠近躯干，上臂保持静止。', '通过收缩二头肌将杠铃向上卷曲，同时呼气。', '继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气时慢慢开始将杠铃拉回起始位置。', '重复所需的重复次数。'],
  'H0452': ['坐在牧师凳上，胸部靠在垫子上，双脚平放在地板上。', '反手抓住 ez 杠铃，双手与肩同宽。', '将上臂放在垫子上，让前臂下垂。', '保持上臂静止，呼气并将杠铃向上弯向肩膀。', '在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H1458': ['坐在长凳上，双脚平放在地上，背部挺直。', '反手握住 ez 杠铃，手掌朝上，双手与肩同宽。', '将上臂放在大腿上，让 ez 杠铃垂在您面前。', '保持上臂静止，呼气并将杠铃向上卷曲至肩膀。', '在顶部暂停片刻，挤压你的二头肌。', '吸气并缓慢地将 ez 杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0453': ['坐在长凳上，背部挺直，双脚平放在地上。', '正手握住 ez 杠铃，双手与肩同宽。', '将杠铃举过头顶，充分伸展双臂。', '保持上臂静止，弯曲肘部将杠铃降低到脑后。', '暂停片刻，然后伸展双臂将杠铃举回起始位置。', '重复所需的重复次数。'],
  'H0454': ['双脚分开与肩同宽站立，反手握住杠铃，手掌朝上。', '将上臂放在牧师凳或稳定球上，让肘部下垂。', '保持上臂静止，呼气并将杠铃向上弯向肩膀。', '在顶部暂停片刻，挤压你的二头肌。', '吸气并慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H2404': ['站直，双脚分开与肩同宽，反手握住 ez 杠铃，手掌朝上。', '将上臂靠在手臂冲击波上，在整个练习过程中保持静止。', '保持肘部靠近身体，呼气并将杠铃向上弯向肩膀。', '在顶部暂停片刻，挤压你的二头肌。', '吸气，慢慢将杠铃放回起始位置，充分伸展双臂。', '重复所需的重复次数。'],
  'H2432': ['平躺在长凳上，双脚平放在地上，背部紧贴长凳。', '紧握杠铃，双手与肩同宽，掌心向前。', '将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。', '慢慢地将杠铃降低到胸部，保持肘部靠近身体。', '当杠铃触及胸部时暂停片刻。', '将杠铃推回到起始位置，完全伸展双臂。', '重复所需的重复次数。'],
  'H2741': ['站直，双脚分开与肩同宽，反手握住杠铃，双手分开比肩宽。', '在整个运动过程中，保持肘部靠近躯干，上臂保持静止。', '收缩二头肌，将杠铃向上弯向肩膀。', '在顶部停顿片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H2133': ['站直，双手各握一个哑铃，手掌朝向身体两侧。', '保持背部挺直，肩膀向后。', '向前迈出小步，控制住，保持直立姿势。', '继续步行所需的距离或时间。', '最后，停止行走并小心地将哑铃降低到身体两侧。'],
  'H0455': ['坐在长凳上，双脚平放在地面上，反手握住杠铃，手掌朝上。', '将前臂放在大腿上，让手腕悬在边缘。', '慢慢地将手指向手掌弯曲，紧紧挤压杠铃。', '保持收缩一会儿，然后慢慢松开手指回到起始位置。', '重复所需的重复次数。'],
  'H3303': ['首先，双手握住一根垂直杆，手掌相对，双臂完全伸展。', '启动你的核心并将双腿抬离地面，保持伸直。', '利用核心和上半身的力量，抬起双腿，直到它们与地面平行。', '尽可能长时间地保持这个姿势，保持身体线条笔直。', '慢慢地将双腿放回起始位置。', '重复所需的重复次数。'],
  'H0456': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。', '同时，将双腿抬离地面，弯曲膝盖并将其拉向胸部。', '在顶部停顿片刻，然后慢慢降低上半身和双腿回到起始位置。', '重复所需的重复次数。'],
  'H0457': ['平躺，双腿伸直，双臂伸直至头顶上方。', '收紧腹肌，将上半身抬离地面，同时将双腿抬向胸部。', '抬起上半身和腿部时，将双手伸向脚趾。', '在顶部停顿片刻，然后慢慢降低上半身和双腿回到起始位置。', '重复所需的重复次数。'],
  'H0458': ['仰卧在地板上，膝盖弯曲，双脚平放在地面上。', '正手握住杠铃，双臂伸直越过胸部。', '慢慢地将杠铃向两侧放低，保持肘部轻微弯曲。', '降低杠铃，直到手臂与地板平行，感觉胸部有拉伸感。', '暂停片刻，然后挤压胸部肌肉，使杠铃回到起始位置。', '重复所需的重复次数。'],
  'H0459': ['平躺，双腿伸展，双手放在身体两侧。', '收紧核心肌群并将双腿抬离地面约 6 英寸。', '保持双腿伸直，交替将一条腿抬得比另一条腿稍高。', '继续这个颤动动作达到所需的重复次数。'],
  'H1472': ['双脚分开与肩同宽站立。', '弯曲膝盖并将身体降低至蹲姿。', '向后摆动手臂以获得动力。', '爆发性地向前跳跃，伸展臀部、膝盖和脚踝。', '脚掌轻轻落地，然后立即进入下一个跳跃。', '重复所需的重复次数。'],
  'H3470': ['站立，双脚分开与臀部同宽，双手放在臀部。', '右脚向前迈出一大步，将身体降低到弓步位置。', '将右膝盖弯曲约 90 度，保持膝盖与脚踝对齐。', '用右脚推出并返回到起始位置。', '用左腿重复上述动作，交替进行所需的重复次数。'],
  'H3194': ['双脚分开与肩同宽站立，双臂伸直将杠铃举在身体前方。', '保持背部挺直，弯曲膝盖和臀部，降低身体，就像坐回椅子上一样。', '继续降低，直到大腿与地面平行，或者尽可能低。', '暂停片刻，然后用力推动脚后跟，回到起始位置。', '重复所需的重复次数。'],
  'H2429': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，将上半身抬离地面，向前卷曲直到躯干呈 45 度角。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H3301': ['从俯卧撑位置开始，双手与肩同宽，双脚并拢。', '弯曲肘部，将身体放低至地面，保持背部挺直。', '当你降低身体时，将双脚抬离地面，并将膝盖靠近胸部。', '保持这个姿势几秒钟，然后向后伸展双腿，并将自己推回到起始位置。', '重复所需的重复次数。'],
  'H3296': ['首先，用正手握法悬挂在引体向上杆上，双手与肩同宽。', '启动你的核心并将肩胛骨向下拉和向后拉。', '弯曲膝盖并将其向胸部靠拢。', '同时，抬起双腿并将其伸直在您面前，保持身体与地面平行。', '尽可能长时间地保持此位置，以达到完全前杆位置。', '要释放，请慢慢降低双腿并返回到起始位置。', '重复所需的重复次数。'],
  'H3295': ['正手握住引体向上杆，手掌背向自己。', '启动你的核心并将肩胛骨向下拉和向后拉。', '保持身体挺直，抬起双腿直至与地面平行。', '尽可能长时间地保持这个姿势，目标是 10-20 秒。', '慢慢地将双腿放回起始位置。', '重复所需的重复次数。'],
  'H0464': ['从高平板支撑位置开始，双手直接放在肩膀下方，身体从头到脚成一条直线。', '调动你的核心和臀部以保持稳定的位置。', '将躯干向右旋转，抬起右臂并向天花板延伸。', '扭转时保持臀部和腿部稳定。', '保持片刻，然后回到起始位置。', '在左侧重复扭转。', '继续交替进行所需的重复次数。'],
  'H3315': ['首先站立，双脚分开与肩同宽，双臂伸直至两侧。', '慢慢向前倾斜，保持手臂伸直，直到上半身与地面平行。', '启动你的核心并保持这个姿势几秒钟。', '通过双脚推动并站起来，回到起始位置。', '重复所需的重复次数。'],
  'H3299': ['从俯卧撑位置开始，双手与肩同宽，手指指向前方。', '启动你的核心并缓慢地将你的重心向前移动，将你的脚抬离地面。', '继续向前移动体重，直到身体与地面平行，并用双手保持平衡。', '尽可能长时间地保持这个姿势，保持身体线条笔直。', '慢慢地将双脚放回地面，然后回到起始位置。', '重复所需的重复次数。'],
  'H3327': ['从俯卧撑位置开始，双手分开略宽于肩宽。', '收紧核心肌群，将身体放低至地面，保持肘部靠近身体两侧。', '当你降低身体高度时，身体向前倾斜，双脚离开地面，用双手保持平衡。', '继续降低身体，直到胸部略高于地面。', '用手推动并伸展双臂，将身体抬回到起始位置。', '在整个运动过程中，从头部到脚后跟保持一条直线。', '重复所需的重复次数。'],
  'H0466': ['面向高杠站立，双脚分开与肩同宽。', '向上伸手，正手握住杠铃，握距略宽于肩宽。', '悬挂在杠上，双臂完全伸展，身体伸直。', '用你的背阔肌和二头肌将你的胸部拉向杠铃杆，以胸骨为主导。', '在最高点暂停片刻，然后慢慢降低回到起始位置。', '重复所需的重复次数。'],
  'H3523': ['坐在长凳边缘，背靠着长凳，双脚平放在地上。', '将双手放在臀部旁边的长凳上以获得支撑。', '收紧臀肌和腿筋，然后将臀部抬离长凳，直到身体从膝盖到肩膀形成一条直线。', '在顶部暂停片刻，然后慢慢将臀部放回起始位置。', '重复所需的重复次数。'],
  'H3193': ['调整臀肌提升机以适合您的身体。', '将自己面朝下放在机器上，固定脚踝。', '将双手放在胸前或交叉在胸前。', '调动腿筋和臀肌，将上半身抬向天花板。', '继续抬起，直到身体从头部到脚后跟成一条直线。', '在顶部停顿片刻，然后慢慢将身体放回起始位置。', '重复所需的重复次数。'],
  'H0467': ['双脚分开与肩同宽站立，膝盖稍微弯曲。', '正手握住引体向上杆，握距略宽于肩宽。', '悬挂在杠上，双臂完全伸展，手掌背向自己。', '收紧核心肌群，将身体拉向杠铃杆，将下巴置于杠铃上方。', '在顶部停顿片刻，然后慢慢将身体放回起始位置。', '重复所需的重复次数。'],
  'H0469': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，将双腿抬离地面，将膝盖靠近胸部。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H1383': ['将雪橇机调整至舒适的重量。', '站在雪橇机上，脚趾放在平台上，脚后跟悬空。', '握住手柄以保持稳定性。', '通过推动脚掌将脚后跟尽可能抬高。', '在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H1384': ['将雪橇机调整到合适的重量。', '一脚站在雪橇机上，另一只脚离开地面。', '握住手柄以保持稳定性。', '尽可能高地抬高脚跟，用脚掌抬起身体。', '在顶部暂停片刻，然后慢慢将脚跟放回起始位置。', '重复所需的重复次数。', '换腿并重复练习。'],
  'H3221': ['双脚分开与肩同宽站立。', '弯曲膝盖并降低身体，就像坐回椅子上一样。', '保持挺胸，将体重放在脚后跟上。', '在底部停顿片刻，然后推动脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H3202': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H2139': ['将座椅高度和车把位置调整至舒适的水平。', '坐在测力计上，背部挺直，双脚放在踏板上。', '双手抓住手柄，并将手臂呈 90 度角。', '开始用手踩踏板，以受控的动作推拉手柄。', '继续踩踏所需的持续时间或重复次数。'],
  'H3218': ['双脚分开与肩同宽站立，双手合十放在胸前。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '将双手向脚趾方向以打圈的方式降低，尽量伸得尽可能远，但不要用力。', '在底部停顿片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H3215': ['双脚分开与肩同宽站立，双臂向两侧伸展。', '腰部向前弯曲，保持背部挺直，膝盖稍微弯曲。', '双手向下伸，并在腿后将它们握在一起。', '慢慢地将双手举过头顶，做圆周运动，保持双腿伸直。', '继续圆周运动，直到双手触及脚趾。', '反转动作并将双手放回起始位置。', '重复所需的重复次数。'],
  'H3302': ['找到一个有足够空间的空地来进行倒立。', '将双手放在地上，与肩同宽，手指指向前方。', '将双腿向上踢向墙壁，用核心和肩膀保持平衡。', '处于倒立位置后，用三头肌来支撑体重。', '只要能保持平衡，就保持倒立。', '下降时，慢慢将双腿放回地面。', '重复所需的重复次数。'],
  'H1764': ['悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。', '弯曲臀部和膝盖，收紧核心并抬起双腿，直到大腿与地面平行。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H1761': ['悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。', '收紧核心并将膝盖抬向胸部，同时将躯干扭转到一侧。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '在另一侧重复上述步骤，向相反方向扭转躯干。', '继续交替进行所需的重复次数。'],
  'H0473': ['悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。', '收紧核心肌群，将双腿向杠铃方向抬起，保持伸直。', '继续抬起身体，直到身体形成“V”形，双腿与地面平行。', '保持该姿势片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H0474': ['悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。', '启动你的核心并将双腿抬起到你面前，直到它们与地面平行。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H0475': ['悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。', '启动你的核心并将双腿抬起到你面前，保持伸直。', '继续抬起，直到双腿与地面平行或达到您可以舒适地达到的高度。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H0476': ['悬挂在引体向上杆上，双臂完全伸展，双腿伸直。', '启动你的核心并将双腿抬向胸部，保持伸直。', '一旦双腿与地面平行，将臀部向一侧扭转，将双腿移向一侧。', '暂停片刻，然后回到起始位置。', '重复这个动作，但这次将臀部扭向另一侧。', '继续交替进行所需的重复次数。'],
  'H3636': ['面向墙壁站立，双脚分开与臀部同宽。', '将双手放在墙上以获得支撑。', '启动你的核心并将右膝抬向胸部，同时将左脚保持在地面上。', '快速换腿，将左膝抬向胸部，然后将右脚放低。', '继续交替双腿进行跑步动作，将膝盖尽可能抬高。', '在整个练习过程中保持快节奏并保持上半身稳定。', '重复所需的持续时间或重复次数。'],
  'H0484': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在身体两侧，掌心朝下。', '收紧核心肌群和臀肌，然后将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。', '在顶部暂停片刻，然后慢慢将臀部放回起始位置。', '重复所需的重复次数。'],
  'H1418': ['首先站立，双脚分开与肩同宽。', '弯曲膝盖并将身体降低至蹲姿。', '当你蹲下时，将膝盖抬向胸部，并用手臂抱住它们。', '保持这个姿势一会儿，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H3234': ['平躺在长凳上，双手各握一个哑铃，手掌相对。', '将手臂伸直越过胸部，肘部稍微弯曲。', '保持肘部轻微弯曲，以宽弧线将哑铃向两侧放低，直到感觉到胸部有拉伸感。', '暂停片刻，然后反转动作，将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0489': ['调整过度伸展凳，使大腿上部放在垫子上并且双脚固定。', '双臂交叉放在胸前或将双手放在脑后。', '将上半身压向地面，同时保持背部挺直。', '在底部停顿片刻，然后抬起上半身，直到与双腿成一直线。', '重复所需的重复次数。'],
  'H0488': ['调整过度伸展凳，使臀部舒适地放在垫子上，并且双脚固定。', '双臂交叉放在胸前或将双手放在脑后。', '慢慢地将上半身降低到地面，同时保持背部挺直。', '在底部停顿片刻，然后抬起上半身，直到与双腿成一直线。', '重复所需的重复次数。'],
  'H3289': ['将自己定位在两个双杠之间，双臂完全伸展，身体悬浮在空中。', '弯曲膝盖并交叉脚踝。', '弯曲肘部降低身体，直到上臂与地面平行。', '暂停片刻，然后伸直手臂，将自己推回起始位置。', '重复所需的重复次数。'],
  'H3698': ['从站立位置开始，双脚分开与臀部同宽。', '腰部向前弯曲，双手放在身前的地面上。', '双手向前移动，直到处于高位平板支撑位置，身体从头到脚成一条直线。', '保持双腿伸直，将脚移向双手，将臀部抬向天花板。', '继续向前移动双手，重复该动作达到所需的重复次数。'],
  'H0490': ['将双手放在较高的表面上，例如长凳或台阶上，双手之间的距离略宽于肩宽。', '将双腿伸到身后，放在脚掌上，身体从头到脚跟形成一条直线。', '弯曲肘部，使肘部靠近身体两侧，将胸部降低到升高的表面。', '在底部暂停片刻，然后伸直手臂将自己推回起始位置。', '重复所需的重复次数。'],
  'H0491': ['躺在倾斜的长凳上，背部平放在长凳上，双腿伸直在身前。', '将双手放在长凳两侧以获得支撑。', '收紧腹肌，将双腿抬离长凳，尽可能抬高双腿，同时保持伸直。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H0492': ['找到一个较高的表面，例如长凳或台阶，并将双手与肩同宽放在边缘。', '双脚向后退一步，保持身体从头到脚跟呈一条直线。', '将胸部向水面边缘降低，弯曲肘部并保持身体对齐。', '推动手掌以伸展手臂并返回到起始位置。', '从水面边缘跳下，膝盖稍微弯曲，轻轻落地。', '重复俯卧撑和深度跳跃达到所需的重复次数。'],
  'H3785': ['将双手放在盒子或高架表面的边缘，距离略宽于肩宽。', '将双腿伸到身后，放在脚掌上，从头到脚跟形成一条直线。', '弯曲肘部，将胸部向箱子方向降低，保持身体呈一条直线。', '在底部暂停片刻，然后伸直手臂将自己推回起始位置。', '重复所需的重复次数。'],
  'H0494': ['将双手放在长凳或高架表面的边缘，距离略宽于肩宽。', '将双腿伸到身后，放在脚掌上，从头到脚跟形成一条直线。', '弯曲肘部，将胸部向长凳方向降低，使其靠近身体两侧。', '在底部暂停片刻，然后伸展双臂将自己推回起始位置。', '重复所需的重复次数。'],
  'H3011': ['设置一个 45 度角的上斜凳。', '将双手放在长凳上，距离略比肩宽。', '将双脚放在地面上，距离与臀部同宽。', '将胸部向长凳方向降低，保持肘部内收。', '当你降低时，缩回肩胛骨，将肩胛骨挤压在一起。', '推动手掌以伸展手臂并返回到起始位置。', '重复所需的重复次数。'],
  'H0495': ['设置一个 45 度角的上斜凳。', '躺在长凳上，双脚固定在脚垫下。', '将双手放在脑后或放在胸前。', '收紧腹肌，将上半身抬离长凳，向前卷曲。', '当你蜷缩起来时，将你的躯干扭转到一侧，将你的肘部拉向另一侧的膝盖。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复这个动作，这次将你的躯干扭转到另一侧。', '继续交替进行所需的重复次数。'],
  'H1564': ['站直，双脚分开与肩同宽。', '抓住一个稳定的物体作为支撑。', '弯曲右膝，将右脚移向臀部，用右手抓住绳子。', '慢慢地将右脚拉向臀部，感受右股四头肌的拉伸。', '保持拉伸 20-30 秒。', '松开拉伸并在左侧重复。'],
  'H0496': ['脸朝下躺在长凳上，臀部位于边缘，双腿伸直在身后。', '抓住长凳以获得支撑。', '保持上半身不动，弯曲膝盖并将双腿向臀部弯曲。', '在顶部停顿片刻，然后慢慢将双腿伸展回起始位置。', '重复所需的重复次数。'],
  'H2400': ['调整缆绳机，使踝带处于最低设置。', '面朝下躺在长凳上，双腿伸展，脚踝带固定在脚上。', '握住长凳的把手以保持稳定。', '弯曲膝盖，将双腿向臀部弯曲，挤压腿筋。', '在动作的最高点暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H0499': ['在腰部高度设置一个杠铃或使用悬挂训练器。', '面向杠铃或悬吊训练器站立，双脚分开与肩同宽。', '正手握住杠铃或手柄，握距略宽于肩宽。', '向后倾斜，保持身体挺直，脚后跟着地。', '将胸部拉向杠铃或手柄，将肩胛骨挤压在一起。', '在顶部停顿片刻，然后慢慢降低回到起始位置。', '重复所需的重复次数。'],
  'H2300': ['在腰部高度设置一根横杆，然后躺在其下方。', '正手握住杠铃，握距略宽于肩宽。', '调整身体位置，使脚后跟着地，身体伸直。', '将肩胛骨挤压在一起，将胸部向上拉向杠铃。', '在顶部停顿片刻，然后慢慢将身体放回起始位置。', '重复所需的重复次数。'],
  'H2298': ['设置一张长凳，其高度应让您的身体可以自由地悬挂在其下方。', '面朝上躺在地上，头朝向长凳。', '向上伸手，正手握住长凳，握距略宽于肩宽。', '调整身体位置，使脚后跟着地，手臂完全伸展。', '当你将胸部拉向长凳时，启动你的核心并将肩胛骨挤压在一起。', '在动作的最高点停顿片刻，然后慢慢降低身体回到起始位置。', '重复所需的重复次数。'],
  'H0497': ['在史密斯机上在腰部高度设置一根杠铃或使用悬挂训练器。', '面向杠铃或悬吊训练器站立，用正手握法抓住它，双手与肩同宽。', '双脚向前走，向后倾斜，直到身体呈轻微角度。', '保持身体挺直，将胸部向上拉向杠铃或手柄，将肩胛骨挤压在一起。', '在最高点暂停片刻，然后慢慢降低回到起始位置。', '重复所需的重复次数。'],
  'H0498': ['在胸部高度设置悬挂训练器或带子。', '面向锚点站立，并用正手握住手柄。', '双脚向前走，向后倾斜，直到身体呈一定角度。', '保持身体挺直并启动核心。', '将胸部拉向手柄，将肩胛骨挤压在一起。', '在顶部停顿片刻，然后慢慢降低回到起始位置。', '重复所需的重复次数。'],
  'H1419': ['平躺，双臂向两侧伸展。', '将双腿抬向天花板，保持伸直。', '慢慢地将双腿降低到一侧，旨在用脚接触地板。', '保持伸展几秒钟，然后将双腿恢复到起始位置。', '在另一侧重复拉伸。', '继续交替进行所需的重复次数。'],
  'H1297': ['双脚分开与肩同宽站立，膝盖稍微弯曲。', '将双臂伸直在身前，与地面平行，手掌相对。', '尽可能用力挤压胸部肌肉，同时保持手臂伸直。', '保持这个姿势几秒钟，专注于收缩胸部肌肉。', '释放挤压并放松胸部肌肉。', '重复所需的重复次数。'],
  'H0500': ['首先平躺在垫子或长凳上。', '将手臂伸直至两侧，与身体垂直。', '启动你的核心并将双腿抬离地面，保持它们并拢并伸直。', '慢慢地将双腿向一侧降低，目标是用脚接触地面，同时保持控制。', '暂停片刻，然后用核心力量将双腿抬回到起始位置。', '重复该动作，这次将双腿降低到另一侧。', '继续交替进行所需的重复次数。'],
  'H0501': ['从站立位置开始，双脚分开与肩同宽。', '将身体降低至蹲姿，将双手放在身前的地面上。', '双脚向后踢，以俯卧撑姿势落地。', '进行俯卧撑，将胸部降低到地面，然后再向上推。', '双脚向前跳，以蹲姿落地。', '爆发性地跳起，将双臂举过头顶。', '轻轻落地并立即回到蹲姿，开始下一次重复。'],
  'H3224': ['双脚并拢站立，双臂放在身体两侧。', '跳起来，分开双脚，将手臂举过头顶。', '当你落地时，迅速跳回起始位置。', '重复所需的重复次数。'],
  'H0507': ['平躺，双腿伸展，双臂举过头顶。', '启动你的核心，同时抬起双腿和上半身，将双手伸向脚趾。', '在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。', '重复所需的重复次数。'],
  'H0508': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H0514': ['双脚分开与肩同宽站立。', '弯曲膝盖并将臀部向后推，将身体降低至蹲姿。', '爆发性地跳离地面，伸展臀部、膝盖和脚踝。', '在半空中时，快速将手臂向前伸以保持平衡。', '脚掌轻轻落地，然后立即进入下一个重复动作。', '重复所需的重复次数。'],
  'H0513': ['双脚分开与肩同宽站立。', '弯曲膝盖并将臀部向后推，将身体降低至蹲姿。', '爆发力跳跃，充分伸展臀部和膝盖。', '脚掌轻轻着地，然后立即将身体放回蹲姿。', '重复所需的重复次数。'],
  'H0517': ['站立，双脚分开比肩宽，脚趾稍微向外。', '右手握住壶铃，手臂伸过头顶，手掌朝前。', '将左脚稍微向右旋转，并将重量转移到左腿上。', '弯曲左膝并铰接在臀部，将躯干向左侧降低。', '保持右臂伸过头顶，眼睛盯着壶铃。', '当你降低躯干时，让右腿伸直，右脚稍微转动。', '降低躯干，直到感觉到左腿筋拉伸并且右臂指向地面。', '暂停片刻，然后启动核心并推动左脚跟返回到起始位置。', '重复所需的重复次数，然后换边。'],
  'H0518': ['双脚分开与肩同宽站立，双手各握一个壶铃，正手握住。', '稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。', '让壶铃悬挂在身体前方，双臂完全伸展。', '以一种流畅的动作，爆发性地伸展臀部，耸肩，并将壶铃拉向肩膀。', '当壶铃到达肩膀高度时，旋转手腕并将壶铃抓住在架子位置，手掌朝内，壶铃放在前臂外侧。', '将壶铃放回起始位置，然后用另一只手臂重复该动作。', '继续交替手臂进行所需的重复次数。'],
  'H0520': ['双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。', '将一只壶铃按过头顶，完全伸展手臂。', '将壶铃降低至肩膀高度。', '用另一只手臂重复上述步骤。', '继续交替手臂进行所需的重复次数。'],
  'H0519': ['首先仰卧在地板上，膝盖弯曲，双脚平放在地面上。', '每只手握住一个壶铃，手掌朝向脚部，手臂伸直向天花板。', '将一个壶铃向肩膀方向降低，同时保持另一个壶铃向上伸直。', '将降低的壶铃按回到起始位置，同时将另一个壶铃向肩膀方向降低。', '继续用每个壶铃交替进行推举动作，达到所需的重复次数。'],
  'H0521': ['从高平板支撑位置开始，双手握住壶铃，双脚分开与臀部同宽。', '收紧核心肌群，保持身体从头到脚跟呈一条直线。', '将一个壶铃向上拉向胸部，保持肘部靠近身体。', '将壶铃放回起始位置，然后用另一只手臂重复该动作。', '继续交替手臂进行所需的重复次数。'],
  'H0522': ['双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个壶铃，手掌朝向身体。', '臀部向前弯曲，保持背部挺直，核心肌群参与。', '将一个壶铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。', '将壶铃放回起始位置，然后用另一只手臂重复该动作。', '继续交替手臂进行所需的重复次数。'],
  'H0523': ['双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高，手掌朝向自己。', '启动你的核心并将壶铃压过头顶，在伸展手臂时旋转手掌以面向前方。', '在动作的最高点暂停，然后慢慢将壶铃放回起始位置。', '重复所需的重复次数。'],
  'H0524': ['双脚分开与肩同宽站立，右手握住壶铃。', '稍微弯曲膝盖，用右臂将壶铃压过头顶，保持肘部锁定。', '将躯干向左旋转，将重量转移到左脚上。', '弯曲左膝，将躯干压向地面，保持右臂伸过头顶。', '当你下降时，眼睛盯着壶铃，胸部抬起。', '左手接触地面后，将左脚推入并伸直左腿，推动臀部向前。', '当你向前推动臀部时，用你的核心和右臂将壶铃推回到起始位置。', '重复所需的重复次数，然后换边。'],
  'H0525': ['双脚分开与肩同宽站立，一只手握住壶铃，正手握住。', '稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。', '让壶铃垂在双腿之间，手臂完全伸展。', '以一种流畅的动作，爆发性地伸展你的臀部和膝盖，同时将壶铃拉向你的肩膀。', '当壶铃到达肩膀高度时，旋转手腕，使壶铃底部朝上。', '在与肩同高的位置抓住壶铃，肘部弯曲，手掌朝上。', '通过反向运动将壶铃降低回到起始位置。', '重复所需的重复次数，然后换边。'],
  'H0526': ['双脚分开与肩同宽站立，双手各握一个壶铃，正手握住。', '稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。', '让壶铃垂直悬挂在身体前方。', '以一种流畅的动作，爆发性地伸展臀部和膝盖，同时耸肩。', '当壶铃上升时，将其拉向肩膀，保持肘部高且向两侧伸展。', '在与肩同高的位置抓住壶铃，手掌朝内，肘部向前。', '将壶铃放回起始位置，然后重复所需的重复次数。'],
  'H0527': ['双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。', '稍微弯曲膝盖并启动核心。', '将壶铃压过头顶，充分伸展手臂。', '弯曲膝盖并快速半蹲。', '爆发性地伸展臀部和膝盖，将壶铃举过头顶。', '锁定双臂，将壶铃举过头顶，膝盖稍微弯曲。', '站直并回到起始位置。', '重复所需的重复次数。'],
  'H0528': ['首先，双脚分开与肩同宽，每只手握住一个壶铃，与肩同高。', '稍微弯曲膝盖并启动核心。', '通过爆发性伸展臀部、膝盖和脚踝来开始运动，将壶铃举过头顶。', '当壶铃到达顶部时，将它们完全压过头顶，锁定手臂。', '弯曲肘部并将壶铃放回至肩膀高度，将壶铃放回起始位置。', '重复所需的重复次数。'],
  'H0529': ['双脚分开与肩同宽站立，每只手各握一个壶铃，放在大腿前面，与手臂保持一定距离。', '稍微弯曲膝盖，臀部向前转动，保持背部平坦，挺胸。', '以一种爆发力动作，伸展臀部、膝盖和脚踝，同时将壶铃拉向肩膀。', '当壶铃达到肩膀水平时，旋转手腕并将壶铃击过头顶，充分伸展手臂。', '将壶铃放回起始位置，然后重复所需的重复次数。'],
  'H0530': ['双脚分开与肩同宽站立，右手握住壶铃。', '将右臂伸过头顶，眼睛盯着壶铃。', '左脚向左旋转 45 度，右脚向右旋转 90 度。', '腰部向左弯曲，保持右臂伸过头顶。', '将壶铃向地面降低，伸向左脚。', '暂停片刻，然后启动核心并推动右脚返回起始位置。', '重复所需的重复次数，然后换边。'],
  'H0531': ['首先仰卧在地板上，膝盖弯曲，双脚平放在地面上。', '一只手握住壶铃，手掌朝向脚部。', '将手臂伸直向上伸向天花板，保持肘部锁定且手腕伸直。', '慢慢地将壶铃放回起始位置，在整个运动过程中保持控制。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0532': ['双脚分开与肩同宽站立，一只手握住壶铃。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '将壶铃放在双腿之间，当壶铃到达双腿后部时交换双手。', '当壶铃向前移动时，将其传递到两腿之间的另一只手。', '继续以 8 字形动作将壶铃传递到双腿之间。', '在整个练习过程中保持稳定的节奏并调动核心力量。', '重复所需的重复次数。'],
  'H0535': ['双脚分开与肩同宽站立，将壶铃放在大腿前面。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '将壶铃放低至地面，使其在双腿之间摆动。', '快速伸展臀部和膝盖，利用动量将壶铃摆动到肩膀高度。', '当壶铃达到肩膀高度时，旋转手腕，将壶铃置于架子位置，肘部内收，壶铃靠在前臂上。', '将壶铃放回双腿之间的起始位置，然后重复所需的重复次数。'],
  'H0536': ['双脚分开与肩同宽站立，双手握住壶铃放在胸前。', '右脚向前迈出一步，将身体降低至弓步位置。', '当你向前弓步时，将壶铃传递到右大腿下方，然后将其转移到左手。', '用右脚蹬地回到起始位置，同时将壶铃传回右手。', '在另一侧重复弓步，将壶铃传递到左大腿下方。', '继续交替弓步并在双手之间传递壶铃，达到所需的重复次数。'],
  'H0537': ['双脚分开与肩同宽站立，一只手握住壶铃，正手握住。', '稍微弯曲膝盖并以臀部为铰链，将壶铃放在两腿之间。', '爆发性地伸展你的臀部、膝盖和脚踝，利用动量将壶铃摆动到肩膀的高度。', '当壶铃到达肩膀高度时，旋转手腕并向上挥拳，将手臂锁定在头顶上方。', '将壶铃放回起始位置，然后重复所需的重复次数。'],
  'H1298': ['仰卧在地板上，膝盖弯曲，双脚平放在地面上。', '一只手握住壶铃，手掌朝向脚部，手臂笔直向上伸向天花板。', '弯曲肘部，慢慢将壶铃降低到胸部，保持上臂靠近身体。', '当壶铃位于胸部正上方时暂停片刻，然后通过伸展肘部将壶铃推回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0538': ['双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。', '稍微弯曲膝盖并启动核心。', '将壶铃沿直线压过头顶，充分伸展手臂。', '当你将壶铃举过头顶时，同时弯曲膝盖并快速伸直以产生动力。', '当壶铃到达最高点时，弯曲膝盖和臀部，快速落到壶铃下方。', '膝盖和臀部稍微弯曲，抓住壶铃，手臂完全伸过头顶。', '站直，充分伸展膝盖和臀部，并将壶铃稳定在头顶上。', '弯曲膝盖和臀部，将壶铃放回起始位置，然后重复所需的重复次数。'],
  'H0539': ['双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。', '启动你的核心并保持背部挺直。', '将壶铃压过头顶，充分伸展手臂。', '在顶部暂停片刻，然后慢慢将壶铃放回起始位置。', '重复所需的重复次数，然后换边。'],
  'H0540': ['双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。', '稍微弯曲膝盖并启动核心。', '伸展手臂并完全伸展双腿，将壶铃压过头顶。', '弯曲膝盖并将壶铃放回肩膀，将壶铃放回起始位置。', '重复所需的重复次数，然后换边。'],
  'H0541': ['双脚分开与肩同宽站立，一只手握住壶铃，正手握住。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。', '将壶铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。', '在顶部暂停片刻，然后慢慢将壶铃放回起始位置。', '重复所需的重复次数，然后换边并用另一只手臂重复。'],
  'H0542': ['双脚分开与肩同宽站立，一只手将壶铃放在两腿之间。', '稍微弯曲膝盖并铰接臀部，将壶铃降低到地面。', '爆发性地伸展你的臀部和膝盖，利用动量将壶铃向上摆动到你的肩膀上。', '当壶铃到达肩膀高度时，旋转你的手并将其直接击打到头顶，完全伸展你的手臂。', '将壶铃放回到双腿之间，然后重复所需的重复次数。'],
  'H0543': ['双脚分开与肩同宽站立，一只手握住壶铃。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '将壶铃举至肩膀高度，保持肘部靠近身体。', '将手臂完全伸过头顶，伸直肘部。', '将壶铃降低至肩膀高度，然后返回起始位置。', '重复所需的重复次数，然后换边。'],
  'H0544': ['双脚分开与肩同宽站立，双手握住壶铃放在胸前。', '将左脚抬离地面并向前伸展，保持与地面平行。', '慢慢地将身体降低到蹲姿，保持右脚平放在地面上，左腿伸展。', '在深蹲底部暂停片刻，然后推动右脚跟返回到起始位置。', '重复所需的重复次数，然后换腿。'],
  'H0545': ['从高平板支撑位置开始，双手放在壶铃上，距离与肩同宽。', '将胸部压向地面，保持肘部靠近身体。', '爆发性地推动你的手，将你的手从壶铃上抬起并完全伸展你的手臂。', '轻轻地回到壶铃上，并立即降低胸部以进行下一次重复。', '重复所需的重复次数。'],
  'H0546': ['坐在长凳上，背部挺直，双脚平放在地上。', '每只手握住一个壶铃，与肩同高，手掌朝前。', '将壶铃压过头顶，充分伸展手臂。', '将壶铃降低至肩膀高度。', '重复所需的重复次数。'],
  'H1438': ['坐在长凳上，背部挺直，双脚平放在地上。', '每只手握住一个壶铃，与肩同高，手掌朝前。', '完全伸展双臂，将壶铃压过头顶。', '在顶部暂停片刻，然后慢慢将壶铃放回肩部水平。', '重复所需的重复次数。'],
  'H0547': ['双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。', '将一个壶铃压过头顶，同时将另一个壶铃保持在肩膀高度。', '将按下的壶铃降低至肩膀高度，同时将另一个壶铃压过头顶。', '继续交替按压动作，形成跷跷板状的运动。', '重复所需的重复次数。'],
  'H0548': ['站立，双脚分开比肩宽，脚趾朝外。', '双手握住壶铃放在身体前方，手臂向下伸展。', '弯曲膝盖，降低臀部至下蹲位置，保持背部挺直。', '脚后跟发力，爆发性伸展臀部和膝盖，将壶铃拉向下巴。', '当你向上拉壶铃时，保持肘部高且宽，并将肩胛骨挤压在一起。', '将壶铃放回起始位置，然后重复所需的重复次数。'],
  'H0550': ['首先，双脚分开与肩同宽站立，双手将壶铃放在胸前，手掌相对。', '弯曲膝盖并将臀部向后推，保持挺胸、背部挺直，进入蹲姿。', '当你到达深蹲底部时，爆发性地通过脚后跟站起来，同时将壶铃压过头顶。', '在动作的最高点锁定你的手臂，完全伸展你的肘部。', '通过反转动作，弯曲肘部并将重量放回胸部，将壶铃放回起始位置。', '重复所需的重复次数。'],
  'H0551': ['首先仰卧，双腿伸展，右手握住壶铃，手臂完全伸展到肩膀上方。', '弯曲右膝，将右脚平放在地面上，保持左腿伸展。', '压右脚，将臀部抬离地面，进入桥位。', '将左腿滑到身体下方，弯曲左膝并将左脚平放在地面上。', '将躯干向左旋转，将左手放在地面上以获得支撑。', '压右脚和左手，将躯干抬离地面，形成跪姿。', '从跪姿站起来，保持壶铃伸过头顶。', '反向运动以返回到起始位置。', '从左手的壶铃开始，在另一侧重复练习。'],
  'H0552': ['双脚分开与肩同宽站立，双手握住壶铃放在大腿前，手掌朝向自己。', '稍微弯曲膝盖并铰接臀部，将壶铃降低到地面。', '爆发性伸展臀部和膝盖，利用动量将壶铃拉向肩膀。', '当壶铃达到肩膀高度时，旋转手腕，将壶铃放在架子上，肘部内收，壶铃放在前臂背面。', '将壶铃放回起始位置，然后重复所需的重复次数。'],
  'H0553': ['双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高，手掌朝前。', '启动你的核心并将壶铃压过头顶，充分伸展你的手臂。', '在顶部暂停片刻，然后慢慢将壶铃放回起始位置。', '重复所需的重复次数。'],
  'H1345': ['双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个壶铃，手掌朝向身体。', '臀部向前弯曲，保持背部挺直，核心肌群参与。', '将壶铃拉向胸部，将肩胛骨挤压在一起。', '在顶部暂停片刻，然后慢慢将壶铃放回起始位置。', '重复所需的重复次数。'],
  'H0554': ['双脚分开与肩同宽站立，右手握住壶铃举过头顶。', '将左脚向外旋转约 45 度，并保持右脚指向前方。', '将你的躯干向左侧弯曲，保持右臂伸过头顶，眼睛盯着壶铃。', '尽可能降低躯干，同时保持右臂伸直，左臂向一侧伸展。', '暂停片刻，然后通过推动右脚并接合斜肌返回到起始位置。', '重复所需的重复次数，然后换边。'],
  'H0555': ['坐在长凳或椅子的边缘，双脚平放在地上，膝盖弯曲成 90 度角。', '稍微向后倾斜，将双手放在长凳或椅子的边缘以获得支撑。', '启动腿筋，将脚抬离地面，并将双腿伸直到身前。', '在顶部停顿片刻，然后慢慢弯曲膝盖，将脚放回身体。', '重复所需的重复次数。'],
  'H0558': ['首先，用正手握法悬挂在引体向上杆上，双手分开的距离略大于肩宽。', '启动你的核心并使用摆动动作来产生动力。', '当你向前挥杆时，将胸部拉向杠铃，用背阔肌和二头肌开始动作。', '继续向上运动，直到胸部到达杠铃，然后向下推杠铃并伸展手臂，过渡到双臂屈伸姿势。', '弯曲手臂并控制下降，将自己放回到起始位置。', '重复所需的重复次数。'],
  'H3640': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，将肩胛骨抬离地面，并将右手伸向左膝盖。', '返回起始位置并重复，这次将左手伸向右膝盖。', '继续交替进行所需的重复次数。'],
  'H1420': ['首先跪在地上，双脚分开与臀部同宽，脚趾向前。', '将杠铃放在上背部，将其放在肩膀上。', '启动你的核心和臀部，然后爆发性地跳到空中，伸展你的臀部和膝盖。', '跳跃时，用脚趾推动并充分伸展脚踝、膝盖和臀部。', '轻轻地回到地面，弯曲膝盖以吸收冲击力。', '立即进入下一个重复，重复跳蹲动作。'],
  'H1346': ['跪在地上，膝盖分开与臀部同宽，脚趾向后。', '将双臂伸过头顶，手指交叉。', '保持背部挺直，慢慢向右侧倾斜，感受左侧背阔肌的拉伸。', '保持伸展动作 20-30 秒，然后回到起始位置。', '在左侧重复该拉伸动作，向左侧倾斜，感受右侧背阔肌的拉伸。', '继续交替进行所需的重复次数。'],
  'H3239': ['从跪姿开始，双手放在地上，与肩同宽。', '将双腿伸到身后，用脚趾支撑，将身体抬起成平板支撑姿势。', '保持核心参与并保持臀部稳定，将一只手抬离地面并拍打另一侧的肩膀。', '将手放回地面并用另一只手重复此操作。', '继续交替进行所需的重复次数。'],
  'H3211': ['首先跪在地上，双手与肩同宽，手指指向前方。', '将双腿伸到身后，放在脚掌上，使身体从头到脚跟形成一条直线。', '弯曲肘部，保持核心靠近身体两侧，将身体压向地面。', '继续降低，直到胸部刚好高于地面，然后伸直手臂，将其推回起始位置。', '重复所需的重复次数。'],
  'H3288': ['将自己定位在两个双杠之间，双臂伸展并支撑体重。', '弯曲肘部降低身体，直到上臂与地面平行。', '暂停片刻，然后伸直手臂，将自己推回起始位置。', '重复所需的重复次数。'],
  'H3418': ['正手握住引体向上杆，握距略宽于肩宽。', '双臂完全伸展，身体伸直。', '收紧背阔肌和二头肌，将身体拉向杠铃杆，保持肘部靠近身体。', '继续拉，直到下巴位于杠铃上方。', '在顶部停顿片刻，然后慢慢将身体放回起始位置。', '重复所需的重复次数。'],
  'H3419': ['坐在地板上，双腿伸到身前。', '将双手放在臀部旁边的地板上，手指指向前方。', '启动你的核心并将双腿抬离地面，保持伸直。', '尝试使双腿与地面平行，与身体形成“L”形。', '尽可能长时间地保持这个姿势。', '慢慢地将双腿放回起始位置。', '重复所需的重复次数。'],
  'H0562': ['双脚分开与肩同宽站立，双手握住杠铃于胸前。', '稍微弯曲膝盖并将躯干向右旋转，将杠铃向下朝右臀部摆动。', '当你到达动作的底部时，快速反向运动并向左旋转你的躯干，向上摆动杠铃并穿过你的身体朝向左肩。', '继续这个扭转动作，两侧交替，达到所需的重复次数。'],
  'H3237': ['站立，双脚分开与肩同宽，膝盖稍微弯曲。', '正手握住杠铃，将其放在肩膀前面。', '保持核心收紧并保持背部挺直，将杠铃向上举起并远离身体，将其提升至肩膀高度。', '在顶部停顿片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H3300': ['从俯卧撑位置开始，双手分开与肩同宽，身体伸直。', '启动你的核心，慢慢地将你的重心向前移动，让你的肩膀越过你的手。', '向前倾时，保持肘部稍微弯曲，身体伸直。', '保持这个姿势几秒钟，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H2271': ['双脚分开与肩同宽站立，膝盖稍微弯曲。', '左手举起以保护脸部，右手握住下巴。', '旋转臀部并以左脚为轴心，同时以出拳动作向前伸展左臂。', '扭转你的躯干并调动你的核心肌肉以产生出拳的力量。', '将手臂拉回到起始位置，然后重复所需的重复次数。'],
  'H0570': ['坐在平坦的长凳上，双腿在身前伸直。', '将双手放在臀部旁边的长凳上以获得支撑。', '收紧腹肌，将双腿抬离地面，使膝盖靠近胸部。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H1576': ['平躺，双腿伸展。', '弯曲一侧膝盖，将其靠近胸部，握住大腿或小腿。', '尽可能伸直腿，同时保持腿抬高。', '保持拉伸 20-30 秒。', '换另一条腿重复上述步骤。'],
  'H2287': ['将杠杆机的座椅和脚踏平台调整到您想要的位置。', '坐在机器上，背部靠在靠背上，双脚放在脚踏板上。', '将手放在机器的手柄或侧面以保持稳定性。', '将一只脚推到脚平台上，伸展腿直到几乎完全伸直。', '暂停片刻，然后慢慢弯曲腿，回到起始位置。', '换另一条腿重复上述步骤。', '继续交替双腿达到所需的重复次数。'],
  'H0571': ['调整座椅高度和踏板位置以确保正确对齐。', '坐在机器上，背部挺直，双脚平放在踏板上。', '紧紧握住手柄，手掌相对。', '在整个练习过程中保持挺胸、肩膀向后。', '将一个手柄拉向您的躯干，同时保持另一个手柄静止。', '在动作结束时将肩胛骨挤压在一起。', '慢慢地将手柄返回到起始位置，并在另一侧重复此操作。', '继续交替进行所需的重复次数。'],
  'H0572': ['将杠杆机调整至您想要的阻力水平。', '站在脚踏板上，正手握住手柄，握距略宽于肩宽。', '双臂完全伸展，保持身体挺直。', '收紧背部肌肉，将身体拉向手柄，以胸部为主导。', '继续拉，直到下巴位于手柄上方。', '在顶部停顿片刻，然后慢慢将身体放回起始位置。', '重复所需的重复次数。'],
  'H0573': ['调整机器以适合您的身体尺寸和运动范围。', '坐在机器上，背部靠在垫子上，双脚固定。', '将手放在手柄或握杆上。', '启动你的核心并慢慢向前倾斜，让你的背部稍微弯曲。', '在底部位置暂停片刻，感觉下背部有拉伸感。', '使用背部肌肉，慢慢将躯干抬回到起始位置。', '重复所需的重复次数。'],
  'H0574': ['站立，双脚分开与肩同宽，膝盖稍微弯曲。', '正手握住杠铃，双手分开略宽于肩宽。', '臀部向前弯曲，保持背部挺直，挺胸。', '将杠铃拉向下胸部，将肩胛骨挤压在一起。', '在顶部停顿片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H3200': ['调整座椅高度并将自己面向机器。', '正手握住 V 形杆，保持背部挺直，膝盖稍微弯曲。', '将 V 形杆拉向腹部，将肩胛骨挤压在一起。', '在动作的最高点暂停片刻，然后慢慢释放重量回到起始位置。', '重复所需的重复次数。'],
  'H0575': ['调整座椅高度并将自己放在机器上，背部靠在垫子上。', '反手握住手柄，手掌朝上，肘部靠近身体两侧。', '呼气并向上弯曲手柄，收缩二头肌。', '在动作的最高点暂停片刻，挤压你的二头肌。', '吸气，慢慢将手柄放回起始位置，充分伸展双臂。', '重复所需的重复次数。'],
  'H2289': ['调整杠杆机的座椅，使肩膀与杠杆垫对齐。', '将脚趾放在杠杆垫上，脚跟悬在边缘上。', '抓住手柄或侧面支撑以保持稳定性。', '伸展脚踝，收缩小腿肌肉，将杠杆垫向下推。', '在动作的底部停顿片刻。', '让脚后跟重新抬起，慢慢回到起始位置。', '重复所需的重复次数。'],
  'H0577': ['调整座椅高度，将自己放在机器上，背部平放在垫子上。', '正手握住手柄，肘部呈 90 度角。', '向前推动手柄，直到手臂完全伸展，运动过程中呼气。', '动作结束时短暂暂停，然后慢慢回到起始位置，同时吸气。', '重复所需的重复次数。'],
  'H0578': ['将座椅高度和脚踏板调整到您想要的位置。', '坐在机器上，背部靠在垫子上，双脚平放在脚踏板上。', '抓住把手或座椅侧面以保持稳定性。', '收紧臀肌和腿筋，并通过脚后跟推动举重。', '保持背部挺直，避免圆肩。', '在动作的最高点完全伸展臀部，挤压臀部。', '以受控的方式降低重量，保持臀肌和腿筋的张力。', '重复所需的重复次数。'],
  'H1300': ['将杠杆机的座椅高度和靠背调整到舒适的位置。', '坐在机器上，背部靠在靠背上，双脚平放在地板上。', '正手握住手柄，双手之间的距离略大于肩宽。', '向前推动手柄并使其远离身体，直到双臂完全伸展。', '慢慢地将手柄放回胸部，保持肘部稍微弯曲。', '在底部暂停片刻，然后将手柄推回起始位置。', '重复所需的重复次数。'],
  'H1253': ['将杠杆机调节至适合您身体的高度。', '面向机器定位，脚趾放在脚踏平台上，脚后跟悬在边缘。', '将手放在手柄或支撑杆上以保持稳定性。', '用脚掌收紧小腿并尽可能高地抬起脚后跟。', '在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H0579': ['调整座椅高度，将自己放在机器上，膝盖位于垫子下方，双脚平放在地面上。', '正手握住手柄，握距略宽于肩宽。', '坐直，胸部抬起，肩膀向后，保持下背部轻微的拱形。', '收紧背阔肌，将手柄向下拉向胸部，将肩胛骨挤压在一起。', '在动作底部暂停片刻，然后慢慢松开手柄回到起始位置。', '重复所需的重复次数。'],
  'H0580': ['调整座椅高度并将自己放在杠杆机上。', '手掌朝内，抓住手柄，双臂完全伸展。', '保持背部挺直，呼气并尽可能抬高肩膀。', '保持收缩一会儿，然后吸气并慢慢将肩膀放回起始位置。', '重复所需的重复次数。'],
  'H1439': ['调整座椅高度并将自己放在机器上，背部靠在垫子上。', '正手握住手柄或杆，保持手臂伸直。', '保持背部挺直，将肩膀尽可能高地抬向耳朵。', '保持收缩一会儿，然后慢慢将肩膀放回起始位置。', '重复所需的重复次数。'],
  'H2288': ['调整座椅高度并握住杠杆机的手柄。', '保持背部挺直，双脚平放在地面上。', '呼气并挤压手柄，收缩前臂。', '保持收缩一秒钟，然后慢慢释放并返回到起始位置。', '重复所需的重复次数。'],
  'H1615': ['调整座椅高度并将自己放在杠杆机上。', '将你的上臂放在讲道垫上，确保你的胸部压在上面。', '用锤子握把抓住手柄（手掌相对）。', '保持上臂静止，呼气并将手柄卷向肩膀。', '在顶部暂停片刻，挤压你的二头肌。', '吸气并慢慢将手柄放回起始位置。', '重复所需的重复次数。'],
  'H0581': ['将座椅高度和脚踏板调整至舒适的位置。', '坐在机器上，胸部靠在垫子上，双脚平放在脚踏平台上。', '正手握住手柄，握距略宽于肩宽。', '保持背部挺直并启动核心肌群。', '将手柄拉向身体，将肩胛骨挤压在一起。', '在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。', '重复所需的重复次数。'],
  'H2286': ['调整机器以适合您的身体，然后坐在机器上，背部靠在靠背上。', '将脚放在脚踏板上并握住手柄以保持稳定。', '启动臀肌和腿筋，然后推动脚踏板以伸展臀部并向后抬起双腿。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H2611': ['调整机器座椅，使双脚放在踏板上时膝盖呈 90 度角。', '坐在机器上，背部靠在靠背上，双脚与肩同宽放在踏板上。', '将手放在机器的手柄或侧面以保持稳定性。', '伸展腿，使背部紧靠靠背，将踏板推离身体。', '在完全伸展位置暂停片刻，然后慢慢弯曲腿回到起始位置。', '重复所需的重复次数，然后换腿。'],
  'H1299': ['将杠杆机的座椅和靠背调整到舒适的位置。', '坐在机器上，背部靠在靠背上，双脚平放在地板上。', '正手握住手柄，双手之间的距离略大于肩宽。', '向前推动手柄并使其远离身体，直到双臂完全伸展。', '暂停片刻，然后慢慢弯曲肘部，将手柄放回到胸部。', '重复所需的重复次数。'],
  'H1479': ['将杠杆机上的座椅高度和靠背角度调整到舒适的位置。', '坐在机器上，背部靠在靠背上，双脚平放在地板上。', '正手握住手柄，双手之间的距离略大于肩宽。', '向前推动手柄并远离身体，直到手臂完全伸展，但不要锁定肘部。', '在完全伸展的位置暂停片刻，然后慢慢弯曲肘部并将手柄放回胸部。', '重复所需的重复次数。'],
  'H0582': ['调整机器以适合您的身体并选择所需的重量。', '面朝下跪在机器上，膝盖放在垫子上，双脚固定在脚垫下。', '抓住机器的手柄或侧面以保持稳定性。', '保持上半身静止，呼气，弯曲膝盖，将双腿向臀肌方向卷起。', '在动作的最高点暂停片刻，挤压你的腿筋。', '吸气，慢慢将双腿放回起始位置，充分伸展膝盖。', '重复所需的重复次数。'],
  'H0583': ['调整座椅高度，将自己放在机器上，膝盖放在垫子上，上半身朝前。', '抓住机器的手柄或侧面以保持稳定性。', '保持核心参与，将躯干尽可能舒适地向一侧扭转。', '暂停片刻，然后慢慢回到起始位置。', '向另一侧重复扭转。', '继续交替进行所需的重复次数。'],
  'H0584': ['调整座椅高度并将自己放在机器上，背部靠在垫子上。', '正手握住手柄并保持手臂伸直。', '呼气并将手臂向两侧抬起，直到与地板平行。', '在顶部停顿片刻，然后吸气，慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H0585': ['调整机器的座椅高度和靠背以适合您的身体。', '坐在机器上，背部靠在靠背上，双脚放在脚垫上。', '抓住手柄或侧杆以保持稳定性。', '伸直膝盖，举起重物，向前伸展双腿。', '在顶部暂停片刻，然后慢慢将重量放回起始位置。', '重复所需的重复次数。'],
  'H0586': ['调整机器以适合您的身体并选择所需的重量。', '面朝下躺在机器上，双腿伸直，脚跟靠在带衬垫的杠杆上。', '抓住机器的手柄或侧面以保持稳定性。', '保持上半身静止，呼气并尽可能向上弯曲双腿，但不要将臀部抬离垫子。', '挤压腿筋时，保持收缩位置短暂停顿。', '吸气并缓慢地将控制杆降低回起始位置。', '重复所需的重复次数。'],
  'H3195': ['调整机器以适合您的身体，然后坐在机器上，背部靠在靠背上。', '将双腿放在脚踝上方的杠杆垫上。', '抓住机器两侧的手柄以提供支撑。', '保持上半身不动，呼气并将双腿向上弯曲至臀部。', '在顶部停顿片刻，然后吸气，慢慢降低双腿回到起始位置。', '重复所需的重复次数。'],
  'H0587': ['调整座椅高度并将自己放在机器上，背部靠在靠背上。', '正手握住手柄，双手之间的距离略大于肩宽。', '向上推动手柄，直到手臂完全伸展，但不要锁住肘部。', '在顶部暂停片刻，然后慢慢将手柄放回起始位置。', '重复所需的重复次数。'],
  'H0588': ['调整座椅高度和脚踏板以确保形状正确。', '坐在机器上，双脚平放在脚踏板上，膝盖稍微弯曲。', '紧紧握住手柄，手掌相对。', '保持背部挺直并稍微向前倾斜。', '将手柄拉向躯干，将肩胛骨挤压在一起。', '在动作的最高点停顿片刻。', '慢慢松开手柄并返回到起始位置。', '重复所需的重复次数。'],
  'H0589': ['双脚分开与肩同宽站立，膝盖稍微弯曲，正手握住杠铃。', '臀部向前弯曲，保持背部挺直，头部抬起。', '让杠铃悬挂在你面前，双臂完全伸展。', '将杠铃拉向胸部，保持肘部靠近身体。', '在动作的最高点将肩胛骨挤压在一起。', '将杠铃降低回到起始位置。', '重复所需的重复次数。'],
  'H1356': ['调整座椅高度并将自己面向机器。', '用一只手抓住手柄并保持背部挺直。', '将手柄拉向身体，保持肘部靠近身体两侧。', '在动作的最高点挤压背部肌肉。', '慢慢松开手柄回到起始位置。', '重复所需的重复次数。'],
  'H1347': ['调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。', '正手握住手柄，完全伸展手臂，保持肘部轻微弯曲。', '将手柄向下拉，穿过身体向对面的臀部方向拉，在动作底部挤压背阔肌。', '慢慢地将手柄返回到起始位置，完全伸展手臂。', '重复所需的重复次数，然后换边。'],
  'H0590': ['调整座椅高度并将自己放在机器上，背部靠在垫子上。', '用一只手抓住杠杆手柄，并将肘部置于 90 度角。', '向上按下控制杆，直到手臂完全伸过头顶。', '在顶部暂停片刻，然后慢慢将控制杆放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H0591': ['将机器调整到合适的高度并将身体固定到位。', '正手握住手柄，调整身体位置，使手臂完全伸展。', '弯曲肘部降低身体，保持上臂靠近身体两侧。', '继续降低，直到上臂与地板平行。', '暂停片刻，然后伸展肘部将自己推回起始位置。', '重复所需的重复次数。'],
  'H0592': ['调整座椅高度并将自己放在杠杆机上。', '将上臂放在垫子上，并用反手握住手柄。', '保持背部挺直，并将肘部放在垫子上。', '呼气并将前臂向上臂弯曲，收缩二头肌。', '在动作的最高点暂停片刻，挤压你的二头肌。', '吸气并慢慢将手柄放回起始位置。', '重复所需的重复次数。'],
  'H1614': ['调整座椅高度，将自己放在机器上，上臂放在垫子上，胸部靠在支撑物上。', '反手握住手柄，握距略宽于肩宽。', '保持上臂静止，呼气，同时将手柄向肩膀卷曲，收缩二头肌。', '在动作的最高点暂停片刻，挤压你的二头肌。', '吸气，慢慢将手柄放回起始位置，充分伸展双臂。', '重复所需的重复次数。'],
  'H2285': ['将杠杆机的座椅和手柄调整到舒适的位置。', '坐在机器上，背部靠在垫子上，并用正手握住手柄。', '保持手臂稍微弯曲，核心肌群参与。', '慢慢地将手柄拉向胸部，挤压背阔肌。', '在收缩高峰时暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H2736': ['调整座椅高度，将自己放在机器上，膝盖位于垫子下方，双脚平放在地面上。', '正手握住手柄，握距略宽于肩宽。', '坐直，挺胸，肩膀向后，保持下背部轻微的拱形。', '将手柄向下拉向胸部，用肘部引导并将肩胛骨挤压在一起。', '在动作底部暂停片刻，然后慢慢松开手柄回到起始位置。', '重复所需的重复次数。'],
  'H1616': ['调整座椅高度并将自己放在杠杆机上。', '反手握住手柄，手掌朝上。', '将上臂放在牧师垫上，确保肘部完全伸展。', '保持上臂静止，呼气并将手柄卷向肩膀。', '在动作的最高点暂停片刻，挤压你的二头肌。', '吸气，慢慢将手柄放回起始位置，充分伸展肘部。', '重复所需的重复次数。'],
  'H1348': ['调整座椅高度和踏板位置以确保正确对齐。', '坐在机器上，胸部靠在垫子上，双脚平放在踏板上。', '反手握住手柄，手掌朝上。', '保持背部挺直并启动核心肌群。', '将手柄拉向胸部，将肩胛骨挤压在一起。', '在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。', '重复所需的重复次数。'],
  'H0593': ['调整杠杆机以适合您的身体并将双脚固定在脚垫中。', '面朝下躺在机器上，上半身悬在机器边缘，臀部放在垫子上。', '双臂交叉放在胸前或放在脑后。', '用臀部和腿筋将双腿向上抬起，直到它们与地面平行。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H1349': ['调整杠杆机上的座椅高度和踏板位置。', '坐在机器上，胸部靠在垫子上，双脚平放在踏板上。', '正手握住手柄，握距略宽于肩宽。', '保持背部挺直并启动核心肌群。', '将手柄拉向胸部，将肩胛骨挤压在一起。', '在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。', '重复所需的重复次数。'],
  'H2315': ['调整座椅高度，使膝盖稍微弯曲，双脚平放在踏板上。', '将脚趾放在踏板上，脚跟悬在踏板边缘。', '抓住机器的手柄或侧面以保持稳定性。', '用脚掌推动，尽可能高地抬高脚后跟。', '在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H2335': ['调整机器的座椅，使您的肩膀与杠杆垫对齐。', '将脚趾放在平台的下部，并将膝盖放在杠杆垫下方。', '抓住座椅两侧的把手以保持稳定性。', '伸展脚踝，将杠杆垫压下，尽可能高地抬起脚后跟。', '在动作的最高点暂停片刻，然后慢慢降低脚跟回到起始位置。', '重复所需的重复次数。'],
  'H0594': ['调整座椅高度，使膝盖稍微弯曲，双脚平放在踏板上。', '将脚趾放在踏板上，脚跟悬在踏板边缘。', '抓住把手或座椅侧面以保持稳定性。', '推动脚掌，将脚后跟尽可能抬高。', '在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H1452': ['坐在杠杆机上，背部靠在垫子上，双脚平放在地板上。', '抓住手柄或将手放在侧垫上以获得支撑。', '收紧腹肌并慢慢向后倾斜，让垫子随着您一起移动。', '一旦你的上半身呈 45 度角，收缩腹肌并向前卷腹，使胸部靠近膝盖。', '在顶部停顿片刻，然后慢慢松开并返回到起始位置。', '重复所需的重复次数。'],
  'H0595': ['根据您的舒适度调整座椅高度和胸垫位置。', '坐在机器上，背部靠在胸垫上，双脚平放在地板上。', '抓住手柄或侧杆以保持稳定性。', '收紧腹肌并慢慢向后倾斜，让胸垫随着您一起移动。', '在最大收缩时暂停片刻，感受腹肌的紧张感。', '收缩腹肌并将自己拉回来，慢慢回到起始位置。', '重复所需的重复次数。'],
  'H3760': ['坐在杠杆机上，背部靠在垫子上，双脚固定在脚垫下。', '将手放在把手上或座椅两侧以获得支撑。', '收紧腹肌，慢慢向前挺胸，使胸部靠近膝盖。', '在动作的最高点暂停片刻，挤压腹肌。', '慢慢回到起始位置，让背部稍微弯曲。', '重复所需的重复次数。'],
  'H1451': ['调整座椅高度，使双脚平放在地面上，膝盖呈 90 度角。', '手掌朝下，抓住杠杆机的手柄，双臂完全伸展。', '弯曲肘部，慢慢降低身体，直到上臂与地面平行。', '暂停片刻，然后伸直手臂，将自己推回起始位置。', '重复所需的重复次数。'],
  'H0596': ['调整座椅高度并将自己放在机器上，背部靠在垫子上。', '旋前抓住手柄，并保持肘部稍微弯曲。', '呼气并将手柄向前推，将它们放在胸前。', '暂停片刻，挤压胸部肌肉。', '吸气并慢慢回到起始位置，让胸部肌肉伸展。', '重复所需的重复次数。'],
  'H3759': ['调整座椅高度，使臀部略高于膝盖。', '坐在机器上，背部靠在垫子上，双脚平放在脚踏板上。', '抓住把手或座椅侧面以保持稳定性。', '保持背部挺直，从臀部开始慢慢向前倾斜，直到上半身与地面平行。', '暂停片刻，然后通过推动臀肌和腿筋慢慢回到起始位置。', '重复所需的重复次数。'],
  'H0597': ['调整座椅高度，使膝盖成 90 度角。', '坐在机器上，背部靠在靠背上，双脚放在脚踏板上。', '将手放在侧手柄上以保持稳定性。', '启动外展肌并慢慢将双腿分开，远离身体中线。', '动作结束时暂停片刻，然后慢慢将双腿放回到起始位置。', '重复所需的重复次数。'],
  'H0598': ['调整座椅高度并将自己放在机器上，背部靠在靠背上。', '将脚放在脚踏板上并抓住手柄以保持稳定。', '收紧内收肌，慢慢将双腿并拢，挤压大腿内侧。', '在收缩高峰时暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H0599': ['调整机器以适合您的身体，然后坐在机器上，背部靠在靠背上。', '将小腿放在带衬垫的杠杆下方，就在脚踝上方。', '抓住机器两侧的手柄以提供支撑。', '保持大腿不动，呼气并尽可能向上弯曲双腿。', '挤压腿筋时，保持收缩位置短暂停顿。', '吸气并缓慢地将控制杆降低回起始位置。', '重复所需的重复次数。'],
  'H0600': ['坐在杠杆机上，背部靠在靠背上，双脚放在脚踏板上。', '抓住手柄或侧杆以保持稳定性。', '收紧腹肌，慢慢地将双腿抬向胸部，同时向前卷曲躯干。', '在顶部停顿片刻，然后慢慢降低双腿和躯干回到起始位置。', '重复所需的重复次数。'],
  'H0602': ['调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。', '正手握住手柄，并保持手臂稍微弯曲。', '呼气并将肩胛骨挤压在一起，同时向后和向外拉动手柄，使其远离身体。', '在收缩峰值时停顿片刻，然后吸气，慢慢回到起始位置。', '重复所需的重复次数。'],
  'H0601': ['调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。', '平行握住手柄，手掌相对，并保持手臂稍微弯曲。', '呼气并将肩胛骨挤压在一起，同时向后和向外拉动手柄，使其远离身体。', '在收缩峰值时停顿片刻，然后吸气，慢慢回到起始位置。', '重复所需的重复次数。'],
  'H1350': ['将座椅高度和脚踏板调整到舒适的位置。', '坐在机器上，胸部靠在垫子上，双脚放在脚踏板上。', '正手握住手柄，距离与肩同宽。', '保持背部挺直，核心肌群参与。', '将手柄拉向身体，将肩胛骨挤压在一起。', '在动作的最高点停顿片刻。', '慢慢松开手柄并返回到起始位置。', '重复所需的重复次数。'],
  'H1385': ['调整压腿机的座椅，使双脚放在踏板上时膝盖稍微弯曲。', '坐在机器上，背部靠在靠背上，双脚平放在踏板上，与肩同宽。', '将脚趾和脚掌放在踏板上，使脚后跟远离边缘。', '松开安全手柄，并通过伸展膝盖将踏板推离您。', '一旦膝盖完全伸展，弯曲小腿，慢慢降低脚后跟。', '在底部停顿片刻，然后通过伸展小腿将踏板向后推。', '重复所需的重复次数。'],
  'H0869': ['将杠杆机的座椅高度和靠背调整到舒适的位置。', '坐在机器上，背部靠在靠背上，双脚平放在地板上。', '正手握住机器的手柄，握距略宽于肩宽。', '向上和向前推动手柄，直到手臂完全伸展，但未锁定。', '在顶部暂停片刻，然后慢慢将手柄放回起始位置。', '重复所需的重复次数。'],
  'H2318': ['将杠杆机的座椅高度和靠背调整到舒适的位置。', '坐在机器上，背部靠在靠背上，双脚平放在地板上。', '正手握住机器的手柄，握距略宽于肩宽。', '向上和向前推动手柄，直到手臂完全伸展，但未锁定。', '在顶部暂停片刻，然后慢慢将手柄放回起始位置。', '重复所需的重复次数。'],
  'H0604': ['调整座椅高度，将自己放在杠杆机上，背部靠在垫子上。', '正手握住手柄并保持手臂伸直。', '保持背部挺直，将肩膀尽可能高地抬向耳朵。', '保持收缩一会儿，然后慢慢将肩膀放回起始位置。', '重复所需的重复次数。'],
  'H3758': ['调整座椅高度并将自己放在机器上，双脚平放在地面上。', '正手握住手柄，并将双手置于胸部水平。', '向前推动手柄，直到手臂完全伸展，保持肘部稍微弯曲。', '暂停片刻，然后慢慢地将手柄拉回到胸部，在整个动作过程中保持控制。', '重复所需的重复次数。'],
  'H0606': ['调整座椅高度和踏板位置以确保正确对齐。', '坐在机器上，胸部靠在垫子上，双脚平放在踏板上。', '正手握住手柄，握距略宽于肩宽。', '保持背部挺直并启动核心肌群。', '将手柄拉向躯干，将肩胛骨挤压在一起。', '在收缩峰值时暂停片刻，然后慢慢松开手柄回到起始位置。', '重复所需的重复次数。'],
  'H1351': ['调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。', '正手握住手柄，握距略宽于肩宽。', '保持背部挺直并启动核心肌群。', '将手柄拉向胸部，将肩胛骨挤压在一起。', '在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。', '重复所需的重复次数。'],
  'H0607': ['调整座椅高度并将自己放在机器上，背部靠在垫子上。', '正手握住手柄，并将手臂完全伸展到身前。', '保持上臂不动，弯曲肘部，慢慢将手柄向前额降低。', '在底部暂停片刻，然后伸展双臂将手柄推回起始位置。', '重复所需的重复次数。'],
  'H1313': ['调整座椅高度并将自己面向机器。', '正手握住手柄并保持背部挺直。', '将手柄拉向身体，将肩胛骨挤压在一起。', '在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。', '重复所需的重复次数。'],
  'H0609': ['将绳子连接到高锚点。', '背对锚点站立，双脚与肩同宽。', '正手握住绳子，手掌朝下。', '稍微向前倾，保持背部挺直，核心参与。', '将绳子拉向身体，将肩胛骨挤压在一起。', '在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。', '重复所需的重复次数。'],
  'H3013': ['平躺，膝盖弯曲，双脚平放在地上。', '将手臂放在身体两侧，手掌朝下。', '启动臀肌和核心肌群，然后将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。', '在顶部暂停片刻，挤压臀部。', '慢慢地将臀部放回起始位置。', '重复所需的重复次数。'],
  'H1352': ['平躺，双腿伸直，双臂放在身体两侧。', '收紧臀肌和腿筋，慢慢将上半身抬离地面，向上弯曲背部。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H3582': ['首先站立，双脚分开与肩同宽。', '右脚向前迈出一步，将身体降低至弓步位置。', '右脚蹬地，跳到空中，在空中改变脚的位置。', '左脚向前轻柔落地，并立即将身体降低至弓步位置。', '继续在弓步和跳跃之间交替进行所需的重复次数。'],
  'H1688': ['首先站立，双脚分开与肩同宽。', '右脚向前迈出一步，将身体降低至弓步位置。', '当你弓步时，将你的躯干向右扭转，将你的左肘拉向你的右膝盖。', '暂停片刻，然后回到起始位置。', '在另一侧重复，左脚向前迈出，并将躯干向左扭转。', '继续交替进行所需的重复次数。'],
  'H0613': ['侧躺，双腿伸直。', '弯曲上面的那条腿，用手抓住脚踝或脚。', '轻轻地将脚踝或脚拉向臀部，直到感觉到股四头肌有拉伸感。', '保持拉伸 20-30 秒。', '松开拉伸并在另一侧重复。'],
  'H2312': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，将上半身抬离地面，将右肘靠近左膝盖。', '同时，将右腿伸直并抬离地面。', '暂停片刻，然后回到起始位置。', '重复该动作，这次将左肘移向右膝盖并伸展左腿。', '继续交替进行所需的重复次数。'],
  'H0620': ['平躺在平坦的长凳上，背部紧贴长凳。', '将双手放在臀部下方以获得支撑。', '保持双腿伸直并拢，然后将它们抬向天花板。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H0865': ['平躺，双腿伸展，双臂放在身体两侧。', '将双手放在臀部下方以获得支撑。', '启动你的核心并将双腿抬离地面，将它们抬向天花板。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H1301': ['调整座椅高度，将自己放在机器上，背部平放在垫子上。', '正手握住手柄，肘部呈 90 度角。', '向前推动手柄，直到手臂完全伸展，运动过程中呼气。', '动作结束时暂停片刻，然后慢慢回到起始位置，同时吸气。', '重复所需的重复次数。'],
  'H0624': ['背靠墙站立，双脚分开与臀部同宽。', '慢慢地将背部滑下墙壁，直到膝盖弯曲成 90 度角。', '将右脚抬离地面，并将膝盖靠近胸部。', '将右脚放低，将左脚抬离地面，将膝盖靠近胸部。', '继续交替抬起右脚和左脚，达到所需的重复次数。'],
  'H1353': ['双脚分开与肩同宽站立，双手握住健身球，与胸部齐平。', '稍微弯曲膝盖并启动核心。', '将身体降低至蹲姿，保持背部挺直、挺胸。', '爆发性伸展臀部和腿部，同时将药球扔过头顶。', '在动作的最高点释放球并在下降的过程中接住它。', '将身体放回蹲姿，然后重复所需的重复次数。'],
  'H1302': ['双脚分开与肩同宽站立，将健身球保持在胸部水平。', '向前伸展双臂，用力将药球推离胸部。', '当你释放球时，用你的手臂和躯干将球从后脚转移到前脚。', '当球从墙壁或伙伴身上反弹时接住球，并立即重复该动作。', '继续进行所需的重复次数。'],
  'H1303': ['以三点姿势开始，一只手放在健身球上，另一只手放在地上。', '伸展双腿并将身体摆成一条直线。', '将胸部压向地面，同时保持背部挺直。', '将药球推离身体，完全伸展手臂。', '返回起始位置并重复所需的重复次数。'],
  'H1304': ['双脚分开与肩同宽站立，将药球举至胸部水平。', '向前伸展双臂，将药球推离胸部。', '暂停片刻，然后慢慢地将健身球放回胸前。', '重复所需的重复次数。'],
  'H1305': ['双脚分开与肩同宽站立，将健身球保持在胸部水平。', '向前伸展双臂，将药球推离胸部。', '暂停片刻，然后慢慢地将健身球放回胸前。', '重复所需的重复次数。'],
  'H1312': ['双脚分开与肩同宽站立，将药球举至胸部水平。', '右脚向前迈出一步，同时向前推动药球，充分伸展双臂。', '当你向前推动球时，松开它并让它向前滚动。', '快速向前跑，在球落地之前接住球。', '接住球后，将其放回胸前，左脚向前重复该动作。', '继续交替双腿并重复练习达到所需的重复次数。'],
  'H1701': ['从高平板支撑位置开始，双手放在健身球上，距离与肩同宽。', '弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。', '推回起始位置，完全伸展双臂。', '重复所需的重复次数。'],
  'H1354': ['双脚分开与肩同宽站立，双手握住药球举过头顶。', '启动你的核心并保持背部挺直。', '稍微弯曲膝盖，用力将药球摔到你面前的地面上。', '当你击球时，用你的整个身体来产生力量，包括你的肩膀和核心。', '接住球的弹跳并重复所需的重复次数。'],
  'H1750': ['平躺在长凳上，膝盖弯曲，双脚平放在地上。', '双手握住药球，将手臂伸直至胸部上方。', '将健身球降低到胸部，保持肘部靠近身体。', '爆发性地将药球向上推，充分伸展双臂并将球扔得尽可能高。', '接住药球并重复所需的重复次数。'],
  'H0627': ['反握（手掌朝向自己）抓住引体向上杆，双手之间的距离略大于肩宽。', '悬挂在杠上，双臂完全伸展，双脚离开地面。', '调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。', '继续拉，直到下巴位于杠铃上方。', '在顶部停顿片刻，然后有控制地慢慢将身体放回起始位置。', '重复所需的重复次数。'],
  'H3217': ['从俯卧撑位置开始，双手分开略宽于肩宽，双脚分开与臀部同宽。', '将身体向地面降低，弯曲肘部并保持核心参与。', '当你降低身体时，将你的重心向后转移，并将臀部向上抬向天花板，与你的身体形成一个倒V形。', '继续降低身体，直到胸部刚好高于地面，然后反向运动，将臀部向下推，并伸展手臂回到起始位置。', '重复所需的重复次数。'],
  'H1421': ['从俯卧撑位置开始，双手直接放在肩膀下方，身体呈一条直线。', '弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。', '一旦肘部成 90 度角，将前臂放低至地面，将肘部保持在肩膀正下方。', '暂停片刻，然后用手掌推动前臂，使其回到起始位置。', '重复所需的重复次数。'],
  'H0628': ['在脚踝周围放置一根阻力带。', '双脚分开与肩同宽站立，稍微弯曲膝盖。', '右脚向一侧迈出一步，保持阻力带的张力。', '左脚跟随，向一侧迈步以返回起始位置。', '重复所需的重复次数，然后换边。'],
  'H0631': ['首先悬挂在引体向上杆上，手掌背向自己，手臂完全伸展。', '启动核心肌群，将身体拉向杠铃杆，以胸部为主导。', '当你到达动作的最高点时，改变你的握力，使你的手掌朝向你。', '继续将自己向上拉，直到胸部位于杠铃上方并且手臂完全弯曲。', '通过慢慢降低自己回到起始位置来反转动作。', '重复所需的重复次数。'],
  'H1401': ['首先悬挂在垂直杆上，手掌背对自己，手臂完全伸展。', '启动核心肌群，将身体拉向杠铃杆，以胸部为主导。', '当你站起来时，稍微向后倾斜，并将肘部移向身体两侧。', '继续拉，直到胸部到达杠铃并且肘部完全弯曲。', '在最高点暂停片刻，然后慢慢降低回到起始位置。', '重复所需的重复次数。'],
  'H2328': ['将稳定球放在地面上，将自己置于俯卧撑位置，双手放在球上，距离略窄于肩宽。', '调动你的核心力量，让你的身体从头到脚保持在一条直线上。', '弯曲肘部，使胸部靠近球，使胸部靠近球。', '在底部暂停片刻，然后伸直手臂将自己推回起始位置。', '重复所需的重复次数。'],
  'H1403': ['站直或坐直，肩膀放松。', '将头向一侧倾斜，将耳朵靠近肩膀。', '保持拉伸 15-30 秒。', '在另一侧重复。', '每侧进行 2-4 组。'],
  'H0634': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H1495': ['仰卧，膝盖弯曲，双脚平放在地上。', '将双手放在脑后或交叉放在胸前。', '收紧腹肌，将肩胛骨抬离地面，将躯干旋转到一侧。', '暂停片刻，然后将肩胛骨放回起始位置。', '在另一侧重复。', '继续交替进行所需的重复次数。'],
  'H0635': ['仰卧，膝盖弯曲，双脚平放在地板上。', '将双手放在脑后或交叉放在胸前。', '收紧腹肌，将肩胛骨抬离地面，将躯干旋转到一侧。', '暂停片刻，然后将肩胛骨放回到地板上。', '在另一侧重复，每次重复时交替进行。'],
  'H0636': ['站直，双脚分开与肩同宽，正手握住奥林匹克杠铃。', '让杠铃悬挂在大腿前面，手掌与身体保持一臂距离。', '保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。', '继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。', '挤压二头肌时，保持收缩位置短暂停顿。', '吸气并慢慢开始将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0637': ['首先，双脚分开与肩同宽站立，并用正手握住杠铃。', '将杠铃举过头顶，充分伸展双臂。', '保持上臂靠近头部，弯曲肘部，慢慢将杠铃降低到脑后。', '暂停片刻，然后将手臂伸回到起始位置。', '重复所需的重复次数。'],
  'H1355': ['面向墙壁站立，双脚分开与肩同宽。', '将一只手臂伸直到身前，将手掌靠在墙上。', '启动你的核心，身体向前倾斜，保持手臂伸直，背部平坦。', '用手掌慢慢推向墙壁，激活背阔肌。', '保持该姿势几秒钟，然后松开并用另一只手臂重复该动作。'],
  'H0638': ['面向引体向上杆站立，双脚分开与肩同宽。', '抬起手，用反握方式抓住杠铃，一只手握住杠铃，另一只手握住手腕以提供支撑。', '悬挂在杠上，手臂完全伸展，保持身体伸直，核心肌群参与。', '弯曲肘部并挤压背部肌肉，将自己拉向杠铃。', '继续拉，直到下巴高于杠铃，然后慢慢降低回到起始位置。', '重复所需的重复次数，然后换臂重复。'],
  'H0639': ['背对长凳或椅子站立，双脚分开与肩同宽。', '将一只手放在身后的长凳或椅子上，手指指向您的身体。', '将双腿向前方伸展，脚跟保持在地面上。', '弯曲肘部，将身体放低至地面，使背部靠近长凳或椅子。', '在底部停顿片刻，然后用手掌推直手臂，回到起始位置。', '重复所需的重复次数，然后换边并用另一只手臂重复。'],
  'H0640': ['双脚分开与肩同宽站立，一只手将健身球放在腰前。', '稍微弯曲膝盖并启动核心。', '将健身球举过头顶，充分伸展手臂。', '用力将药球摔到地上，用你的核心和肩膀产生力量。', '抓住弹起的实心球，然后重复所需的重复次数。'],
  'H1773': ['双脚分开与肩同宽站立，膝盖微曲，单手握住毛巾。', '腰部向前弯曲，保持背部挺直，核心肌群参与。', '完全伸展手臂，让毛巾挂在您面前。', '将毛巾拉向胸部，将肩胛骨挤压在一起。', '在顶部停顿片刻，然后慢慢将毛巾放回起始位置。', '重复所需的重复次数，然后换臂。'],
  'H1386': ['双脚分开与肩同宽站立，脚趾指向前方。', '将双手放在稳定的表面上以获得支撑，例如墙壁或酒吧。', '将一条腿抬离地面，保持膝盖稍微弯曲。', '使用小腿肌肉，尽可能高地抬高脚跟。', '在顶部停顿片刻，然后慢慢降低脚跟。', '重复所需的重复次数，然后换腿。'],
  'H1476': ['双脚分开与肩同宽站立。', '向前伸出一条腿，使其离开地面。', '弯曲站立的腿并降低身体，就像坐回椅子上一样。', '保持挺胸、背部挺直。', '推动脚后跟返回到起始位置。', '换另一条腿重复上述步骤。'],
  'H0641': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H0642': ['从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。', '弯曲肘部，将身体降低到地面，保持背部挺直，核心参与。', '当你向后推时，将一条腿踢向一侧，完全伸展并启动臀部。', '将腿恢复到起始位置并重复俯卧撑，每次重复时交替腿。', '继续交替踢腿和俯卧撑，达到所需的重复次数。'],
  'H0643': ['站立或坐直，双脚分开与肩同宽。', '将一只手臂伸过头顶，弯曲肘部，使手伸向对面的肩胛骨。', '用另一只手轻轻地将伸出的手臂的肘部拉向头部的另一侧，感受三头肌的拉伸。', '保持拉伸 15-30 秒，然后放松。', '在另一侧重复。'],
  'H1422': ['仰卧，膝盖弯曲，双脚平放在地上。', '将手臂放在身体两侧，手掌朝下。', '调动你的臀肌和核心肌肉。', '向上倾斜骨盆，将臀部抬离地面。', '保持桥位置几秒钟。', '慢慢地将臀部放回起始位置。', '重复所需的重复次数。'],
  'H1388': ['坐在地上，双腿在身前伸展。', '将绳子绕在脚掌上，并用手握住绳子的末端。', '轻轻地将绳子拉向自己，弯曲脚并伸展小腿肌肉。', '保持拉伸 15-30 秒。', '释放绳子上的张力，然后在另一条腿上重复拉伸。', '重复所需的重复次数。'],
  'H3662': ['从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。', '收紧核心肌群，将臀部抬向天花板，与身体形成倒V字形。', '弯曲肘部，使上半身靠近地面，使上半身靠近地面。', '当你下降时，将你的重心向前移动，并通过伸直手臂并抬起胸部来过渡到眼镜蛇姿势。', '通过弯曲肘部并将胸部放回到地面来扭转运动。', '双手用力推回到倒V字形。', '通过将臀部放回地面继续运动，回到起始俯卧撑位置。', '重复所需的重复次数。'],
  'H1306': ['从高平板支撑位置开始，双手分开略宽于肩宽。', '弯曲肘部，将胸部压向地面，保持身体呈一条直线。', '爆发性地推离地面，利用胸部肌肉将上半身推离地面。', '双手回到起始位置，轻轻落地。', '重复所需的重复次数。'],
  'H1687': ['站立，双脚分开与臀部同宽，双臂放在身体两侧。', '右脚向后退一步，用脚掌着地。', '弯曲左膝并将身体降低至弓步位置。', '当你降低弓步时，同时将手臂举过头顶。', '在弓步底部暂停片刻，然后通过推动左脚跟并将右脚向前拉回到起始位置。', '在另一侧重复该动作，左脚向后退一步并弯曲右膝盖。', '继续交替进行所需的重复次数。'],
  'H1389': ['坐在地上，双腿在身前伸展。', '将绳子绕在脚掌上，并用手握住绳子的末端。', '轻轻地将绳子拉向自己，弯曲脚并伸展小腿肌肉。', '保持拉伸 20-30 秒。', '释放绳子上的张力并放松脚。', '在另一条腿上重复该拉伸动作。'],
  'H3119': ['双脚分开与肩同宽站立，脚趾稍微向外。', '弯曲膝盖并将臀部向后推，降低身体，就像坐在椅子上一样。', '在整个动作过程中保持挺胸、背部挺直。', '降低自己，直到大腿与地面平行或尽可能低。', '在底部停顿片刻，然后推动脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H3132': ['双脚分开与肩同宽站立，脚趾稍微向外。', '抓住稳定的支撑物，例如椅子或墙壁，以保持平衡。', '弯曲膝盖并将臀部向后推，将身体降低至蹲姿。', '在整个动作过程中保持挺胸、背部挺直。', '在底部停顿片刻，然后推动脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H0648': ['首先将杠铃放在你面前的地面上，双脚分开与肩同宽。', '弯腰，正手握住杠铃，握距略宽于肩宽。', '将杠铃提离地面时，保持背部挺直，挺胸，伸展臀部和膝盖。', '当杠铃到达大腿中部时，爆发性地将其向上拉，耸肩并将肘部拉高并向两侧拉。', '当杠铃到达最高点时，迅速下降到其下方，旋转肘部，以前蹲姿势将杠铃接在肩膀上。', '握住杠铃站起来，充分伸展臀部和膝盖。', '将杠铃放回起始位置，在整个运动过程中保持对重量的控制。', '重复所需的重复次数。'],
  'H3665': ['从高平板支撑位置开始，双手直接放在肩膀下方，身体从头到脚成一条直线。', '启动你的核心并挤压你的臀肌以保持稳定的位置。', '将身体放低到前臂上，一次一只手臂，从头到脚保持一条直线。', '保持这个姿势所需的时间，保持核心肌群和臀肌的参与。', '要返回到起始位置，请推动前臂并将身体抬回到高位平板支撑位置。', '重复所需的重复次数。'],
  'H3203': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H1707': ['首先，面朝下躺在稳定球上，双脚分开与肩同宽，脚趾接触地面。', '将双手放在脑后或交叉放在胸前。', '启动核心肌肉，慢慢将上半身抬离球，保持背部挺直。', '将躯干旋转到一侧，使肩膀靠近臀部。在整个运动过程中保持臀部和腿部稳定。', '暂停片刻，然后回到起始位置。', '重复旋转到另一侧。', '继续交替进行所需的重复次数。'],
  'H0651': ['用中立握法（手掌相对）悬挂在引体向上杆上，双臂完全伸展。', '启动你的核心并将肩胛骨挤压在一起。', '弯曲肘部并将肘部向下推向臀部，将身体向上拉向杠铃。', '继续拉，直到下巴位于杠铃上方。', '在顶部停顿片刻，然后有控制地慢慢将身体放回起始位置。', '重复所需的重复次数。'],
  'H0650': ['首先坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。', '将双手放在稳定球的两侧以获得支撑。', '收紧腹肌，慢慢向前滚动臀部，使膝盖靠近胸部。', '在动作的最高点停顿片刻，然后慢慢将双腿伸展回起始位置。', '重复所需的重复次数。'],
  'H1689': ['从俯卧撑位置开始，双手分开略宽于肩宽，身体呈一条直线。', '弯曲肘部，将胸部压向地面，保持身体伸直。', '推动手掌以伸展手臂并返回到起始位置。', '从俯卧撑位置开始，弯曲肘部，将胸部拉向地面，保持身体伸直。', '推动手掌以伸展手臂并返回到起始位置。', '重复所需的重复次数。'],
  'H3638': ['从俯卧撑位置开始，双手分开与肩同宽，身体呈一条直线。', '弯曲肘部，将胸部压向地面，保持身体伸直。', '用手推动以伸展手臂并返回到起始位置。', '快速将一个膝盖靠近胸部，然后快速切换并将另一只膝盖靠近胸部。', '继续尽可能快地交替膝盖，同时保持良好的姿势。', '继续所需的持续时间或重复次数。'],
  'H1307': ['将博苏球平放在地上，平面朝上。', '将自己置于俯卧撑位置，双手放在博苏球的外边缘。', '弯曲肘部，调动核心力量，将身体向博苏球方向降低。', '伸展双臂，将自己推回到起始位置。', '重复所需的重复次数。'],
  'H0653': ['将博苏球平放在地上，平面朝上。', '将自己置于俯卧撑位置，双手放在博苏球的外边缘。', '弯曲肘部，调动核心力量，将身体向博苏球方向降低。', '伸展双臂，将自己推回到起始位置。', '重复所需的重复次数。'],
  'H0655': ['将稳定球放在地上，面朝下，双手放在球上，与肩同宽。', '将双腿伸直在身后，用脚趾保持平衡。', '弯曲肘部，调动核心力量，将胸部向球方向降低，保持身体呈一条直线。', '在底部暂停片刻，然后伸直手臂将自己推回起始位置。', '重复所需的重复次数。'],
  'H0659': ['面向墙壁站立，距离大约一臂距离。', '将双手放在墙上，与肩同高，距离略宽于肩宽。', '后退几英尺，保持身体挺直，双脚分开与臀部同宽。', '弯曲肘部，将胸部向墙壁降低，保持身体呈一条直线。', '推回起始位置，伸直手臂。', '重复所需的重复次数。'],
  'H0658': ['面向墙壁站立，距离大约一臂距离。', '将双手放在墙上，与肩同高，距离略宽于肩宽。', '双脚向后退一步，保持与臀部同宽。', '收紧核心肌群，保持身体从头到脚跟呈一条直线。', '弯曲肘部，将胸部向墙壁降低，保持身体挺直。', '暂停片刻，然后将自己推回到起始位置。', '重复所需的重复次数。'],
  'H0660': ['从俯卧撑位置开始，双手并拢，直接放在肩膀下方。', '每只手握住一个哑铃，将其放在地上。', '弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。', '推动手掌以伸展手臂并返回到起始位置。', '重复所需的重复次数。'],
  'H0661': ['从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。', '弯曲肘部，将身体降低到地面，保持背部挺直，核心肌群参与。', '当你向后推时，将一条腿抬离地面并将其踢向一侧，保持伸直。', '将腿放下并重复俯卧撑，然后换另一条腿。', '每次重复俯卧撑时继续交替踢腿。'],
  'H0663': ['从高平板支撑位置开始，双手放在健身球上，距离与肩同宽。', '弯曲肘部，保持背部挺直，调动核心力量，将身体降低至地面。', '推动手掌以伸展手臂并返回到起始位置。', '重复所需的重复次数。'],
  'H1467': ['从平板支撑位置开始，前臂放在地面上，肘部位于肩膀正下方。', '调动你的核心力量，让你的身体从头到脚保持在一条直线上。', '弯曲肘部，使胸部靠近地面，使胸部靠近地面。', '在底部暂停片刻，然后将自己推回到起始位置。', '重复所需的重复次数。'],
  'H3145': ['从高位平板支撑开始，双手分开略宽于肩宽，身体从头到脚跟呈一条直线。', '弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。', '一旦你的胸部刚好高于地面，用力推动你的手臂，伸展你的手臂并抬起你的上半身。', '在动作的最高点，将上背部推向天花板，从而伸展肩胛骨。', '暂停片刻，然后通过缩回肩胛骨并将身体放回起始位置来反转动作。', '重复所需的重复次数。'],
  'H0664': ['从俯卧撑位置开始，双手分开与肩同宽，身体呈一条直线。', '弯曲肘部，将身体降低到地面，保持核心参与。', '推回到起始位置。', '将体重转移到左手上，然后将身体向右旋转，将右臂举向天花板。', '保持侧板姿势几秒钟，然后返回到起始位置。', '在另一侧重复俯卧撑和侧板支撑。', '继续交替进行所需的重复次数。'],
  'H3533': ['双脚分开与肩同宽站立。', '弯曲膝盖并将臀部向后推，降低身体，就像坐在椅子上一样。', '保持挺胸、背部挺直。', '降低身体直到大腿与地面平行。', '推动脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H3201': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H3552': ['双脚分开与肩同宽站立，双臂放在身体两侧。', '首先快速上下移动双脚，就像原地跑步一样。', '保持动作快速而轻盈，重点放在脚掌上。', '继续所需的持续时间或重复次数。'],
  'H0666': ['从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。', '将一只手臂伸直至一侧，与地面平行。', '弯曲肘部，将身体降低到地面，保持背部挺直，核心参与。', '推回起始位置，使用胸部肌肉抬起身体。', '另一只手臂伸出，重复上述动作。'],
  'H0668': ['仰卧，双脚平放在地上，膝盖弯曲。', '将手臂放在身体两侧，手掌朝下。', '收紧臀肌和腿筋，将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。', '保持这个姿势几秒钟，然后慢慢地将臀部放回起始位置。', '重复所需的重复次数。'],
  'H0669': ['站直，双脚分开与肩同宽。', '将右臂伸过胸部，将左手放在右肘上。', '轻轻地将右臂拉向左肩，感受右肩的拉伸。', '保持拉伸 15-30 秒，然后放松。', '在另一侧重复。'],
  'H0670': ['正手握住引体向上杆，握距略宽于肩宽。', '悬挂在杠上，双臂完全伸展，身体伸直。', '收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。', '继续拉，直到下巴位于杠铃上方。', '在顶部停顿片刻，然后慢慢将身体放回起始位置。', '重复所需的重复次数。'],
  'H1582': ['仰卧，双腿伸展，双臂放在身体两侧。', '将绳子绕在右脚掌上，并用手握住绳子的末端。', '慢慢地将右腿抬向胸部，保持膝盖伸直，脚弯曲。', '保持伸展几秒钟，然后慢慢将腿放回起始位置。', '左腿重复上述动作。', '继续交替双腿达到所需的重复次数。'],
  'H3236': ['首先跪在地上，膝盖分开与臀部同宽，双脚弯曲。', '将阻力带缠绕在大腿上，就在膝盖上方。', '将双手放在臀部或向前伸展以保持平衡。', '调动你的臀肌和核心肌肉。', '当你将膝盖抬离地面时，向前推动臀部并挤压臀部，伸展臀部直到大腿与地面平行。', '保持该姿势片刻，然后慢慢将膝盖放回起始位置。', '重复所需的重复次数。'],
  'H3007': ['将阻力带固定在坚固的锚点上，并将其固定在脚踝上。', '面向锚点站立，双脚分开与肩同宽。', '保持核心参与并保持上半身稳定，将腿伸直到身前。', '在顶部暂停片刻，然后慢慢地将腿放回起始位置。', '重复所需的重复次数，然后换腿。'],
  'H3123': ['坐在椅子或长凳上，背部挺直，双脚平放在地面上。', '反手握住阻力带，手掌朝上，手臂向下伸展到身体两侧。', '保持上臂静止，呼气并将阻力带向上卷向肩膀。', '在顶部暂停片刻，挤压你的二头肌。', '吸气并慢慢降低阻力带回到起始位置。', '重复所需的重复次数。'],
  'H3124': ['坐在椅子或长凳上，背部挺直，双脚平放在地面上。', '每只手握住阻力带手柄，手掌朝下，肘部弯曲成 90 度角。', '向前伸展双臂，将阻力带推离胸部。', '动作结束时暂停片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H3006': ['坐在椅子或长凳上，背部挺直，双脚平放在地面上。', '将阻力带缠绕在大腿上，就在膝盖上方。', '将双手放在椅子或长凳的两侧以获得支撑。', '启动外展肌（大腿外侧肌肉），并克服弹力带的阻力，慢慢将膝盖分开。', '动作结束时暂停片刻，然后慢慢将膝盖放回一起。', '重复所需的重复次数。'],
  'H3122': ['坐在椅子或长凳上，背部挺直，双脚平放在地面上。', '双手握住阻力带，手掌朝前，将其拉至肩部水平。', '将弹力带压过头顶，充分伸展双臂。', '在顶部停顿片刻，然后慢慢将弹力带降低至肩部水平。', '重复所需的重复次数。'],
  'H3144': ['坐在地板上，双腿伸展，将阻力带绕在脚上。', '双手握住阻力带的两端，手掌相对。', '保持背部挺直，稍微向后倾斜，锻炼核心肌群。', '将阻力带拉向胸部，将肩胛骨挤压在一起。', '在最高点停顿片刻，然后慢慢释放张力，回到起始位置。', '重复所需的重复次数。'],
  'H0672': ['将自己定位在两个双杠之间，双臂完全伸展，身体伸直。', '弯曲肘部降低身体，直到上臂与地面平行。', '暂停片刻，然后伸直手臂，将自己推回起始位置。', '重复所需的重复次数。'],
  'H0673': ['调整座椅高度，将自己放在机器上，膝盖位于垫子下方，双脚平放在地面上。', '反手握住手柄，握距略宽于肩宽。', '坐直，挺胸，肩膀向后，保持下背部轻微的拱形。', '将手柄向下拉向胸部，将肩胛骨挤压在一起。', '在动作底部暂停片刻，然后慢慢松开手柄回到起始位置。', '重复所需的重复次数。'],
  'H0674': ['双手分开与肩同宽，反握抓住引体向上杆。', '悬挂在杠上，双臂完全伸展，身体伸直。', '调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。', '继续拉，直到下巴位于杠铃上方。', '在顶部停顿片刻，然后慢慢将身体放回起始位置。', '重复所需的重复次数。'],
  'H0675': ['面朝下躺在稳定球上，臀部放在球上，双腿伸直在身后。', '将双手放在身前的地面上以保持稳定。', '调动臀肌和腿筋，将双腿尽可能高地抬向天花板。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H1423': ['脸朝下躺在平坦的长凳上，臀部位于边缘，双腿悬在长凳上。', '抓住长凳以保持稳定。', '保持双腿伸直，尽可能将它们抬向天花板。', '在动作的最高点挤压臀部。', '慢慢地将双腿放回起始位置。', '重复所需的重复次数。'],
  'H3663': ['坐在地上，双腿向前伸展，双手放在身后的地面上，手指指向脚部。', '双手用力，将臀部抬离地面，进入反向平板支撑位置。', '启动你的核心并将一条腿抬离地面，将其笔直向上伸向天花板。', '保持一会儿，然后将腿放下。', '换另一条腿重复上述步骤。', '继续交替双腿达到所需的重复次数。'],
  'H0677': ['首先，将手臂完全伸展，身体伸直，挂在吊环上。', '弯曲肘部，降低身体，直到肩膀低于肘部。', '伸直手臂，将自己推回起始位置。', '重复所需的重复次数。'],
  'H2571': ['首先跪在地上，膝盖分开与臀部同宽。', '将双手放在身前的地面上以获得支撑。', '慢慢向前倾，将重心转移到双手上，并将双腿伸到身后。', '当你将臀部向后推向天花板时，保持背部挺直并收紧臀部。', '保持这个姿势几秒钟，感受臀部的拉伸。', '弯曲膝盖并降低臀部，慢慢回到起始位置。', '重复所需的重复次数。'],
  'H0678': ['站在引体向上杆前，双脚分开与肩同宽。', '向上伸手，正手握住杠铃，握距略宽于肩宽。', '悬挂在杠上，双臂完全伸展，身体伸直。', '调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。', '在顶部停顿片刻，然后慢慢将身体放回起始位置。', '重复所需的重复次数。'],
  'H2208': ['首先坐在地上，双腿在身前伸展。', '将滚轮垂直于您的身体放置，位于臀部下方。', '慢慢向后滚动你的身体，让滚轮向上移动你的背部。', '继续滚动，直到滚轮到达您的上背部。', '暂停片刻，然后慢慢滚回到起始位置。', '重复所需的重复次数。'],
  'H2204': ['从平板支撑位置开始，前臂放在滚轴上，身体呈一条直线。', '启动你的核心并缓慢向前滚动滚轮，在保持控制的同时尽可能地伸展你的身体。', '在最远点暂停片刻，然后慢慢地将滚轮滚回到起始位置。', '重复所需的重复次数。'],
  'H2205': ['首先跪在地上，将滚轮放在臀部下方。', '将双手放在滚轮上以获得支撑。', '慢慢地向前滚动滚轮，伸展臀部并伸展臀部。', '保持伸展几秒钟，然后滚回起始位置。', '重复所需的重复次数。'],
  'H2202': ['首先坐在地上，双腿在身前伸展。', '将滚轮放在臀部下方、膝盖上方。', '向后倾斜，双手放在身后的地面上以获得支撑。', '收紧臀部，慢慢向前滚动滚轮，弯曲膝盖并将其拉向胸部。', '动作结束时暂停片刻，感受臀部的拉伸。', '慢慢地将滚轮滚回起始位置，伸展双腿。', '重复所需的重复次数。'],
  'H2206': ['平躺，双臂伸直过头顶，双腿伸直在身前。', '将滚筒放在双脚之间，并用脚趾抓住它。', '收紧腹肌，将双腿抬离地面，将膝盖向胸部弯曲，将滚轮向身体方向滚动。', '在顶部停顿片刻，然后慢慢将双腿放回起始位置，将滚轮滚离身体。', '重复所需的重复次数。'],
  'H2203': ['坐在平坦的表面上，双腿在身前伸展。', '双手握住滚轮，掌心朝下，将其放在大腿上。', '稍微向前倾，将滚轮滚离身体，将手臂伸直在身前。', '暂停片刻，然后慢慢将滚轮向身体方向滚动，弯曲手臂，将滚轮拉回到大腿处。', '重复所需的重复次数。'],
  'H2209': ['坐在平坦的表面上，双腿在身前伸展。', '双手握住滚轮，掌心朝下，将其放在大腿上。', '稍微向后倾斜并锻炼核心肌肉。', '将滚轮抬高至肩部高度，保持手臂伸直。', '慢慢地将滚轮放回到大腿处。', '重复所需的重复次数。'],
  'H2207': ['双脚分开与肩同宽站立，双手握住滚轮放在身体前方。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '向前伸展双臂，将滚轮向脚部方向滚动，感受背阔肌的拉伸。', '保持拉伸几秒钟，然后慢慢地将滚轮滚动回起始位置。', '重复所需的重复次数。'],
  'H0680': ['面向绳子站立，双脚分开与肩同宽。', '用双手抓住绳子，手掌朝向自己。', '稍微弯曲膝盖并启动核心。', '开始通过交替的双手动作将自己拉上绳子。', '用双腿协助向上运动。', '继续攀爬，直到到达所需的高度或绳索的顶部。', '要下降，请在控制下降的同时反转双手的动作。', '重复所需的重复次数。'],
  'H0685': ['首先站直，双脚分开与臀部同宽。', '启动你的核心并保持上半身放松。', '开始原地慢跑，将膝盖抬向胸部，然后轻轻落在脚掌上。', '保持稳定的步伐并继续慢跑所需的时间或距离。', '记住在整个练习过程中深呼吸并保持良好的姿势。'],
  'H0684': ['首先站直，双脚分开与臀部同宽。', '启动你的核心并保持上半身放松。', '开始原地慢跑，将膝盖抬向胸部，然后轻轻落在脚掌上。', '保持稳定的步伐并继续慢跑所需的时间或距离。', '记住在整个练习过程中深呼吸并保持良好的姿势。'],
  'H1585': ['双脚分开与臀部同宽站立。', '右脚向前迈出一步，保持左脚踩地。', '弯曲右膝，降低身体，保持左腿伸直。', '将双手放在右大腿上以获得支撑。', '保持拉伸 20-30 秒，然后换边重复。'],
  'H3021': ['从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。', '将胸部压向地面，保持肘部靠近身体。', '当你下降时，将肩胛骨挤压在一起并将胸部向前推。', '在底部停顿片刻，然后推回到起始位置。', '重复所需的重复次数。'],
  'H3219': ['双脚分开与肩同宽站立。', '跳离地面，同时将右腿交叉到左腿前面。', '落地时，快速换腿，将左腿交叉在右腿前面。', '继续交替双腿并尽可能快地跳跃。', '重复所需的重复次数。'],
  'H1390': ['坐在椅子或长凳的边缘，双脚平放在地面上。', '将一只腿伸直在身前，脚跟保持在地面上。', '稍微向前倾，感受小腿肌肉的拉伸。', '保持拉伸 20-30 秒。', '换腿并重复拉伸。'],
  'H1424': ['坐在地上，双腿在身前伸展。', '弯曲右膝，将右脚踝交叉在左大腿上。', '将右手放在身后的地面上以获得支撑。', '用左手轻轻按下右膝盖以加深伸展。', '保持拉伸 30 秒到 1 分钟。', '换边并重复。'],
  'H0689': ['坐在平坦的长凳上，背部挺直，双脚平放在地面上。', '将双手放在长凳两侧以获得支撑。', '保持双腿伸直，慢慢将它们抬起到您面前，直到它们与地面平行。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H0690': ['坐在椅子边缘，双脚平放在地面上。', '将双手放在大腿上或椅子两侧以获得支撑。', '从臀部开始慢慢向前倾斜，保持背部挺直。', '感受下背部的拉伸并保持 20-30 秒。', '慢慢回到起始位置并重复所需的重复次数。'],
  'H2567': ['坐在地上，双腿在身前伸展。', '弯曲右膝，将右脚放在左膝外侧。', '将左肘放在右膝外侧，轻轻地将躯干向右扭转。', '保持拉伸 20-30 秒，然后换边重复。'],
  'H0691': ['坐在地板上，背靠墙，双腿在身前伸展。', '弯曲膝盖，将双脚平放在地板上，与臀部同宽。', '将双手放在脑后，肘部朝外。', '收紧腹肌并向一侧倾斜，将肘部靠近臀部。', '暂停片刻，然后回到起始位置。', '在另一侧重复。', '继续交替进行所需的重复次数。'],
  'H1587': ['坐在地上，双腿大角度伸展。', '弯曲你的脚并锻炼你的股四头肌。', '将双手放在身后的地面上以获得支撑。', '保持背部挺直，从臀部向前倾。', '继续向前倾斜，直到感觉到腿筋被拉伸。', '保持这个姿势几个呼吸。', '慢慢释放拉伸并返回到起始位置。', '重复所需的重复次数。'],
  'H0697': ['平躺在垫子或长凳上，双腿伸展。', '将双手放在身体两侧或臀部下方以获得支撑。', '弯曲膝盖，将脚抬离地面，将大腿靠近胸部。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H0696': ['平躺，双腿伸展，双臂放在身体两侧。', '弯曲膝盖，将双脚平放在地面上，距离与臀部同宽。', '将臀部抬离地面，锻炼臀肌和腿筋。', '慢慢地将双腿向臀部弯曲，保持臀部抬起。', '在顶部停顿片刻，然后慢慢将双腿伸展回起始位置。', '将臀部放回地面。', '重复所需的重复次数。'],
  'H3222': ['双脚分开与肩同宽站立。', '弯曲膝盖并将身体降低至蹲姿。', '爆发性跳跃，伸展臀部和膝盖，同时摆动手臂以获得动力。', '脚掌轻轻落地，然后立即进入下一个重复动作。', '重复所需的重复次数。'],
  'H3656': ['找一个空地或跑步机来进行锻炼。', '站直，双脚分开与臀部同宽。', '开始原地慢跑，抬起膝盖并挥动手臂。', '几秒钟后，开始小步前进，保持快速的步伐。', '继续小步跑所需的时间或距离。'],
  'H1763': ['握距与肩同宽，抓住引体向上杆，手掌背向自己。', '双臂完全伸展，自由悬挂。', '启动背部肌肉，将身体向上拉向杠铃，直到下巴位于杠铃上方。', '在顶部停顿片刻，然后慢慢将身体放回起始位置。', '重复所需的重复次数。'],
  'H3699': ['从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。', '启动你的核心并将右手抬离地面，伸手拍打你的左肩。', '将右手放回地面，然后用左手轻拍右肩，重复此操作。', '继续交替轻拍肩膀，同时保持臀部和躯干稳定。', '重复所需的重复次数。'],
  'H0699': ['从高位平板支撑开始，双手分开略宽于肩宽，身体从头到脚跟呈一条直线。', '弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。', '当你向后推时，将右手抬离地面并轻拍左肩。', '将右手放回地面并重复俯卧撑，这次抬起左手并拍打右肩。', '每次重复俯卧撑时，继续交替拍肩。', '在整个练习过程中保持核心稳定并避免臀部过度旋转。', '重复所需的重复次数。'],
  'H1774': ['侧躺，双腿伸展并叠放在一起。', '用前臂支撑自己，将肘部保持在肩膀正下方。', '启动你的核心并将臀部抬离地面，从头到脚形成一条直线。', '在保持核心肌群参与的同时，尽可能高地抬起上面的那条腿，但不要旋转臀部。', '在顶部停顿片刻，然后将腿放下。', '重复所需的重复次数，然后换边。'],
  'H0705': ['侧躺，双腿伸展并叠放在一起。', '将前臂放在肩膀正下方的地面上，肘部弯曲成 90 度角。', '启动你的核心并将臀部抬离地面，从头到脚形成一条直线。', '保持此位置所需的时间。', '将臀部放低至起始位置。', '在另一侧重复。'],
  'H0709': ['站在两根平行杠之间，双脚分开与肩同宽。', '将双手放在横杆上，将身体抬离地面，用手臂支撑体重。', '收紧腹肌，慢慢将双腿向一侧抬起，保持伸直。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H0710': ['双脚分开与肩同宽站立，双手放在臀部。', '将重心转移到一条腿上，并将另一条腿向一侧抬起，保持伸直。', '在顶部暂停片刻，然后慢慢将腿放回起始位置。', '在另一侧重复。', '继续交替进行所需的重复次数。'],
  'H1358': ['侧躺，双腿伸直，下臂伸直过头顶。', '弯曲上面的膝盖，将脚放在下面的腿前面的地面上。', '将上臂伸过头顶，抓住稳定的东西，例如墙壁或一件家具。', '慢慢地将下面的腿抬离地面，保持伸直，直到感觉到身体一侧有拉伸感。', '保持拉伸 20-30 秒，然后慢慢将腿放下。', '在另一侧重复。'],
  'H3667': ['侧躺，双腿伸直并叠放在一起。', '将下臂放在头下方以获得支撑。', '启动内收肌并尽可能高地抬起上面的腿，但不要旋转臀部或向后倾斜。', '在顶部暂停片刻，然后慢慢将腿放回起始位置。', '重复所需的重复次数，然后换边。'],
  'H0716': ['站直或坐直，肩膀放松。', '将头向右倾斜，将右耳靠近右肩。', '将右手放在头部左侧，轻轻施加压力以增加拉伸。', '保持拉伸 15-30 秒。', '在另一侧重复，将头向左倾斜并用左手施加压力。', '每侧重复拉伸 2-3 次。'],
  'H0717': ['首先侧躺，双腿伸展并叠放在一起。', '将下面的手放在肩膀正下方的地面上，手指指向前方。', '用下面的手将身体抬离地面，保持双腿伸直，核心肌群参与。', '将上臂伸向天花板，形成从头部到脚后跟的直线。', '有控制地降低身体回到起始位置。', '重复所需的重复次数，然后换边。'],
  'H0721': ['双脚分开与肩同宽站立，双臂在身前伸展。', '将右臂向侧面伸出，与地面平行，手掌朝下。', '用左手抓住右手，轻轻地将其拉向身体，感觉右前臂有拉伸感。', '保持拉伸 15-30 秒，然后放松。', '在另一侧重复。'],
  'H0720': ['双脚分开与肩同宽站立，膝盖稍微弯曲。', '正手握住引体向上杆，双手之间的距离略大于肩宽。', '悬挂在杠上，双臂完全伸展，身体放松。', '弯曲肘部并将下巴朝向杠铃杆，将自己拉起，同时保持身体挺直。', '一旦你的下巴高于杠铃，就将自己放低回到起始位置。', '重复所需的重复次数。'],
  'H3213': ['双脚分开与肩同宽站立，双臂向两侧伸展。', '腰部向右弯曲，将右手伸向右脚，同时保持左手向一侧延伸。', '返回起始位置，然后腰部向左弯曲，将左手伸向左脚，同时保持右手向侧面延伸。', '重复左右弯曲动作达到所需的重复次数。'],
  'H0725': ['从俯卧撑位置开始，双手分开与肩同宽，一只手比另一只手稍宽。', '弯曲肘部，保持背部挺直，调动核心力量，将身体降低至地面。', '当你降低身体时，将你的重心转移到一侧，并将另一只手臂抬离地面，将其笔直延伸到一侧。', '推动胸部和三头肌，将身体抬回到起始位置，同时将伸出的手臂放回地面。', '重复该动作，每次重复时交替伸展手臂。'],
  'H3645': ['仰卧，膝盖弯曲，双脚平放在地上。', '将一条腿伸直在您面前。', '收紧臀部并将臀部抬离地面，从膝盖到肩膀形成一条直线。', '在顶部保持片刻，然后慢慢将臀部放回起始位置。', '重复所需的重复次数，然后换腿。'],
  'H0727': ['双脚分开与臀部同宽站立，一只手握住哑铃。', '将一只脚抬离地面并用另一只脚保持平衡。', '使用小腿肌肉，慢慢地将脚跟抬高，尽可能高。', '在顶部停顿片刻，然后慢慢降低脚跟。', '重复所需的重复次数，然后换另一条腿。'],
  'H0730': ['首先将一只脚站在平台或滑板上。', '稍微弯曲膝盖，将脚向后滑动到平台上，伸展腿。', '在整个运动过程中保持核心参与并保持笔直姿势。', '将脚滑回初始位置，慢慢返回起始位置。', '重复该动作达到所需的重复次数，然后换腿。'],
  'H1759': ['双脚分开与肩同宽站立，双臂在身前伸展。', '将右脚抬离地面并向前伸展。', '弯曲左膝并将臀部向后推，慢慢降低身体。', '降低身体时，保持挺胸、背部挺直。', '降低直到左大腿与地面平行，或者尽可能降低到您能舒服的高度。', '在底部停顿片刻，然后推动左脚跟回到起始位置。', '重复所需的重复次数，然后换腿。'],
  'H0735': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H3679': ['平躺，膝盖弯曲，双脚平放在地上。', '双臂交叉于胸前。', '收紧腹肌，将上半身抬离地面，靠近膝盖。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H3361': ['双脚分开与肩同宽站立。', '稍微弯曲膝盖，向右跳，右脚着地。', '落地时，将左腿摆动到右腿后面，并用左脚趾敲击地面。', '立即向左侧跳跃，左脚着地。', '落地时，将右腿摆动到左腿后面，并用右脚趾敲击地面。', '继续交替两侧，跳跃并用每条腿敲击地面。', '重复所需的重复次数。'],
  'H2142': ['将座椅高度和脚踏板调整到舒适的位置。', '正手握住手柄，手掌朝下。', '坐直，双脚平放在脚踏板上。', '将手臂伸直在身前，保持肘部稍微弯曲。', '收紧三头肌并将手柄向下推向大腿。', '在底部停顿片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H3671': ['双脚分开与肩同宽站立。', '稍微弯曲膝盖并保持背部挺直。', '跳到右侧，右脚着地，同时将左腿摆动到右腿后面。', '立即向左侧跳，左脚着地，同时将右腿摆动到左腿后面。', '继续从一侧到另一侧交替跳跃，模仿滑雪动作。', '重复所需的重复次数。'],
  'H3304': ['首先，将双臂完全伸展，身体放松地悬挂在杆上。', '收紧核心并抬起双腿，使膝盖靠近胸部。', '继续将双腿举过头顶，让身体穿过手臂。', '一旦双腿完全伸过头顶，就开始将它们放回起始位置。', '当你降低双腿时，让你的身体通过手臂向后移动，直到你再次完全伸展手臂悬挂。', '重复所需的重复次数。'],
  'H1425': ['将雪橇机调整至 45 度角。', '坐在雪橇机上，背部靠在垫子上，双脚放在踏板上。', '将一只脚放在踏板上并伸展腿，将雪橇推离您。', '慢慢弯曲膝盖，将雪橇放回起始位置。', '换另一条腿重复上述步骤。', '继续交替双腿达到所需的重复次数。'],
  'H0738': ['将雪橇机调整至 45 度角。', '将脚放在雪橇平台上，脚趾朝前。', '伸展脚踝和小腿，将雪橇平台推离您。', '在顶部暂停片刻，然后慢慢将雪橇平台放回起始位置。', '重复所需的重复次数。'],
  'H0739': ['将雪橇机的座椅和脚踏板调整到舒适的位置。', '坐在雪橇机上，背部靠在靠背上，双脚与肩同宽放在踏板上。', '握住座椅两侧的把手以保持稳定性。', '伸展双腿，将脚踏板推离身体，脚后跟保持在脚踏板上。', '继续推动，直到双腿几乎完全伸展，但不要锁住膝盖。', '在动作的最高点暂停片刻，然后弯曲膝盖，慢慢地将踏板放回到身体的方向。', '重复所需的重复次数。'],
  'H1464': ['调整雪橇机的座椅，使膝盖成45度角。', '坐在雪橇机上，背部靠在靠背上，双脚与肩同宽放在踏板上。', '握住座椅两侧的把手以保持稳定性。', '伸展双腿，将脚踏板推离身体，脚后跟保持在脚踏板上。', '在完全伸展的位置暂停片刻。', '慢慢弯曲膝盖，将踏板放回到身体的方向，控制动作。', '重复所需的重复次数。'],
  'H1463': ['调整雪橇机的座椅，使双脚放在踏板上时膝盖呈90度角。', '坐在雪橇机上，背部平放在靠背上，双脚与肩同宽放在踏板上。', '握住座椅两侧的把手以保持稳定性。', '推动脚踏板以伸展双腿，将其完全伸直。', '在顶部停顿片刻，然后慢慢弯曲膝盖，将踏板放回起始位置。', '重复所需的重复次数。'],
  'H0740': ['将雪橇机调整至 45 度角。', '坐在雪橇机上，背部靠在垫子上，双脚放在脚踏平台上。', '双脚分开的距离比肩宽。', '推动脚部平台以伸展双腿并伸直膝盖。', '动作结束时暂停片刻，然后慢慢弯曲膝盖回到起始位置。', '重复所需的重复次数。'],
  'H1391': ['调整压腿机的座椅，使双脚踩在雪橇上时膝盖稍微弯曲。', '将双脚与肩同宽放在雪橇上，脚趾指向前方。', '松开安全手柄，并通过伸展膝盖和脚踝将雪橇推离您。', '在动作的最高点暂停片刻，然后弯曲膝盖和脚踝，慢慢将雪橇放回原处。', '重复所需的重复次数。'],
  'H0741': ['将雪橇机调整到舒适的重量，并将背部靠在垫子上。', '将双脚分开与肩同宽放在平台上，脚趾稍微向外。', '握住机器两侧的手柄以保持稳定性。', '弯曲膝盖和臀部，调动核心力量，慢慢降低身体，保持背部挺直。', '继续降低，直到大腿与地面平行或略低于地面。', '在底部停顿片刻，然后用脚跟推动双腿并返回到起始位置。', '重复所需的重复次数。'],
  'H0742': ['将雪橇机调整到舒适的重量，然后将自己放在机器上，脚趾放在平台上，脚后跟悬空。', '将手放在机器的手柄或侧面上以获得支撑。', '收紧小腿，慢慢地尽可能高地抬起脚后跟，克服雪橇的阻力。', '在动作的最高点暂停片刻，然后慢慢降低脚跟回到起始位置。', '重复所需的重复次数。'],
  'H0743': ['将雪橇机调整到适合您身高的舒适位置。', '双脚与肩同宽站立在平台上，脚趾稍微向外。', '握住手柄或杆以保持稳定性。', '弯曲膝盖和臀部，降低身体，保持背部挺直，挺胸。', '继续降低，直到大腿与地面平行或略低于地面。', '暂停片刻，然后用脚后跟将身体抬回到起始位置。', '重复所需的重复次数。'],
  'H2334': ['将雪橇机调整至舒适的重量。', '坐在雪橇机上，背部靠在垫子上，双脚放在平台上。', '将脚趾和脚掌放在平台边缘，脚跟悬空。', '伸展脚踝，将平台推离您，保持膝盖稍微弯曲。', '继续用力，直到小腿完全收缩。', '保持收缩一会儿，然后慢慢将平台放回起始位置。', '重复所需的重复次数。'],
  'H0744': ['将雪橇机调整至舒适的重量。', '仰卧在雪橇机上，双脚放在踏板上。', '双脚分开与肩同宽，并稍微向外倾斜。', '握住雪橇机的手柄以保持稳定。', '调动你的臀肌和核心肌肉。', '脚后跟用力，双腿伸直，抬起雪橇。', '弯曲膝盖和臀部，将雪橇放回原位。', '重复所需的重复次数。'],
  'H1392': ['调整压腿机的座椅，使双脚踩在雪橇上时膝盖稍微弯曲。', '坐在机器上，背部靠在靠背上，双脚放在雪橇上，与肩同宽。', '将脚趾和脚掌放在雪橇上，保持脚跟离开。', '伸展脚踝，保持膝盖稍微弯曲，将雪橇向前推。', '在顶部停顿片刻，然后通过弯曲脚踝慢慢将雪橇放回原处。', '重复所需的重复次数。'],
  'H1496': ['双脚分开与肩同宽站立，双手握住大锤。', '启动你的核心并保持背部挺直。', '使用核心和上半身的力量，将大锤向下挥向地面。', '当你向下挥杆时，转动臀部并将力量传递到锤子上。', '重复所需的重复次数。'],
  'H0746': ['双脚分开与肩同宽站立，膝盖稍微弯曲。', '正手握住杠铃，双手间距略宽于肩宽。', '保持手臂伸直，让杠铃挂在大腿前面。', '将肩膀向耳朵方向伸直，挤压斜方肌顶部。', '保持一会儿，然后将肩膀放回起始位置。', '重复所需的重复次数。'],
  'H0747': ['调整史密斯机的座椅高度，使杠铃与肩部齐平。', '双脚分开与肩同宽站立，膝盖稍微弯曲。', '正手握住杠铃，握距略宽于肩宽。', '将杠铃从架子上抬起并向后退一步，保持稳定的姿势。', '将杠铃降低到颈后，保持肘部向前。', '将杠铃向上推过头顶，直到双臂完全伸展。', '在顶部暂停片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0749': ['首先站立，双脚分开与肩同宽，脚趾指向前方。', '将杠铃放在上背部，放在斜方肌上。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '降低躯干直到与地面平行，感觉腿筋被拉伸。', '启动臀肌和腿筋，将躯干抬回到起始位置。', '重复所需的重复次数。'],
  'H1359': ['将史密斯机设置为与臀部高度相同的杠铃。', '面向杠铃站立，双脚分开与肩同宽。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '正手握住杠铃，双手距离略宽于肩宽。', '将杠铃拉向下胸部，将肩胛骨挤压在一起。', '在顶部暂停片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0750': ['将史密斯机杆的高度调整到舒适的位置。', '站立，双脚分开与肩同宽，脚趾稍微向外。', '将杠铃放在上背部，放在斜方肌上。', '通过弯曲膝盖和臀部慢慢降低身体，收紧核心并保持挺胸。', '继续降低，直到大腿与地面平行，或者尽可能低。', '暂停片刻，然后用力推动脚后跟，回到起始位置。', '重复所需的重复次数。'],
  'H0752': ['将史密斯机设置为与臀部高度相同的杠铃。', '双脚分开与肩同宽站立，脚趾稍微向外。', '弯曲臀部和膝盖，保持背部挺直，挺胸，正手握住杠铃，握距略宽于肩宽。', '伸展臀部和膝盖，调动核心力量并举起杠铃，保持杠铃靠近身体。', '站直，充分伸展臀部和膝盖。', '通过弯曲臀部和膝盖来降低杠铃，保持控制并保持背部挺直。', '重复所需的重复次数。'],
  'H0753': ['将下斜凳调整至所需角度。', '躺在长凳上，双脚固定在脚垫下。', '正手握住杠铃，握距略宽于肩宽。', '松开杠铃，慢慢将其降低到胸部，保持肘部内收。', '在底部停顿片刻，然后将杠铃推回到起始位置。', '重复所需的重复次数。'],
  'H0754': ['将史密斯机调整至下降位置。', '躺在长凳上，双脚固定在脚垫下。', '反握抓住杠铃，双手分开略宽于肩宽。', '松开杠铃并将其向胸部降低，保持肘部内收。', '在底部停顿片刻，然后将杠铃推回到起始位置。', '重复所需的重复次数。'],
  'H1433': ['将杠铃置于肩高的史密斯机上。', '面向杠铃站立，双脚与肩同宽。', '正手握住杠铃，握距略宽于肩宽。', '后退一步，将杠铃放在前肩上，放在锁骨和三角肌上。', '保持挺胸、背部挺直、核心收紧。', '弯曲膝盖和臀部，降低身体，就像坐回椅子上一样。', '继续降低，直到大腿与地面平行或略低于地面。', '暂停片刻，然后用力推动脚后跟，回到起始位置。', '重复所需的重复次数。'],
  'H0756': ['将自己放在史密斯机上，背部靠在垫子上，双脚分开与肩同宽。', '将双手放在杠铃上，距离略宽于肩宽。', '启动你的核心肌群和臀大肌，然后通过脚后跟将臀部抬离地面。', '继续提升，直到身体从膝盖到肩膀形成一条直线。', '在顶部保持片刻，然后慢慢将臀部放回起始位置。', '重复所需的重复次数。'],
  'H0758': ['将史密斯机的座椅调整到舒适的倾斜角度。', '坐在机器上，背部靠在垫子上，双脚平放在地面上。', '正手握住杠铃，握距略宽于肩宽。', '松开杠铃并将其缓慢降低至胸部，同时保持肘部内收。', '当杠铃位于胸部正上方时，暂停片刻。', '将杠铃推回到起始位置，完全伸展双臂。', '重复所需的重复次数。'],
  'H0759': ['将史密斯机调整至倾斜位置。', '面向机器站立，双脚分开与肩同宽。', '正手握住杠铃，握距略宽于肩宽。', '保持背部挺直，核心参与。', '将杠铃举向天花板，用肘部引导。', '在顶部停顿片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0760': ['将史密斯机的座椅和脚踏板调整到舒适的位置。', '坐在机器上，背部靠在靠背上，双脚与肩同宽放在踏板上。', '抓住机器的手柄或侧面以保持稳定性。', '伸展双腿，使背部紧靠靠背，将脚踏板推离您。', '在完全伸展的位置暂停片刻。', '慢慢弯曲膝盖，将脚踏板向您的方向放低，回到起始位置。', '重复所需的重复次数。'],
  'H1434': ['将史密斯机与杠铃设置在一个高度，以便您可以将其舒适地放在上背部。', '站立，双脚分开与肩同宽，脚趾稍微向外转动。', '走到杠铃下方，将其放在上背部上方，将其放在斜方肌上。', '双手握住杠铃，距离略大于肩宽。', '伸直双腿并从架子上退后，将杠铃松开。', '深呼吸并支撑你的核心。', '通过向后推臀部并弯曲膝盖来开始深蹲。', '降低身体，直到大腿与地面平行或稍低于地面。', '在整个动作过程中保持挺胸、背部挺直。', '通过脚后跟站起来，伸展臀部和膝盖。', '重复所需的重复次数。'],
  'H1683': ['将史密斯机杆的高度调整到腰部水平。', '面对史密斯机站立，双脚与肩同宽。', '反手握住杠铃，双手间距略大于肩宽。', '保持肘部靠近身体两侧，上臂保持静止。', '呼气并将杠铃向上卷向肩膀，收缩二头肌。', '在动作的最高点暂停片刻，挤压你的二头肌。', '吸气并慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H1625': ['将史密斯机上的长凳调整至下降位置。', '躺在长凳上，双脚牢牢踩在地上。', '紧紧握住杠铃，握距略窄于肩宽。', '松开杠铃并将其缓慢降低至胸部，保持肘部靠近身体。', '当杠铃位于胸部正上方时，暂停片刻。', '将杠铃推回到起始位置，完全伸展双臂。', '重复所需的重复次数。'],
  'H1752': ['调整史密斯机的座椅，使杠铃处于肩部高度。', '坐在长凳上，背部靠在垫子上，双脚平放在地上。', '正手握住杠铃，握距略宽于肩宽。', '充分伸展双臂，将杠铃从架子上提起，并将其保持在胸部正上方。', '慢慢地将杠铃降低到前额，保持肘部靠近头部。', '在底部暂停片刻，然后将杠铃推回到起始位置。', '重复所需的重复次数。'],
  'H1626': ['将史密斯机调整至下降位置。', '躺在长凳上，双脚固定在脚垫下。', '紧紧握住杠铃，握距略窄于肩宽。', '松开杠铃，慢慢将其降低到胸部，保持肘部内收。', '在底部停顿片刻，然后将杠铃推回到起始位置。', '重复所需的重复次数。'],
  'H0761': ['调整座椅高度并将自己放在机器上，双脚平放在地板上。', '正手握住手柄，握距略窄于肩宽。', '当您将手柄拉向身体时，保持背部挺直，挺胸，将肩胛骨挤压在一起。', '在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。', '重复所需的重复次数。'],
  'H1360': ['将史密斯机杆的高度调整至腰部水平。', '面对史密斯机站立，双脚与肩同宽。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '用一只手正手握住杠铃，手掌朝下。', '保持肘部靠近身体，将杠铃拉向腰部，将肩胛骨挤压在一起。', '在动作的最高点暂停片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数，然后换到另一只手臂。'],
  'H1393': ['将自己放在史密斯机杆下方的地板上，背对机器。', '将脚掌放在凸起的表面上，例如举重板或杠铃块。', '将史密斯机杆放在小腿上，就在脚踝上方。', '用手握住横杆以保持稳定。', '伸展脚踝，将脚后跟抬离地面，抬起身体。', '在动作的最高点暂停，然后慢慢降低脚跟回到起始位置。', '重复所需的重复次数。'],
  'H0763': ['将史密斯机杆调整到略低于肩膀的高度。', '面向杠铃站立，双脚分开与臀部同宽，脚趾向前。', '将脚掌放在台阶或平台的边缘，脚后跟悬空。', '握住杠铃以提供支撑，保持背部挺直，核心肌群参与。', '尽可能高地抬高脚后跟，将身体重量转移到脚掌上。', '在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H1361': ['将史密斯机设置为与臀部高度相同的杠铃。', '面向杠铃站立，双脚分开与肩同宽。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '反手握住杠铃，双手与肩同宽。', '将杠铃拉向下胸部，将肩胛骨挤压在一起。', '在顶部暂停片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0764': ['将史密斯机杆的高度调整至胸部水平。', '面向杠铃站立，双脚分开与肩同宽。', '正手握住杠铃，双手距离略宽于肩宽。', '退后一步，膝盖稍微弯曲。', '在整个练习过程中保持挺胸并保持核心参与。', '将杠铃向胸部方向降低，保持肘部内收。', '在底部暂停片刻，然后将杠铃推回到起始位置。', '重复所需的重复次数。'],
  'H1395': ['坐在机器上，背部靠在垫子上，双脚放在脚踏板上。', '将一条腿放在脚踏板上，另一条腿离开脚踏板。', '使用小腿肌肉，尽可能高地抬高脚跟。', '在顶部暂停片刻，然后慢慢将脚跟放回起始位置。', '重复所需的重复次数，然后换腿并重复。'],
  'H0765': ['调整座椅高度，使手柄与肩部齐平。', '坐在机器上，背部靠在垫子上，双脚平放在地板上。', '正手握住手柄，将其提离支撑物，充分伸展双臂。', '将手柄降低至肩部水平，保持肘部稍微弯曲。', '将手柄向上推过头顶，直到手臂完全伸展。', '在顶部暂停片刻，然后慢慢将手柄放回至肩部水平。', '重复所需的重复次数。'],
  'H1426': ['坐在史密斯机前的长凳上，双脚平放在地面上。', '反握抓住杠铃，双手与肩同宽。', '将前臂放在大腿上，让手腕悬垂。', '慢慢向上弯曲手腕，将杠铃拉向前臂。', '在顶部停顿片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0769': ['将杠铃置于臀部高度的史密斯机上。', '背对机器站立，双脚与肩同宽。', '右脚向后退一步，将其放在杠铃上，将脚尖放在杠上。', '弯曲左膝，将身体降低到弓步位置，保持背部挺直。', '推动左脚跟返回到起始位置。', '在另一侧重复，左脚向后退一步。', '继续交替进行所需的重复次数。'],
  'H0770': ['将史密斯机和杠铃设置在适合深蹲的高度。', '站立，双脚分开与肩同宽，脚趾稍微向外。', '将自己置于杠铃下方，将其放在斜方肌上部和肩膀上。', '宽握距握住杠铃，握距略宽于肩宽。', '启动你的核心并打开杠铃，后退以清理架子。', '保持胸部挺直，背部挺直，通过弯曲臀部和膝盖开始深蹲。', '降低身体，直到大腿与地面平行或稍低于地面。', '在底部停顿片刻，然后用脚后跟恢复到起始位置。', '重复所需的重复次数。'],
  'H0771': ['面对史密斯机站立，双脚与肩同宽。', '正手握住杠铃，双手与肩同宽。', '保持背部挺直，肘部靠近身体。', '慢慢向上弯曲手腕，将杠铃拉向身体。', '在顶部停顿片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0772': ['调整史密斯机的座椅高度，使杠铃与肩部齐平。', '双脚分开与肩同宽站立，膝盖稍微弯曲。', '正手握住杠铃，握距略宽于肩宽。', '将杠铃从架子上抬起并向后退一步，保持稳定的姿势。', '将杠铃放在脑后，放在斜方肌上部。', '在整个练习过程中保持核心收紧并抬起胸部。', '伸展双臂，完全伸直，将杠铃推过头顶。', '在动作的最高点稍作停顿，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H0773': ['将史密斯机杆调整到一个高度，使您能够双脚平放在地面上且肩膀位于杆下方。', '将自己置于杠铃下方，双脚分开与肩同宽，脚趾向前。', '将双手放在横杆上以保持稳定。', '收紧小腿，慢慢将脚跟抬离地面，将身体抬起到脚趾上。', '在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H0774': ['双脚分开与肩同宽站立，膝盖稍微弯曲。', '正手握住杠铃，握距略宽于肩宽。', '将杠铃从架子上提起，并将其降至与肩同高，手掌朝前。', '向上推杠铃，直到手臂完全伸过头顶。', '在顶部停顿片刻，然后慢慢将杠铃放回至肩部水平。', '重复所需的重复次数。'],
  'H3142': ['将杠铃置于臀部高度的史密斯机上。', '站立，双脚分开比肩宽，脚趾朝外。', '将自己置于杠铃下方，将其放在上背部和肩膀上。', '当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。', '放低身体，直到大腿与地面平行，或者尽可能低到您能舒服的高度。', '在底部停顿片刻，然后推动脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H1396': ['将史密斯机杆调整到一个高度，让您可以舒适地站立，双脚平放在地面上。', '将自己置于杠铃下方，肩膀位于杠铃正下方，双脚分开与肩同宽。', '将脚掌放在升高的平台或重量板上，脚后跟悬在边缘。', '正手握住杠铃，握距略宽于肩宽。', '在整个练习过程中启动你的核心并保持背部挺直。', '慢慢地尽可能高地抬起脚后跟，将身体重量转移到脚掌上。', '在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H1308': ['将史密斯机上的长凳调整到舒适的位置。', '躺在长凳上，双脚平放在地上。', '宽握距抓住杠铃，握距略宽于肩宽。', '松开杠铃并将其慢慢降低到胸部，保持肘部向两侧伸出。', '当杠铃触及胸部时暂停片刻。', '将杠铃推回到起始位置，完全伸展双臂。', '重复所需的重复次数。'],
  'H1309': ['将下斜凳调整至所需角度。', '躺在长凳上，双脚固定在脚垫下。', '宽握距抓住杠铃，握距略宽于肩宽。', '松开杠铃并将其慢慢降低到胸部，保持肘部朝外。', '当杠铃触及胸部时暂停片刻。', '将杠铃推回到起始位置，完全伸展双臂。', '重复所需的重复次数。'],
  'H0776': ['双脚分开与肩同宽站立，杠铃放在你面前的地面上。', '弯曲膝盖并以臀部为铰链，降低至下蹲位置，用正手握住杠铃。', '当你通过脚后跟将杠铃抬离地面时，保持背部挺直，挺胸，伸展臀部和膝盖。', '当杠铃到达臀部水平时，爆发性地将其向上拉，耸肩并将肘部向两侧拉高。', '当杠铃到达最高点时，迅速落到杠铃下方，将自己拉成深蹲位置。', '双臂完全伸展，膝盖弯曲，将杠铃举过头顶。', '伸展臀部和膝盖站起来，将杠铃保持在头顶上方。', '通过反向运动将杠铃降低回起始位置。', '重复所需的重复次数。'],
  'H0777': ['双脚分开与肩同宽站立，一只手握住哑铃。', '稍微弯曲膝盖，腰部向前转动，保持背部挺直。', '将哑铃伸向另一只脚的手臂，同时旋转躯干。', '返回起始位置并在另一侧重复。', '继续交替进行所需的重复次数。'],
  'H1362': ['面朝下躺在地上，前臂平放在地板上，肘部直接位于肩膀下方。', '收紧核心肌群，将胸部抬离地面，将前臂和脚趾保持在地板上。', '保持这个姿势几秒钟，确保颈部保持在中立位置。', '慢慢地将胸部放回起始位置。', '重复所需的重复次数。'],
  'H0778': ['从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。', '将右膝靠近右肘，使其离开地面。', '当您将右膝向后拉时，同时弯曲肘部将身体降低到地面。', '推回起始位置，然后将左膝朝向左肘重复此动作。', '继续交替进行所需的重复次数。'],
  'H1363': ['坐在地上，双腿在身前伸展。', '将双手放在身后的地面上，手指指向身体。', '启动你的核心并慢慢向后倾斜，保持背部挺直。', '继续向后倾斜，直到感觉到脊柱被拉伸。', '保持伸展几秒钟，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H2329': ['坐在地上，双腿在身前伸展。', '弯曲膝盖，将双脚平放在地面上，距离与臀部同宽。', '将双手放在脑后，肘部朝外。', '收紧腹肌，慢慢向右扭转躯干，将右肘拉向左膝盖。', '扭转结束时暂停片刻，然后慢慢回到起始位置。', '向左侧重复扭转，将左肘拉向右膝盖。', '继续交替进行所需的重复次数。'],
  'H0786': ['首先将杠铃放在肩膀上，双脚分开与肩同宽。', '将身体降低至蹲姿，保持挺胸，膝盖位于脚趾上方。', '当你到达深蹲底部时，爆发性地用腿发力，并将杠铃推过头顶。', '当杠铃到达最高点时，迅速落入分体位置，一脚向前，一脚向后。', '双臂完全伸展，后膝盖稍微接触地面，将杠铃举过头顶。', '从分开的位置站起来，将双脚重新并拢。', '将杠铃放回肩膀处，然后重复所需的重复次数。'],
  'H1705': ['将博苏球平放在地上。', '双脚分开与肩同宽站立，将自己放在博苏球的顶部。', '弯曲膝盖和臀部，降低身体，就像坐回椅子上一样。', '保持挺胸，将体重放在脚后跟上。', '降低身体直到大腿与地面平行。', '暂停片刻，然后用力推动脚后跟，回到起始位置。', '重复所需的重复次数。'],
  'H1686': ['站立，双脚分开与肩同宽，脚趾稍微外翻。', '弯曲膝盖并将臀部向后推，将身体降低至蹲姿。', '当你从深蹲中站起来时，将手臂举过头顶并将躯干扭转到一侧。', '返回起始位置并重复下蹲，这次将躯干扭转到另一侧。', '每次深蹲重复时继续交替进行。'],
  'H2297': ['坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。', '将双手放在脑后，肘部朝外。', '收紧腹肌，慢慢向前弯曲上半身，使胸部靠近膝盖。', '在顶部停顿片刻，然后慢慢降低上半身回到起始位置。', '重复所需的重复次数。'],
  'H3291': ['首先站立，双脚分开与肩同宽，双臂伸过头顶。', '稍微弯曲膝盖并启动核心。', '将身体降低至蹲姿，同时保持手臂伸过头顶。', '当你蹲下时，将手臂向下压向地面，锻炼三头肌。', '在深蹲底部停顿片刻，然后用脚后跟站起来，同时将手臂举过头顶。', '重复所需的重复次数。'],
  'H3669': ['双脚分开与肩同宽站立，膝盖稍微弯曲。', '将双臂伸直至前方，与肩同高，与地面平行。', '将躯干向右旋转，保持双臂伸展，背部挺直。', '旋转时，向前伸展右臂，向后伸展左臂，模仿拉弓弦的动作。', '保持该姿势片刻，然后回到起始位置。', '重复该动作，这次将躯干向左旋转，左臂向前伸展，右臂向后伸展。', '继续交替进行所需的重复次数。'],
  'H0788': ['双脚分开与肩同宽站立，用正手握法将杠铃握在颈后。', '保持背部挺直，核心参与。', '伸展手臂，充分伸展肘部，将杠铃推过头顶。', '在顶部停顿片刻，然后慢慢将杠铃放回起始位置。', '重复所需的重复次数。'],
  'H1490': ['站在台阶或坚固平台的边缘，脚后跟悬垂，脚趾放在台阶上。', '如果需要，抓住栏杆或墙壁以保持平衡。', '慢慢地尽可能高地抬起脚后跟，将身体重量转移到脚掌上。', '在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。', '重复所需的重复次数。'],
  'H1397': ['双脚分开与肩同宽站立，脚趾指向前方。', '将脚后跟抬离地面，尽可能高，用脚趾站立。', '保持该姿势片刻，然后慢慢降低脚跟回到起始位置。', '重复所需的重复次数。'],
  'H1398': ['面朝墙壁或坚固物体站立，距离大约一臂远。', '将手放在与肩同高的墙壁或物体上。', '一只脚向后退一步，保持脚跟平放在地面上。', '稍微弯曲前膝盖并向前倾斜，保持后腿伸直。', '您应该感觉到小腿肌肉有拉伸感。', '保持拉伸 20-30 秒。', '在另一条腿上重复。'],
  'H1599': ['站直，双脚分开与肩同宽。', '用双手握住带子并将其放在脚掌周围。', '保持腿伸直，从臀部慢慢向前倾斜，保持背部挺直。', '感受腿筋和小腿肌肉的拉伸。', '保持拉伸 20-30 秒。', '放松拉伸并用另一条腿重复。', '重复所需的重复次数。'],
  'H0794': ['双脚分开与肩同宽站立，膝盖稍微弯曲。', '将双臂伸直至两侧，与地面平行。', '慢慢将上半身向一侧倾斜，感觉侧面和背阔肌有拉伸感。', '保持拉伸 15-30 秒。', '返回起始位置并在另一侧重复。', '重复所需的重复次数。'],
  'H1364': ['双脚分开与肩同宽站立，膝盖稍微弯曲。', '将双手放在臀部或垂在身体两侧。', '调动核心肌肉并向前倾斜骨盆，将下背部推向身后的墙壁。', '保持该位置几秒钟，然后松开并返回到起始位置。', '重复所需的重复次数。'],
  'H0795': ['站立，双脚分开与臀部同宽，双手放在臀部。', '将体重转移到左腿上，将右脚抬离地面，弯曲膝盖。', '慢慢地将右脚跟卷向臀部，挤压腿筋。', '在顶部暂停片刻，然后慢慢将右脚放回起始位置。', '重复所需的重复次数，然后换腿。'],
  'H0796': ['首先，站直，双脚分开与肩同宽，滚轮位于您的前方。', '弯腰，慢慢向前滚动轮子，保持背部挺直，核心肌群参与。', '继续向前滚动，直到感觉到腹肌拉伸并且身体尽可能伸展。', '暂停片刻，然后慢慢地将轮子向身体方向滚动，回到起始位置。', '重复所需的重复次数。'],
  'H3223': ['双脚分开与肩同宽站立，双臂放在身体两侧。', '稍微弯曲膝盖并爆发性地跳起来。', '跳跃时，张开双腿，将手臂向两侧伸展，与身体形成星形。', '膝盖轻轻弯曲，脚掌轻轻着地。', '重复所需的重复次数。'],
  'H2138': ['调整座椅高度和位置以确保正确对齐。', '将脚放在踏板上，并用带子（如果有）将其固定。', '以舒适的速度开始踩踏板。', '保持稳定的节奏并根据需要增加阻力。', '调动核心肌肉以保持稳定性和正确的姿势。', '继续踩踏板达到所需的锻炼时间。', '逐渐减小阻力并减速，然后完全停止。', '锻炼后伸展双腿并放松。'],
  'H0798': ['调整固定自行车上的座椅高度和位置，以确保正确对齐。', '将脚放在踏板上，并用带子（如果有）将其固定。', '以舒适的速度开始踩踏，保持背部挺直，核心参与。', '保持稳定的节奏，并根据需要增加阻力水平。', '继续踩踏您的有氧运动所需的持续时间。', '通过逐渐降低步速和阻力水平来冷静下来。', '锻炼后伸展腿部肌肉，以防止紧绷并促进恢复。'],
  'H3314': ['首先，悬挂在一对环上，双臂完全伸展，身体呈一条直线。', '双腿分开，形成跨坐姿势。', '启动你的核心并慢慢降低你的身体，直到你的手臂与地面平行。', '保持这个姿势几秒钟，然后将自己推回到起始位置。', '重复所需的重复次数。'],
  'H3298': ['从俯卧撑位置开始，双手与肩同宽，双脚分开。', '启动你的核心，慢慢地将你的重心向前移动，将你的肩膀放在你的手上。', '弯曲肘部，将身体放低至地面，保持肘部靠近身体两侧。', '在底部停顿片刻，然后双手用力伸直手臂，将身体抬回到起始位置。', '重复所需的重复次数。'],
  'H1427': ['侧躺，双腿伸直并叠放在一起。', '将下臂放在头下方以获得支撑。', '启动你的核心并尽可能高地抬起你的上腿，不要旋转你的臀部或向后倾斜。', '在顶部暂停片刻，然后慢慢将腿放回起始位置。', '重复所需的重复次数，然后换边。'],
  'H0803': ['从高位平板支撑开始，双手分开略宽于肩宽，双脚并拢。', '收紧核心，将身体降低到地面，保持肘部靠近身体两侧。', '当你降低身体时，同时将右臂和左腿抬离地面，笔直向外伸展。', '在顶部暂停片刻，然后放下手臂和腿，同时将自己推回起始位置。', '重复该动作，这次抬起左臂和右腿。', '继续交替进行所需的重复次数。'],
  'H0805': ['将悬挂训练器连接到高锚点并将带子调整至腰部高度。', '背对锚点站立，并握住手柄，双臂向前伸展。', '腰部向前倾，保持身体挺直，核心肌群参与。', '尽可能降低身体，同时保持腹肌的控制和紧张。', '在底部停顿片刻，然后慢慢抬起身体回到起始位置。', '重复所需的重复次数。'],
  'H0806': ['找到一个悬挂训练器并将其调整到合适的高度。', '背对锚点站立，并用正手握住手柄。', '双脚向前走，身体向前倾斜，直到悬架训练器支撑您的体重。', '保持身体从头到脚跟伸直，核心部位收紧，胸部朝手柄方向降低。', '推动你的胸部和手臂回到起始位置。', '重复所需的重复次数。'],
  'H0807': ['悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。', '收紧核心肌群，将膝盖抬向胸部，将骨盆卷向胸腔。', '在顶部暂停片刻，然后慢慢将膝盖放回起始位置。', '重复所需的重复次数。'],
  'H0808': ['将悬挂训练器设置在适当的高度。', '面向锚点站立，双脚分开与肩同宽。', '正手握住手柄，手掌相对。', '向后倾斜，保持身体挺直，脚后跟着地。', '将胸部拉向手柄，将肩胛骨挤压在一起。', '在顶部停顿片刻，然后慢慢降低回到起始位置。', '重复所需的重复次数。'],
  'H0809': ['背对悬吊训练器站立，双脚与肩同宽。', '向前伸展一条腿，将脚背放在悬吊训练器的脚托中。', '弯曲站立的腿，将身体降低到弓步位置，保持胸部向上，膝盖与脚趾对齐。', '推动脚后跟返回到起始位置。', '重复所需的重复次数，然后换腿。'],
  'H3433': ['脸朝下躺在垫子上，双臂伸过头顶。', '启动核心肌群，同时将胸部和腿部抬离地面。', '以扑动的动作上下踢腿，就像在游泳一样。', '继续踢所需的重复次数。', '将胸部和双腿放低至起始位置。'],
  'H3318': ['站立，双脚分开与肩同宽，膝盖稍微弯曲。', '将双臂伸直在身前，与地面平行。', '启动你的核心并以圆周运动摆动你的手臂，同时旋转你的躯干。', '继续圆周运动，摆动手臂并旋转躯干，达到所需的重复次数。', '记住在整个练习过程中保持呼吸。'],
  'H1753': ['坐在长凳上，双手抓住边缘，手指指向前方。', '将臀部滑离长凳，用手支撑体重。', '弯曲肘部并降低身体，直到上臂与地面平行。', '将自己推回到起始位置。', '重复所需的重复次数。'],
  'H2459': ['双脚分开与肩同宽站立，面向轮胎。', '弯曲膝盖并以臀部为铰链，降低至蹲姿。', '向下伸手，用双手抓住轮胎的底部边缘，手指朝向您。', '调动你的臀部和腿部肌肉，并爆发性地推动你的腿，将轮胎抬离地面。', '当轮胎翻转时，用上半身的力量引导轮胎并保持控制。', '轮胎完全翻转后，迅速后退并重置姿势。', '重复所需的重复次数。'],
  'H0812': ['坐在长凳边缘，双手抓住边缘，手指指向前方。', '双脚向前走，将臀部滑离长凳，然后伸直手臂。', '弯曲肘部，将身体放低至地面，保持背部靠近长凳。', '推动手掌以伸直手臂并返回到起始位置。', '重复所需的重复次数。'],
  'H0813': ['坐在长凳上，双手抓住长凳边缘，手指指向前方。', '将臀部滑离长凳，用手支撑体重。', '弯曲肘部，将身体放低至地面，保持背部靠近长凳。', '在底部暂停片刻，然后将自己推回到起始位置。', '重复所需的重复次数。'],
  'H0815': ['坐在椅子或长凳的边缘，双手放在臀部旁边，手指指向前方。', '将你的屁股从椅子前面滑下来，双腿伸到你面前。', '伸直手臂，保持肘部稍微弯曲，以保持三头肌和肘关节的张力。', '慢慢弯曲你的肘部，将你的身体向地板降低，直到你的肘部成大约 90 度角。', '一旦到达动作的底部，向下压入椅子以伸直肘部，返回到起始位置。', '重复所需的重复次数。'],
  'H0816': ['双脚分开与肩同宽站立，膝盖稍微弯曲。', '将双臂伸直在身前，与地面平行。', '弯曲肘部，将身体放低至地面，保持上臂靠近身体两侧。', '在底部暂停片刻，然后将自己推回到起始位置。', '重复所需的重复次数。'],
  'H0817': ['站立或坐直，背部挺直。', '将一只手臂伸过头顶，肘部弯曲。', '将另一只手放在弯曲的肘部上，然后轻轻地将其拉向头部。', '保持拉伸 15-30 秒，感受三头肌的轻微拉伸。', '松开拉伸并在另一只手臂上重复。'],
  'H0871': ['平躺，膝盖弯曲，双脚平放在地上。', '将双手放在脑后，肘部朝外。', '收紧腹肌，将肩胛骨抬离地面，将膝盖靠近胸部，同时将上半身卷向膝盖。', '在顶部停顿片刻，然后慢慢降低肩胛骨并将双腿伸展回起始位置。', '重复所需的重复次数。'],
  'H0818': ['调整座椅高度并将自己面向电缆机。', '正手握住手柄，双手与肩同宽。', '坐下来，将大腿放在大腿垫下方，保持双脚平放在地板上。', '稍微向后倾斜，挺胸，保持脊柱中立。', '将手柄向下拉至上胸部，将肩胛骨挤压在一起。', '在动作的底部暂停片刻，感受背阔肌的收缩。', '慢慢松开手柄并返回到起始位置。', '重复所需的重复次数。'],
  'H1466': ['仰卧，膝盖弯曲，双脚平放在地上。', '将双手放在身体两侧以获得支撑。', '收紧臀部并将臀部抬离地面，从膝盖到肩膀形成一条直线。', '在保持臀部抬起的同时，将下半身扭转到右侧，使膝盖靠近地面。', '返回起始位置并向左侧重复扭转。', '继续交替扭转所需的重复次数。'],
  'H2802': ['平躺，双腿伸展，双臂放在身体两侧。', '将双手放在臀部下方以获得支撑。', '收紧腹肌，将双腿抬离地面，保持伸直。', '当你抬起双腿时，将臀部扭向一侧，将双腿拉向对面的肩膀。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复这个动作，这次将臀部扭到另一侧。', '继续交替进行所需的重复次数。'],
  'H2801': ['平躺，双腿伸展，双臂放在身体两侧。', '弯曲膝盖，将双腿抬离地面，将它们拉向胸部。', '当你抬起双腿时，将臀部扭向一侧，将膝盖移向另一侧的肩膀。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复这个动作，这次将臀部扭到另一侧。', '继续交替进行所需的重复次数。'],
  'H3231': ['双脚分开与肩同宽站立，双臂向两侧伸展。', '腰部向前弯曲，保持背部挺直，膝盖稍微弯曲。', '双手向下伸向脚趾，保持双腿伸直。', '在底部停顿片刻，然后慢慢回到起始位置。', '重复所需的重复次数。'],
  'H1365': ['站直，双脚分开与肩同宽。', '将双臂伸直在身前，与地面平行。', '手指交叉，手掌旋转远离身体。', '慢慢地将手臂举过头顶，保持它们伸直并彼此平行。', '当你举起手臂时，将肩胛骨挤压在一起。', '保持拉伸 15-30 秒，然后松开并重复。'],
  'H1366': ['脸朝下躺在地板上，双腿伸到身后。', '将双手放在下肋骨旁边的地板上，手指指向前方。', '双手用力按在地板上，伸直手臂，将躯干和大腿抬离地面。', '向后和向下转动肩膀，打开胸部，将目光转向天花板。', '保持这个姿势几次呼吸，然后慢慢将身体放回起始位置。', '重复所需的重复次数。'],
  'H3420': ['坐在地板上，双腿伸到身前。', '稍微向后倾斜，将双腿抬离地面，保持伸直。', '同时，将上半身抬离地面，并将手臂伸向腿部。', '保持这个姿势几秒钟，然后慢慢降低上半身和双腿回到起始位置。', '重复所需的重复次数。'],
  'H0826': ['悬挂在双杠上，双臂完全伸展，身体伸直。', '启动你的核心并将双腿抬起到你面前，保持伸直。', '继续抬起，直到双腿与地面平行或稍高。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H2141': ['将椭圆机的阻力水平和倾斜度调整到您想要的设置。', '踩上机器的踏板并轻轻握住手柄。', '首先用脚向下压，然后将手柄拉向身体。', '继续这个动作，交替推和拉，以模拟行走或跑步动作。', '在整个练习过程中保持稳定的步伐并保持核心参与。', '继续进行有氧运动所需的持续时间。', '下车前逐渐降低机器的强度和速度。'],
  'H3655': ['双脚分开与臀部同宽站立。', '将右膝尽可能高地抬向胸部，同时用左腿保持平衡。', '右脚向前迈出一步，身体降低成弓步姿势，双膝弯曲成 90 度角。', '用右脚推出，并将左膝抬向胸部。', '左脚向前迈出一步，将身体降低至弓步位置。', '继续交替双腿并向前冲刺，保持核心参与并保持稳定的步伐。', '重复所需的重复次数。'],
  'H1460': ['双脚分开与肩同宽站立。', '右腿向前迈出一步，将身体降低至弓步位置。', '保持躯干直立，前膝与脚踝对齐。', '右脚蹬地，左脚向前，左腿呈弓步姿势。', '继续交替双腿向前行走，保持受控且稳定的步伐。', '重复所需的重复次数。'],
  'H3666': ['将跑步机的倾斜度调整到您想要的强度。', '站在跑步机上，双脚分开与肩同宽。', '开始以舒适的步伐行走，确保保持正确的姿势。', '在整个练习过程中，调动核心肌肉并保持背部挺直。', '继续在倾斜跑步机上行走，完成有氧运动所需的时间。', '逐渐降低跑步机的坡度和速度，使其冷却后再停止。'],
  'H2311': ['将步进机调整到舒适的水平。', '走上机器，将双手放在扶手上以获得支撑。', '开始行走时，将一只脚放在台阶上，然后将另一只脚放在台阶上，双腿交替。', '保持直立姿势并锻炼核心肌肉。', '继续步行所需的时间或距离。', '当您对锻炼感到更加舒适时，逐渐增加强度或速度。', '完成练习后记得冷静下来并伸展身体。'],
  'H2987': ['站在俯卧撑前面，用反握抓住双杠，双手与肩同宽。', '悬挂在杠上，双臂完全伸展，双脚离开地面，身体伸直。', '收紧背部肌肉，将身体拉向杠铃，保持肘部靠近身体两侧。', '继续拉，直到下巴高于杠铃，然后暂停片刻。', '慢慢地将身体放回起始位置，充分伸展双臂。', '重复所需的重复次数。'],
  'H3643': ['站立时双脚分开比肩宽，脚趾稍微向外。', '用双手将重物放在胸前。', '将您的体重转移到一侧，并通过弯曲您转移一侧的膝盖来降低身体，同时保持另一条腿伸直。', '尽可能降低身体高度，同时保持平衡并挺胸。', '推动弯曲腿的脚跟以返回到起始位置。', '在另一侧重复，双腿之间交替。'],
  'H1310': ['从高位平板支撑开始，双手分开略宽于肩宽，双脚并拢。', '将胸部压向地面，保持肘部靠近身体。', '一旦你的胸部刚好高于地面，爆发性地把自己推起来，将双手抬离地面。', '当你向上推时，快速将双手移至两侧并稍微向前，让你的身体向地面落下。', '将双手置于更宽的位置，然后立即再次将胸部降低到地面。', '重复俯卧撑动作，下降并用双手抓住自己在较窄的位置。', '继续在更宽和更窄的手位置之间交替，以达到所需的重复次数。'],
  'H0834': ['双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向大腿。', '保持双臂伸直，呼气并将哑铃举至身前，直至与肩齐平。', '在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。', '重复所需的重复次数。'],
  'H0866': ['悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。', '启动你的核心并将双腿抬起到你面前，保持伸直。', '继续抬起，直到双腿与地面平行或稍高。', '在顶部暂停片刻，然后慢慢将双腿放回起始位置。', '重复所需的重复次数。'],
  'H0835': ['将自己面朝下放在稳定球上，臀部放在球上，双脚靠在墙上以保持稳定。', '将双手放在脑后或交叉放在胸前。', '启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体形成一条直线。', '在顶部停顿片刻，然后慢慢将上半身放回起始位置。', '重复所需的重复次数。'],
  'H3641': ['从跪姿开始，膝盖分开与臀部同宽，背部挺直。', '每只手各握一个重物，双臂在身前笔直向下伸展。', '启动你的核心肌群，将重物向上举过头顶，保持手臂伸直。', '将重量放回起始位置，然后重复所需的重复次数。'],
  'H3644': ['双脚分开与肩同宽站立，每只手各握一个重物。', '右脚向前迈出一步，将身体降低至弓步位置。', '当你向前冲时，向前和向上摆动重物，保持手臂伸直。', '用右脚推出并返回到起始位置，将重物向下摆动。', '用左脚重复上述动作，并继续交替双腿，完成所需的重复次数。'],
  'H3286': ['首先悬挂在引体向上杆上，手掌背向自己，双手之间的距离略大于肩宽。', '启动核心肌群，将身体拉向杠铃杆，以胸部为主导。', '当你到达动作的最高点时，改变你的握力，使你的手掌朝向你。', '继续拉起自己，直到胸部到达杠铃，然后暂停片刻。', '慢慢地将自己放回到起始位置，在整个运动过程中保持控制。', '重复所需的重复次数。'],
  'H3312': ['首先悬挂在引体向上杆上，手掌背向自己，双手之间的距离略大于肩宽。', '启动你的核心并将肩胛骨向下拉和向后拉。', '弯曲肘部，将胸部拉向杠铃杆，保持身体挺直。', '当你的胸部到达杠铃时，用手向下推并将肘部向后推，将身体提升到杠铃上方。', '在动作的最高点暂停，然后慢慢降低回到起始位置。', '重复所需的重复次数。'],
  'H3290': ['正手握住引体向上杆，握距略宽于肩宽。', '悬挂在杠上，手臂完全伸展，身体伸直。', '弯曲肘部并挤压背部肌肉，调动核心力量，将身体拉向杠铃杆。', '继续拉，直到下巴位于杠铃上方。', '有控制地降低身体回到起始位置。', '重复所需的重复次数。'],
  'H0840': ['坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。', '双手握住杠铃片或哑铃，并将手臂伸过头顶。', '收紧腹肌，慢慢向前弯曲躯干，使胸部靠近膝盖。', '在顶部暂停片刻，然后慢慢将躯干放回起始位置。', '重复所需的重复次数。'],
  'H0844': ['双脚分开与肩同宽站立，每只手各握一个哑铃。', '稍微弯曲膝盖，髋部向前转动，保持背部挺直。', '将手臂向两侧举起，肘部保持轻微弯曲。', '继续举起手臂，直到它们与地面平行。', '在顶部暂停片刻，然后慢慢将手臂放回起始位置。', '重复所需的重复次数。'],
  'H0845': ['坐在地上，膝盖弯曲，双脚离开地面，保持双腿并拢。', '用双手将重物放在胸前，保持肘部稍微弯曲。', '稍微向后倾斜以锻炼核心肌肉。', '将躯干向右扭转，将重量移向右侧地面。', '暂停片刻，然后将躯干向左扭转，将重量转移到左侧地面。', '继续交替进行所需的重复次数。'],
  'H2371': ['坐在地上，膝盖弯曲，双脚平放在地板上。', '用双手将重物放在胸前。', '稍微向后倾斜以锻炼核心肌肉。', '将躯干向右扭转，将重量移至身体右侧。', '暂停片刻，然后将躯干向左扭转，将重量移向身体的左侧。', '继续交替进行所需的重复次数。'],
  'H0847': ['坐在稳定球上，双脚平放在地面上，背部挺直。', '反手握住健身球，手掌朝上，让手臂垂在身体两侧。', '保持上臂静止，呼气并将药球向上卷向肩膀。', '在顶部暂停片刻，挤压你的二头肌。', '吸气并缓慢地将健身球放回起始位置。', '重复所需的重复次数。'],
  'H0849': ['坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。', '双手靠近胸部握住杠铃片或哑铃。', '启动你的核心并慢慢地将你的躯干旋转到一侧，保持臀部稳定。', '旋转结束时暂停片刻，然后慢慢回到起始位置。', '重复旋转到另一侧。', '继续交替进行所需的重复次数。'],
  'H0852': ['双脚分开与肩同宽站立，脚趾稍微向外。', '将重物放在胸前或肩膀上。', '收紧核心并保持挺胸，同时降低臀部和向后倾斜，就像坐在椅子上一样。', '降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。', '推动脚后跟站起来，在顶部挤压臀部。', '重复所需的重复次数。'],
  'H0853': ['双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。', '保持肘部靠近躯干，并在将哑铃弯举至肩部水平时呼气。', '在顶部暂停片刻，然后吸气，慢慢将重量放回起始位置。', '重复所需的重复次数。'],
  'H0854': ['双脚分开与肩同宽站立，每只手各握一个重物。', '将双臂伸直在身前，手掌相对。', '尽可能用力将双手握在一起，用力接触前臂。', '按住挤压几秒钟，然后松开。', '重复所需的重复次数。'],
  'H3313': ['将自己置于双杠之间，双臂完全伸展，身体伸直。', '弯曲肘部降低身体，直到上臂与地面平行。', '暂停片刻，然后伸直手臂，将自己推回起始位置。', '重复所需的重复次数。'],
  'H3642': ['双脚分开与肩同宽站立。', '右脚向前迈出一步，保持背部挺直。', '弯曲膝盖降低身体，直到右大腿与地面平行。', '推动右脚跟回到起始位置。', '左腿重复上述动作。', '继续交替双腿达到所需的重复次数。'],
  'H0856': ['双脚分开与肩同宽站立，双手将杠铃片放在胸前。', '保持肘部稍微弯曲，手掌相对。', '将配重板直接压在您面前，完全伸展双臂。', '动作结束时暂停片刻，然后慢慢将配重板放回起始位置。', '重复所需的重复次数。'],
  'H1754': ['坐在长凳边缘，双手抓住边缘，手指指向前方。', '双脚向前走，将臀部滑离长凳，并用手臂支撑体重。', '弯曲肘部降低身体，使背部靠近长凳。', '在底部暂停片刻，然后将自己推回到起始位置。', '重复所需的重复次数。'],
  'H1767': ['将自己定位在两个双杠之间，双手握住杠，双臂完全伸展。', '弯曲肘部并降低身体，直到上臂与地面平行。', '暂停片刻，然后用手掌推直手臂并返回到起始位置。', '重复所需的重复次数。'],
  'H0857': ['跪在地板上，将滚轮放在您面前。', '将双手放在滚轮的手柄上，并将手臂伸直至前方。', '调动你的核心肌肉，慢慢向前滚动轮子，保持背部挺直，腹肌紧张。', '继续向前滚动，直到身体完全伸展并且手臂举过头顶。', '暂停片刻，然后慢慢地将轮子向膝盖方向滚动，保持控制并保持腹肌接合。', '重复所需的重复次数。'],
  'H3637': ['从平板支撑位置开始，双手放在方向盘上，身体伸直。', '启动你的核心并通过伸展双臂开始向前滚动轮子。', '继续滚动，直到身体完全伸展并且手臂举过头顶。', '使用你的核心和手臂将轮子拉回你的身体，从而扭转运动。', '重复所需的重复次数。'],
  'H1429': ['悬挂在引体向上杆上，手掌背向自己，双手之间的距离比肩宽。', '启动你的核心并将肩胛骨挤压在一起。', '将身体向上拉向杠铃，直到下巴位于杠铃上方。', '有控制地降低身体回到起始位置。', '重复所需的重复次数。'],
  'H1367': ['正手宽握抓住引体向上杆，双手间距略宽于肩宽。', '悬挂在杠上，双臂完全伸展，身体伸直。', '调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。', '继续拉，直到下巴位于杠铃上方。', '在顶部停顿片刻，然后慢慢将身体放回起始位置。', '重复所需的重复次数。'],
  'H1311': ['从高平板支撑位置开始，双手分开比肩宽。', '保持身体从头到脚呈一条直线。', '弯曲肘部，将胸部压向地面，使其靠近身体两侧。', '推动手掌以伸展手臂并返回到起始位置。', '重复所需的重复次数。'],
  'H2363': ['将自己置于双杠上，双臂完全伸展，身体悬浮在空中。', '稍微向前倾，弯曲肘部降低身体，直到胸部位于杠铃上方。', '暂停片刻，然后伸直手臂，将自己推回起始位置。', '重复所需的重复次数。'],
  'H0858': ['找一个空地或跑道来进行练习。', '首先站立，双脚分开与肩同宽。', '开始尽可能快地跑步，挥动手臂并抬起膝盖。', '继续冲刺特定的距离或时间。', '休息并重复所需的重复次数。'],
  'H1604': ['从弓步位置开始，右脚向前，左脚向后。', '将双手放在右脚两侧的地面上。', '将左膝降低到地面并伸展右腿，保持右脚平放在地面上。', '向右旋转你的躯干，将你的右臂伸向天花板。', '保持这个姿势几秒钟，然后回到起始位置。', '换边并重复拉伸，左脚向前。'],
  'H1428': ['将双臂伸直在身前。', '双手握拳。', '以圆周运动旋转手腕，保持手臂静止。', '继续手腕转圈达到所需的重复次数。'],
  'H0859': ['将重物固定在绳子或杆的一端。', '用双手握住绳子或杆的另一端，手掌朝下。', '双脚分开与肩同宽站立，双臂完全伸展在身前。', '弯曲手腕，慢慢地将重物向上滚动到手上。', '在顶部暂停片刻，然后慢慢将重量放回起始位置。', '重复所需的重复次数。'],
  'Y90_90_Hamstring': ['仰卧，一条腿伸直。', '另一条腿屈髋屈膝至90度，必要时可用手扶住腿部，此为起始姿势。', '将腿伸直向上举起，顶端稍作停顿，然后回到起始姿势。', '重复10至20次，然后换另一条腿。'],
  'YAb_Crunch_Machine': ['选择较轻的阻力，坐在腹肌训练器上，双脚置于脚踏垫下，双手握住上方把手，手臂弯曲约90度，将肱三头肌靠在垫子上，此为起始姿势。', '同时抬起双腿并卷起上半身，动作过程中呼气；务必采用缓慢受控的节奏，放松双腿和双脚，专注于用腹部发力移动重量。', '停顿一秒后，吸气并缓慢回到起始姿势。', '按规定的次数重复该动作。'],
  'YAb_Roller': ['双手握住健腹轮，跪在地板上。', '将健腹轮置于身前地面，呈四肢着地的跪撑姿势（类似跪姿俯卧撑），此为起始姿势。', '慢慢将健腹轮向前滚出，身体伸展成一条直线；在不触碰地面的前提下尽量前伸，此阶段吸气。', '在伸展位稍作停顿后，呼气将身体拉回起始姿势；全程放慢速度并始终保持腹部收紧。'],
  'YAdductor': ['俯卧，将一条腿置于泡沫轴上。', '转动腿部使泡沫轴贴住大腿内侧，在可承受范围内将尽可能多的体重压到泡沫轴上。', '尽量放松大腿内侧肌肉，在髋与膝之间滚动泡沫轴，在酸痛点保持10至30秒，然后换另一条腿重复。'],
  'YAdductor_Groin': ['仰卧，双脚朝天花板抬起。', '让同伴握住你的双脚或脚踝，将双腿尽量向外打开，此为起始姿势。', '尝试并拢双腿并保持10秒以上，同时同伴施加阻力阻止你并拢。', '此时放松腿部肌肉，由同伴将你的双脚向外推开，拉伸到你觉得舒适的幅度；拉伸到位时一定要告知同伴停止，以防过度拉伸或受伤。'],
  'YAdvanced_Kettlebell_Windmill': ['单臂将壶铃翻举并推举至头顶。', '始终保持壶铃锁定在头顶，臀部朝举铃一侧顶出，非工作手臂置于背后，双脚朝持铃手臂方向外展约45度。', '尽量向下俯身。', '停顿一秒，然后反向还原到起始姿势。'],
  'YAll_Fours_Quad_Stretch': ['从四肢跪撑开始，将一条腿抬离地面，用手握住同侧脚。', '用手握住脚或脚踝，保持膝盖完全屈曲，拉伸股四头肌和髋屈肌。', '专注于伸展髋部，将髋部向地面方向前推，保持10至20秒后换边。'],
  'YAlternate_Hammer_Curl': ['站直身体，双手各持一只哑铃垂于体侧，肘部贴近躯干。', '掌心朝向躯干，此为起始姿势。', '上臂保持不动，呼气的同时收缩肱二头肌，将右侧哑铃向前弯举，直至肱二头肌完全收缩、哑铃到达肩部高度，顶端挤压肱二头肌并保持一秒；注意只有前臂应移动。', '吸气并缓慢将哑铃放回起始姿势。', '换左手重复该动作，左右各一次计为一组动作。', '按此方式交替进行建议的次数。'],
  'YAlternate_Incline_Dumbbell_Curl': ['坐在上斜凳上，双手各持一只哑铃自然下垂；肘部贴近躯干，此为起始姿势。', '上臂保持不动，呼气并收缩肱二头肌将右侧哑铃向前弯举，过程中旋转手腕使掌心朝上，直至肱二头肌完全收缩、哑铃到达肩部高度，顶端挤压肱二头肌并保持一秒；只有前臂应移动。', '吸气并缓慢将哑铃放回起始姿势。', '换左手重复该动作，左右各一次计为一组动作。', '按此方式交替进行建议的次数。'],
  'YAlternate_Leg_Diagonal_Bound': ['采取舒适的站立姿势，一只脚略在前。', '用前腿发力蹬地，将对侧膝盖向前向上高高顶起后落地，每次跳跃尽量向两侧覆盖更远的距离。', '可以在地面画一条线来辅助判断两侧跳出的距离。', '换另一条腿重复这一系列动作。'],
  'YAlternating_Cable_Shoulder_Press': ['将绳索滑轮移至龙门架底部，选择合适的重量。', '握住绳索把手置于肩部高度，掌心朝前，此为起始姿势。', '保持抬头挺胸，通过肘部伸展将一侧直接推举过头顶。', '顶端停顿后回到起始姿势，换另一侧重复。'],
  'YAlternating_Deltoid_Raise': ['站立，双手各持一只哑铃置于体侧。', '肘部微屈，将哑铃从正前方平举至肩部高度，避免晃动或借力。', '将哑铃放回体侧。', '下一次重复时改为侧向平举，将哑铃从身体两侧举起至约肩部高度。', '回到起始姿势，继续交替进行前平举和侧平举。'],
  'YAlternating_Floor_Press': ['仰卧在地面上，两只壶铃放在肩旁。', '先将一只壶铃置于胸前位置，再放另一只，握壶铃把手时掌心朝前。', '伸直双臂将壶铃举于胸前上方，然后下放一侧壶铃至胸口，手腕向锁定壶铃的一侧旋转。', '举起该侧壶铃，换另一侧重复。'],
  'YAlternating_Hang_Clean': ['将两只壶铃放在两脚之间，臀部后坐、目视前方，进入起始姿势。', '将一只壶铃翻举至肩部，另一只保持悬垂握持；翻举时通过伸髋伸膝发力把壶铃拉向肩部，同时旋转手腕。', '将翻举的壶铃下放至悬垂位，再翻举另一只壶铃，重复进行。'],
  'YAlternating_Kettlebell_Press': ['将两只壶铃翻举至肩部；翻举时通过伸髋伸膝发力把壶铃拉向肩部，同时旋转手腕。', '单侧通过肘部伸展直接将壶铃推举过头顶，转动手腕使掌心朝前，另一只壶铃保持不动。', '将推举的壶铃下放回起始姿势，立即换另一只手臂推举。'],
  'YAlternating_Kettlebell_Row': ['将两只壶铃放在脚前，微屈膝并尽量向后顶髋，俯身进入起始姿势的同时握住两只壶铃的把手。', '一只手握住另一只壶铃保持稳定，将一侧壶铃拉离地面；屈肘的同时后收同侧肩胛骨，把壶铃拉向腹部或肋部。', '下放工作手臂的壶铃，换另一只手臂重复。'],
  'YAlternating_Renegade_Row': ['将两只壶铃按肩宽放在地面，以俯卧撑姿势撑在壶铃把手上，身体保持一条直线；如需更稳可将双脚分得宽一些。', '一只手臂将壶铃压向地面，另一侧屈肘划起壶铃，同时后收同侧肩胛骨，把它拉向体侧。', '将壶铃放回地面，换另一只手划起，重复若干次。'],
  'YAnkle_On_The_Knee': ['仰卧，屈膝，双脚踩地。', '将一只脚的脚踝搭在对侧膝盖上。', '抱住下方腿的大腿或膝盖，将双腿拉向胸口，放松颈部与肩部，保持10至20秒后换边。'],
  'YAnterior_TibialisSMR': ['坐在地面上，双腿弯曲，双脚踩地。', '用泡沫轴或擀面杖对小腿前外侧的肌肉施加压力，从膝盖下方滚到脚踝上方，在酸痛点停留10至30秒，换另一条腿重复。'],
  'YAntiGravity_Press': ['将杠铃放在上斜凳头端后方的地面上。', '俯卧在凳上，用正握（掌心向下）握姿将杠铃从地面拿起，屈肘做反握弯举动作把杠铃带到胸前，此为起始姿势。', '开始动作：伸肘将杠铃向头部前方推出，动作全程保持手臂与地面平行。', '回到起始姿势并重复以完成该组训练。'],
  'YArm_Circles': ['站立，双臂向两侧伸直，与地面平行、与躯干垂直（呈90度），此为起始姿势。', '用伸出的双臂缓慢画直径约1英尺（约30厘米）的圆圈，动作过程中保持正常呼吸。', '双臂保持画圆约十秒，然后反方向画圆。'],
  'YArnold_Dumbbell_Press': ['坐在有靠背的训练凳上，双手各持一只哑铃置于胸前约上胸高度，掌心朝向身体，肘部弯曲；手臂贴近躯干，起始姿势应类似哑铃弯举的收缩位置。', '开始动作：向上举起哑铃的同时旋转手腕，直至掌心朝前。', '继续上举直到双臂在头顶伸直，此阶段呼气。', '顶端停顿一秒后，旋转手腕使掌心朝向自己，将哑铃下放回原位；左臂逆时针旋转、右臂顺时针旋转，此阶段吸气。', '按建议的次数重复。'],
  'YAround_The_Worlds': ['仰卧在平凳上，双手各持一只哑铃，掌心朝上；手臂与地面平行、贴近大腿，肘部保持微屈以防受伤，此为起始姿势。', '将哑铃画半圆从起始位置移动到头顶上方，全程保持手臂与地面平行，此阶段吸气。', '呼气并反向移动，将哑铃放回起始姿势。'],
  'YAtlas_Stone_Trainer': ['这台训练器适合没有阿特拉斯石的人练习其力量，通常由杠铃杆端或重型钢管制成。', '先将目标重量装到杠铃上，跨立于重物上方，屈髋俯身，双臂环抱住器械。', '伸髋发力将重物拉过膝盖高度；当重物越过膝盖后，可将其搁在大腿上并后坐，把它紧紧抱在胸前。', '最后伸髋伸膝将重物尽量举高完成动作，下一次重复前可将重物放回大腿上或地面。'],
  'YAtlas_Stones': ['从阿特拉斯石位于两脚之间开始，屈髋俯身，双臂竖直环抱住石头，尽量把手指伸到石头底部；很多石头底部有小平面，更容易抓握。', '把石头贴向躯干，用脚掌后侧发力蹬地，将石头从地面拉起。', '当石头越过膝盖时，向后坐下，把石头拉到大腿上方的位置。', '身体压低，换握为越过石头顶部，把石头抬高贴到胸前；随后起身，用髋部发力顶起，靠近装载平台，身体后仰并伸髋将石头举到尽可能高的位置。'],
  'YAxle_Deadlift': ['走向杠铃，使杠铃位于双脚正上方，双脚约与髋同宽；屈髋俯身，以肩宽握距握住杠铃，允许肩胛骨前伸，通常采用正反握。', '站姿和握距就位后深吸一口气，下放髋部、屈膝直至小腿触到杠铃；头部目视前方，挺胸、背部保持弓起，开始用脚跟蹬地发力将重量向上拉起。', '杠铃越过膝盖后，用力将杠铃拉向身体，后收肩胛骨，同时将髋部向前顶入杠铃。', '屈髋俯身，将杠铃沿原路放回地面。'],
  'YBack_Flyes__With_Bands': ['将弹力带绕过固定立柱（如深蹲架立柱）。', '握住弹力带把手并向后站，使弹力带产生张力。', '双臂向前伸直抬起；手臂伸直并与地面平行、与躯干垂直，双脚稳稳踩地、与肩同宽，此为起始姿势。', '呼气时将双臂向两侧后方打开，保持手臂伸直并与地面平行，直至双臂展开到身体两侧。', '稍作停顿后，吸气回到起始姿势。', '按建议的次数重复。'],
  'YBackward_Drag': ['在雪橇上装上目标重量，并系上可手握的绳索或绑带。', '开始向后拖动雪橇走完既定距离；身体后仰，双腿小步快速蹬地移动。'],
  'YBackward_Medicine_Ball_Throw': ['这个动作最好与搭档一起完成；没有搭档时，可以把球抛出再捡回，或朝墙投掷。', '站在距搭档几米远的位置，两人面朝同一方向，开始时把药球夹在双腿之间。', '屈膝下蹲，然后猛地反向起身、完全伸展身体，将药球从头顶向后抛给搭档。', '搭档随后将球滚回给你，按目标次数重复。'],
  'YBall_Leg_Curl': ['仰卧在地面上，双脚踩在球上。', '调整球的位置，使双腿伸直时脚踝正好位于球顶，此为起始姿势。', '将髋部抬离地面，体重落在肩胛骨和双脚上。', '屈膝把球尽量拉向身体，收缩腘绳肌。', '稍作停顿后回到起始姿势。'],
  'YBand_Good_Morning': ['使用41英寸（约104厘米）的弹力带，踩住一端，双脚略分开；屈髋俯身，把弹力带另一端套在颈后，此为起始姿势。', '保持双腿伸直，通过伸髋恢复到接近直立的位置。', '回到起始姿势时注意不要让背部弓起。'],
  'YBand_Good_Morning_Pull_Through': ['把弹力带绕在立柱上，站开一段距离，将另一端套在颈后，可用手帮助固定弹力带的位置。', '屈髋俯身，臀部尽可能向后坐；保持背部平直，身体前倾约90度，膝盖微屈即可。', '用髋部发力向前顶，回到站立起始姿势。'],
  'YBand_Hip_Adductions': ['把弹力带固定在一个稳固的立柱或其他物体上。', '左侧对着立柱站立，将右脚穿进弹力带，套在脚踝上。', '站直身体，必要时扶住立柱，此为起始姿势。', '保持膝盖伸直，将右腿向侧方尽量抬高。', '回到起始姿势，按目标次数重复。', '换边进行。'],
  'YBand_Skull_Crusher': ['将弹力带固定在器械架底座或凳子上，仰卧在凳上，使弹力带与头部对齐。', '抓住弹力带，抬起肘部使上臂与地面垂直；屈肘时弹力带位于头顶上方，此为起始姿势。', '保持上臂不动，伸展肘部伸直手臂，在动作顶端停顿后回到起始姿势。'],
  'YBarbell_Ab_Rollout': ['做这个动作时需要摆出俯卧撑姿势，但双手不撑地，而是握住一根奥林匹克杠铃（两侧各装2.3至4.5公斤），此为起始姿势。', '背部保持轻微弓起，呼气的同时抬起髋部，将杠铃向脚的方向滚出；动作过程中臀部应随之抬起，腹部始终收紧、背部姿态保持稳定，双臂全程与地面垂直，否则会更多练到肩部和背部而不是腹部。', '顶端收缩一秒后，吸气并缓慢将杠铃滚回起始姿势。', '按建议的次数重复。'],
  'YBarbell_Ab_Rollout__On_Knees': ['握住一根两侧各装2.3至4.5公斤的奥林匹克杠铃，跪在地面上。', '将杠铃放在身前地面，呈四肢着地的跪撑姿势（类似跪姿俯卧撑），此为起始姿势。', '慢慢将杠铃向前滚出，身体伸展成一条直线；在不触碰地面的前提下尽量前伸，此阶段吸气。', '在伸展位停顿一秒后，呼气将身体拉回起始姿势；全程放慢速度并始终保持腹部收紧。'],
  'YBarbell_Bench_Press__Medium_Grip': ['仰卧在平凳上，采用中距握法（动作中段前臂与上臂呈90度），将杠铃从架子上取下，双臂锁定举在胸口正上方，此为起始姿势。', '从起始姿势吸气，缓慢下放杠铃，直至触到胸部中段。', '稍作停顿后呼气用胸部发力将杠铃推回起始姿势；顶端锁定手臂并挤压胸肌，保持一秒后再次缓慢下放；理想情况下下放时间约为上推时间的两倍。', '按规定的次数重复该动作。', '完成后将杠铃放回架子上。'],
  'YBarbell_Curls_Lying_Against_An_Incline': ['仰靠在上斜凳上，双手握住杠铃，手臂自然下垂呈水平位，此为起始姿势。', '上臂保持不动，挤压肱二头肌把杠铃尽量向上弯举，此阶段呼气；只有前臂应移动，不要摆动双臂。', '收缩一秒后，吸气缓慢回到起始姿势，一定要放到底。', '按建议的次数重复。'],
  'YBarbell_Hip_Thrust': ['坐在地面上，身后放一张凳子，将装好重量的杠铃置于腿上；使用加粗杠铃杆或在杆上加垫子可大幅减轻不适。', '滚动杠铃使其位于髋部正上方，背靠凳子，使肩胛骨靠近凳面顶端。', '双脚蹬地发力，髋部垂直向上顶起杠铃，体重由肩胛骨和双脚支撑；尽量顶到最高，然后反向还原到起始姿势。'],
  'YBarbell_Incline_Bench_Press__Medium_Grip': ['仰卧在上斜凳上，采用中距握法（动作中段前臂与上臂呈90度），将杠铃从架子上取下，双臂锁定举于胸口上方，此为起始姿势。', '吸气并缓慢下放杠铃，直至触到上胸位置。', '停顿一秒后呼气用胸部发力将杠铃推回起始姿势；顶端锁定手臂、挤压胸肌，保持一秒后再次缓慢下放；下放时间至少应为上推时间的两倍。', '按规定的次数重复该动作。', '完成后将杠铃放回架子上。'],
  'YBarbell_Rollout_from_Bench': ['将装好重量的杠铃放在地面、靠近凳尾的位置，双腿跪在凳上，以中距到窄距握法握住杠铃，此为起始姿势。', '开始动作：伸髋发力慢慢将杠铃向前滚出，滚动过程中屈肩使杠铃越过头部上方，全程保持手臂伸直。', '当杠铃滚到最远位置后，回到起始姿势。'],
  'YBarbell_Shoulder_Press': ['坐在深蹲架内有靠背的凳子上，将杠铃调整到略高于头顶的位置，用正握（掌心向前）握住杠铃。', '以合适的握距拿起杠铃后，锁定双臂将杠铃举过头顶，停在约肩部高度、略在头部前方，此为起始姿势。', '吸气并缓慢将杠铃下放至肩部。', '呼气将杠铃推回起始姿势。', '按建议的次数重复。'],
  'YBarbell_Shrug_Behind_The_Back': ['站直身体，双脚与肩同宽，双手在背后以正握（掌心朝后）握住杠铃；双手略宽于肩，可用腕带增强握力，此为起始姿势。', '呼气时将肩膀尽量向上耸起并保持收缩一秒；不要用肱二头肌的力量去提杠铃，手臂全程保持伸直。', '吸气缓慢回到起始姿势。', '按建议的次数重复。'],
  'YBarbell_Side_Bend': ['站直身体，将杠铃置于肩后（略低于颈部），双脚与肩同宽，此为起始姿势。', '保持背部挺直、抬头，仅以腰部向右侧弯到最大幅度，侧屈时吸气，停顿一秒后呼气回正；身体其余部分保持不动。', '现在换向左侧弯，同样停顿一秒后回到起始姿势。', '按建议的次数重复。'],
  'YBarbell_Squat': ['出于安全考虑，该动作最好在深蹲架内完成；先将杠铃架调至略低于肩部的高度，选好高度并装好重量后，钻到杠铃下方，把杠铃横在肩后（略低于颈部）的位置。', '双手在两侧握住杠铃，先以腿部发力蹬起，同时挺直躯干，将杠铃从架上抬起。', '后退离开架子，采用与肩同宽的中等站距，脚尖略向外；全程抬头、保持背部挺直，此为起始姿势（此处采用中等站距以全面发展，也可选择三种站距中的其他两种）。', '保持抬头直背，屈膝屈髋缓慢下放杠铃，直到大腿与小腿之间的夹角略小于90度，此阶段吸气；动作正确时膝盖前端应与脚尖成一条垂直的假想直线，若膝盖越过该线（超过脚尖），则说明动作错误且膝盖承受了过大压力。', '呼气时用脚跟蹬地发力，伸直双腿将杠铃推回起始姿势。', '按建议的次数重复。'],
  'YBarbell_Squat_To_A_Bench': ['出于安全考虑，该动作最好在深蹲架内完成；先在身后放一张平凳或跳箱，平凳用于帮你学会髋部后坐并蹲到足够深度。', '', '然后将杠铃架调到适合你的高度，装好重量后钻到杠铃下方，把杠铃横在肩后（略低于颈部）的位置。', '双手在两侧握住杠铃，先以腿部发力蹬起，同时挺直躯干，将杠铃从架上抬起。', '后退离开架子，采用与肩同宽的中等站距，脚尖略向外；全程抬头，低头会失去平衡，同时保持背部挺直，此为起始姿势（此处采用中等站距以全面发展，也可选择其他两种站距）。', '保持抬头直背，屈膝并让臀部向后坐，缓慢下放杠铃，直到臀部轻轻碰到身后的凳子，此阶段吸气；动作正确时膝盖前端应与脚尖成一条垂直的假想直线，若膝盖越过该线，则膝盖承受了过大压力、动作有误。', '呼气时用脚跟蹬地，伸直双腿并伸展髋部，回到起始姿势。', '按建议的次数重复。'],
  'YBarbell_Step_Ups': ['站直身体，将杠铃置于肩后（略低于颈部），站在一个高台后方，此为起始姿势。', '右脚踩上高台，通过伸展右腿的髋关节和膝关节登上平台，主要用脚跟发力带动身体上升，左腿也踩上平台；发力上登时呼气。', '吸气，屈曲右腿髋膝，让左腿先下台阶，回到起始站立位置。', '右腿按建议次数重复后，换左腿进行。'],
  'YBarbell_Walking_Lunge': ['站姿开始，双脚与肩同宽，杠铃横在上背部。', '一条腿向前迈出，屈膝下放髋部，直到后腿膝盖接近地面；躯干保持直立，前膝保持在脚尖正上方。', '用前脚脚跟蹬地发力，伸直双膝将身体顶起。', '后腿继续向前迈出，换另一条腿重复箭步蹲。'],
  'YBear_Crawl_Sled_Drags': ['穿上背带或宽松的负重腰带，把链条连接在背部，使身体背对雪橇；俯身双手撑地，背部保持平直、膝盖弯曲，此为起始姿势。', '双腿交替发力蹬地拖行，双手用于保持平衡并辅助拉动；爬行过程中尽量保持背部平直，移动完既定距离。'],
  'YBench_Dips': ['在身后放一张凳子，凳子与身体垂直，背对凳子，双手与肩同宽撑在凳沿上，手臂完全伸直；双腿向前伸出，屈髋，身体与凳沿、地面垂直，此为起始姿势。', '吸气，屈肘缓慢下放身体，直到上臂与前臂夹角略小于90度；全程肘部尽量贴近身体，前臂始终保持竖直向下。', '用肱三头肌发力将身体撑回起始姿势。', '按建议的次数重复。'],
  'YBench_Jump': ['在身前1至2英尺（约30至60厘米）处放一个跳箱或凳子，双脚与肩同宽站立，此为起始姿势。', '起跳前先做一个小幅度的下蹲预备动作，同时双臂向后摆。', '借助反弹力，伸展髋、膝、踝关节尽量向上跳起，双臂向前上方摆动。', '跳过凳子，屈膝落地，用双腿缓冲冲击。', '转身面向反方向，再跳回越过凳子。'],
  'YBench_Press__Powerlifting': ['仰卧在凳上，头尽量越过杠铃正下方；双脚收向身体下方并弓起背部，借助杠铃分担体重，将肩部抬离凳面并后收，夹紧肩胛骨，用双脚发力把斜方肌压进凳子，整个动作过程中保持身体紧绷。', '无论握距多宽，手都要覆盖杠铃上的标记环；将杠铃从架上取出时不要让肩部前伸，专注于握紧杠铃并尝试把它掰开。', '将杠铃下放至下胸或上腹位置，杠铃、手腕、肘部全程保持在一条直线上。', '杠铃触到躯干时稍作停顿，然后尽全力将杠铃推起，肘部在锁定前始终保持内收。'],
  'YBench_Press__With_Bands': ['使用平凳，将弹力带固定在靠近头部的凳腿下方。', '弹力带固定好后，双手握住两端把手，仰卧在凳上。', '伸直双臂，在胸前与肩同宽的位置握住弹力带把手。', '确定肩宽握距后，向前旋转手腕使掌心朝前远离身体，此为起始姿势。', '缓慢下放把手，直到肘部弯成90度，全程保持完全控制。', '呼气时用胸肌发力将把手推起，顶端锁定手臂、挤压胸肌，保持一秒后缓慢下放；下放时间至少应为上推时间的两倍。', '按训练计划规定的次数重复该动作。'],
  'YBench_Press_with_Chains': ['调整牵引链，缩短到所需长度，然后把链条挂在杠铃杆的套筒上。', '仰卧在凳上，头尽量越过杠铃正下方；双脚收向身体下方并弓起背部，借助杠铃分担体重，将肩部抬离凳面并后收，夹紧肩胛骨，用双脚发力把斜方肌压进凳子，整个动作过程中保持身体紧绷；无论握距多宽，手都要覆盖杠铃上的标记环。', '将杠铃从架上取出时不要让肩部前伸，专注于握紧杠铃并尝试把它掰开；将杠铃下放至下胸或上腹位置，杠铃、手腕、肘部全程保持在一条直线上。', '杠铃触到躯干时稍作停顿，然后尽全力将杠铃推起，肘部在锁定前始终保持内收。'],
  'YBench_Sprint': ['站在地面上，一只脚踩在凳子或跳箱上，脚跟贴近边缘。', '踩凳的脚发力蹬起，伸展髋关节和膝关节。', '换另一只脚落在箱子上，原脚回到起始位置。', '继续这样交替换脚，完成整组训练。'],
  'YBentArm_Barbell_Pullover': ['仰卧在平凳上，以肩宽握距握住杠铃。', '屈臂将杠铃举在胸口正上方，此为起始姿势。', '保持屈臂姿势，吸气并沿弧线将杠铃缓慢下放到头后方，直到胸部有拉伸感。', '然后沿下放的弧线将杠铃拉回起始姿势，动作过程中呼气。', '在起始位置保持一秒，按规定的次数重复动作。'],
  'YBentArm_Dumbbell_Pullover': ['将一只哑铃竖放在平凳上。', '确保哑铃稳稳放在凳面上端，身体与凳子垂直横躺（呈十字形），只有肩部靠在凳面上；髋部低于凳面，双腿弯曲、双脚踩实地面，头部悬在凳外。', '双手握住哑铃，屈臂举在胸口正上方，双掌贴住哑铃一侧的下端面，此为起始姿势；务必确保哑铃片锁紧，松动的哑铃可能散架砸到脸上。', '保持屈臂姿势不动，吸气并沿弧线将哑铃缓慢下放到头后方，直到胸部有拉伸感。', '然后沿下放的弧线将哑铃拉回起始姿势，动作过程中呼气。', '在起始位置保持一秒，按规定的次数重复动作。'],
  'YBentKnee_Hip_Raise': ['平躺在地面上，双臂放在身体两侧。', '屈膝约75度，将双脚抬离地面约2英寸（约5厘米）。', '保持双腿75度屈曲，用下腹部发力将膝盖向身体拉近，继续动作直到骨盆后卷、髋部抬离地面，此阶段呼气；动作结束时膝盖应位于胸口上方。', '动作顶端收紧腹部保持一秒，然后吸气缓慢回到起始姿势；全程保持受控的节奏。', '按建议的次数重复。'],
  'YBent_Over_Barbell_Row': ['以正握（掌心向下）握住杠铃，微屈膝，弯腰将躯干前倾，保持背部挺直直至躯干几乎与地面平行；抬头，双臂垂直于地面和躯干，杠铃自然悬垂在身前，此为起始姿势。', '躯干保持不动，呼气将杠铃拉向身体；肘部贴近身体，前臂只负责握住重量，顶端收缩位挤压背部肌肉并短暂停顿。', '然后吸气，缓慢将杠铃放回起始姿势。', '按建议的次数重复。'],
  'YBent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench': ['站直身体，双手各持一只哑铃，身前放一张上斜凳。', '保持背部挺直、维持自然生理曲度，身体前倾直到额头贴到面前的凳子上；双臂自然下垂与地面垂直，掌心相对，躯干与地面平行，此为起始姿势。', '躯干保持前倾不动，手臂伸直、肘部微屈，将哑铃向身体两侧直臂举起，直到双臂与地面平行；举起时呼气，避免躯干摆动或把手臂向后带。', '顶端收缩一秒后，缓慢将哑铃放回起始姿势。', '按建议的次数重复。'],
  'YBent_Over_LowPulley_Side_Lateral': ['选择合适的重量，用右手握住低位滑轮的把手。', '弯腰俯身直到躯干几乎与地面平行；双腿微屈，左手扶在左大腿下段，右臂自然下垂、肘部微屈，此为起始姿势。', '右臂微屈肘向侧方举起，直到手臂与地面平行、与右耳齐平，此步骤中呼气。', '吸气并缓慢将重量放回起始姿势。', '按建议的次数重复，然后换另一只手臂进行。'],
  'YBent_Over_OneArm_Long_Bar_Row': ['在奥林匹克杠铃的一端装上重量，另一端顶在两堵墙的墙角，或在地面放重物挡住，防止杠铃向后滑动。', '身体前倾，躯干尽量接近与地面平行，膝盖微屈。', '单手在装片一侧的杠铃片后方握住杠铃，另一只手放在膝盖上，此为起始姿势。', '肘部贴近身体将杠铃竖直向上拉起（以最大化背部刺激），直到杠铃片触到下胸；拉起时挤压背部肌肉，顶端保持一秒，拉起过程呼气；不要摆动躯干，只有手臂应移动。', '缓慢将杠铃放回起始姿势，让背阔肌获得充分拉伸；不要让杠铃片触地，为保证最佳活动范围，建议使用小号杠铃片（25磅）而不是大号片（35至45磅）。', '按建议的次数重复，然后换手臂。'],
  'YBent_Over_TwoArm_Long_Bar_Row': ['在奥林匹克杠铃的一端装上重量，另一端顶在两堵墙的墙角，或在地面放重物挡住，防止杠铃向后滑动。', '身体前倾，躯干尽量接近与地面平行，膝盖微屈。', '双手在装片一侧的杠铃片后方握住杠铃，此为起始姿势。', '肘部贴近身体将杠铃竖直向上拉起（以最大化背部刺激），直到杠铃片触到下胸；拉起时挤压背部肌肉，顶端保持一秒，拉起过程呼气；也可用马镫式或双手把手的绳索附件钩在杠铃一端使用。', '缓慢将杠铃放回起始姿势，让背阔肌获得充分拉伸；不要让杠铃片触地，为保证最佳活动范围，建议使用小号杠铃片（25磅）而不是大号片（35至45磅）。', '按建议的次数重复。'],
  'YBent_Over_TwoDumbbell_Row': ['双手各持一只哑铃（掌心朝向躯干），微屈膝，弯腰前倾躯干，保持背部挺直直至躯干几乎与地面平行；抬头，双臂垂直于地面和躯干，哑铃自然悬垂在身前，此为起始姿势。', '躯干保持不动，呼气将哑铃拉向体侧，肘部贴近身体（前臂除了握住重量外不要额外发力）；顶端收缩位挤压背部肌肉并保持一秒。', '吸气并缓慢将哑铃放回起始姿势。', '按建议的次数重复。'],
  'YBent_Over_TwoDumbbell_Row_With_Palms_In': ['双手各持一只哑铃（掌心相对），微屈膝，弯腰前倾躯干，保持背部挺直直至躯干几乎与地面平行；抬头，双臂垂直于地面和躯干，哑铃自然悬垂在身前，此为起始姿势。', '躯干保持不动，呼气将哑铃拉向体侧，同时夹紧肩胛骨；顶端收缩位挤压背部肌肉并保持一秒。', '吸气并缓慢将哑铃放回起始姿势。', '按建议的次数重复。'],
  'YBent_Press': ['将一只壶铃翻举至肩部；翻举时通过伸腿伸髋发力把壶铃带到肩旁，同时旋转手腕，此为起始姿势。', '眼睛始终盯住壶铃，身体向持铃对侧倾斜，直到空出的手能触到地面；同时通过伸展肘部将壶铃垂直向上推起，手臂保持与地面垂直。', '回到直立姿势，壶铃举过头顶，然后把壶铃放回肩部，按目标次数重复。'],
  'YBicycling': ['开始时坐上自行车，把座椅调整到适合你身高的位置。'],
  'YBicycling_Stationary': ['开始时坐上自行车，把座椅调整到适合你身高的位置。', '从菜单选择想要的模式，可能需要开始踩踏才能开机；可选择手动模式或预设程序，通常可输入年龄和体重来估算运动消耗的热量，训练中可随时调整阻力，握住把手可监测心率以保持合适的运动强度。'],
  'YBoard_Press': ['仰卧在凳上，头尽量越过杠铃正下方；可将1至5块2x6规格的木板拧在一起，由训练搭档压住、用弹力带固定或直接塞在衣服下。', '双脚收向身体下方并弓起背部，借助杠铃分担体重，将肩部抬离凳面并后收，夹紧肩胛骨，用双脚发力把斜方肌压进凳子，整个动作过程中保持身体紧绷。', '可采用标准卧推握距，或用肩宽握距侧重肱三头肌；将杠铃从架上取出时不要让肩部前伸，杠铃、手腕、肘部全程保持在一条直线上，专注于握紧杠铃并尝试把它掰开。', '将杠铃下放到木板上，然后尽全力将杠铃推起，肘部在锁定前始终保持内收。'],
  'YBody_Tricep_Press': ['将杠铃放在架子上，高度与胸部齐平。', '站立，以肩宽握距握住杠铃，后退一两码（约1至2米），双脚并拢、手臂伸直，身体前倾靠在杠铃上，此为起始姿势。', '屈肘，将身体向杠铃方向下放。', '稍作停顿，然后伸肘反向推起身体。', '适应自重后可加挂链条搭在肩上增加负荷。'],
  'YBodyweight_Flyes': ['将两根负载相同的曲杆杠铃并排放在地面上，确保它们可以滚动。', '在杠铃上方摆出俯卧撑姿势，用脚尖和双手支撑体重，手臂伸直、身体成一条直线。', '将双手放在杠铃上，此为起始姿势。', '用缓慢受控的动作将双手向身体中线两侧移动，让杠铃向外滚开，此阶段吸气。', '杠铃滚到尽量分开的位置后，呼气并拉动它们合拢，回到起始姿势。'],
  'YBodyweight_Mid_Row': ['在引体向上器械上采用中距到宽距握法，掌心朝前；从悬垂开始，收膝至胸前、身体后仰，把双腿绕过引体向上器械的同侧，此为起始姿势。', '从手臂伸直开始，屈肘并后收肩胛骨，将身体拉起，直到双腿碰到引体向上器械。', '稍作停顿后回到起始姿势。'],
  'YBodyweight_Walking_Lunge': ['站姿开始，双脚与肩同宽，双手叉腰。', '一条腿向前迈出，屈膝下放髋部，直到后腿膝盖接近地面；躯干保持直立，前膝保持在脚尖正上方。', '用前脚脚跟蹬地发力，伸直双膝将身体顶起。', '后腿继续向前迈出，换另一条腿重复箭步蹲。'],
  'YBosu_Ball_Cable_Crunch_With_Side_Bends': ['在绳索训练器的两侧各装一个标准把手，并把它们调到最低位置。', '取一个波速球，放在绳索训练器正前方居中位置。', '仰卧在波速球上，腰部弓起贴合球面，臀部贴近但不接触地面。', '双手向后伸，分别握住两侧绳索的把手。', '双脚宽站距踩实，双臂伸直向前伸出、位于双膝之间，双手与膝盖同高。', '保持手臂伸直，与绳索向上的角度保持一致；以卷腹动作抬起躯干，手臂不要下放或弯曲。', '手臂保持固定位置，缓慢下降回到起始姿势，背部弓起贴合波速球，腹部充分拉长。', '重复上述动作直到力竭。', '力竭后保持腹部收紧，把躯干抬成平板支撑姿势，使背部离开波速球。', '手臂保持伸直放回体侧，开始交替做侧屈，尽量伸手去够脚跟！这个收尾动作主要刺激腹斜肌。'],
  'YBottomsUp_Clean_From_The_Hang_Position': ['开始动作：直立站立，单手握住一只壶铃。', '用力将壶铃向后摆，再猛烈反向发力，尽可能用力握紧壶铃把手，将壶铃翻举至肩部。'],
  'YBox_Jump_Multiple_Response': ['放松站立，面对约一臂之遥的跳箱或平台，双臂垂于体侧，双腿微屈。', '借助摆臂助力爆发起跳，向上向前跃起，双脚同时落在跳箱或平台上。', '立即跳回或走下地面回到原位，然后重复上述过程。'],
  'YBox_Skip': ['需要若干个跳箱，间隔约8英尺（约2.4米）排成一行。', '面向第一个跳箱站立，一条腿略位于另一条腿后方。', '用后腿蹬地起跳，尽量把髋部抬到最高。', '落在箱上后立即换另一条腿向前上方发力，从箱上跃出以获得高度和远度，用落在第一个箱上的那条腿在头两个箱之间落地。', '然后走向下一个箱，重复动作。'],
  'YBox_Squat': ['箱式深蹲能让你蹲到目标深度，并发展深蹲动作中的爆发力；在深蹲架内开始，身后放置合适高度的箱子，通常箱高以蹲到大腿平行地面为准，也可按需调整高低。', '钻到杠铃下方，将杠铃横在肩后；夹紧肩胛骨、肘部向前旋，有意识地把杠铃在肩上压弯；下背部保持紧张弓起，将杠铃从架上取出后退到站位；双脚分宽更侧重背部、臀大肌、内收肌和腘绳肌，站窄更侧重股四头肌，头部始终目视前方。', '保持背部、肩部和核心收紧，膝盖与臀部向外打开开始下蹲，髋部后坐直到坐稳在箱子上；理想状态下小腿与地面垂直，触箱时稍作停顿并放松髋屈肌，绝不要在箱子上反弹。', '体重压在脚跟，双脚和膝盖向外撑开，以头部引导发力从箱上站起，继续向上站直，从头到脚保持全程紧绷。'],
  'YBox_Squat_with_Bands': ['在深蹲架内开始，身后放置合适高度的箱子；把弹力带套在杠铃套筒上，另一端固定到弹力带挂柱、架子或哑铃上，确保张力合适；若用哑铃固定，要确保它们不会移动且足够重，必要时可再加杠铃片压住；需要更大张力时可加宽地面支点或缩短弹力带；箱高通常以蹲到大腿平行地面为准，也可按需调整。', '钻到杠铃下方，将杠铃横在肩后；夹紧肩胛骨、肘部向前旋，有意识地把杠铃在肩上压弯；下背部保持紧张弓起，将杠铃从架上取出后退到站位；双脚分宽更侧重背部、臀大肌、内收肌和腘绳肌，站窄更侧重股四头肌，头部始终目视前方。', '保持背部、肩部和核心收紧，膝盖与臀部向外打开开始下蹲，髋部后坐直到坐稳在箱子上；理想状态下小腿与地面垂直，触箱时稍作停顿并放松髋屈肌，绝不要在箱子上反弹。', '体重压在脚跟，双脚和膝盖向外撑开，以头部引导发力从箱上站起，继续向上站直，从头到脚保持全程紧绷；结束后小心地将杠铃放回架子上。'],
  'YBox_Squat_with_Chains': ['在深蹲架内开始，身后放置合适高度的箱子；箱高通常以蹲到大腿平行地面为准，也可按需调整高低。', '安装链条：先把牵引链环套在杠铃套筒上，重链用弹簧扣连接；调整牵引链的长度，使动作顶端时仍有几节链条落在地面上。', '钻到杠铃下方，将杠铃横在肩后；夹紧肩胛骨、肘部向前旋，有意识地把杠铃在肩上压弯；下背部保持紧张弓起，将杠铃从架上取出后退到站位；双脚分宽更侧重背部、臀大肌、内收肌和腘绳肌，站窄更侧重股四头肌，头部始终目视前方。', '保持背部、肩部和核心收紧，膝盖与臀部向外打开开始下蹲，髋部后坐直到坐稳在箱子上；理想状态下小腿与地面垂直，触箱时稍作停顿并放松髋屈肌，绝不要在箱子上反弹。', '体重压在脚跟，双脚和膝盖向外撑开，以头部引导发力从箱上站起，继续向上站直，从头到脚保持全程紧绷。'],
  'YBrachialisSMR': ['侧卧，上臂压在泡沫轴上；上臂与身体大致平行，让肱二头肌外侧贴住泡沫轴。', '把髋部抬离地面，用上臂和双脚支撑体重，保持10至30秒后换边。'],
  'YBradford_Rocky_Presses': ['坐在军事推举凳上，杠铃置于肩部高度，用正握（掌心向前）握杠；握距略宽于肩，杠铃下放时前臂与上臂应呈90度，此为起始姿势。', '以正确握距拿起杠铃后，锁定双臂将杠铃举过头顶。', '吸气并缓慢将杠铃下放到头后。', '呼气将杠铃推回起始姿势。', '吸气缓慢将杠铃下放回起始姿势，这算一次重复。', '按此方式交替进行，直到完成建议的次数。'],
  'YButt_Lift_Bridge': ['仰卧平躺在地面上，双手放在身体两侧，屈膝，双脚与肩同宽踩地，此为起始姿势。', '主要用脚跟发力，保持背部挺直将髋部抬离地面，此阶段呼气并在顶端保持一秒。', '吸气缓慢回到起始姿势。'],
  'YButterfly': ['坐在蝴蝶机上，背部平贴靠垫。', '握住把手；上臂应大致与地面平行，可按此调整器械，此为起始姿势。', '缓慢将把手向中间合拢，同时挤压胸部中缝，此阶段呼气并保持收缩一秒。', '吸气缓慢回到起始姿势，直到胸部肌肉完全拉伸。', '按建议的次数重复。'],
  'YCable_Chest_Press': ['调好合适重量后坐下，握住把手；上臂与身体约成45度，抬头挺胸，肘部弯曲约90度，此为起始姿势。', '开始动作：伸展肘部，将双手把向正前方推出并拢，动作过程中保持肩胛骨后收。', '完全伸展处稍作停顿后回到起始姿势，全程保持绳索张力。', '你也可以背部离开靠垫、抬高或降低角度，或交替单手来做这个动作。'],
  'YCable_Crunch': ['跪在高位滑轮下方，滑轮上装有绳索附件。', '握住绳索附件，把绳索拉低到双手位于面部两侧。', '髋部微屈，让重量把下背部拉伸到过伸位置，此为起始姿势。', '髋部保持不动，收缩腹部向前卷屈躯干，使肘部向大腿中部移动；此阶段呼气并保持收缩一秒。', '吸气缓慢回到起始姿势；全程保持腹部持续受力，也不要选过重的重量以免下背部承受主要负荷。', '按建议的次数重复。'],
  'YCable_Deadlifts': ['把绳索滑轮移到龙门架底部，选择合适的重量，站在两根立柱正中间。', '开始动作：屈髋屈膝下蹲，直到能抓住把手。', '抓住把手后开始起身，用脚跟蹬地发力，伸髋伸膝站起，双手自然垂在体侧，全程保持抬头挺胸。', '完全站直后回到起始姿势并重复。'],
  'YCable_Hammer_Curls__Rope_Attachment': ['在低位滑轮上装上绳索附件，面向器械站立，距器械约12英寸（约30厘米）。', '用中立握（掌心相对）握住绳索，站直身体，保持背部自然生理曲度，躯干稳定不动。', '肘部贴紧体侧，整个动作过程中肘部保持固定不动；只有前臂应移动，上臂不动，此为起始姿势。', '呼气时用肱二头肌发力将手臂拉起，直到肱二头肌触到前臂；记得保持肘部内收、上臂固定。', '挤压肱二头肌收缩一秒后，缓慢将重量放回原位。', '按建议的次数重复。'],
  'YCable_Iron_Cross': ['先把滑轮调到高位，选择要用的阻力，双手各握一只把手。', '站在两个滑轮正中间，双臂向两侧伸直呈"T"字，抬头挺胸，此为起始姿势。', '保持肘部伸直，将双臂向身体两侧下方拉。', '在顶峰收缩处停顿后，将双臂放回起始姿势。', '按规定的次数继续重复该动作。'],
  'YCable_One_Arm_Tricep_Extension': ['用右手以反握（掌心朝上）握住连接高滑轮的单把手，身体正对配重片站好。', '现在将把手拉下，让上臂和肘部贴紧身体侧面固定，上臂与前臂应呈小于90度的锐角；另一只手可放在腰间，也可一腿在前、一腿在后以保持更好的平衡，这就是起始姿势。', '收缩肱三头肌时，将单把手向身体侧下方移动，直到手臂伸直，动作过程中呼气；提示：只有前臂应该移动，上臂全程保持不动。', '顶峰收缩，挤压肱三头肌并在收缩位置保持一秒。', '缓慢将把手放回起始位置。', '按建议次数完成重复，然后换另一只手臂做同样的动作。'],
  'YCable_Rear_Delt_Fly': ['将滑轮调整到合适高度并设置好重量，滑轮应高于头顶。', '右手抓左侧滑轮把手、左手抓右侧滑轮把手，在身前交叉，这就是起始姿势。', '开始动作：手臂向后向外打开，动作过程中保持手臂伸直。', '动作末端稍作停顿，再将把手放回起始位置。'],
  'YCable_Rope_Overhead_Triceps_Extension': ['将绳索把手连接到滑轮机的底部滑轮上。', '双手握住绳索，采用中立握（掌心相对），将手臂伸直举过头顶，肘部贴近头部，手臂与地面垂直，指关节朝向天花板，这就是起始姿势。', '保持上臂固定，缓慢将绳索降到头后，动作过程中吸气，当肱三头肌完全拉伸时稍作停顿。', '呼气并收缩肱三头肌，回到起始位置。', '按建议次数完成重复。'],
  'YCable_Rope_RearDelt_Rows': ['像做坐姿绳索划船练背一样，坐在低位滑轮划船器的同一位置上。', '将绳索连接到滑轮上，用正握抓住绳索，手臂伸直并与地面平行，肘部向外打开。', '保持下背部直立，臀部向后滑动，让膝盖微微弯曲，这就是起始姿势。', '将绳索把手拉向上胸部、颈部下方的位置，同时保持肘部向上并向两侧打开，呼气并继续拉，直到肘部略微超过身体后方；提示：全程保持上臂水平、与躯干垂直并与地面平行。', '回到手臂伸直、肩膀向前伸展的初始位置，做这一部分动作时吸气。', '按建议次数完成重复。'],
  'YCable_Russian_Twists': ['连接一个标准把手，并将绳索调整到中滑轮位置。', '侧身躺在瑜伽球上，身体与绳索方向垂直，用一只手抓住把手，距离滑轮约一臂远，让绳索承受配重的张力。', '用双手握住把手，将手臂完全伸直举在胸部上方，双手应与滑轮保持在一条直线上，如果不在一条线上，就上下调整滑轮直到对齐。', '保持臀部抬高、腹部收紧，将躯干向远离滑轮的方向旋转四分之一圈，身体从头到膝盖保持平直。', '稍作停顿，然后缓慢、有控制地回到起始姿势，休息位置时绳索应仍保持侧向张力。', '继续重复同样的动作直到力竭。', '然后重新调整位置，在另一侧重复同样的系列动作。'],
  'YCable_Seated_Lateral_Raise': ['站在两个相对的低滑轮中间，身后放一张平凳（与身体垂直放置，凳子的窄边朝向自己），然后设置好每个滑轮的重量。', '现在坐在身后平凳的边缘，双脚放在膝盖前方。', '保持背部平直向前俯身，将躯干靠在双腿上。', '让同伴把连接滑轮的把手递给你，选好重量后右手抓左侧滑轮、左手抓右侧滑轮，绳索应从膝盖下方穿过，手臂伸直、掌心相对、肘部微屈，这就是起始姿势。', '保持手臂固定，将上臂向两侧抬起，直到与地面平行、与肩同高，动作过程中呼气，顶峰收缩保持一秒。', '吸气，缓慢将手臂放回起始位置。', '按建议次数完成重复；提示：全程保持上臂与躯干垂直，肘部固定在10度到30度角。'],
  'YCable_Shrugs': ['用与肩同宽或略宽的过握（掌心向下）抓住连接低位滑轮的横杆把手。', '靠近滑轮直立站好，手臂前伸握住横杆，这就是起始姿势。', '呼气，将肩膀尽可能高地向上耸起，顶部收缩保持一秒；提示：手臂全程保持伸直，不要借助肱二头肌抬杆，只有肩膀应上下移动。', '将横杆放回原位。', '按建议次数完成重复。'],
  'YCalfMachine_Shoulder_Shrug': ['在提踵机上站好，让肩垫位于肩膀上方，躯干挺直，手臂自然垂于体侧，这就是起始姿势。', '呼气，将肩膀向上耸向耳朵方向，顶峰收缩保持整整一秒。', '吸气，缓慢回到起始姿势。', '按建议次数完成重复。'],
  'YCalf_Press': ['调整座椅，使起始姿势时双腿略微弯曲，前脚掌应稳稳踩在踏板上。', '选择合适重量并握住把手，这就是起始姿势。', '通过伸膝伸直双腿，刚好把重量从配重片中微微抬起，脚踝完全屈曲、脚尖朝上，然后通过前脚掌尽可能用力向下压，完成动作。', '短暂停顿后，反向还原并重复。'],
  'YCalf_Press_On_The_Leg_Press_Machine': ['使用腿举机，坐在器械上，将双脚放在正前方的踏板上，采用中距（与肩同宽）站距。', '放下固定负重平台的安全杆，将平台完全向上推，直到双腿在身前完全伸直且膝盖不锁死（注：有些腿举机可以保留安全杆以获得更高安全性，如果设备允许，这是优选做法）；躯干与双腿应呈标准90度角，然后小心地把脚趾和前脚掌放在平台下缘，脚跟悬出边缘，脚尖按本章开头所述朝前、朝外或朝内，这就是起始姿势。', '呼气，通过尽可能高地伸踝、收缩小腿，抬起脚跟压向踏板，确保膝盖全程保持固定、任何时候都不弯曲，在收缩位置保持一秒再开始回落。', '吸气，缓慢放下脚跟、屈曲脚踝，直到小腿得到拉伸，回到起始姿势。', '按建议次数完成重复。'],
  'YCalf_Raise_On_A_Dumbbell': ['扶着稳固的物体保持平衡，站在一个哑铃的握柄上，最好选用圆片哑铃，这样它会滚动，你需要更费力地稳定身体，从而提高训练效果。', '现在将脚稍微向前滚动，让小腿得到充分拉伸，这就是起始姿势。', '将脚滚过握柄顶端做起踵，获得完全的伸展，动作过程中呼气，顶部用力收缩小腿并保持一秒；提示：上来时让哑铃略微向后滚动。', '吸气，下落时让哑铃略微向前滚动，以获得更好的拉伸。', '按建议次数完成重复。'],
  'YCalf_Raises__With_Bands': ['拿起一根弹力带，用脚尖踩住它，确保脚与手臂之间的弹力带长度两侧一致。', '握住弹力带两端把手，把手臂举到头侧，就像准备做肩上推举一样，掌心朝前、肘部弯曲并指向两侧，这个动作会给弹力带制造张力，这就是起始姿势。', '双手保持在肩旁，呼气并踮起脚尖站起，动作顶部用力收缩小腿。', '收缩保持一秒后，缓慢回到起始姿势。', '按建议次数完成重复。'],
  'YCalf_Stretch_Elbows_Against_Wall': ['面对墙壁站立，离墙约两英尺。', '前倾靠墙，将体重压在前臂上。', '尽量保持脚跟不离地，保持10到20秒；可以靠近或远离墙壁来相应增加或减小难度。'],
  'YCalf_Stretch_Hands_Against_Wall': ['面对墙壁站在几步之外，双脚前后交错站立，一只脚向前。', '身体前倾，双手撑墙，保持脚跟、髋部和头部在一条直线上。', '尽量保持脚跟不离地，保持10到20秒，然后换边。'],
  'YCalvesSMR': ['先坐在地板上，将泡沫轴垫在小腿下方，另一条腿可以交叉搭在对侧腿上或放在地板上分担部分体重，这就是起始姿势。', '双手放在体侧或身后稍后方，撑地抬起髋部离开地面，将大部分体重压在腓肠肌上，从膝盖下方到脚踝上方滚动，在紧张点停顿10到30秒，然后换另一条腿重复。'],
  'YCar_Deadlift': ['这项赛事器械通常配有中立握把手，但有些是直杆，可以像常规硬拉一样操作；器械上可以装载车辆或其他重物，如拖拉机轮胎或啤酒桶。', '如果深蹲力量强，就站在把手正中；如果硬拉力量强，则向后站几英寸，双脚约与髋同宽，屈髋抓住把手；脚和握姿就位后深吸一口气，然后降髋屈膝。', '目视前方，挺胸弓背，开始用脚跟发力将重量向上移动，重量上升时收紧肩胛骨，同时髋部向前顶。', '屈髋将重量下降，引导其落回地面。'],
  'YCar_Drivers': ['直立站好，双手在3点和9点钟位置握住杠铃片，掌心相对，手臂向前伸直，这就是起始姿势。', '开始动作：将杠铃片尽可能向一侧旋转，就像向一侧打方向盘一样。', '反向转动，一直转到另一侧。', '按建议次数完成重复。'],
  'YCarioca_Quick_Step': ['双脚分开几英寸站立，左臂抬起，保持放松的运动姿态。', '右脚快速向后交叉一步，并向上提膝。', '提右膝时手臂迅速向上摆回，注意膝盖应笔直上下移动；移动过程中避免脚步旋转，侧向移动时保持目视前方。'],
  'YCat_Stretch': ['四肢着地跪在地板上。', '收腹，弓起脊柱、下背部、肩膀和颈部，让头部自然下垂。', '保持15秒。'],
  'YCatch_and_Overhead_Throw': ['站立开始，面对墙壁或同伴。', '双手将球置于头后，尽可能向后伸展，然后用力将球向前抛出。', '确保随挥动作完整，并准备好接住抛球后弹回的球；如果是对墙抛，要站得离墙足够近以便接住回弹，瞄准高度要比与同伴练习时略高。'],
  'YChain_Handle_Extension': ['这个动作需要两个绳索把手配件、一张平凳以及链条；将链条中间夹在把手上，然后躺在平凳上，肘部应朝上指。', '开始动作：保持上臂不动、手腕旋前（掌心向下），通过伸肘完成伸展。', '在锁定位置稍作停顿，反向往返回到起始位置。'],
  'YChain_Press': ['先把链条连接到绳索把手配件上，像做哑铃推举一样躺在平凳上，手腕旋前（掌心向下），手臂垂直于地面，这就是起始姿势。', '屈肘将链条放下，让部分链条卸落到地板上。', '继续下降到肘部呈90度角，然后反向通过伸肘回到锁定位置。'],
  'YChair_Lower_Back_Stretch': ['在椅子上坐直。', '将手臂举过头顶向一侧弯曲，另一只手可以扶住椅子。', '保持10秒，然后换另一侧重复。'],
  'YChair_Squat': ['首先将杠铃调到最适合自己身高的位置，装好重量后钻到杠下，将杠铃横在肩后。', '双手掌心向前抓住杠铃，解锁杠铃，通过伸腿将其抬起离开架子。', '双脚向前移动约18英寸，站距与肩同宽、脚尖微微外展；全程目视前方，保持脊柱中立或略微弓起，这就是起始姿势。', '屈膝缓慢下放杠铃，保持身体挺直、头部抬起，继续下降直到大小腿之间的角度小于90度。', '呼气，用脚跟踩地、伸膝将杠铃抬起，回到起始姿势。', '按建议次数完成重复。'],
  'YChair_Upper_Body_Stretch': ['坐在椅子边缘，双手抓住椅背。', '挺直背部、伸直手臂，将上半身向前拉，直到感觉到拉伸，保持20到30秒。'],
  'YChest_Push_from_3_point_stance': ['以三点支撑姿势开始：下蹲、背部平直、单手撑地，将药球放在正前方。', '开始动作：迈出第一步，同时把球拉向胸口，双手就位准备投掷。', '迈出第二步时，尽可能爆发性地将球向前推出。'],
  'YChest_Push_multiple_response': ['跪姿面对墙壁开始，或与同伴配合，双手将球紧紧抱在胸前。', '完成传接：髋部爆发性向前向外发力，同时尽可能用力推球。', '随势前扑，用双手撑住自己。', '立即回到直立姿势，按所需次数重复。'],
  'YChest_Push_single_response': ['跪姿开始，双手将药球紧紧抱在胸前。', '完成传接：髋部爆发性向前向外发力，同时尽可能远地推球。', '随势前扑，用双手撑住自己。'],
  'YChest_Push_with_Run_Release': ['以运动姿态开始：屈膝、髋部后坐、背部平直，将药球握在腿旁，这就是起始姿势。', '迈出第一步时，把药球拉向胸口。', '迈出第二步时，爆发性地将球向前推出，出手后立即冲刺10码；如果速度够快，你甚至能接住自己传出的球。'],
  'YChest_Stretch_on_Stability_Ball': ['在瑜伽球旁边四肢着地跪好。', '将肘部放在球顶，手臂向体侧伸出，这就是起始姿势。', '保持肘部在球上，躯干向地面下降，保持拉伸20到30秒，换另一只手臂重复。'],
  'YChilds_Pose': ['四肢着地跪好，双手向前爬行。', '臀部向后坐，坐到脚跟上，后坐时让手臂沿地面拖行，以拉伸整条脊柱。', '坐到脚跟上后，把手移到脚边放松，把呼吸「送」进背部，额头贴地；有膝部问题者应避免这个姿势。'],
  'YChin_To_Chest_Stretch': ['在地板上坐好。', '双手放在头后，十指交叉、拇指朝下、肘部指向前方，缓慢将头拉向胸口，保持20到30秒。'],
  'YCircus_Bell': ['马戏铃是一种带粗握柄的超大号哑铃；把哑铃放在双脚之间，双手握住握柄。', '通过伸髋伸膝把哑铃翻举到目标肩上，另一只手松开。', '确保哑铃的一头置于肩后，以免失去平衡；要举过头顶时，屈膝下蹲蓄力，然后向上伸展将哑铃举过头顶，同时身体略微向远离哑铃的一侧倾斜。', '小心地将铃引导回地面，尽量保持全程可控；最好在厚橡胶垫上进行，以防损坏地板。'],
  'YClean': ['杠铃放在地面贴近小腿，在腿外侧采用正握（或勾握），降髋、重心放在脚跟，背部挺直、头朝前、挺胸、肩膀略在杠铃前方，这就是起始姿势。', '', '开始第一段上拉：脚跟发力蹬地、伸膝，背部角度保持不变，手臂保持伸直，有控制地将杠铃继续拉过膝盖上方。', '接下来是第二段上拉，这是翻举加速的主要来源；杠铃接近大腿中部时开始伸髋，以跳跃般的发力方式通过伸髋、伸膝、伸踝加速，用速度把杠铃向上带，不需要主动用手臂拉杠加速；第二段结束时身体应完全伸展、略微后仰，手臂仍保持伸直。', '达到完全伸展后，进入第三段上拉：用力耸肩并屈臂，肘部向上向外；在伸展最高点，猛烈地把自己拉向杠下，同时肘部绕到杠下，以前蹲姿势接杠，下蹲深度取决于第三段结束时杠铃的高度；杠铃应架在向前送出的肩膀上、轻触咽喉、双手放松，继续下蹲到底部深蹲位置，这有助于后续站起。', '立即用脚跟发力站起，保持躯干直立、肘部抬起，直到完全站直。'],
  'YClean_Deadlift': ['站好，杠铃贴近小腿，双脚在髋部正下方、脚尖微微外展，用双正握或勾握、约与肩同宽握住杠铃，下蹲到杠前；脊柱完全伸展，背部角度让肩膀位于杠铃前方、背部尽可能垂直。', '开始动作：通过前脚掌发力蹬地，杠铃上升时保持背部角度不变，膝盖向外展开，避免挡住杠铃路径。', '杠铃越过膝盖后，髋部向前顶进杠铃，直到髋膝完全伸展，完成拉起。'],
  'YClean_Pull': ['杠铃放在地面贴近小腿，在腿外侧采用正握或勾握，降髋、重心放在脚跟，背部挺直、头朝前、挺胸、肩膀略在杠铃前方，这就是起始姿势。', '开始第一段上拉：脚跟发力蹬地、伸膝，背部角度保持不变，手臂保持伸直、肘部向外，有控制地将杠铃继续拉过膝盖上方。', '接下来是第二段上拉，这是翻举加速的主要来源；杠铃接近大腿中部时开始伸髋，以跳跃般的发力方式通过伸髋、伸膝、伸踝加速，用速度把杠铃向上带，不需要主动用手臂拉杠加速；第二段结束时身体应完全伸展、略微后仰，手臂仍保持伸直；完全伸展应当猛烈而干脆，确保伸展时间不要拖得比必要更长。'],
  'YClean_Shrug': ['采用与肩同宽的双正握或勾握，杠铃悬垂于大腿中部位置，背部挺直并略微前倾。', '将肩膀耸向耳朵方向；虽然这个动作通常能比翻举加载更重的重量，但要避免负荷过重导致动作速度变慢。'],
  'YClean_and_Jerk': ['杠铃放在地面贴近小腿，在腿外侧采用正握或勾握，降髋、重心放在脚跟，背部挺直、头朝前、挺胸、肩膀略在杠铃前方，这就是起始姿势。', '开始第一段上拉：脚跟发力蹬地、伸膝，背部角度保持不变，手臂保持伸直，有控制地将杠铃继续拉过膝盖上方。', '接下来是第二段上拉，这是翻举加速的主要来源；杠铃接近大腿中部时开始伸髋，以跳跃般的发力方式通过伸髋、伸膝、伸踝加速，用速度把杠铃向上带，不需要主动用手臂拉杠加速；第二段结束时身体应完全伸展、略微后仰，手臂仍保持伸直。', '达到完全伸展后，进入第三段上拉：用力耸肩并屈臂，肘部向上向外；在伸展最高点，猛烈地把自己拉向杠下，同时肘部绕到杠下，以前蹲姿势接杠，下蹲深度取决于第三段结束时杠铃的高度；杠铃应架在向前送出的肩膀上、轻触咽喉、双手放松，继续下蹲到底部深蹲位置，这有助于后续站起。', '立即用脚跟发力站起，保持躯干直立、肘部抬起，直到完全站直。', '第二阶段是上挺，将重量举过头顶；杠铃架在肩前后站立，先做预蹲：双脚在髋部正下方，屈膝但髋部不后移，只下蹲一点点，然后尽可能有力地反向蹬起。', '通过脚跟发力，制造尽可能大的速度和力量，杠铃离开肩膀时记得把头让开。', '双脚离地的那一刻，要尽快进入接杠姿势；在双脚不主动蹬地的短暂瞬间，运动员向上推杠的力会把身体向下带；双脚应前后分开，一只脚在前、一只脚在后，双臂锁定将杠铃接在头顶上方，然后回到站立姿势。'],
  'YClean_and_Press': ['采用与肩同宽的站距，膝盖位于手臂内侧；保持背部平直，屈膝屈髋，用略宽于肩的正握在手臂完全伸直时抓住杠铃，肘部向外打开，杠铃应贴近小腿，肩膀位于杠铃正上方或略靠前，建立平背姿势，这就是起始姿势。', '开始伸膝拉动杠铃，髋部前移与肩膀抬升保持相同速度，背部角度保持不变，继续让杠铃贴近身体垂直上升。', '杠铃过膝后，像跳跃一样爆发性地伸展脚踝、膝盖和髋部，同时双手继续引导杠铃，耸肩并借助身体运动产生的动量把杠铃拉到尽可能高；杠铃应贴近身体，肘部保持向外。', '在最高点时双脚应离开地面，开始把自己拉向杠下，具体机制会因重量不同略有变化；应下蹲进入蹲姿，同时把自己拉向杠下。', '杠铃到达最高高度时，肘部绕到杠下并压到杠下，将杠铃架在肩前，同时保持躯干直立、屈髋屈膝以缓冲杠铃重量。', '站到完全直立，保持翻举姿势持杠。', '双脚不动，呼气将杠铃推举过头顶，然后有控制地将杠铃放下。'],
  'YClean_from_Blocks': ['杠铃放在目标高度的箱子或架上，在腿外侧采用正握或勾握，降髋、重心放在脚跟，背部挺直、头朝前、挺胸、肩膀略在杠铃前方，这就是起始姿势。', '开始第一段上拉：脚跟发力蹬地、伸膝，背部角度保持不变，手臂保持伸直、肘部向外。', '达到完全伸展后，进入接杠姿势：用力耸肩并屈臂，肘部向上向外；猛烈地把自己拉向杠下，同时肘部绕到杠下，以前蹲姿势接杠，下蹲深度取决于第三段结束时杠铃的高度；杠铃应架在向前送出的肩膀上、轻触咽喉、双手放松，继续下蹲到底部深蹲位置，这有助于后续站起。', '立即用脚跟发力站起，保持躯干直立、肘部抬起，直到完全站直，然后把杠铃放回箱上，准备下一次重复。'],
  'YCloseGrip_Barbell_Bench_Press': ['躺在平凳上，用窄握（约与肩同宽）将杠铃从架子上取下，手臂锁定，直举在身体上方，这就是起始姿势。', '吸气，缓慢下降，直到感觉杠铃触到胸中位置；提示：与常规卧推不同，要始终让肘部贴近躯干，以最大化肱三头肌参与。', '停顿一秒后，呼气，用肱三头肌发力把杠铃推回起始位置，在收缩位置锁定手臂保持一秒，然后再次缓慢下降；提示：下降时间至少应是上升时间的两倍。', '按规定的次数重复动作。', '完成后，将杠铃放回架子上。'],
  'YCloseGrip_Dumbbell_Press': ['把一个哑铃竖着放在平凳上。', '确保哑铃稳固地立在凳端，身体与凳子垂直躺下，只有肩膀落在凳面上，髋部低于凳面，双腿弯曲、双脚稳稳踩地。', '双手握住哑铃，在胸前上方一臂距离处举直，双手掌心应压住哑铃两侧下端，这就是起始姿势。', '开始动作：将哑铃下降到胸口。', '通过伸肘回到起始位置。'],
  'YCloseGrip_EZBar_Curl_with_Band': ['在曲杆两端各套一条弹力带，拿起杠铃，一只脚踩在弹力带中间；直立站好，用窄握反握握住曲杆杠铃，肘部贴近躯干，这就是起始姿势。', '保持上臂位置不动，屈肘完成弯举，举起重量时呼气。', '继续动作直到肱二头肌完全收缩、杠铃达到肩部高度，在收缩位置保持一秒并用力挤压肱二头肌。', '吸气，缓慢将杠铃放回起始位置。', '按建议次数完成重复。'],
  'YCloseGrip_EZBar_Press': ['躺在平凳上，曲杆杠铃加载合适重量。', '用窄握举起杠铃，肘部内收，直举在躯干上方，手臂应垂直于地面，这就是起始姿势。', '吸气，将杠铃下降到胸下部，动作过程中保持肘部内收。', '呼气，用肱三头肌发力、伸肘把杠铃推回起始位置。', '重复。'],
  'YCloseGrip_EZ_Bar_Curl': ['直立站好、躯干挺直，握住曲杆杠铃内侧的窄握把位，掌心朝前，由于杠铃形状，手掌会略微向内倾斜，肘部贴近躯干，这就是起始姿势。', '保持上臂固定，呼气并收缩肱二头肌，将重量向前弯举；提示：只有前臂应该移动。', '继续动作直到肱二头肌完全收缩、杠铃达到肩部高度，在收缩位置保持一秒并用力挤压肱二头肌。', '吸气，缓慢将杠铃放回起始位置。', '按建议次数完成重复。'],
  'YCloseGrip_Front_Lat_Pulldown': ['坐在高位下拉机上，顶部滑轮连接宽杆，确保调整膝垫高度以适合自己，膝垫可防止身体被杠铃的阻力拉起。', '按规定的握距掌心向前握住横杆；握距说明：宽握时双手间距大于肩宽，中握时等于肩宽，窄握时小于肩宽。', '双臂在身前伸直握住横杆（保持所选握距），将躯干后倾约30度，同时下背部弓起、挺胸，这就是起始姿势。', '呼气，将横杆向下拉至上胸位置，同时肩部和上臂向下向后收；提示：到达完全收缩位时集中挤压背部肌肉，上躯干保持固定（只有手臂移动），前臂除了握住横杆外不做其他工作，不要试图用前臂拉杆。', '在收缩位保持一秒，同时收紧肩胛骨，缓慢将横杆放回起始位置，此时手臂完全伸直、背阔肌完全拉伸，做这一部分动作时吸气。', '按规定的次数重复这个动作。'],
  'YCloseGrip_PushUp_off_of_a_Dumbbell': ['俯卧在地板上，双手撑在一个竖立的哑铃上，用脚尖和双手支撑体重，躯干保持刚性、肘部内收、手臂伸直，这就是起始姿势。', '吸气，屈肘下降身体，保持身体平直，不要让髋部抬起或下沉。', '通过伸肘把自己推回起始位置，做这一步时呼气。', '在收缩位置稍作停顿，按规定的次数重复动作。'],
  'YCloseGrip_Standing_Barbell_Curl': ['双手握住杠铃，掌心向上，双手间距几英寸。', '站立时躯干挺直、抬头，双脚约与肩同宽、肘部贴近躯干，这就是起始姿势；提示：整个动作过程中上臂和肘部保持固定。', '以半圆弧轨迹把杠铃弯举起来，直到前臂碰到肱二头肌，做这一部分动作时呼气，顶部用力收缩肱二头肌一秒；提示：举重时避免弓背或借力摆动，只有前臂应该移动。', '吸气，缓慢下放回到起始位置。', '按建议次数完成重复。'],
  'YConans_Wheel': ['装载好重量后，用祖赫尔式握法握住器械末端，把杠放在肘弯处并抓住自己的手腕，尽量让重量不压在前臂上。', '开始把重量从地面提起，保持躯干收紧直立，开始行走，步伐短促快速；转圈时抬头看向远处，整个过程中不要憋气，继续行走直到完成一整圈或多圈。'],
  'YConcentration_Curls': ['坐在平凳上，一个哑铃放在双腿之间的身前；双腿分开、膝盖弯曲、双脚踩地。', '用右臂拿起哑铃，把右上臂后侧放在右大腿内侧顶端，旋转手掌直到掌心朝前、远离大腿；提示：手臂应伸直，哑铃应悬于地面上方，这就是起始姿势。', '保持上臂固定，呼气并收缩肱二头肌，将重量向前弯举，只有前臂移动；继续动作直到肱二头肌完全收缩、哑铃达到肩部高度；提示：动作顶端确保小指高于拇指，这能保证良好的收缩；挤压肱二头肌，在收缩位置保持一秒。', '吸气，缓慢将哑铃放回起始位置；注意：任何时候都要避免摆动借力。', '按建议次数完成重复，然后换左臂重复动作。'],
  'YCross_Over__With_Bands': ['将弹力带固定在稳固的立柱上。', '背对立柱站立，抓住弹力带两端的把手，向前迈步给弹力带制造张力。', '将双臂向两侧举起，与地面平行、与躯干垂直（躯干和手臂应像字母「T」），掌心向前，手臂伸直、肘部微屈，这就是起始姿势。', '保持手臂伸直，呼气并收缩胸肌，以半圆弧轨迹将双臂在胸前交叉到前方，收缩保持一秒。', '吸气，缓慢回到起始位置。', '按建议次数完成动作。'],
  'YCrossover_Reverse_Lunge': ['双脚与肩同宽站立，这就是起始姿势。', '做后撤箭步蹲：一只脚向后迈步，屈髋并屈前膝，同时躯干向前腿方向旋转。', '短暂停顿后回到起始位置，换另一侧重复，两侧交替进行。'],
  'YCrucifix': ['十字架式：静态地将重量向两侧平举并保持时间；虽然这个项目可以用哑铃练习，但最好用各种专用器械练习，如斧头或锤子，因为感觉完全不同。', '站立开始，将手臂向两侧抬起握住器械，手臂应与地面平行；比赛中，裁判或传感器会提示你何时低于平行位置。尽可能久地保持，通常重量应足够重，使你在30到60秒内力竭。'],
  'YCrunch__Legs_On_Exercise_Ball': ['仰卧平躺，双脚搭在瑜伽球上，膝盖弯曲呈90度角。', '双脚分开三到四英寸，脚尖向内相对并互相接触。', '双手轻轻放在头两侧，保持肘部内收；提示：不要十指交叉抱在脑后。', '把下背部压向地面，以更好地孤立腹部肌群，这就是起始姿势。', '开始将肩膀卷离地面，同时用下背部尽可能用力下压；肩膀只需离地约四英寸，下背部保持贴地，做这一部分动作时呼气，在收缩顶部用力挤压腹部并保持一秒；提示：专注于缓慢、有控制的动作，任何时候不要借助惯性。', '吸气，缓慢回到起始位置。', '按建议次数完成重复。'],
  'YCrunches': ['仰卧平躺，双脚平放地面，或搭在凳上屈膝呈90度角；如果脚搭在凳上，双脚分开三到四英寸，脚尖向内相对并互相接触。', '双手轻轻放在头两侧，保持肘部内收；提示：不要十指交叉抱在脑后。', '把下背部压向地面以更好地孤立腹部肌群，同时开始将肩膀卷离地面。', '收缩腹部并呼气，同时用下背部尽可能用力下压；肩膀只需离地约四英寸，下背部保持贴地，在动作顶端用力收缩腹部并保持一秒；提示：专注于缓慢、有控制的动作，不要靠惯性偷懒。', '收缩保持一秒后，吸气，开始缓慢下降回到起始位置。', '按建议次数完成重复。'],
  'YCuban_Press': ['站立，双手各持一只哑铃，采用正握；抬起上臂至与地面平行，让前臂自然下垂呈「稻草人」姿势，这就是起始姿势。', '开始动作：肩部外旋，将上臂旋转180度；上臂保持原位，旋转直到手腕位于肘部正上方、前臂垂直于地面。', '现在通过伸肘推举哑铃，将手臂伸直举过头顶。', '吸气，按相反顺序回到起始位置。', '按建议次数完成重复。'],
  'YDancers_Stretch': ['坐在地板上。', '将右腿交叉搭在左腿上，膝盖保持弯曲，左腿伸直平放在地面上。', '左手放在右腿上，右手撑地。', '上半身向右旋转，保持10到20秒，换边。'],
  'YDeadlift_with_Bands': ['用短弹力带做硬拉时，只需在开始前把弹力带套在杠铃上，然后踩进去设置好；长弹力带需要固定在稳固的基座上，比如沉重的哑铃或深蹲架。', '脚和握姿就位后，深吸一口气，然后降髋屈膝，直到小腿接触杠铃；目视前方，挺胸弓背，开始用脚跟发力将重量向上移动；杠铃过膝后，用力把杠铃拉向身体，收紧肩胛骨，同时髋部向前顶进杠铃。', '屈髋将杠铃下降，引导其落回地面。'],
  'YDeadlift_with_Chains': ['可以把链条挂在杠铃套筒上，或直接把链条中部搭在杠上，这样拉起时重量会逐渐增加。', '走向杠铃，使其位于双脚正中，双脚约与髋同宽；屈髋用与肩同宽握距握住杠铃，让肩胛骨前伸，通常重负荷组会用正握或正反握；脚和握姿就位后，深吸一口气，降髋屈膝，直到小腿接触杠铃。', '目视前方，挺胸弓背，开始用脚跟发力将重量向上移动；杠铃过膝后，用力把杠铃拉向身体，收紧肩胛骨，同时髋部向前顶进杠铃。', '屈髋将杠铃下降，引导其落回地面。'],
  'YDecline_Barbell_Bench_Press': ['将双腿固定在下斜凳末端，缓慢躺到凳上。', '用中握（动作中段前臂与上臂呈90度角的握距）将杠铃从架子上取下，手臂锁定，直举在身体上方，手臂应垂直于地面，这就是起始姿势；提示：为保护肩袖，最好让保护者帮你把杠铃从架上取下。', '吸气，缓慢下降，直到感觉杠铃触到胸下部。', '停顿一秒后，呼气，用胸部肌肉发力将杠铃推回起始位置，锁定手臂并在收缩位挤压胸肌、保持一秒，然后再次缓慢下降；提示：下降时间至少应是上升时间的两倍。', '按规定的次数重复动作。', '完成后，将杠铃放回架子上。'],
  'YDecline_CloseGrip_Bench_To_Skull_Crusher': ['将双腿固定在下斜凳末端，缓慢躺到凳上。', '用窄握（略窄于肩宽的握距）将杠铃从架子上取下，手臂锁定、肘部内收，直举在身体上方，手臂应垂直于地面，这就是起始姿势；提示：为保护肩袖，最好让保护者帮你把杠铃从架上取下。', '吸气，将杠铃下降到胸下部，动作过程中保持肘部内收。', '呼气，用肱三头肌发力把杠铃推回起始位置。', '吸气并保持上臂固定，前臂以半圆弧轨迹向自身方向移动，缓慢下降杠铃，直到感觉杠铃轻轻碰到额头，做这一部分动作时吸气。', '收缩肱三头肌并呼气，将杠铃举回起始位置。', '重复第3至第6步，直到完成建议次数。'],
  'YDecline_Dumbbell_Bench_Press': ['将双腿固定在下斜凳末端，双手各持一只哑铃放在大腿上躺下，掌心相对。', '躺好后，把哑铃移到身前、与肩同宽。', '到达肩宽位置后，向前旋转手腕，使掌心朝前远离自己，这就是起始姿势。', '呼气，缓慢将重量向身体两侧放下，全程完全控制哑铃；提示：整个动作过程中，前臂应始终垂直于地面。', '呼气，用胸肌发力将哑铃推起，在收缩位置锁定手臂、挤压胸部、保持一秒，然后开始缓慢下降；提示：下降时间至少应是上升时间的两倍。', '按训练计划规定的次数重复动作。'],
  'YDecline_Dumbbell_Flyes': ['将双腿固定在下斜凳末端，双手各持一只哑铃放在大腿上躺下，掌心相对。', '躺好后，把哑铃移到身前、与肩同宽，掌心相对，手臂垂直于地面并完全伸直，这就是起始姿势。', '肘部微屈以防肱二头肌肌腱受压，以大幅弧线将双臂向两侧下降，直到胸部感到拉伸，做这一部分动作时吸气；提示：整个动作过程中手臂保持固定，只应在肩关节处发生移动。', '挤压胸肌并呼气，将双臂收回起始位置；提示：确保使用与下降时相同的弧线轨迹。', '在收缩位保持一秒，按规定的次数重复动作。'],
  'YDecline_Dumbbell_Triceps_Extension': ['将双腿固定在下斜凳末端，双手各持一只哑铃放在大腿上躺下，掌心相对。', '躺好后，把哑铃移到身前、与肩同宽，掌心相对，手臂垂直于地面并完全伸直，这就是起始姿势。', '吸气并保持上臂固定（肘部内收），前臂以半圆弧轨迹向自身方向移动，缓慢下降哑铃，直到拇指到达耳朵旁边，做这一部分动作时吸气。', '收缩肱三头肌并呼气，将哑铃举回起始位置。', '按建议次数完成重复。'],
  'YDecline_EZ_Bar_Triceps_Extension': ['将双腿固定在下斜凳末端，缓慢躺到凳上。', '用窄握（略窄于肩宽的握距）将曲杆杠铃从架子上取下，手臂锁定、肘部内收，直举在身体上方，手臂应垂直于地面，这就是起始姿势；提示：为保护肩袖，最好让保护者帮你把杠铃从架上取下。', '吸气并保持上臂固定，前臂以半圆弧轨迹向自身方向移动，缓慢下降杠铃，直到感觉杠铃轻轻碰到额头，做这一部分动作时吸气。', '收缩肱三头肌并呼气，将杠铃举回起始位置。', '重复直到完成建议次数。'],
  'YDecline_Oblique_Crunch': ['将双腿固定在下斜凳末端，缓慢躺到凳上。', '抬起上半身离开凳面，直到躯干与地面呈约35到45度角。', '一只手放在头旁，另一只手放在大腿上，这就是起始姿势。', '从起始位置缓慢抬起上半身，同时躯干向左旋转；呼气并继续卷起，直到右肘触到左膝，在收缩位保持一秒；提示：保持腹部收紧，动作缓慢而有控制。', '吸气，缓慢将身体放回起始位置。', '右侧按建议次数完成一组后，换到左侧；提示：到顶时真正扭转躯干并感受收缩。'],
  'YDecline_Reverse_Crunch': ['仰卧在下斜凳上，双手抓住凳子上端，不要让身体从该位置滑落。', '用腹部力量将双腿保持在与地面平行的位置，膝盖和双脚并拢；提示：双腿应完全伸直、膝盖微微弯曲，这就是起始姿势。', '呼气，骨盆向后卷、髋部抬离凳面，同时将双腿向躯干方向移动，动作结束时膝盖会碰到胸口。', '收缩保持一秒，吸气，将双腿放回起始位置。', '按建议次数完成重复。'],
  'YDecline_Smith_Press': ['将下斜凳放在史密斯机下方，把杠铃调到躺下时手臂几乎完全伸直能够到的位置；用宽于肩的正握解锁杠铃，手臂伸直，将杠铃直举在身体上方，这就是起始姿势。', '吸气，屈肘有控制地下降杠铃，轻轻接触躯干。', '短暂停顿后，伸肘将杠铃推回起始位置，同时呼气。', '按规定的次数重复动作。', '一组完成后，把杠铃锁回架子上。'],
  'YDeficit_Deadlift': ['先准备一个可以站上去的平台或杠铃片，通常高1到3英寸；走向杠铃，使其位于双脚正中，双脚约与髋同宽；屈髋用与肩同宽握距握住杠铃，让肩胛骨前伸，通常重负荷组会用正握或正反握。', '脚和握姿就位后，深吸一口气，然后降髋屈膝，直到小腿接触杠铃；目视前方，挺胸弓背，开始用脚跟发力将重量向上移动；杠铃过膝后，用力把杠铃拉向身体，收紧肩胛骨，同时髋部向前顶进杠铃。', '屈髋将杠铃下降，引导其落回地面。'],
  'YDepth_Jump_Leap': ['这个训练需要两个箱子或凳子，一个高12到16英寸，另一个高22到26英寸。', '站在其中一个箱子上，双臂垂于体侧，双脚并拢、脚尖略微超出边缘，就像做跳深一样；把另一个箱子放在前方约两三英尺处、正对练习者。', '开始动作：从第一个箱子上跳下，落地同时双脚立即起跳。', '尽可能猛烈地向上向外反弹，借助手臂和身体的完全伸展跳到更高的箱子上，同样用腿部缓冲冲击。'],
  'YDip_Machine': ['在臂屈伸机上坐稳，选择重量并牢牢握住把手。', '保持肘部贴近身体两侧，以重点刺激肱三头肌，肘部应弯曲呈90度角。', '呼气，收缩肱三头肌，将手臂向下伸展；提示：动作底部注意保留手臂略微弯曲，以保持肱三头肌张力。', '吸气，缓慢让手臂回到起始位置。', '按建议次数完成重复。'],
  'YDips__Chest_Version': ['这个动作需要双杠；要进入起始姿势，将身体撑在杠上，手臂伸直（锁定）支撑。', '吸气，躯干前倾约30度、肘部略微外展，缓慢下降身体，直到胸部感到轻微拉伸。', '感到拉伸后，呼气，用胸部力量将身体推回起始位置；提示：动作顶部记得挤压胸部一秒。', '按规定的次数重复动作。'],
  'YDips__Triceps_Version': ['要进入起始姿势，将身体撑在杠上，手臂几乎完全锁定。', '吸气，缓慢下降身体；躯干保持直立，肘部贴近身体，这有助于更好地集中刺激肱三头肌，一直下降到上臂与前臂呈90度角。', '呼气，用肱三头肌发力将躯干推回起始位置。', '按规定的次数重复动作。'],
  'YDonkey_Calf_Raises': ['这个动作需要驴踢提踵机；首先将下背部和髋部置于带衬垫的杠杆下方，尾骨区域应接触垫子。', '双臂放在两侧把手上，前脚掌踩在提踵踏块上，脚跟悬出边缘；根据想要刺激的部位让脚尖朝前、朝内或朝外，伸直膝盖但不要锁死，这就是起始姿势。', '呼气，尽可能高地伸踝、收缩小腿以抬起脚跟；确保膝盖全程保持固定、任何时候都不弯曲，在收缩位置保持一秒再开始回落。', '吸气，缓慢放下脚跟、屈曲脚踝，直到小腿得到拉伸，回到起始位置。', '按建议次数完成重复。'],
  'YDouble_Kettlebell_Alternating_Hang_Clean': ['将两只壶铃放在双脚之间，臀部向后推、目视前方，进入起始姿势。', '将一只壶铃翻举到肩上，另一只继续握住。', '以流畅的动作，将上方的壶铃放下，同时把下方的壶铃向上翻举。'],
  'YDouble_Kettlebell_Jerk': ['双手各握一只壶铃的手柄。', '通过伸腿伸髋把壶铃拉向肩膀完成翻举，同时旋转手腕使掌心朝前，这就是起始姿势。', '屈膝预蹲，保持躯干直立。', '立即反向发力，脚跟蹬地，实际上是跳跃来制造动量。', '同时伸臂将壶铃推举过头顶锁定，借助身体动量移动重量。', '双脚前后分开落地，一只脚在前、一只脚在后。', '保持重量在头顶，回到站立姿势、双脚并拢，放下壶铃进行下一次重复。'],
  'YDouble_Kettlebell_Push_Press': ['将两只壶铃翻举到肩上。', '下蹲几英寸并迅速反向发力，借助腿部动量将壶铃推过头顶。', '壶铃锁定后，将壶铃放回肩上并重复。'],
  'YDouble_Kettlebell_Snatch': ['将两只壶铃放在双脚后方，屈膝、臀部后坐，拿起壶铃。', '用力将壶铃在双腿之间向后摆荡，然后反向。', '髋部发力向前顶，一气呵成地将壶铃锁定在头顶上方。'],
  'YDouble_Kettlebell_Windmill': ['将一只壶铃放在前脚前方，用对侧手臂将另一只壶铃翻举并推举过头顶；通过伸腿伸髋把壶铃拉向肩膀完成翻举，同时旋转手腕使掌心朝前。', '全程保持壶铃锁定，臀部向持壶铃一侧顶出；双脚向外转45度角（相对于持壶铃的手臂方向）。', '向一侧屈髋、臀部后顶，缓慢侧倾身体，直到能从地面拿起壶铃；全程眼睛始终盯着头顶的壶铃。', '从地面拿起壶铃后停顿一秒，然后反向回到起始位置。'],
  'YDouble_Leg_Butt_Kick': ['站立开始，膝盖微屈。', '快速下蹲一小段距离（屈髋屈膝），然后立即伸展起跳，争取最大垂直高度。', '上升过程中屈膝收脚跟，尝试踢到臀部。', '落地时膝盖仅微屈，用腿部吸收冲击，完成动作。'],
  'YDownward_Facing_Balance': ['俯卧在瑜伽球上。', '腹部趴在球上，双手沿地面向前爬行并抬起双腿，同时伸直肘部和膝盖。'],
  'YDrag_Curl': ['用反握（掌心向前）抓住杠铃，肘部贴近躯干并向后收，这就是起始姿势。', '呼气，弯举杠铃向上，同时肘部保持向后，让杠铃贴住躯干「拖」着向上；提示：可以看到，你并不是把肘部固定在身体两侧，而是让它们向后移动，同时不要耸肩。', '缓慢回到起始位置，全程让杠铃始终贴住躯干。', '按建议次数完成重复。'],
  'YDrop_Push': ['放置两个距离2到3英尺的低箱或平台。', '在它们之间摆出俯卧撑姿势，双手撑在箱子上支撑身体。', '保持良好姿态，向上撑起并从平台上落下，双手移到与肩同宽，用手臂吸收冲击来缓冲落地。'],
  'YDumbbell_Alternate_Bicep_Curl': ['站立（躯干挺直），双手各持一只哑铃垂于体侧，肘部贴近躯干，掌心朝向大腿。', '保持上臂固定，将右手重量弯举起来，同时旋转手掌直到掌心朝前；继续呼气收缩肱二头肌，直到肱二头肌完全收缩、哑铃达到肩部高度，挤压肱二头肌并在收缩位保持一秒；提示：只有前臂应该移动。', '吸气，缓慢将哑铃放回起始位置；提示：下降时记得把掌心转回起始位置（朝向大腿）。', '换左手重复动作，这算一次完整重复。', '按这种方式交替进行，完成建议次数。'],
  'YDumbbell_Bench_Press_with_Neutral_Grip': ['双手各持一只哑铃，躺到平凳上，双脚平放地面，肩胛骨后收。', '保持中立握、掌心相对，手臂在正上方伸直、垂直于地面，这就是起始姿势。', '开始动作：屈肘，将上臂向两侧下降，直到哑铃降到躯干旁。', '停顿，然后伸肘回到起始位置。'],
  'YDumbbell_Bicep_Curl': ['直立站好，双手各持一只哑铃垂于体侧，肘部贴近躯干，旋转手掌直到掌心朝前，这就是起始姿势。', '现在，保持上臂固定，呼气并收缩肱二头肌弯举重量；继续上举直到肱二头肌完全收缩、哑铃达到肩部高度，挤压肱二头肌，在收缩位置短暂停顿。', '然后吸气，缓慢将哑铃放回起始位置。', '按建议次数完成重复。'],
  'YDumbbell_Floor_Press': ['仰卧在地板上，双手持哑铃，膝盖可以弯曲，以重量完全伸直举于上方开始。', '下降重量，直到上臂接触地面；可以把肘部内收来侧重肱三头肌的围度和力量，或让手臂向两侧打开来重点刺激胸部。', '底部停顿，然后伸肘将重量在顶部并拢。'],
  'YDumbbell_Flyes': ['躺在平凳上，双手各持一只哑铃放在大腿上，掌心相对。', '借助大腿帮助抬起哑铃，一次一只，将哑铃举到身前、与肩同宽，掌心相对；像推举一样把哑铃举起，但在锁定前停下保持，这就是起始姿势。', '肘部微屈以防肱二头肌肌腱受压，以大幅弧线将双臂向两侧下降，直到胸部感到拉伸，做这一部分动作时吸气；提示：整个动作过程中手臂保持固定，只应在肩关节处发生移动。', '挤压胸肌并呼气，将双臂收回起始位置；提示：确保使用与下降时相同的弧线轨迹。', '在收缩位保持一秒，按规定的次数重复动作。'],
  'YDumbbell_Lunges': ['躯干挺直站立，双手各持一只哑铃垂于体侧，这就是起始姿势。', '右腿向前迈出约2英尺（相对于留在身后的静止脚），下降上半身，保持躯干直立并维持平衡，下降时吸气；注意：和其他动作一样，下降时不要让膝盖超过脚尖，否则会给膝关节带来过度压力，确保前腿小腿与地面垂直。', '主要用脚跟发力，呼气，推起并回到起始位置。', '按建议次数重复动作，然后换左腿。'],
  'YDumbbell_OneArm_Triceps_Extension': ['抓一只哑铃，坐在军式推举凳或带靠背的多功能凳上，把哑铃竖着放在大腿上，或者站直身体。', '把哑铃翻举到肩部高度，然后手臂伸直举过头顶，使整条手臂与地面垂直且紧贴头部，哑铃应位于身体正上方，另一只手可以完全伸直放在体侧、放在腰部、扶住持铃一侧的上臂，或者抓住一个固定物。', '转动手腕，使掌心朝前，小指朝向天花板，这是你的起始姿势。', '上臂保持不动，缓慢地把哑铃降到头后方，下降时吸气，当肱三头肌完全拉伸时稍作停顿。', '呼气时收缩肱三头肌回到起始姿势，提示：务必只有前臂在移动，上臂要始终保持静止贴住头部。', '重复完成建议的次数，然后换另一侧手臂。'],
  'YDumbbell_Scaption': ['这个矫正性动作可以强化稳定肩胛骨的肌肉，双手各持一个轻重量，自然垂于体侧，拇指朝上。', '开始动作时，双臂向前方抬起，偏离身体中线约30度，整个动作过程中手臂保持完全伸直。', '继续上抬直到双臂与地面平行，然后回到起始姿势。'],
  'YDumbbell_Seated_Box_Jump': ['把跳箱放在凳子侧边一两英尺远的位置，双手把哑铃抱在胸前，坐在凳子上面对跳箱，这是你的起始姿势。', '双脚稳稳踩住地面，身体前倾，通过髋部和膝盖伸展发力向上向前跳起。', '双脚落在跳箱上，屈髋屈膝缓冲落地冲击。', '走下跳箱，回到起始姿势。'],
  'YDumbbell_Shoulder_Press': ['双手各持一只哑铃，坐在有靠背的军式推举凳或多功能凳上，把哑铃竖着放在大腿上。', '现在借助大腿把哑铃一只一只推到肩部高度。', '确保转动手腕使掌心朝前，这是你的起始姿势。', '呼气，把哑铃向上推起，直到顶端两只哑铃相碰。', '在顶端收缩位置稍作停顿后，吸气，缓慢把重量降回起始姿势。', '重复完成建议的次数。'],
  'YDumbbell_Squat_To_A_Bench': ['站直身体，身后放一张平凳，双手各持一只哑铃（掌心朝向腿侧）。', '双脚采用与肩同宽的中等站距，脚尖微微外展，全程保持抬头，低头会破坏平衡，同时保持背部挺直，这是你的起始姿势。注意：这里我们采用上述中等站距来全面发展腿部，你也可以在脚位章节介绍的三种站距中任选一种。', '保持抬头挺直姿态，屈膝缓慢降低躯干，继续下蹲直到臀部轻轻触到身后的凳子，下蹲时吸气。提示：如果动作正确，膝盖前侧应与脚尖形成一条垂直于前方的假想直线，如果膝盖超过这条假想线（超过脚尖），说明膝盖承受了不必要的压力，动作有误。', '呼气，主要用脚跟推地，同时伸直双腿，把杠铃抬起回到起始姿势。', '重复完成建议的次数。'],
  'YDumbbell_Step_Ups': ['站直身体，双手各持一只哑铃（掌心朝向腿侧）。', '右脚踩上高台，通过右腿伸髋伸膝踏上平台，主要用脚跟发力把身体其余部分带起，左脚也踩上平台，向上发力时呼气。', '吸气，左腿先下，屈右腿的髋和膝，回到原站立位置，把右脚放回左脚旁。', '用右腿重复完成建议的次数，然后换左腿进行。'],
  'YDumbbell_Tricep_Extension_Pronated_Grip': ['躺在平凳上，双手各持一只哑铃，直臂举在肩部正上方，手臂完全伸直，与躯干和地面形成90度角。', '掌心朝前，肘部内收，这是你的起始姿势。', '吸气，缓慢下放哑铃直到接近耳朵两侧，务必保持上臂静止、肘部内收。', '呼气，用肱三头肌把重量送回起始姿势。'],
  'YDynamic_Back_Stretch': ['双脚与肩同宽站立，这是你的起始姿势。', '保持手臂伸直，在身体正前方上下摆臂5到10次，每次逐渐加大摆动幅度，直到手臂举过头顶。'],
  'YDynamic_Chest_Stretch': ['双手合拢，双臂伸直指向前方站立，这是你的起始姿势。', '保持手臂伸直，快速把双臂向后尽量打开再收回，类似夸张的击掌动作，重复5到10次，并逐渐加快速度。'],
  'YEZBar_Curl': ['站直身体，双手握住曲杆杠铃外侧的宽握位，掌心朝前，由于杠铃形状双手微微内旋，肘部贴近躯干，这是你的起始姿势。', '上臂保持不动，呼气，收缩肱二头肌把重量向前弯起，注意只移动前臂。', '继续上举直到肱二头肌完全收缩、杠铃到达肩部高度，在顶端收缩位置停顿片刻并挤压肱二头肌。', '吸气，缓慢把杠铃放回起始姿势。', '重复完成建议的次数。'],
  'YEZBar_Skullcrusher': ['用窄握距握住曲杆杠铃，躺在凳上，肘部内收持铃，手臂与地面垂直，这是你的起始姿势。', '上臂保持不动，弯曲肘部下放杠铃，下放时吸气，当杠铃到达前额正上方时稍作停顿。', '伸肘并呼气，把杠铃举回起始姿势。', '重复。'],
  'YElbow_Circles': ['坐下或站立，双脚微微分开。', '双手搭在肩上，肘部与肩同高并向外打开。', '用肘部缓慢画圈，开始画圈时呼气，完成画圈时吸气。'],
  'YElbows_Back': ['站直身体。', '双手放在下背部，手指朝下，肘部向外打开。', '然后温和地把双肘向后拉，试着让两肘相互靠拢。'],
  'YElevated_Back_Lunge': ['把杠铃放到肩部高度的架子上并配好合适的重量，身后放一个低矮的抬高平台。', '杠铃架在上背部，保持背部收紧拱起，双脚站上抬高平台，这是你的起始姿势。', '一条腿向后撤步，屈髋屈膝下降，直到后膝触地。', '稍作停顿，伸髋伸膝站起，完全回到起始姿势后再换腿。'],
  'YElevated_Cable_Rows': ['找一个约4到6英寸高的平台（可以是踏板或提踵踏板）。', '把它放在绳索划船机的座椅上。', '坐上器械，双脚踩在前方平台或横杆上，确保膝盖微屈而不是锁死。', '保持背部自然对齐，身体前倾，握住V型把手。', '手臂伸直向后拉，直到躯干与双腿成90度角，背部应微微拱起、挺胸，持铃于身前时应能感到背阔肌充分拉伸，这是动作的起始姿势。', '躯干保持不动，手臂贴近躯干把把手拉向腹部，拉到触腹为止，拉动时呼气，此时应用力挤压背部肌肉，保持收缩一秒，然后吸气缓慢回到原位。', '重复完成建议的次数。'],
  'YExercise_Ball_Crunch': ['躺在瑜伽球上，让下背部弧度贴住球的球面，双脚屈膝稳稳踩地，上身躯干悬在球顶之外，双臂放在身体两侧或交叉抱在胸前，这两种姿势可以避免颈部劳损（不要采用双手抱头的姿势）。', '降低躯干进入拉伸位置，全程保持颈部不动，这是你的起始姿势。', '髋部保持不动，收缩腹部屈曲腰腹，把肩部和躯干卷起，直到腹部有良好的收缩感，手臂如果在体侧就顺着腿侧滑上来，如果交叉抱胸就保持在胸前，下背部始终贴住球面，动作时呼气并保持收缩一秒。', '吸气，回到起始姿势。', '重复完成建议的次数。'],
  'YExercise_Ball_PullIn': ['把瑜伽球放在旁边，面对球俯身趴在地上，双手与肩同宽撑地，呈俯卧撑姿势。', '现在把小腿胫骨搭在瑜伽球上，提示：此时双腿应完全伸直，胫骨放在球上，上半身呈俯卧撑姿势，由身前伸直的双臂支撑，这是你的起始姿势。', '保持背部完全挺直、上半身不动，呼气，把膝盖向胸部收拢，让球向前滚到脚踝下方，收紧腹部并保持该姿势一秒。', '吸气，缓慢伸直双腿，让球滚回起始姿势。', '重复完成建议的次数。'],
  'YExtended_Range_OneArm_Kettlebell_Floor_Press': ['躺在地上，摆好一只壶铃准备单臂推举，握住壶铃手柄，推举一侧的同侧腿屈膝，膝盖越过身体中线。', '伸肘并内收手臂把壶铃推举到身体上方，然后回到起始姿势。'],
  'YExternal_Rotation': ['侧躺在平凳上，一只手握哑铃，另一只手折放在凳面上垫着头。', '弯曲持铃手臂的肘部，使上臂与前臂成90度角，提示：保持手臂与躯干平行。', '保持上臂不动弯曲肘部，此时前臂与地面平行、与躯干垂直（提示：前臂正好在你正前方），上臂贴住躯干保持静止并与地面平行（始终与躯干对齐），这是你的起始姿势。', '呼气，前臂向外旋转，保持上臂与前臂90度夹角，让哑铃沿半圆轨迹被举起，继续外旋直到前臂与地面垂直、朝向天花板，此时保持收缩一秒。', '吸气，缓慢回到起始姿势。', '重复完成建议的次数，然后换另一侧手臂。'],
  'YExternal_Rotation_with_Band': ['把弹力带绕在柱子上打结系紧，弹力带的高度应与肘部同高，左侧身体朝向弹力带，站在一两英尺开外。', '右手抓住弹力带末端，肘部用力贴住体侧，建议用肘部夹住一块垫子或泡沫轴来保持位置稳定。', '上臂就位后，肘部屈曲90度，手横过躯干前侧，这是你的起始姿势。', '以反手挥拍的轨迹旋转手臂完成动作，肘部保持不动。', '尽量转到位后停顿，然后回到起始姿势。'],
  'YExternal_Rotation_with_Cable': ['把绳索调整到与肘部同高，左侧身体朝向绳索，站在一两英尺开外。', '右手握住把手，肘部用力贴住体侧，建议用肘部夹住一块垫子或泡沫轴来保持位置稳定。', '上臂就位后，肘部屈曲90度，手横过躯干前侧，这是你的起始姿势。', '以反手挥拍的轨迹旋转手臂完成动作，肘部保持不动。'],
  'YFarmers_Walk': ['农夫行走可以使用多种器械，如果没有专用器械，也可以用较重的哑铃或短杠铃代替，先站在器械之间。', '握住把手后，通过脚跟发力把器械提起，保持背部挺直、抬头。', '以小步快走的方式前进，别忘了呼吸，通常以尽可能快的速度走完50到100英尺的距离。'],
  'YFast_Skipping': ['以放松的姿势开始，一条腿略微在前，这是你的起始姿势。', '按照右-右-迈、左-左-迈的节奏做单脚跳步，如此交替进行。', '做快速跳步时尽量贴近地面，减少腾空时间，以最快速度移动。'],
  'YFlat_Bench_Cable_Flyes': ['把平凳放在两个低位滑轮之间，躺下时胸部与绳索滑轮对齐。', '平躺在凳上，双脚踩地。', '让同伴把两个把手递到你手中，用掌心朝上的握法握住每个单把手附件。', '双臂在体侧伸直，肘部微屈，提示：整个动作过程中要保持这个屈肘角度不变，双臂应与地面平行，这是你的起始姿势。', '现在以半圆轨迹在身体正前方举起双臂，把绳索向中间拉拢，直到双手在动作顶端相会，动作时挤压胸部并呼气，在顶端保持收缩一秒。提示：动作正确时，在顶端位置双臂应与躯干垂直，双手在胸部上方相触。', '缓慢回到起始姿势。', '重复完成建议的次数。'],
  'YFlat_Bench_Leg_PullIn': ['躺在瑜伽垫或平凳上，双腿伸出末端。', '双手放在臀部下（掌心向下）或放在体侧抓住凳子（在瑜伽垫上则掌心向下放在体侧），同时把双腿伸直，这是你的起始姿势。', '呼气，屈膝把大腿上部收向腹部，继续动作直到膝盖接近胸部，保持收缩位置一秒。', '吸气，缓慢回到起始姿势。', '重复完成建议的次数。'],
  'YFlat_Bench_Lying_Leg_Raise': ['背部平躺在凳上，双腿向前伸出凳端。', '双手放在臀部下（掌心向下）或放在体侧抓住凳子，这是你的起始姿势。', '保持双腿伸直、膝盖微屈锁定，抬起双腿直到与地面成90度角，动作时呼气，在顶端保持收缩一秒。', '吸气，缓慢把双腿放回起始姿势。'],
  'YFlexor_Incline_Dumbbell_Curls': ['握哑铃时偏向远端一侧，让更多重量落在靠近自己的一侧（在所有的哑铃二头肌动作中这样做都能取得良好效果），然后做常规的上斜哑铃弯举，但手腕尽量向后收，以消除手腕承受的压力。', '坐在呈45度角的上斜凳上，双手各持一只哑铃。', '双臂自然垂于体侧，肘部内收，掌心向前转，拇指指向身体外侧，提示：整个动作过程中保持这个手位，上举时手不应有任何扭转，这是你的起始姿势。', '两只哑铃同时弯举，直到肱二头肌完全收缩并呼气，提示：不要摆臂或借助惯性，全程保持可控动作，在顶端保持收缩一秒。', '吸气，缓慢回到起始姿势。', '重复完成建议的次数。'],
  'YFloor_GluteHam_Raise': ['这个动作可以让同伴帮忙，或者把脚别在稳固的物体下。', '双膝跪地开始，大腿与躯干竖直，如果使用同伴，对方会牢牢按住你的双脚让你保持位置，这是你的起始姿势。', '通过伸膝降低身体，注意向前倾时不要屈髋。', '手触地时把双手撑在身前，这个动作难度很大，没有辅助可能无法完成，可以借手臂轻轻推地帮助回到起始姿势。'],
  'YFloor_Press': ['调整J型挂钩到合适高度以便挂杠，头靠近深蹲架的一端仰卧在地上，肩胛骨收紧，把杠铃从挂钩上取下。', '把杠铃下放到胸部下端或上腹部位置，下放时握紧杠铃并试着把它向两侧掰开，全程保持肘部内收，杠铃下放到上臂触地后停顿，避免重量砸地或弹起。', '以最快速度把杠铃推回，上推时保持杠铃、手腕和肘部在一条直线上。'],
  'YFloor_Press_with_Chains': ['调整J型挂钩到合适高度以便挂杠，这个动作要把链条直接搭在杠铃两端，尽量让链条末端远离杠铃片。', '头靠近深蹲架的一端仰卧在地上，肩胛骨收紧，把杠铃从挂钩上取下。', '把杠铃下放到胸部下端或上腹部位置，下放时握紧杠铃并试着把它向两侧掰开，全程保持肘部内收，杠铃下放到上臂触地后停顿，避免重量砸地或弹起。', '以最快速度把杠铃推回，上推时保持杠铃、手腕和肘部在一条直线上。'],
  'YFootSMR': ['这个动作拉伸足部肌肉的筋膜，先脱鞋坐下，用足底滚轮或类似物品（如一小段PVC管）抵住脚弓位置，这是你的起始姿势。', '用力下压，沿脚弓来回滚动，保持10到30秒，然后换脚。'],
  'YForward_Drag_with_Press': ['把带双把手的链条或绳索附件挂到雪橇上，身体背对雪橇，双手各握一个把手。', '向前迈一步开始动作，身体前倾，通过腿和髋伸展发力移动，每迈一步停顿一下，同时伸肘把双手向前推出，继续向前迈步，直到回到预备推举的起始位置。'],
  'YFreehand_Jump_Squat': ['双臂交叉抱在胸前。', '抬头挺背，双脚与肩同宽站立。', '保持背部挺直、胸部打开，吸气下蹲，直到大腿上部与地面平行或更低。', '主要用前脚掌发力，像弹簧一样用大腿力量尽可能高地垂直跳起，跳起阶段呼气。', '再次触地后，立即下蹲再跳。', '重复完成建议的次数。'],
  'YFrog_Hops': ['双手抱在脑后站立，保持躯干挺直、抬头，下蹲，这是你的起始姿势。', '向前跳出几英尺远，不要跳得过高，脚落地时用腿部缓冲，然后立即再跳，重复5到10次。'],
  'YFrog_SitUps': ['背部平躺在地上（或瑜伽垫上），双腿向前伸直。', '屈膝，大腿外侧贴地（或贴垫），让两脚脚底相对。', '保持大腿外侧贴地（至少几乎贴地），试着把双脚脚底尽量收向身体，提示：这个姿势下双腿应呈菱形。', '双臂在胸前交叉，手搭对侧肩膀，这是你的起始姿势。', '呼气，下背部贴地，同时把躯干向上卷起，提示：这就像完成卷腹前四分之一幅度的动作，在顶端保持一秒。', '吸气，缓慢回到起始姿势。', '重复完成建议的次数。'],
  'YFront_Barbell_Squat': ['出于安全考虑，这个动作最好在深蹲架内完成，先把杠铃放在与自己身高匹配的架子上，选好高度并配好重量后，双臂从杠下抬起，保持肘部抬高、上臂略高于与地面平行，把杠铃架在三角肌上方，双臂交叉握住杠铃以完全控制。', '先用腿发力把杠铃从架上顶起，同时挺直躯干。', '离开架子，双脚采用与肩同宽的中等站距，脚尖微微外展，全程保持抬头，低头会破坏平衡，同时保持背部挺直，这是你的起始姿势（注意：这里我们采用上述中等站距来全面发展腿部，你也可以在脚位章节介绍的三种站距中任选一种）。', '保持抬头挺直姿态，屈膝缓慢下放杠铃，继续下蹲直到大腿与小腿之间的夹角略小于90度（即大腿低于与地面平行的位置），下蹲时吸气。提示：如果动作正确，膝盖前侧应与脚尖形成一条垂直于前方的假想直线，如果膝盖超过这条假想线（超过脚尖），说明膝盖承受了不必要的压力，动作有误。', '呼气，主要用脚掌中部推地，同时伸直双腿把杠铃抬起，回到起始姿势。', '重复完成建议的次数。'],
  'YFront_Barbell_Squat_To_A_Bench': ['出于安全考虑，这个动作最好在深蹲架内完成，先在你身后放一张平凳，再把杠铃放在与自己身高匹配的架子上，选好高度并配好重量后，双臂从杠下抬起，保持肘部抬高、上臂略高于与地面平行，把杠铃架在三角肌上方，双臂交叉握住杠铃以完全控制。', '先用腿发力把杠铃从架上顶起，同时挺直躯干。', '离开架子，双脚采用与肩同宽的中等站距，脚尖微微外展，全程保持抬头，低头会破坏平衡，同时保持背部挺直，这是你的起始姿势（注意：这里我们采用上述中等站距来全面发展腿部，你也可以在脚位章节介绍的三种站距中任选一种）。', '保持抬头挺直姿态，屈膝缓慢下放杠铃，继续下蹲直到臀部触到身后的凳子，下蹲时吸气。提示：如果动作正确，膝盖前侧应与脚尖形成一条垂直于前方的假想直线，如果膝盖超过这条假想线（超过脚尖），说明膝盖承受了不必要的压力，动作有误。', '呼气，主要用脚跟推地，同时伸直双腿把杠铃抬起，回到起始姿势。', '重复完成建议的次数。'],
  'YFront_Box_Jump': ['在身前1到2英尺处放一个高度合适的跳箱，双脚与肩同宽站立，这是你的起始姿势。', '做一个短促的预蹲准备起跳，双臂向后摆。', '从预蹲位置反弹，通过伸髋、伸膝、伸踝尽可能高地跳起，双臂向前上方摆动。', '屈膝落在跳箱上，用腿部缓冲冲击，可以从跳箱直接跳回地面，但最好还是一只脚一只脚地走下来。'],
  'YFront_Cable_Raise': ['在低位滑轮器械上选择合适的重量，左手握住连接低位滑轮的单手绳索把手。', '背对滑轮，手臂伸直下垂，绳索把手位于大腿前方、手臂长度可及的位置，掌心朝向大腿，这是你的起始姿势。', '躯干保持不动（不要摆动），左臂微屈肘向正前方举起，掌心始终朝下，继续上举直到手臂略高于与地面平行，动作时呼气，在顶端停顿一秒。', '吸气，缓慢把手臂放回起始姿势。', '完成该侧所有建议次数后，换右手进行。'],
  'YFront_Cone_Hops_or_hurdle_hops': ['摆一排标志桶或其他小障碍物，每个间隔几英尺。', '站在第一个标志桶前，双脚与肩同宽，这是你的起始姿势。', '双脚同时起跳越过第一个标志桶，起跳时双臂摆动。', '屈膝缓冲落地冲击，紧接着反弹起跳越过下一个标志桶。', '继续跳跃直到越过所有标志桶。'],
  'YFront_Dumbbell_Raise': ['拿起两只哑铃，躯干挺直站立，哑铃位于大腿前方、手臂长度可及处，掌心朝向大腿，这是你的起始姿势。', '躯干保持不动（不要摆动），左臂微屈肘向正前方举起哑铃，掌心始终朝下，继续上举直到手臂略高于与地面平行，动作时呼气，在顶端停顿一秒，停顿后吸气。', '缓慢放下左臂哑铃回到起始姿势，同时抬起右臂哑铃。', '按此方式交替进行，直到每侧手臂都完成建议的次数。'],
  'YFront_Incline_Dumbbell_Raise': ['坐在上斜凳上，靠背角度设在30到60度之间，双手各持一只哑铃，提示：每次可以微调角度，以不同的方式刺激肌肉。', '双臂向前伸直，掌心朝下，哑铃举在大腿上方约1英寸处，这是你的起始姿势。', '保持肘部锁定，缓慢把哑铃直直上举到略高于肩膀的位置，在顶端挤压一秒，动作过程中务必呼气。提示：全程保持头部靠住凳面、双脚踩地。', '吸气，把手臂放回起始姿势。', '重复完成建议的次数。'],
  'YFront_Leg_Raises': ['站在椅子或其他支撑物旁，单手扶住支撑。', '保持腿伸直向前摆腿，然后向下向后摆动，摆到柔韧性允许的最大幅度，重复5到10次，然后换腿。'],
  'YFront_Plate_Raise': ['站直身体，双手在3点和9点钟位置握住杠铃片，掌心相对，手臂伸直锁定、肘部微屈，杠铃片尽量放低垂在身前腰部附近，提示：整个动作过程中手臂保持这个位置，这是你的起始姿势。', '呼气，缓慢举起杠铃片直到略高于肩部，保持收缩一秒。提示：不要摆动重量，也不要屈肘，躯干在整个动作中应保持不动。', '吸气，缓慢把杠铃片放回起始姿势。', '重复完成建议的次数。'],
  'YFront_Raise_And_Pullover': ['躺在平凳上，掌心向下握住杠铃，握距约15英寸。', '把杠铃放在大腿上部，手臂伸直锁定，肘部微屈，这是你的起始姿势。', '吸气，保持手臂伸直，以半圆轨迹举起重量，继续同一轨迹直到杠铃到达头部上方另一侧（提示：杠铃大约走过180度），此时双臂应与地面平行，掌心朝向天花板。', '呼气，沿相反轨迹把杠铃放回起始姿势。', '重复完成建议的次数。'],
  'YFront_Squat_Clean_Grip': ['先把杠铃放在略低于肩部的架子上，杠铃架在三角肌上，抵住锁骨，轻轻触到喉部，双手采用翻举握法，只用手指接触杠铃帮助固定位置。', '先用腿发力把杠铃从架上顶起，同时挺直躯干，离开架子，双脚采用与肩同宽的中等站距，脚尖微微外展，全程保持抬头抬肘，这是你的起始姿势。', '屈膝下蹲，坐向两腿之间，继续下蹲直到腘绳肌压在小腿上，下蹲时主动用髋外展肌把膝盖向外推，保持膝盖与脚尖对齐。', '呼气，主要用脚跟或脚掌中部推地，同时伸直双腿举起杠铃，回到起始姿势。'],
  'YFront_Squats_With_Two_Kettlebells': ['把两只壶铃翻举到肩部，通过伸腿伸髋把壶铃拉向肩部，同时转动手腕。', '全程目视前方，尽可能深地蹲下并在底部停顿，下蹲时把膝盖向外推，应在两腿之间下蹲，保持躯干挺直、抬头挺胸。', '通过脚跟发力站起，然后重复。'],
  'YFront_TwoDumbbell_Raise': ['拿起两只哑铃，躯干挺直站立，哑铃位于大腿前方、手臂长度可及处，掌心朝向大腿，这是你的起始姿势。', '躯干保持不动（不要摆动），双臂微屈肘向正前方举起，掌心始终朝下，继续上举直到手臂略高于与地面平行，动作时呼气，在顶端停顿一秒。', '吸气，缓慢把哑铃放回起始姿势。', '重复完成建议的次数。'],
  'YFull_RangeOfMotion_Lat_Pulldown': ['站立或坐在高凳上，握住连接高位滑轮的两个马镫形绳索，采用交叉握法，使双臂在身前交叉，掌心朝前。', '保持挺胸、下背部微微拱起，像做普通高位下拉一样把把手向下拉，动作轨迹更像一条弧线，动作过程中转动手腕，使底部位置掌心相对而不是朝前，缓慢回到起始姿势后重复。'],
  'YGironda_Sternum_Chins': ['用与肩同宽的反握（掌心朝自己）抓住引体向上横杆。', '现在双臂完全伸直悬垂，挺胸后仰，提示：整个动作过程中都要保持后仰，这是你的起始姿势。', '开始把自己拉向横杆，全程保持脊柱拱起、头部尽量后仰远离横杆，动作时呼气。提示：在动作上端，髋部和腿部与地面约成45度角。', '继续上拉直到锁骨越过横杆、下胸部或胸骨区域触到横杆，保持收缩一秒。提示：完成这一段时，头部应与地面平行。', '吸气，缓慢回到起始姿势。', '重复完成建议的次数。'],
  'YGlute_Kickback': ['跪在地上或瑜伽垫上，屈髋俯身，双臂向前伸直（与躯干垂直），摆出跪姿俯卧撑姿势，但双手间距与肩同宽，头部朝前看，屈膝使腘绳肌与小腿成90度角，这是你的起始姿势。', '呼气，抬起右腿，保持90度屈膝，直到腘绳肌与背部成一条直线，全程收缩臀大肌，在顶端保持收缩一秒。提示：动作结束时大腿应平行于地面，小腿垂直于地面。', '吸气回到起始姿势，然后换左腿重复。', '继续交替双腿，直到完成所有建议的次数。'],
  'YGoblet_Squat': ['站立，双手捧住一只较轻壶铃的壶身两侧，贴近胸前，这是你的起始姿势。', '在两腿之间下蹲，直到腘绳肌压在小腿上，保持挺胸抬头、背部挺直。', '在底部位置停顿，用肘部把膝盖向外推，回到起始姿势，重复10到20次。'],
  'YGood_Morning': ['先把杠铃放在肩部高度的架子上，像做力量深蹲那样把杠铃架在肩后部，而不是架在肩膀上方，背部收紧、肩胛骨夹拢、膝盖微屈，从架前退后一步。', '从髋部开始屈曲，臀部向后移，身体前倾到接近与地面平行，保持背部拱起、颈椎处于正确对齐位置。', '用臀大肌和腘绳肌伸髋，反向完成动作，直到回到起始姿势。'],
  'YGood_Morning_off_Pins': ['先把杠铃放在与腹部大致同高的架子上，弯腰钻到杠下，像做力量深蹲那样把杠铃架在肩后部，而不是架在肩膀上方，高度合适时前倾身体应接近与地面平行，背部收紧、肩胛骨夹拢、膝盖微屈，保持背部拱起、颈椎处于正确对齐位置。', '用臀大肌和腘绳肌伸髋开始动作，带着重量站起，然后缓慢把重量放回安全销，回到起始姿势。'],
  'YGorilla_Chin_Crunch': ['用略宽于肩的反握（掌心朝向自己）挂在引体横杆上。', '屈膝90度，使小腿平行于地面、大腿垂直于地面，这是你的起始姿势。', '呼气，把自己向上拉，同时卷起膝盖，直到膝盖到达胸部高度，当鼻子与横杆同高时停止上拉。提示：到达这个位置时，卷腹动作也应同时完成。', '缓慢吸气，回到起始姿势。', '重复完成建议的次数。'],
  'YGroin_and_Back_Stretch': ['坐在地上，屈膝，双脚并拢。', '十指交叉抱在脑后，这是你的起始姿势。', '向下卷曲，把肘部带向大腿内侧，短暂停顿后，抬头挺背回到起始姿势，重复10到20次。'],
  'YGroiners': ['先在地面呈俯卧撑姿势，这是你的起始姿势。', '双腿同时向前跳，双脚落在双手旁边，跳跃时保持抬头。', '回到起始姿势后立即重复，持续完成10到20次。'],
  'YHammer_Curls': ['站直身体，躯干挺直，双手各持一只哑铃垂于体侧，肘部贴近躯干。', '掌心朝向躯干，这是你的起始姿势。', '上臂保持不动，呼气，收缩肱二头肌把重量向前弯起，继续上举直到肱二头肌完全收缩、哑铃到达肩部高度，挤压肱二头肌并在收缩位置保持片刻。提示：专注于保持肘部不动，只移动前臂。', '短暂停顿后，吸气，缓慢把哑铃放回起始姿势。', '重复完成建议的次数。'],
  'YHammer_Grip_Incline_DB_Bench_Press': ['靠在上斜凳上，双手各持一只哑铃放在大腿上，掌心相对。', '借助大腿把哑铃顶起，用翻举动作一次举起一只手臂，使哑铃到达肩宽位置。', '到肩宽位置后保持中立握（掌心相对），肘部外展，上臂与肩部对齐（与躯干垂直），屈肘使上臂与前臂成90度角，这是你的起始姿势。', '吸气，缓慢把重量下放到体侧，全程完全控制哑铃。', '呼气，用胸大肌把哑铃推起，在收缩位置锁定手臂，保持一秒，然后开始缓慢下放。提示：下放的时间至少应是上举的两倍。', '按规定的次数重复动作。', '完成后把哑铃放回大腿上，再放到地面，这是放下哑铃最安全的方式。'],
  'YHamstringSMR': ['坐姿，双腿伸过泡沫轴，让泡沫轴位于大腿后侧，双手放在体侧或身后支撑体重，这是你的起始姿势。', '用双手把髋部抬离地面，把体重转移到泡沫轴上的一条腿上，放松被拉伸腿的腘绳肌。', '在泡沫轴上从髋部下方向膝盖后上方滚动，在紧张点停顿10到30秒，另一条腿重复。'],
  'YHandstand_PushUps': ['背对墙，弯腰，双手与肩同宽撑地。', '手臂伸直，借力踢腿上墙，身体倒立，手臂和腿完全伸直，整个身体尽量保持笔直。提示：第一次做时让同伴保护，还要确保始终面朝墙壁，而不是低头看地。', '吸气，缓慢降低身体，直到头部几乎触地。提示：为了避免头部受伤，下放时必须缓慢，这一点至关重要。', '呼气，缓慢推起身体，直到肘部几乎锁定。', '重复完成建议的次数。'],
  'YHang_Clean': ['采用与肩同宽的双手正握或锁握，杠铃悬在大腿中段位置，背部挺直、微微前倾。', '用力伸髋、伸膝、伸踝，把重量向上带起，同时耸肩，让肩膀向耳朵方向耸起。', '立即通过脚跟蹬地发力恢复，保持躯干挺直、抬肘，继续直到完全站直。'],
  'YHang_Clean__Below_the_Knees': ['采用与肩同宽的双手正握或锁握，杠铃悬在膝盖正下方，背部挺直、微微前倾。', '用力伸髋、伸膝、伸踝，把重量向上带起，同时耸肩，让肩膀向耳朵方向耸起，完成完全伸展后，用力耸肩并屈臂、肘部向上向外，过渡到第三段发力。', '在伸展最高点用力把自己向下拉，同时肘部转到杠下，以前蹲姿势接住杠铃，下蹲深度取决于第三段发力结束时杠铃的高度，杠铃应架在向前送出的肩膀上，轻轻触喉、双手放松，继续下蹲到深蹲底部，这有助于站起。', '立即通过脚跟蹬地发力恢复，保持躯干挺直、抬肘，继续直到完全站直。'],
  'YHang_Snatch': ['采用宽握距的正握或锁握，双脚位于髋部正下方、脚尖外展，膝盖微屈，躯干前倾，脊柱完全伸展，目视前方，杠铃位于髋部，这是你的起始姿势。', '用力伸腿伸髋，在伸展最高点耸肩，让肘部向两侧屈曲。', '双脚移动到接铃位置的同时，把杠铃举过头顶，用力把自己拉到杠下，以尽可能低的姿态接住杠铃，双臂在头顶完全伸直。', '带着杠铃回到站姿，然后控制着把杠铃放回地面。'],
  'YHang_Snatch__Below_Knees': ['采用宽握距的正握或锁握，双脚位于髋部正下方、脚尖外展，膝盖微屈，躯干前倾，脊柱完全伸展，目视前方，杠铃位于膝盖正下方，这是你的起始姿势。', '用力伸腿伸髋，在伸展最高点耸肩，让肘部向两侧屈曲。', '双脚移动到接铃位置的同时，把杠铃举过头顶，用力把自己拉到杠下，以尽可能低的姿态接住杠铃，双臂在头顶完全伸直。', '带着杠铃回到站姿，然后控制着把杠铃放回地面。'],
  'YHanging_Bar_Good_Morning': ['先把杠铃放在与腹部大致同高的架子上，用链条或悬挂带把杠铃吊起来。', '弯腰钻到杠下，像做力量深蹲那样把杠铃架在肩后部，而不是架在斜方肌上，高度合适时前倾身体应接近与地面平行，背部收紧、肩胛骨夹拢、膝盖微屈，保持背部拱起、颈椎处于正确对齐位置。', '用臀大肌和腘绳肌伸髋开始动作，带着重量站起。', '缓慢把重量放回起始位置，由链条支撑重量。'],
  'YHeaving_Snatch_Balance': ['这个练习帮助你学习抓举，先把一个轻重量横放在肩后部，双脚略宽于髋、脚尖外展，与深蹲姿势相同。', '双膝轻微下蹲弹起，短暂卸掉杠铃的重量，把自己驱动到杠下，下蹲进入全蹲的同时把杠铃举过头顶。', '回到站姿。'],
  'YHeavy_Bag_Thrust': ['这个动作使用沙袋，在沙袋旁以直立站姿站好，双脚前后交错、间距较宽，手放在沙袋上大约胸部高度，这是你的起始姿势。', '扭转腰部，尽可能用力把沙袋向前推，动作要快，把沙袋从身体推离。', '沙袋摆回时，反向重复上述动作接住它。'],
  'YHigh_Cable_Curls': ['站在两个高位滑轮之间，双手各握一个把手，上臂抬到与地面平行，掌心朝向自己，这是你的起始姿势。', '把把手向自己弯举，直到靠近耳朵两侧，动作时务必收缩肱二头肌并呼气，上臂保持不动，只移动前臂，在收缩位置挤压肱二头肌并保持一秒。', '缓慢把手臂放回起始姿势。', '重复完成建议的次数。'],
  'YHip_Circles_prone': ['双手双膝撑地，保持良好姿态，把一条屈膝的腿抬离地面，这是你的起始姿势。', '保持屈膝，让股骨沿弧线旋转，试着用膝盖画一个大圈。', '缓慢完成若干次后，换另一侧重复。'],
  'YHip_Extension_with_Bands': ['把弹力带一端固定在立柱下部，另一端绑在脚踝上。', '面向弹力带的固定点，扶住立柱稳定身体。', '保持抬头挺胸，保持膝盖伸直，把受阻力的一条腿尽量向后踢。', '把腿放回起始姿势。'],
  'YHip_Flexion_with_Band': ['把弹力带一端固定在立柱下部，另一端绑在脚踝上。', '背对弹力带的固定点。', '保持抬头挺胸，把膝盖向上抬到90度并停顿。', '把腿放回起始姿势。'],
  'YHip_Lift_with_Band': ['选择一条合适的弹力带，把弹力带固定在身体两侧后躺在深蹲架中央，如果架子没有卡栓，可以用较重的哑铃或类似物体压住弹力带，确保它们不会移动。', '调整位置让弹力带正好位于髋部上方，屈膝，双脚平踩地面，双手可以放在地上或扶住弹力带保持位置。', '肩膀保持贴地，通过脚跟发力抬起髋部，尽可能高地顶压弹力带。', '在动作顶端停顿，然后回到起始姿势。'],
  'YHug_A_Ball': ['坐在地上。', '把瑜伽球夹在两腿之间，髋部向地面降低。', '双臂环抱住球来支撑身体，调整腿部使双脚平踩地面、膝盖位于脚踝正上方，牢牢抱住球，防止球滚走让你向后坐到地上。'],
  'YHug_Knees_To_Chest': ['仰卧，把双膝拉向胸部。', '双臂环抱在膝盖下方，而不是上方（环抱上方会给膝关节带来过大压力）。', '缓慢把膝盖拉向肩膀方向，这个动作同时拉伸臀部肌肉。'],
  'YHurdle_Hops': ['摆一排栏架或其他小障碍物，每个间隔几英尺。', '站在第一个栏架前，双脚与肩同宽，这是你的起始姿势。', '双脚同时起跳越过第一个栏架，起跳时双臂摆动。', '屈膝缓冲落地冲击，紧接着反弹起跳越过下一个栏架，继续跳跃直到越过所有栏架。'],
  'YHyperextensions_Back_Extensions': ['俯卧在罗马椅上，脚踝牢牢卡在脚垫下方。', '如果可能的话调整上垫，让大腿上部平贴宽垫，给腰腹屈曲留出足够空间。', '身体保持笔直，双臂交叉在胸前（个人偏好）或抱在脑后，这是你的起始姿势。提示：也可以在交叉的双臂下、身前抱一块杠铃片增加阻力。', '保持背部平直，从腰部缓慢向前屈曲到最大幅度，动作时吸气，继续前屈直到腘绳肌有良好的拉伸感、再继续就会弓背为止。提示：做这个动作时绝不要弓背，有些人幅度比其他人更大，关键是做到身体允许的最大幅度而不弓背。', '吸气，缓慢把躯干抬回起始位置。提示：不要过度后仰超过直线，任何时候都不要摆动躯干，以免伤到背部。', '重复完成建议的次数。'],
  'YHyperextensions_With_No_Hyperextension_Bench': ['让同伴按住你的双腿，自己滑到平凳边缘，让髋部悬出凳端。提示：上半身应完全垂下朝向地面，此时姿势与在罗马椅上相同，但由于平凳高度较低，动作幅度会更小。', '身体保持笔直，双臂交叉在胸前（个人偏好）或抱在脑后，这是你的起始姿势。提示：也可以在交叉的双臂下、身前抱一块杠铃片增加阻力。', '保持背部平直，从腰部缓慢向前屈曲到最大幅度，动作时吸气，继续前屈直到几乎触地或腘绳肌有良好的拉伸感（以先到者为准）。提示：做这个动作时绝不要弓背。', '呼气，缓慢把躯干抬回起始位置。提示：不要过度后仰超过直线，任何时候都不要摆动躯干，以免伤到背部。', '重复完成建议的次数。'],
  'YIT_Band_and_Glute_Stretch': ['用腰带、绳子或弹力带套住一只脚，躺在地上，保持腿伸直，把这条腿摆过身体到对侧，这是你的起始姿势。', '脚保持离地，拉动腰带，借拉力把脚趾向上勾，保持10到20秒，换另一侧重复。'],
  'YIliotibial_TractSMR': ['侧躺，下方腿放在髋部与膝盖之间的泡沫轴上，另一条腿可以交叉放在身前。', '把尽可能多的体重压到下方腿上（以可承受为度），下方腿不需要接触地面，务必放松被拉伸腿的肌肉。', '让腿在泡沫轴上从髋部滚向膝盖，在紧张点停顿10到30秒，换另一条腿重复。'],
  'YIncline_Barbell_Triceps_Extension': ['用略窄于肩的正握（掌心向下）握住杠铃。', '仰躺在上斜凳上，靠背角度设在45到75度之间。', '手臂伸直、肘部内收，把杠铃举过头顶，手臂应与头部上方的躯干对齐，这是你的起始姿势。', '以半圆轨迹把杠铃降到头后方，直到前臂触到肱二头肌，动作时吸气。提示：全程保持上臂静止、贴近头部，只有前臂移动。', '呼气并收缩肱三头肌回到起始姿势，保持收缩一秒。', '重复完成建议的次数。'],
  'YIncline_Bench_Pull': ['双手各持一只哑铃，俯卧在约30度角的上斜凳上。', '双臂完全伸直垂向地面。', '转动手腕，采用旋前握（掌心向下）。', '现在肘部向外展开，这是你的起始姿势。', '呼气，像做反向卧推一样把哑铃向上拉起，通过屈肘、上臂上抬、前臂自然下垂来完成，继续动作直到上臂与背部齐平。提示：肘部会向两侧打开，动作顶端上臂与躯干应呈字母"T"形，在顶端保持收缩一秒。', '吸气，缓慢回到起始姿势。', '重复完成建议的次数。'],
  'YIncline_Cable_Chest_Press': ['调整到合适的重量坐下，握住把手，上臂与身体约成45度角，抬头挺胸，肘部弯曲约90度，这是你的起始姿势。', '伸肘开始动作，把把手在身体正前方相互推拢，动作过程中保持肩胛骨后收。', '在完全伸展位置停顿后，回到起始姿势，保持绳索张力。'],
  'YIncline_Cable_Flye': ['进入起始姿势：把滑轮调到地面高度（器械上低于躯干的最低档位）。', '在两个滑轮之间放一张上斜凳（设为45度），两边各选好重量，双手各抓一个滑轮把手。', '双手各握一个把手，躺在上斜凳上，双臂在脸前伸直并拢，这是你的起始姿势。', '肘部微屈（以避免肱二头肌腱压力），双臂沿宽弧线向两侧下放，直到胸部有拉伸感，下放时吸气。提示：整个动作中手臂应保持伸直状态，动作只发生在肩关节。', '挤压胸部肌肉并呼气，把手臂收回到起始姿势，保持收缩位置一秒。提示：确保使用与下放时相同的弧线轨迹。', '按规定的次数重复动作。'],
  'YIncline_Dumbbell_Bench_With_Palms_Facing_In': ['靠在上斜凳上，双手各持一只哑铃放在大腿上，掌心相对。', '借助大腿把哑铃顶起，用翻举动作一次举起一只手臂，使哑铃到达肩宽位置。', '到肩宽位置后保持中立握（掌心相对），肘部外展，上臂与肩部对齐（与躯干垂直），屈肘使上臂与前臂成90度角，这是你的起始姿势。', '吸气，缓慢把重量下放到体侧，全程完全控制哑铃。', '呼气，用胸大肌把哑铃推起，在收缩位置锁定手臂，保持一秒，然后开始缓慢下放。提示：下放的时间至少应是上举的两倍。', '按规定的次数重复动作。', '完成后把哑铃放回大腿上，再放到地面，这是放下哑铃最安全的方式。'],
  'YIncline_Dumbbell_Flyes': ['双手各持一只哑铃，躺在角度不超过30度的上斜凳上。', '双臂在身体上方伸直，肘部微屈。', '转动手腕使掌心朝向自己，提示：小指应相互挨着，这是你的起始姿势。', '吸气，保持手臂伸直，缓慢把双臂向两侧下放，同时转动手腕直到掌心相对。提示：动作结束时双臂位于体侧，掌心朝向天花板。', '呼气，反向动作把哑铃举回起始姿势，同时转动手腕让小指再次相互挨着。提示：记住动作只发生在肩关节和手腕，肘关节没有任何动作。', '重复完成建议的次数。'],
  'YIncline_Dumbbell_Flyes__With_A_Twist': ['双手各持一只哑铃，躺在角度不超过30度的上斜凳上。', '双臂在身体上方伸直，肘部微屈。', '转动手腕使掌心朝向自己，提示：小指应相互挨着，这是你的起始姿势。', '吸气，保持手臂伸直，缓慢把双臂向两侧下放，同时转动手腕直到掌心相对。提示：动作结束时双臂位于体侧，掌心朝向天花板。', '呼气，反向动作把哑铃举回起始姿势，同时转动手腕让小指再次相互挨着。提示：记住动作只发生在肩关节和手腕，肘关节没有任何动作。', '重复完成建议的次数。'],
  'YIncline_Dumbbell_Press': ['靠在上斜凳上，双手各持一只哑铃放在大腿上，掌心相对。', '借助大腿把哑铃顶起，一次举起一只，使哑铃到达肩宽位置。', '哑铃举到肩宽位置后，向前转动手腕使掌心朝外，这是你的起始姿势。', '务必全程完全控制哑铃，然后呼气，用胸部把哑铃推起。', '在顶端锁定手臂，保持一秒，然后开始缓慢下放。提示：下放的时间最好约为上举的两倍。', '按规定的次数重复动作。', '完成后把哑铃放回大腿上，再放到地面，这是放下哑铃最安全的方式。'],
  'YIncline_Hammer_Curls': ['坐在上斜凳上，双手各持一只哑铃，背部贴紧靠背、双脚并拢，哑铃以中立握自然垂在体侧，这是你的起始姿势。', '屈肘开始动作，尽量保持上臂不动。', '继续做到动作顶端并停顿，然后缓慢回到起始位置。'],
  'YIncline_Inner_Biceps_Curl': ['双手各握一只哑铃，仰卧在上斜凳上。', '哑铃垂于身体两侧、手臂伸直，掌心朝外，此为起始姿势。', '呼气时，保持前臂与侧三角肌对齐，将重量向外向上弯举，直至哑铃到达肩部高度、位于三角肌两侧，动作末端应类似展示肱二头肌的造型。', '动作顶端收缩一秒钟后，吸气并沿原路径缓慢将重量放回起始姿势。', '按建议次数重复。'],
  'YIncline_PushUp_CloseGrip': ['面向适当高度的史密斯机杠或牢固的高台站立。', '双手并拢放在杠上。', '双脚后撤，手臂与身体保持笔直，此为起始姿势。', '保持身体笔直，屈臂将胸部下放至杠前。', '伸直肘部，将身体推回起始姿势。'],
  'YIncline_PushUp_Medium': ['面向适当高度的史密斯机杠或牢固的高台站立。', '双手与肩同宽放在杠上。', '双脚后撤，手臂与身体保持笔直，此为起始姿势。', '保持身体笔直，屈臂将胸部下放至杠前。', '伸直肘部，将身体推回起始姿势。'],
  'YIncline_PushUp_Reverse_Grip': ['面向适当高度的史密斯机杠或牢固的高台站立。', '双手掌心朝上、与肩同宽握住杠。', '双脚后撤，手臂与身体保持笔直，此为起始姿势。', '保持身体笔直，屈臂将胸部下放至杠前。', '伸直肘部，将身体推回起始姿势。'],
  'YIncline_PushUp_Wide': ['面向适当高度的史密斯机杠或牢固的高台站立。', '双手放在杠上，握距宽于肩。', '双脚后撤，手臂与身体保持笔直，双臂与身体垂直，此为起始姿势。', '保持身体笔直，屈臂将胸部下放至杠前。', '伸直肘部，将身体推回起始姿势。'],
  'YIntermediate_Groin_Stretch': ['仰卧并伸直双腿，用腰带、绳子或弹力带套住一只脚，将这条腿尽量向侧方摆动，此为起始姿势。', '轻拉腰带，让腹股沟和腘绳肌产生张力，保持10至20秒，换另一侧重复。'],
  'YInternal_Rotation_with_Band': ['将弹力带绕在柱子上，高度与肘部齐平，身体右侧朝向弹力带，站在距其一两英尺处。', '用右手抓住弹力带末端，肘部紧贴身体一侧，建议用肘部夹住一块垫子或泡沫轴，以固定肘部位置。', '上臂固定，肘部屈曲90度，手远离躯干，此为起始姿势。', '保持肘部不动，以正手（向内）方向转动手臂完成动作。', '转动到力所能及的最大幅度，稍作停顿，然后回到起始姿势。'],
  'YIron_Crosses_stretch': ['俯卧在地面上，双臂向两侧伸展，手掌压地，此为起始姿势。', '开始时，屈曲一侧膝盖，将该腿跨过身体后方，尝试让膝盖触地并靠近对侧手的位置。', '迅速将腿收回起始位置，换另一条腿快速重复，双腿交替进行10至20次。'],
  'YIsometric_Chest_Squeezes': ['坐姿或站姿均可，双臂屈曲90度，双手手掌在胸前合拢，手掌张开、手指朝前（与躯干垂直）。', '收缩胸肌的同时双手互推，从缓慢发力开始逐渐加大力度，过程中保持正常呼吸。', '保持建议的秒数。', '然后缓慢释放张力。', '休息建议的时间后重复。'],
  'YIsometric_Neck_Exercise__Front_And_Back': ['头部和颈部保持中立位（抬头目视前方的正常姿势），双手放在头部前侧。', '收缩颈部肌肉的同时轻轻向前推，但抵抗头部的任何移动，从缓慢发力逐渐加大力度，过程中保持正常呼吸。', '保持建议的秒数。', '然后缓慢释放张力。', '休息建议的时间后，将双手放在头部后侧重复。'],
  'YIsometric_Neck_Exercise__Sides': ['头部和颈部保持中立位（抬头目视前方的正常姿势），左手放在头部左侧。', '收缩左侧颈部肌肉的同时轻轻向左推，但抵抗头部的任何移动，从缓慢发力逐渐加大力度，过程中保持正常呼吸。', '保持建议的秒数。', '然后缓慢释放张力。', '休息建议的时间后，将右手放在头部右侧重复。'],
  'YJefferson_Squats': ['将杠铃放在地面上。', '沿杠铃长度方向站在杠铃中间。', '屈膝弯腰、保持背部挺直，用右手抓住杠铃前段，掌心朝内（中立握），面向左侧。', '用左手抓住杠铃后段，掌心保持中立握（掌心朝右），握距要均衡，躯干位于杠铃正中，躯干到右手（在前）的距离与躯干到左手（在后）的距离相等。', '然后负重站直，双脚与肩同宽，脚尖微微向外。', '屈膝下蹲并保持背部挺直，直到大腿上部与地面平行，背部尽量垂直于地面、抬头，注意膝盖不要超过脚尖，下蹲过程中吸气。', '用脚蹬地发力回到起始姿势，保持杠铃手臂悬垂，肘部微屈锁定，手臂只起钩子作用，不要用手臂发力，用大腿发力完成起立。'],
  'YJerk_Balance': ['此练习帮助你学会在挺举时下潜到足够低的位置，并纠正动作中身体后移的问题，起始时杠铃架在挺举位，肩膀前送、躯干直立、双脚略微前后分开。', '像正常挺举那样启动动作：保持躯干垂直、屈膝下潜，然后用力向上蹬起，借助惯性而不是手臂将重量举高。', '后脚保持不动，借其发力将身体推入完整的分腿位完成挺举，然后站起、将重量举过头顶完成还原。'],
  'YJerk_Dip_Squat': ['此动作强化挺举的下潜环节，起始时杠铃架在挺举位，肩膀前送形成支撑架、杠铃轻触喉部，双脚位于髋部正下方，脚尖按舒适度外展。', '保持躯干垂直，屈膝下潜，让膝盖前移而髋部不后移，下潜幅度不宜过大，然后用力蹬地回到起始姿势。'],
  'YJogging_Treadmill': ['开始时踏上跑步机，在菜单中选择所需模式，多数跑步机有手动模式，也可选择预设程序，通常可以输入年龄和体重来估算运动消耗的热量，调整坡度可改变训练强度。', '跑步机方便、有助于心肺训练，且通常比户外慢跑冲击更小，一名150磅的人慢跑30分钟约消耗250千卡，而跑步消耗超过450千卡，慢跑时保持正确姿势，只在必要时（如下机或测心率时）扶扶手。'],
  'YKeg_Load': ['装载酒桶时，将需要数量的酒桶放在距装载台一定距离处，通常为30至50英尺。', '先抓住第一个酒桶近侧的手柄，将其倾倒侧放以抓住桶底对侧边缘，把酒桶提至胸前。', '酒桶放得越高，移动上台就越快，通常不允许扛上肩，务必牢牢抱住酒桶，以最快速度移动到装载台，髋、膝、踝同时伸展发力将其举到尽可能高的位置完成装载。', '回到起点取下一个酒桶，重复直到完成全部搬运。'],
  'YKettlebell_Dead_Clean': ['将壶铃放在两脚之间，臀部后推、目视前方，进入起始姿势。', '通过伸腿伸髋将壶铃提至肩部完成翻举，过程中手腕顺势旋转。', '放下壶铃，保持背部挺直、臀部后坐，让腘绳肌持续受力。'],
  'YKettlebell_OneLegged_Deadlift': ['单手握住壶铃把手，单腿站立，站立腿与持壶铃侧相同。', '保持该膝微屈，以髋为轴做直腿硬拉，另一条腿向后伸展保持平衡。', '继续下放壶铃直到身体与地面平行，然后回到直立姿势。'],
  'YKettlebell_Pass_Between_The_Legs': ['将一个壶铃放在两腿之间，采取舒适的站姿，臀部后推、背部保持平直俯身。', '拿起壶铃，在双腿之间以画"W"的轨迹传递给另一只手，来回传递数次。'],
  'YKettlebell_Pirate_Ships': ['双脚宽站位，双手握住壶铃，手臂伸直让壶铃垂于腰际，此为起始姿势。', '向一侧转体启动动作，将壶铃摆荡至头部高度，在动作顶端短暂停顿。', '向另一侧转体的同时让壶铃下落，再次将壶铃举至头部高度。', '按所需次数重复。'],
  'YKettlebell_Turkish_GetUp_Lunge_style': ['仰卧地面，伸直肘部将壶铃推举至顶端锁定，弯曲持壶铃一侧的膝盖。', '始终保持壶铃锁定，向对侧转体，用非持壶铃的手臂辅助撑地驱动身体进入箭步蹲位，用空出的手将自己推至坐姿，再进阶到单膝跪姿。', '眼睛始终注视着壶铃缓慢站起，然后按原路径反向回到起始姿势并重复。'],
  'YKnee_Across_The_Body': ['仰卧地面，右腿伸直，弯曲左腿并将其跨过身体下放，用右手将膝盖压向地面（如果柔韧性不足，膝盖不必触地）。', '左臂舒适地放在身旁，头转向左侧，想象尾骨上绑着重物，让尾骨向地面沉落、胸部向相反方向延伸以拉伸下背部，然后换边。'],
  'YKnee_Circles': ['双腿并拢站立，双手放在腰侧。', '保持正常呼吸，双膝做画圈运动。', '按建议次数重复。'],
  'YKnee_Hip_Raise_On_Parallel_Bars': ['在垂直举腿架上调整身体位置，前臂放在躯干两侧的垫板上并握住把手，手臂弯曲90度。', '躯干保持笔直，下背部贴紧器械垫板，双腿伸直指向地面，此为起始姿势。', '呼气时保持双腿伸直向上抬起，直到双腿大致与地面平行，顶端收缩保持一秒，过程中不要借助惯性或摆动。', '吸气时缓慢回到起始姿势。', '按建议次数重复。'],
  'YKnee_Tuck_Jump': ['以舒适的站姿开始，膝盖微屈，双手放在身前、掌心朝下、指尖并拢置于胸前高度，此为起始姿势。', '快速下蹲至四分之一蹲后立即爆发向上跳起，收膝向胸口方向提，尝试让膝盖触碰手掌。', '尽最大高度起跳并向上提膝，然后重新伸直双腿、屈膝缓冲落地，确保落地平稳。'],
  'YKneeling_Arm_Drill': ['此练习帮助提高跑步时的手臂效率，开始时跪姿，左脚在前、右膝着地，通过前脚脚跟施压，保持臀大肌和腘绳肌激活。', '先以大幅、钟摆式的摆动来制动手臂，然后收紧手臂角度，像慢跑时那样摆臂，逐步过渡到跑步、最后到冲刺。', '冲刺时，手一过髋部就立即加速向前摆，让手臂移动尽可能快。', '交换膝盖位置后重复。'],
  'YKneeling_Cable_Crunch_With_Alternating_Oblique_Twists': ['将绳索把手装在高位滑轮绳索上，并在其前方地面铺好垫子。', '双手握住绳索，在距滑轮立柱约两英尺处跪姿。', '将绳索置于头后，双手放在耳朵两侧。', '双手位置不动，收缩腹部，以卷腹动作向下拉绳索，直到肘部触到膝盖。', '底部短暂停顿，然后缓慢、有控制地回到起始姿势。', '重复同样的下压动作，下压到一半时开始将一侧肘部转向对侧膝盖。', '底部再次短暂停顿，然后缓慢、有控制地回到起始姿势。', '重复之前的动作，但换另一侧肘部转向对侧膝盖。', '持续进行这组动作直到力竭。'],
  'YKneeling_Cable_Triceps_Extension': ['在高位滑轮器械前横放一张长凳。', '双手掌心朝下、相距约6英寸握住直杆把手，位于头顶上方。', '背对器械跪姿。', '将头部和上臂后侧放在凳上，肘部弯曲、前臂指向高位滑轮，此为起始姿势。', '始终保持上臂贴近头部、肘部内收，以半圆弧轨迹向外推杠，直到肘部伸直锁死、手臂与地面平行，用力收缩肱三头肌并保持一秒，动作过程中呼气。', '吸气时缓慢回到起始姿势。', '按建议次数重复。'],
  'YKneeling_Forearm_Stretch': ['先跪在垫子上，手掌平放，手指指向膝盖方向。', '手掌保持贴地，身体缓慢后仰，直到手腕和前臂感到拉伸，保持20至30秒。'],
  'YKneeling_High_Pulley_Row': ['在头顶上方的滑轮上选择合适的重量，将绳索装到钢缆上，在几英尺外跪姿，双臂伸直将绳索保持在身体前方，此为起始姿势。', '屈肘并完全后收肩胛启动动作，肘部向外打开，将绳索拉向上胸部。', '短暂停顿后，缓慢回到起始姿势。'],
  'YKneeling_Hip_Flexor': ['跪在垫子上，右膝抬起、右脚掌踩地，左腿向后伸直、脚背贴地。', '重心前移直到髋部感到拉伸，保持15秒，然后换另一侧重复。'],
  'YKneeling_SingleArm_High_Pulley_Row': ['在高位滑轮上安装单把手并选择合适的重量。', '跪在绳索立柱前，单手伸直握住绳索，此为起始姿势。', '起始时掌心朝前，屈肘将重量拉向躯干并后收肩胛骨，同时旋转手腕，动作完成时掌心朝向自己。', '短暂停顿后回到起始姿势。'],
  'YKneeling_Squat': ['在深蹲架中将杠铃调到合适高度，跪在杠铃后方（可在膝下垫垫子），滑到杠下，将杠铃横架在肩后，收紧肩胛、杠铃贴紧背部，然后出杠。', '目视前方，臀部向后坐，直到臀部触碰到小腿。', '反向动作，将躯干恢复到直立位置。'],
  'YLandmine_180s': ['将杠铃插入地雷管装置，或稳固地固定在墙角，加载合适的重量。', '将杠铃从地面抬起，双臂在身前伸直、双手将其举到肩部高度，双脚宽站位，此为起始姿势。', '旋转躯干和髋部，将杠铃摆向一侧放至最低点，整个动作过程中保持手臂伸直。', '反向动作，将杠铃摆向另一侧最低点。', '继续交替摆动，直到完成整组。'],
  'YLandmine_Linear_Jammer': ['将杠铃插入地雷管装置，如果没有就稳固固定在墙角，加载合适重量并将把手附件装在杠上。', '将杠铃从地面抬起，双手握住把手至肩部高度，此为起始姿势。', '采取运动站姿，屈髋、髋部后坐下蹲，保持手臂弯曲。', '反向动作：髋、膝、踝强有力伸展，同时伸肘伸直手臂，以爆发式完成，从深蹲中尽可能有力地蹬起至完全伸展。', '回到起始姿势。'],
  'YLateral_Bound': ['与移动方向呈90度站立，取半蹲姿势，此为起始姿势。', '前导腿向内做预摆动作，同时将重心移到外侧腿上。', '立即蹬地发力伸展，尽可能向侧面跳出最远距离。', '落地后立即向相反方向蹬出，回到起始位置。', '来回连续跳数次。'],
  'YLateral_Box_Jump': ['以舒适的站姿站立，旁边放一个矮跳箱，此为起始姿势。', '快速下蹲至四分之一蹲以启动牵张反射，立即反向发力向侧上方起跳。', '膝盖抬高，确保双脚充分越过跳箱。', '落在跳箱中央，用双腿缓冲冲击。', '小心地跳到跳箱另一侧，来回连续跳数次。'],
  'YLateral_Cone_Hops': ['将若干标志桶排成一列，彼此相隔数英尺。', '站在标志桶一端旁边，身体与行进方向呈90度，此为起始姿势。', '起跳前屈膝下蹲启动牵张反射，立即反向蹬地，向侧上方跳过标志桶。', '落地时用双腿缓冲，并顺势反弹进入下一次跳跃，沿标志桶队列连续跳完。'],
  'YLateral_Raise__With_Bands': ['开始时双脚踩住弹力带，使张力从手臂伸直时就开始产生，用掌心朝向大腿的正握握法、略窄于肩宽抓住把手，把手贴在大腿两侧，手臂伸直、肘部微屈，背部挺直，此为起始姿势。', '呼气时用肩部侧束将把手向两侧抬起，直到略高于水平位置，抬举时手腕微微倾斜像在倒水，保持手臂伸直、躯干稳定，顶端停顿一秒。', '缓慢将把手放回起始姿势，下放过程中吸气。', '按建议次数重复。'],
  'YLatissimus_DorsiSMR': ['仰卧地面，将泡沫轴放在背部一侧、腋窝后方的位置，此为起始姿势。', '被拉伸一侧的手臂保持在身体后侧，将重心移到背阔肌上，上体离开地面，保持10至30秒，换边。'],
  'YLegOver_Floor_Press': ['仰卧地面，单手握住壶铃把手将其放在胸前，将发力侧腿交叉搭在非发力侧腿上，空出的手臂可向侧方伸展支撑。', '将壶铃推举至手臂锁定的顶端位置。', '下放重量直到肘部触地，保持壶铃位于肘部上方，按所需次数重复。'],
  'YLeg_Extensions': ['此动作需要使用腿屈伸机，先选择重量坐在器械上，双腿放在垫板下（脚尖朝前）、双手握住两侧把手，此为起始姿势，需调整垫板使其落在小腿上（脚踝上方），并确保大小腿之间呈90度角，若角度小于90度说明膝盖超过脚尖、会给膝关节带来过大压力，如果器械如此设计，要么换一台器械，要么开始做动作时下放到90度角就停止。', '呼气时用股四头肌的力量将腿伸直至最大限度，身体其余部分保持稳定坐在座椅上，收缩位停顿一秒。', '吸气时缓慢将重量放回原位，注意不要超过90度角限制。', '按建议次数重复。'],
  'YLeg_Lift': ['双脚并拢约与肩同宽直立站好，抓住稳固的支撑物（如深蹲架两侧或椅背顶端）以保持平衡。', '可选择是否佩戴脚踝负重，一条腿保持伸直，另一条腿向后抬起，像做站立式腿弯举一样，动作过程中呼气。', '吸气时缓慢将抬起的腿放回地面。', '按建议次数重复。', '换另一条腿重复该动作。'],
  'YLeg_PullIn': ['仰卧在瑜伽垫上，双腿伸直，双手可掌心朝下放在身体两侧或垫在臀部下（更推荐放在身体两侧），此为起始姿势。', '呼气时屈膝，将大腿拉向腹部，直到膝盖接近胸部高度，过程中收缩腹部并在顶端保持一秒，动作全程小腿应始终与地面保持平行。', '吸气时回到起始姿势。', '按建议次数重复。'],
  'YLeverage_Chest_Press': ['在插销上加载合适重量并按身高调整座椅，动作开始时把手应位于胸大肌下部或中部附近。', '挺胸抬头、收紧肩胛骨，此为起始姿势。', '伸肘发力将把手向前推出。', '顶端短暂停顿后，将重量放回略高于起始的位置，整组完成前不把重量放回限位器，以保持肌肉张力。'],
  'YLeverage_Deadlift': ['在插销上加载合适重量，站在两个把手正中间，以舒适握距抓住下方把手，吸气时下沉髋部，目视前方、挺胸，此为起始姿势。', '将重量还原到起始姿势。'],
  'YLeverage_Decline_Chest_Press': ['在插销上加载合适重量并按身高调整座椅，动作开始时把手应位于胸大肌下部附近，挺胸抬头、收紧肩胛骨，此为起始姿势。', '伸肘发力将把手向前推出。', '顶端短暂停顿后，将重量放回略高于起始的位置，整组完成前不把重量放回限位器，以保持肌肉张力。'],
  'YLeverage_High_Row': ['在插销上加载合适重量并调整座椅高度，使你能刚好够到上方把手，调整膝垫帮助固定身体，正握抓住把手，此为起始姿势。', '屈肘将把手拉向躯干，同时后收肩胛骨。', '在动作底部停顿，然后缓慢将把手放回起始位置。', '多次重复时，避免将重量完全放回限位器，以保持目标肌肉的张力。'],
  'YLeverage_Incline_Chest_Press': ['在插销上加载合适重量并按身高调整座椅，动作开始时把手应位于胸大肌上部附近，挺胸抬头、收紧肩胛骨，此为起始姿势。', '伸肘发力将把手向前推出。', '顶端短暂停顿后，将重量放回略高于起始的位置，整组完成前不把重量放回限位器，以保持肌肉张力。'],
  'YLeverage_Iso_Row': ['在插销上加载合适重量并调整座椅高度，使把手位于胸部高度，可用中立握或正握抓住把手，此为起始姿势。', '屈肘将把手拉向躯干，同时后收肩胛骨。', '在动作底部停顿，然后缓慢将把手放回起始位置，多次重复时避免将重量完全放回限位器，以保持目标肌肉的张力。'],
  'YLeverage_Shoulder_Press': ['在插销上加载合适重量并按身高调整座椅，动作开始时把手应位于肩部上方附近，挺胸抬头、正握抓住把手，此为起始姿势。', '伸肘发力将把手向上推出。', '顶端短暂停顿后，将重量放回略高于起始的位置，整组完成前不把重量放回限位器，以保持肌肉张力。'],
  'YLeverage_Shrug': ['在插销上加载合适重量，站在两个把手正中间。', '以舒适握距抓住上方把手，吸气时下沉髋部，目视前方、挺胸。', '脚后跟蹬地，伸髋伸膝起身站直，整个动作中保持手臂伸直，结束时肩膀后展，此为起始姿势。', '耸肩将肩膀向耳朵方向抬起，做笔直的上下移动。', '动作顶端停顿，然后将重量放回起始位置。'],
  'YLinear_3Part_Start_Technique': ['此练习帮助你在静止状态下尽可能快地加速进入冲刺，建议借助一条线作为起点，开始时双脚踩线，左脚脚尖放在右脚踝旁边，右脚放在左脚后方4至6英寸处。', '右手放在线上，然后把鼻子靠近左膝。', '身体前倾下蹲，头部低于髋部，重心压在左腿上，此为起始姿势。', '将左手抬起与地面平行、指向身后，准备好后爆发冲出。'],
  'YLinear_Acceleration_Wall_Drill': ['身体约45度角前倾靠墙，双脚并拢，收紧臀部。', '开始时快速抬起右膝，稍作停顿，然后直直地向下蹬踏地面。', '换腿，抬起另一侧膝盖，然后垂直向下发力蹬地。', '右腿再做一次，右脚一触地就立即快速交替左右腿蹬踏，尽可能快地连续进行。'],
  'YLinear_Depth_Jump': ['需要两个相距数英尺的跳箱或长凳，先站在其中一个跳箱上，面向另一个跳台。', '启动动作时轻轻落到两个跳台之间的地面，顺势屈膝屈髋。', '立即反向爆发，髋、膝、踝同时伸展，跳到另一个跳台上。', '轻柔落地，用双腿缓冲冲击。'],
  'YLog_Lift': ['开始时站在圆木前，抓住把手开始翻举，俯身启动翻举时尽量将圆木拉高至胸前，通过伸髋伸膝将其提至胸口完成翻举。', '头向后靠并向上看，在胸前形成支撑架托住圆木，屈膝微蹲借力后立即反向发力开始推举，借助这股惯性让圆木向上移动，接着伸肘将圆木推举过头顶，动作形式没有严格规定，用你最有效率的技术即可，每次推举时都要向前探出头部、目视前方。', '尽可能多地重复，放回地面时尽量控制圆木下落的节奏。'],
  'YLondon_Bridges': ['将攀爬绳固定在高横梁或横杆上，确保下方史密斯机杠铃被安全锁锁定无法移动，也可以改用稳固的跳箱。', '站在杠上，用绳索保持平衡，此为起始姿势。', '保持身体笔直，身体后仰，双手交替缓慢换握绳索向下放低身体，直到身体与地面垂直。', '保持身体笔直，反向动作，双手交替换握回到起始姿势。'],
  'YLooking_At_Ceiling': ['跪在地面上，双手握住脚跟。', '臀部向上向前抬起，同时头部后仰看向天花板，使背部形成反弓。'],
  'YLow_Cable_Crossover': ['进入起始姿势前，将滑轮调到低位，选择合适的阻力，双手各握一个把手。', '向前迈步让滑轮产生张力，掌心朝前、双手位于腰部下方、手臂伸直，此为起始姿势。', '手臂微屈，将双手向上并向身体中线方向拉起，双手在胸前合拢，掌心朝上。', '短暂停顿后，将手臂放回起始位置。'],
  'YLow_Cable_Triceps_Extension': ['选择合适的重量，仰卧在装有绳索附件的坐姿划船机凳上，头部朝向绳索附件。', '抓住绳索两端外侧，掌心相对（中立握）。', '肘部弯曲90度，上臂与躯干垂直（90度角），保持肘部内收，上臂指向天花板、前臂指向头顶上方的滑轮，此为起始姿势。', '呼气时将前臂伸直至垂直位置，整个动作中上臂和肘部保持不动，只有前臂移动，用力收缩肱三头肌一秒。', '吸气时缓慢回到起始姿势。', '按建议次数重复。'],
  'YLow_Pulley_Row_To_Neck': ['坐在装有绳索附件的低位滑轮划船机上。', '掌心朝下抓住绳索两端，背部挺直、膝盖微屈坐好，背部尽量保持垂直、手臂在身前完全伸直，此为起始姿势。', '保持躯干不动，呼气时抬起肘部并开始屈肘，将绳索拉向颈部，整个动作中上臂保持与地面平行，直到双手几乎贴近耳朵（动作结束时前臂会略微向上倾斜、不再与地面平行）、肘部向两侧打开远离身体。', '在收缩位保持约一秒钟后，吸气时缓慢回到起始姿势，整个动作过程中躯干任何时刻都不要移动。', '按建议次数重复。'],
  'YLower_BackSMR': ['坐姿，将泡沫轴放在下背部下方，双臂交叉抱在胸前、肩膀前伸，此为起始姿势。', '髋部抬离地面并向后靠，让重心落在下背部，然后略微将重心移向一侧，避开脊柱、将压力放在脊柱两侧的肌肉上，在下背部来回滚动，在紧张点上保持10至30秒，换另一侧重复。'],
  'YLunge_Pass_Through': ['躯干直立站立，右手持一只壶铃，此为起始姿势。', '左脚向前迈步，屈髋屈膝下蹲、保持躯干直立，后膝下放至几乎触地。', '下蹲过程中，将壶铃从前腿下方传递给另一只手。', '用脚跟蹬地发力，回到起始姿势。', '按建议次数重复该动作，双腿交替进行。'],
  'YLunge_Sprint': ['将史密斯机杠铃调到合适高度，站在杠下将杠横架于肩后，出杠后双脚前后分开站立，一前一后，此为起始姿势。', '屈膝下蹲、下沉髋部，后膝下放至接近地面。', '下蹲到底端时立即反向发力，前脚脚跟爆发蹬地、后脚轻微施压，向上跳起并交换双腿前后位置。', '按建议次数重复。'],
  'YLying_Bent_Leg_Groin': ['仰卧，屈膝、双脚脚掌相对，让同伴按住你的双膝，此为起始姿势。', '尝试将双膝向内夹拢，同伴则阻止膝盖发生任何移动。', '10至20秒后放松肌肉，让同伴轻柔地将你的膝盖压向地面，拉伸到位时要及时告知同伴，以防受伤或过度拉伸。'],
  'YLying_Cable_Curl': ['双手以反握（掌心朝上）、与肩同宽的握距抓住连接低位滑轮的直杆或曲杆附件。', '仰卧在配重片前方的瑜伽垫上，双脚平踩在滑轮器械框架上，双腿伸直。', '手臂伸直、肘部贴近身体并微微弯曲手臂，此为起始姿势。', '保持上臂不动、肘部贴近身体，呼气时缓慢将杠弯举向胸部并收缩肱二头肌。', '动作顶端再收缩一秒后，缓慢回到起始姿势。', '按建议次数重复。'],
  'YLying_Cambered_Barbell_Row': ['将弧形杠铃放在训练凳下方。', '俯卧在训练凳上，用宽于肩距的正握（掌心朝下）抓住杠铃，此为起始姿势。', '呼气时肘部贴近身体将杠铃划向上方，拉到胸部以针对上中背部训练，或拉到腹部以针对背阔肌。', '顶端保持一秒后，吸气时缓慢将杠铃放回起始姿势。'],
  'YLying_CloseGrip_Bar_Curl_On_High_Pulley': ['在高位滑轮或高位下拉器械前放置一张平凳。', '以约与肩同宽的反握（掌心朝上）握住直杆附件。', '仰卧，头部位于长凳末端之外。', '双臂在肩部正上方伸直，躯干与手臂呈90度角，肘部内收，此为起始姿势。', '呼气时以半圆弧轨迹将杠向下弯举至触碰下巴，顶端收缩位挤压肱二头肌一秒，动作中只有前臂移动，上臂全程保持垂直不动。', '缓慢回到起始姿势。', '按建议次数重复。'],
  'YLying_CloseGrip_Barbell_Triceps_Extension_Behind_The_Head': ['正握（掌心朝前）握住杠铃或曲杆，仰卧平凳、头部靠近长凳末端，若用直杠采取与肩同宽握距，若用曲杆则握住内侧把手。', '双臂向前伸直，保持手臂伸直，以半圆弧轨迹将杠缓慢移回头顶上方，此时手臂过头且与地面平行，此为起始姿势，全程保持肘部内收。', '吸气时屈肘下放杠铃、上臂保持不动，一直下放到前臂与地面垂直。', '呼气时以半圆弧轨迹将杠推回起始姿势，直到前臂也与地面平行，动作顶端用力收缩肱三头肌一秒，同样只有前臂移动，上臂全程保持不动。', '按建议次数重复。'],
  'YLying_CloseGrip_Barbell_Triceps_Press_To_Chin': ['正握（掌心朝前）握住杠铃或曲杆，仰卧平凳、头部悬出长凳末端，若用直杠采取与肩同宽握距，若用曲杆则握住内侧把手。', '双臂在胸前上方伸直握住杠铃，手臂与躯干垂直（90度角），此为起始姿势。', '吸气时屈肘、保持上臂不动且肘部内收，以半圆弧轨迹下放杠铃，直到杠铃轻轻触碰到下巴。', '呼气时以半圆弧轨迹将杠推回起始姿势，动作顶端用力收缩肱三头肌一秒，同样只有前臂移动，上臂全程保持不动。', '按建议次数重复。'],
  'YLying_Crossover': ['仰卧，双腿伸直。', '屈膝将一条腿跨过身体，尝试让膝盖触地，同伴跪在你身旁，一只手按住你的肩膀、另一只手控制跨过来的腿，此为起始姿势。', '尝试将弯曲的膝盖抬离地面，同伴则阻止其发生实际移动。', '10至20秒后放松腿部，让同伴轻柔地将膝盖压向地面，换另一侧重复。'],
  'YLying_Dumbbell_Tricep_Extension': ['仰卧平凳，双手持哑铃举于胸前正上方，双臂完全伸直、与躯干和地面呈90度角，掌心相对、肘部内收，此为起始姿势。', '吸气时保持上臂不动、肘部内收，缓慢下放重量直到哑铃靠近耳朵。', '然后保持肘部内收、上臂不动，呼气时用肱三头肌将重量推回起始姿势。', '按建议次数重复。'],
  'YLying_Face_Down_Plate_Neck_Resistance': ['俯卧平凳、全身伸直，双手将杠铃片放在头后，需要调整位置让肩膀略高于凳端，使上胸、颈部和面部悬出凳外，此为起始姿势。', '保持杠铃片稳固贴在后脑，吸气时缓慢低头（像做点头动作）。', '呼气时以半圆弧轨迹将头抬起回到起始姿势，保持收缩一秒。', '按建议次数重复。'],
  'YLying_Face_Up_Plate_Neck_Resistance': ['仰卧平凳、全身伸直，双手将杠铃片放在前额上方，需要调整位置让肩膀略高于凳端，使斜方肌、颈部和头部悬出凳外，此为起始姿势。', '保持杠铃片稳固贴在前额，吸气时以半圆弧轨迹缓慢将头向后放低。', '呼气时以半圆弧轨迹将头抬起回到起始姿势，保持收缩一秒。', '按建议次数重复。'],
  'YLying_Glute': ['仰卧，同伴跪在你身旁。', '屈曲一侧髋部将腿抬离地面，旋转该腿让脚搭在对侧髋部上方、小腿与身体垂直，同伴固定住膝盖和脚踝，此为起始姿势。', '尝试将腿推向同伴，同伴则阻止腿发生实际移动。', '10至20秒后完全放松，让同伴轻柔地将脚踝和膝盖推向你的胸部，拉伸到位时要及时告知同伴，以防受伤或过度拉伸。'],
  'YLying_Hamstring': ['仰卧、双腿伸直，同伴跪在你身旁，将一条腿抬起指向天花板，让同伴抓住脚踝，必要时同伴可用肩膀抵住你的腿，此为起始姿势。', '同伴固定住你的腿，尝试屈膝，收缩腘绳肌10至20秒。', '然后放松腿部，让同伴轻柔地将腿推向你的头部方向，拉伸到位时要及时告知同伴，以防受伤或过度拉伸，完成后换边。'],
  'YLying_High_Bench_Barbell_Curl': ['俯卧在高平凳上，反握（掌心朝上）握住杠铃，若用直杠采取与肩同宽握距，若用曲杆则握住内侧把手，上半身调整到上胸部位于凳端上方，杠铃垂于身前、手臂伸直且与地面垂直，此为起始姿势。', '保持肘部内收、上臂不动，呼气时收缩肱二头肌，以半圆弧轨迹将重量弯举向上，顶端保持一秒。', '吸气时缓慢回到起始姿势，全程完全控制重量、避免摆动，记住整个动作中只有前臂移动。', '按建议次数重复。'],
  'YLying_Leg_Curls': ['按身高调整器械杠杆，俯卧在腿弯举机上，将杠杆垫板放在腿后侧（小腿下方几英寸处），建议优先使用有角度的腿弯举机而非平式，因为倾斜角度更有利于募集腘绳肌。', '躯干保持平贴凳面，确认双腿完全伸直，抓住器械两侧把手，脚尖朝前（也可采用脚部定位部分介绍的另外两种姿势），此为起始姿势。', '呼气时将双腿尽量向上弯举，注意大腿不要离开垫板，到达完全收缩位后保持一秒。', '吸气时将双腿放回起始位置，按建议次数重复。'],
  'YLying_Machine_Squat': ['调整腿举机高度，使你屈膝进入器械内时大腿略低于平行位置。', '选定重量后，仰卧进入器械内，屈膝、大腿略低于与踏板平行的位置，确保膝盖不超过脚尖，腘绳肌与小腿之间的角度应略小于90度（因为起始位置要求略低于平行），背部和头部靠在器械上，肩膀抵在肩垫下方。', '双手握住把手，双脚与肩同宽、脚尖微微向外，此为起始姿势。', '呼气时用前脚掌蹬踏发力，收缩股四头肌将全身蹬直，收缩位保持一秒，由于从低于平行的位置开始，第一次重复时可以选择用手辅助按压大腿帮助蹬起。', '吸气时缓慢下蹲，但不要完全回到起始位置，大腿与踏板平行时就停止，此时腘绳肌与小腿之间呈90度角。', '按建议次数重复。'],
  'YLying_OneArm_Lateral_Raise': ['单手持哑铃，俯卧在平凳上，另一只手可抓住凳腿保持稳定。', '持哑铃的手掌心保持中立（掌心朝内朝向躯干），手臂伸直、肘部微屈，此为起始姿势。', '呼气时将持哑铃的手臂向侧方抬起，直到肘部与肩同高、手臂大致与地面平行，整个动作中手臂与躯干垂直并保持伸直，顶端收缩保持一秒。', '吸气时缓慢将哑铃放回起始姿势。', '按建议次数重复。'],
  'YLying_Prone_Quadriceps': ['俯卧地面，同伴跪在你身旁，屈曲一侧膝盖将腿抬离地面，尝试用脚跟触碰臀部，同伴固定住膝盖和脚踝，此为起始姿势。', '尝试伸直膝盖，同伴则阻止其发生实际移动。', '10至20秒后放松肌肉，让同伴轻柔地将脚推向臀部，进一步拉伸股四头肌和髋屈肌。', '10至20秒后换边。'],
  'YLying_Rear_Delt_Raise': ['双手各持一只哑铃，俯卧在平凳上。', '双手掌心保持中立（掌心朝内朝向躯干），手臂伸直、肘部微屈，此为起始姿势。', '呼气时将双臂向两侧抬起，直到肘部与肩同高、手臂大致与地面平行，整个动作中手臂与躯干垂直并保持伸直，顶端收缩保持一秒。', '吸气时缓慢将哑铃放回起始姿势。', '按建议次数重复，然后换另一侧手臂。'],
  'YLying_Supine_Dumbbell_Curl': ['仰卧平凳，双手各持一只哑铃放在大腿上方。', '手臂伸直将哑铃移到身体两侧，掌心朝向大腿（中立握）。', '保持手臂贴近躯干、肘部内收，手臂伸直略带微屈，缓慢向下放低至尽可能接近地面，放到最低点后将上臂锁定在该位置，此为起始姿势。', '呼气时开始缓慢弯举，同时旋转手腕使掌心朝上，继续弯举直到肱二头肌完全收缩，顶端用力挤压一秒，只有前臂移动，上臂保持不动、肘部全程内收。', '非常缓慢地回到起始姿势。'],
  'YLying_TBar_Row': ['为T杠划船机加载所需重量并调整腿部高度，使上胸部位于垫板顶端，某些器械只能通过站上合适的台阶来达到上胸部与垫板顶端齐平的高度。', '俯卧在垫板上抓住把手，可根据想要重点刺激的背部部位选择掌心朝下、掌心朝上或掌心相对的握法。', '将杠铃从支架上抬起，双臂在身前伸直，此为起始姿势。', '呼气时缓慢将重量拉起，动作顶端挤压背部肌肉，全程尽量让上臂贴近躯干以更好地募集背部肌肉，任何时候都不要让身体离开垫板，也不要借助肱二头肌发力提起重量。', '动作顶端收缩一秒后，吸气时缓慢回到起始姿势。', '按建议次数重复。'],
  'YLying_Triceps_Press': ['仰卧平凳，在头后地面放置曲杆（更推荐）或直杆，双脚踩地。', '用中距正握抓住身后（头后）的杠铃，将杠举到身前、手臂伸直，手臂与躯干及地面垂直，肘部内收，此为起始姿势。', '吸气时保持上臂和肘部不动，缓慢下放重量直到杠铃轻轻触碰额头。', '然后呼气时用肱三头肌将重量推回起始姿势。', '按建议次数重复。'],
  'YMachine_Bench_Press': ['坐在胸部推举机上并选择重量。', '踩下器械自带的踏板，它会把把手送向前方，方便你抓住把手并完全伸直手臂。', '掌心朝下抓住把手，抬起肘部使上臂与地面平行、位于躯干两侧，由于抓着把手，前臂会指向前方，把手前送、手臂伸直后即为起始姿势。', '吸气时将把手拉向自己。', '呼气时收缩胸肌将把手向外推出，收缩保持一秒后回到起始姿势。', '按建议次数重复。', '完成后再次踩下踏板，缓慢将把手放回原位。'],
  'YMachine_Bicep_Curl': ['将座椅调整到合适高度并选择重量，上臂贴住垫板、抓住把手，此为起始姿势。', '屈肘将前臂拉向上臂完成动作。', '动作顶端停顿，然后缓慢将重量放回起始位置。', '整组完成前不要把重量完全放回限位器，以保持目标肌肉的张力。'],
  'YMachine_Preacher_Curls': ['坐在托臂弯举机上并选择重量。', '将上臂后侧（肱三头肌一侧）放在托臂垫上，反握（掌心朝上）抓住把手，手臂放上垫板时注意保持肘部内收，此为起始姿势。', '呼气时收缩肱二头肌将把手向上抬起，顶端保持收缩一秒，只有前臂移动，上臂全程保持不动并贴住垫板。', '吸气时缓慢将把手放回起始姿势。', '按建议次数重复。'],
  'YMachine_Shoulder_Military_Press': ['坐在肩部推举机上并选择重量。', '抓住身体两侧的把手，保持肘部弯曲并与躯干对齐，此为起始姿势。', '呼气时将把手向上推起、完全伸直手臂，顶端保持收缩一秒。', '吸气时缓慢将把手放回起始姿势。', '按建议次数重复。'],
  'YMedicine_Ball_Full_Twist': ['这个动作需要药球和一位搭档，两人背对背站立，间隔约60至90厘米（2-3英尺），这就是起始姿势。', '将药球抱在躯干前方，与搭档同时打开髋部并转动肩部。', '为了完成完整旋转，你和搭档应向同一方向转体，即逆时针方向。', '把球传给搭档，然后两人反方向转体，重复上述动作。'],
  'YMedicine_Ball_Scoop_Throw': ['呈半蹲姿势，双手持药球，手臂自然下垂，让球靠近双脚。', '双腿蹬伸的同时髋部前顶，向上跳起。', '同时保持手臂伸直，将球从头顶向后上方挥出，在动作最高点松手，目标是让球向后飞出尽可能远的距离。'],
  'YMiddle_Back_Shrug': ['俯卧在上斜凳上，双手各持一只哑铃，手臂完全伸直自然下垂指向地面，掌心相对，这就是起始姿势。', '呼气时收紧肩胛骨，保持顶峰收缩一秒钟；提示：这个动作就像拥抱的反向动作，或者像没有手臂一样做俯身侧平举。', '吸气时回到起始姿势。', '按建议次数重复。'],
  'YMiddle_Back_Stretch': ['站立，双脚与肩同宽，双手叉腰。', '以腰部为轴转体至有拉伸感，保持10至15秒，然后转向另一侧。'],
  'YMixed_Grip_Chin': ['双手握距比肩略宽约2.5厘米（1英寸），一只手正握、另一只手反握抓住引体向上杠，这就是起始姿势。', '呼气时开始向上拉起自己；提示：反握的那只手臂要集中用背部肌肉发力，肘部贴近躯干，正握的手臂肘部稍向外但与躯干保持一条直线，集中用背阔肌把身体拉起来。', '在顶端停顿收缩一秒后，吸气并缓慢下放身体。', '按建议次数重复。', '下一组交换握法；如果上一组是右手反握、左手正握，下一组就换成右手正握、左手反握。'],
  'YMountain_Climbers': ['以俯卧撑姿势开始，用手和脚尖支撑身体，屈膝屈髋将一条腿收至膝盖约在髋部正下方，这就是起始姿势。', '爆发性地交换双腿位置，把弯曲的腿向后蹬直用脚尖支撑，同时另一条腿屈髋屈膝收向前，如此交替进行20至30秒。'],
  'YMoving_Claw_Series': ['这个动作帮助优化跑姿，让你在冲刺跑中表现更好；跑步时注意屈膝，髋部伸展时让脚跟踢向臀部。', '腿向前摆回时让股四头肌重新蓄力，下一步主动下压蹬地。', '跑步时确保手臂前后摆动，以快速的一二节奏前后摆臂。'],
  'YMuscle_Snatch': ['宽握距握住已加片的杠铃，置于大腿中部高度，双脚位于髋部正下方、按需外展，屈髋下蹲、挺胸抬头目视前方，肩部略在杠铃前方，这就是起始姿势。', '以前脚掌发力蹬地开始上拉杠铃，随后髋、膝、踝同时伸展进入第二次发力，尽可能快地向上带动杠铃，杠铃应始终贴近身体。', '保持膝盖不再弯曲，继续把杠铃举至头顶上方。'],
  'YNarrow_Stance_Hack_Squats': ['将躯干背部贴紧倒蹬机的靠背垫，肩膀卡在肩垫下方。', '在踏板上采用窄于肩宽的站距，脚尖微微外展，双脚间距约7.5厘米（3英寸）以内；提示：全程抬头，背部始终贴紧靠垫。', '双手握住机器两侧的把手，解除安全杆锁定（多数机型通过把侧把手从朝前位置转到斜向位置来解除）。', '伸直双腿但不要锁死膝盖，这就是起始姿势。', '保持身体挺直、抬头（背部始终贴垫），屈膝缓慢下放器械，直到大腿与小腿的夹角略小于90度（此时大腿低于与地面平行的位置），下放过程中吸气。', '呼气时主要用脚跟蹬踏板，重新伸直双腿，将器械推回起始位置。', '按建议次数重复。'],
  'YNarrow_Stance_Leg_Press': ['坐在腿举机上，双脚置于前方踏板上，采用窄于肩宽的站距、脚尖微微外展，双脚间距约7.5厘米（3英寸）以内；提示：全程抬头，背部始终贴紧靠垫。', '放下固定负重踏板的安全杆，将踏板向上推至双腿完全伸直；提示：不要锁死膝盖，躯干与大腿应呈标准的90度角，这就是起始姿势。', '吸气时缓慢下放踏板，直到大腿与小腿呈90度角。', '呼气时主要用脚跟发力、以股四头肌带动回到起始位置。', '按建议次数重复，完成后务必插好安全销，别让满载的踏板砸下来。'],
  'YNarrow_Stance_Squats': ['出于安全考虑，这个动作最好在深蹲架内进行；先把杠铃放到适合你身高的架钩高度，调整好高度并加好片后，走到杠铃下方，让杠铃横在肩部后方（略低于颈部）。', '双手在两侧握住杠铃，先用腿发力蹬起，同时挺直躯干，把杠铃从架上抬离。', '后退离开深蹲架，采用窄于肩宽的站距、脚尖微微外展，双脚间距约7.5至15厘米（3-6英寸），全程抬头（低头会失去平衡）并保持背部挺直，这就是起始姿势；说明：这里采用中等站距以全面发展腿部，你也可以在脚位章节中选择其他站距。', '保持身体挺直、抬头，屈膝缓慢下放杠铃，直到大腿与小腿的夹角略小于90度（此时大腿低于与地面平行的位置），下放时吸气；提示：动作正确时，膝盖前缘应与脚尖在同一条垂直线上，如果膝盖超过脚尖这条线，说明膝盖承受了过大压力，动作做错了。', '呼气时主要用脚跟蹬地，重新伸直双腿，将杠铃推回起始位置。', '按建议次数重复。'],
  'YNatural_Glute_Ham_Raise': ['利用高位下拉机的腿部挡垫或托臂凳，把脚踝卡在挡垫下、膝盖跪在座位上，背对器械，身体保持直立、姿态良好。', '这就是起始姿势；有控制地下放身体，直到膝盖几乎完全伸直。', '保持控制，把身体抬回起始位置。', '如果无法完成一次，可以用弹力带、让搭档帮忙或借助箱子蹬地来完成。'],
  'YNeckSMR': ['使用泡沫轴或擀面杖，将其放在头后抵住颈部；注意不要直接把滚轴压在脊柱上，要稍微偏转，让滚轴压在脊柱两侧的肌肉上，这就是起始姿势。', '从颈部顶端开始，缓慢向下滚动颈部肌肉，在紧张点停留10至30秒。'],
  'YNeck_Press': ['仰卧在平凳上，采用中等握距（动作中点时前臂与上臂呈90度的握距），把杠铃从架上举起，手臂锁定，直直地举在颈部上方，这就是起始姿势。', '吸气时缓慢下放，直到感觉到杠铃触到颈部。', '停顿一秒后，呼气并用胸肌发力把杠铃推回起始位置，在顶端锁定手臂、收紧胸部，保持一秒后再缓慢下放；提示：下放时间至少应是上推时间的两倍。', '按规定的次数重复动作。', '完成后把杠铃放回架上。'],
  'YOblique_Crunches': ['平躺在地面上，下背部贴地，一只手放在头侧，另一只手放在体侧撑地。', '确保双脚抬起，搭在一个平面上。', '现在抬起手贴着头那一侧的肩部。', '把肩部连同身体向上卷起，直到触碰到膝盖；例如右手放在头侧时，就把身体卷起直到右肘碰到左膝，反过来用左肘碰右膝也是一样的做法。', '膝盖碰到肘部后，把身体下放回起始位置。', '记住在离心（下放）阶段吸气，在向心（上卷）阶段呼气。', '照此交替进行，直到完成每侧建议的次数。'],
  'YOblique_Crunches__On_The_Floor': ['侧躺，右侧身体着地，双腿叠放，膝盖微微弯曲。', '左手放在头后。', '摆好姿势后，像做普通卷腹一样把左肘向上抬起，但这次主要发力部位是腹斜肌。', '尽力向上卷腹，顶峰收缩一秒，然后缓慢落回起始位置。', '记住在离心（下放）阶段吸气，在向心（上卷）阶段呼气。'],
  'YOlympic_Squat': ['将杠铃置于斜方肌上方，挺胸、目视前方，双脚采用与髋同宽的站距，按需外展。', '屈膝下蹲，尽量不让髋部向后移，这会要求膝盖向前移动，确保膝盖与脚尖方向一致，目标是把躯干尽量保持竖直，一路下蹲到底，重心保持在前脚掌。', '当大腿触碰到小腿时反向发力，把重量向上推起。'],
  'YOnYourBack_Quad_Stretch': ['仰卧在平凳或台阶上，让一条腿和同侧手臂垂在边缘外侧。', '屈膝并抓住脚背，注意不要弓起下背部。', '收腹贴向脊柱保持中立位，把脚向下压进手里；如果想加强髋部拉伸，就把被抓住那条腿的髋部向天花板方向抬起。', '换边重复。'],
  'YOn_Your_Side_Quad_Stretch': ['右侧躺，右膝弯曲呈90度，放在身前的地面上（这能稳定躯干）。', '左膝向后弯曲，用左手抓住左脚；拉伸髋屈肌时，把左脚向后压进手里，同时左髋向前送，然后换边。'],
  'YOneArm_Flat_Bench_Dumbbell_Flye': ['仰卧在平凳上，一只手握哑铃放在大腿上，握哑铃的手采用中立握姿。', '借大腿发力把哑铃带起，翻举到胸前、举起的手臂完全伸直，全程保持中立握姿，另一只手扶住平凳侧面以加强支撑，这就是起始姿势。', '持重的手臂肘部保持微屈，以保护肱二头肌肌腱；吸气并把持哑铃的手臂沿大幅弧线向下展开，直到胸部有拉伸感；提示：整个动作中持铃手臂基本不动，只发生在肩关节处。', '呼气并收紧胸肌，把持铃手臂沿同样的弧线回到起始位置；提示：上收时要用与下放相同的运动弧线。', '在顶峰收缩位置保持一秒，按规定的次数重复动作。', '换手臂重复动作。'],
  'YOneArm_HighPulley_Cable_Side_Bends': ['把标准把手装到龙门架上，将绳索调到最高滑轮位。', '侧身对着绳索站立，单手向上用反手（手心朝上）抓住把手。', '向下拉动绳索，直到肘部贴近体侧、把手位于肩膀旁。', '双脚与髋同宽站立，另一只手叉腰，帮助找到转动支点。', '保持手臂位置固定，收缩腹斜肌，以侧卷腹的方式带动重量向下。', '达到最大收缩后，缓慢将重量放回起始位置，重量片在静止时也不能完全卸力，目标是整组动作保持持续张力。', '重复至力竭。', '然后调整站位，在另一侧重复同样的动作。'],
  'YOneArm_Incline_Lateral_Raise': ['侧卧在上斜凳上，手中握一只哑铃，确保肩部贴紧斜凳，手臂横放在身体前方，掌心朝向肚脐方向。', '上方手臂伸直，持哑铃与地面平行地举在身前，这就是起始姿势。', '保持哑铃始终与地面平行，做侧平举，手臂直直向上抬起直到指向天花板；提示：动作过程中呼气，在顶端保持一秒，感受肩部收缩。', '吸气，把哑铃横过身体放回起始位置。', '按规定的次数重复动作。', '换手臂重复动作。'],
  'YOneArm_Kettlebell_Clean': ['把壶铃放在双脚之间，俯身去抓壶铃时臀部向后推，眼睛始终目视前方。', '蹬伸双腿和髋部，把壶铃翻举到肩部位置，同时手腕随之旋转。', '把重量放回起始位置。'],
  'YOneArm_Kettlebell_Clean_and_Jerk': ['握住壶铃手柄。', '蹬伸双腿和髋部，把壶铃拉向肩部完成翻举，同时转动手腕使掌心朝前。', '屈膝下蹲预蹲，保持躯干直立。', '立刻反向发力，以脚跟蹬地，实质上是跳起来制造动量，借身体的动量伸直手臂把壶铃推举到头顶锁定。', '在重量下方屈膝成半蹲位接住头顶的壶铃。', '保持壶铃在头顶，站回直立位置，然后把壶铃放回地面，进行下一次动作。'],
  'YOneArm_Kettlebell_Floor_Press': ['躺在垫子上，单手持壶铃，上臂贴地支撑，掌心朝向身体内侧。', '转动腕部，把壶铃直直推向天花板。', '把壶铃放回起始位置并重复。'],
  'YOneArm_Kettlebell_Jerk': ['握住壶铃手柄，蹬伸双腿和髋部，把壶铃拉向肩部完成翻举，同时转动手腕使掌心朝前，这就是起始姿势。', '屈膝下蹲预蹲，保持躯干直立。', '立刻反向发力，以脚跟蹬地、实质是跳起制造动量，借身体的动量伸直手臂把壶铃推举到头顶锁定，然后在重量下方屈膝成半蹲位接住，保持壶铃在头顶站回直立位置。', '下放重量，进行下一次动作。'],
  'YOneArm_Kettlebell_Military_Press_To_The_Side': ['蹬伸双腿和髋部，把壶铃翻举到肩部，同时转动手腕使掌心朝内，这就是起始姿势。', '目视壶铃，把它向上向外推举，直到在头顶完全锁定。', '有控制地把壶铃放回肩部并重复，记得用力收紧背阔肌、臀部和腹部，以增强稳定性和力量。'],
  'YOneArm_Kettlebell_Para_Press': ['蹬伸双腿和髋部，把壶铃翻举到肩部，同时转动手腕使掌心朝前，这就是起始姿势。', '肘部向侧面打开，把壶铃向上向外推举，直到在头顶完全锁定。', '有控制地把壶铃放回肩部并重复，记得用力收紧背阔肌、臀部和腹部，以增强稳定性和力量。'],
  'YOneArm_Kettlebell_Push_Press': ['握住壶铃手柄，蹬伸双腿和髋部，把壶铃拉向肩部完成翻举，同时转动手腕使掌心朝前，这就是起始姿势。', '屈膝下蹲预蹲，保持躯干直立。', '立刻反向发力，以脚跟蹬地、实质是跳起制造动量，借身体的动量伸直手臂把壶铃推举到头顶锁定，然后下放重量进行下一次动作。'],
  'YOneArm_Kettlebell_Row': ['把壶铃放在双脚前方，微屈膝盖，俯身时尽量向后推臀进入起始姿势，抓住壶铃，收紧肩胛骨、屈肘把它拉向腹部，保持背部挺直，下放并重复。'],
  'YOneArm_Kettlebell_Snatch': ['把壶铃放在双脚之间，屈膝、臀部向后推，摆好正确的起始姿势。', '目视前方，把壶铃向后摆荡到双腿之间。', '立刻反向，用髋部和膝盖发力带动壶铃向上加速，壶铃升到肩部高度时转动手腕并直臂向上冲拳，借助动量在头顶锁定接住壶铃。'],
  'YOneArm_Kettlebell_Split_Jerk': ['握住壶铃手柄，蹬伸双腿和髋部，把壶铃拉向肩部完成翻举，同时转动手腕使掌心朝前，这就是起始姿势。', '屈膝下蹲预蹲，保持躯干直立。', '立刻反向发力，以脚跟蹬地、实质是跳起制造动量，借身体的动量伸直手臂把壶铃推举到头顶锁定。', '在重量下方屈膝成半蹲位接住头顶的壶铃，前后脚分开成弓步。', '保持壶铃在头顶，站回直立位置并拢双脚，然后下放重量进行下一次动作。'],
  'YOneArm_Kettlebell_Split_Snatch': ['单手握壶铃手柄。', '向地面下蹲，然后反向发力，依次伸展髋、膝、踝，把壶铃高举过头。', '身体完全伸展后，下落成前后分腿的弓步姿势接住头顶的壶铃，确保髋部持续发力，在一气呵成的动作中把壶铃锁定在头顶。', '保持壶铃在头顶站回直立并拢双脚，放下壶铃回到起始位置。'],
  'YOneArm_Long_Bar_Row': ['把杠铃一端插进地雷架或顶在墙角固定住，在另一端装上合适的重量。', '站在杠铃旁，单手在靠近铃片处握住杠铃，用髋部和腿部力量站起来。', '屈膝、髋部后坐、挺胸，手臂伸直，这就是起始姿势。', '收紧肩胛、屈肘把重量拉向体侧，动作过程中不要猛拉或借力。', '短暂停顿后回到起始位置。'],
  'YOneArm_Medicine_Ball_Slam': ['站立，采用前后交错的运动姿态，单手持药球，持球手与后腿同侧，这就是起始姿势。', '先摆臂把药球举过头顶，同时伸展髋、膝、踝为砸球蓄力。', '在伸展到最高点时，屈曲肩、脊柱和髋部，把药球用力砸向正前方地面。', '接住弹起的球，按目标次数继续重复。'],
  'YOneArm_Open_Palm_Kettlebell_Clean': ['把一个壶铃放在双脚之间。', '单手抓住手柄快速向上提起壶铃，让它翻转，使壶身落进你的手掌里。', '把壶铃向前抛出，用单手接住手柄。', '把壶铃放回地面并重复，记得两侧手臂都要练。'],
  'YOneArm_Overhead_Kettlebell_Squats': ['单臂把壶铃翻举到肩部（蹬伸腿髋、转动手腕），再伸直肘部把壶铃推举到头顶，这就是起始姿势。', '目视前方，保持壶铃锁定在头顶，屈膝屈髋下蹲，躯干下落到双腿之间，全程抬头挺胸。', '在底部停顿一秒，然后脚跟蹬地回到最高点。'],
  'YOneArm_Side_Deadlift': ['站在杠铃侧面、靠近杠铃中心的位置，屈膝下蹲直到能够到杠铃。', '像提公文包一样抓住杠铃（因为杠铃是横放的，掌心朝向自己），重量较大时建议佩戴护腕，这就是起始姿势。', '呼气时借助腿部力量把杠铃提起，手臂完全伸直，直到身体站直。', '吸气时缓慢下放杠铃；提示：下放时务必屈膝，避免受伤。', '按建议次数重复。', '换手臂重复动作。'],
  'YOneArm_Side_Laterals': ['单手拿起一只哑铃，另一只手扶住一个稳固的物体（如上斜凳），身体向持铃一侧倾斜、远离扶凳的手，这样能保持平衡。', '躯干挺直站立，哑铃垂在体侧、手臂伸直，掌心朝向自己，这就是起始姿势。', '保持躯干固定（不要摆动），肘部微屈、手腕像倒水一样微微前倾，把哑铃向体侧举起，直到手臂与地面平行，动作过程中呼气，在顶端停顿一秒。', '吸气，缓慢把哑铃放回起始位置。', '按建议次数重复。', '换手臂重复动作。'],
  'YOneLegged_Cable_Kickback': ['把皮革脚踝绑带挂到低位绳索滑轮上，再把绑带固定在脚踝上。', '面对配重片、距其约60厘米（2英尺）站立，双手扶住钢架作为支撑。', '保持膝盖和髋部微屈、腹部收紧，呼气时收缩臀大肌，让工作腿沿半圆弧线尽量向后上方踢出；提示：在完全伸展时收紧臀肌一秒，以获得顶峰收缩。', '然后缓慢把工作腿向前收回，抵抗绳索的拉力，回到起始位置。', '按建议次数重复。', '换腿，在另一侧重复动作。'],
  'YOne_Arm_Dumbbell_Bench_Press': ['仰卧在平凳上，一只手握哑铃放在大腿上。', '借大腿发力把哑铃带起，翻举到肩宽位置举在胸前，用不持铃的手帮助把哑铃摆正到身体上方。', '到肩宽位置后，向前转动手腕使掌心朝前，这就是起始姿势。', '吸气时缓慢把哑铃下放到体侧，全程完全控制哑铃；提示：刚开始可能会有些吃力，可以用不持铃的手辅助保持平衡，只在需要时使用，否则让它放在体侧休息。', '呼气时用胸肌把哑铃推起，在顶端锁定手臂、收紧胸部保持一秒，然后再缓慢下放；提示：下放时间至少应是上推时间的两倍。', '按训练计划规定的次数重复动作。', '换手臂重复动作。'],
  'YOne_Arm_Dumbbell_Preacher_Curl': ['右手握一只哑铃，上臂放在托臂凳或上斜凳上，哑铃与肩同高，这就是起始姿势。', '吸气时缓慢下放哑铃，直到上臂伸直、肱二头肌完全拉伸。', '呼气时用肱二头肌把哑铃弯举起来，直到肌肉完全收缩、哑铃与肩同高；再次提醒，要确保完全收缩，小指侧要举得比拇指侧更高。', '在收缩位置用力挤压肱二头肌一秒，按建议次数重复。', '换手臂重复动作。'],
  'YOne_Arm_Floor_Press': ['仰面平躺在地面或瑜伽垫上，背部贴地，膝盖保持弯曲。', '让搭档把杠铃递到你单手中，开始时手臂几乎完全伸直，类似杠铃卧推的起始姿势，但这次采用中立握姿（掌心朝向躯干）。', '确保不持铃的手放在体侧。', '开始下放杠铃直到肘部触地，这个离心（下放）阶段记得吸气。', '然后把杠铃推回原来的起始位置，向心（上推）阶段记得呼气。', '重复直到完成建议的次数。', '换手臂重复动作。'],
  'YOne_Arm_Lat_Pulldown': ['选择合适的重量，调整膝垫压住双腿，正握抓住把手，这就是起始姿势。', '向下拉把手，屈肘时把肘部向体侧收紧。', '在动作底部停顿，然后缓慢把把手放回起始位置。', '多次重复时，不要完全放回重量，以保持目标肌肉的张力。'],
  'YOne_Arm_Pronated_Dumbbell_Triceps_Extension': ['平躺在凳上，手臂伸直持哑铃，手臂与身体垂直，掌心朝向脚的方向，这个动作需要正握。', '另一只手放在肱二头肌上作支撑。', '吸气时缓慢下放哑铃。', '然后收缩肱三头肌把哑铃向上举起，向心（上举）阶段记得呼气。', '重复直到完成规定的次数。', '换手臂重复动作。'],
  'YOne_Arm_Supinated_Dumbbell_Triceps_Extension': ['平躺在凳上，手臂伸直持哑铃，手臂与身体垂直，掌心朝向面部，这个动作需要反握。', '另一只手放在肱二头肌上作支撑。', '吸气时缓慢下放哑铃。', '然后收缩肱三头肌把哑铃向上举起，向心（上举）阶段记得呼气。', '重复直到完成规定的次数。', '换手臂重复动作。', '再换一次手臂，重复动作。'],
  'YOne_Half_Locust': ['俯卧在地面上。', '把左手垫在左侧髋骨下方，为髋部和耻骨提供缓冲。', '弯曲右膝，用右手抓住右脚。', '把脚向上抬起，同时让肩膀离地，这个动作还能拉伸右侧髋屈肌以及胸部与肩部，然后换边；如果背部没有不适，也可以尝试双臂双腿同时进行。'],
  'YOne_Handed_Hang': ['用正握单手握杠（引体向上杠），脚踩在地面或台阶上，让大部分体重悬吊在这只手上，保持10至20秒后换边。'],
  'YOne_Knee_To_Chest': ['先仰卧在地面上。', '一条腿伸直，把另一条腿的膝盖拉向胸口，手抓住膝关节下方以保护髌骨。', '轻轻把该膝盖向鼻子的方向拉。', '换边；这个动作能拉伸弯曲腿一侧的臀部和下背部，以及伸直腿一侧的髋屈肌。'],
  'YOne_Leg_Barbell_Squat': ['背对平凳站立，距凳子约60至90厘米（2-3英尺），杠铃放在身前地面；提示：双脚与肩同宽。', '屈膝，采用宽于肩距的正握，把杠铃提起放到胸前。', '然后把杠铃举过头顶，放到颈后根部；一只脚向后撤，脚尖搭在平凳上，另一只脚固定在前方；全程抬头（低头会失去平衡）并保持背部挺直；提示：做这个动作时背部要直、胸部要挺。', '吸气时缓慢下蹲，直到大腿与地面平行，此时膝盖应在脚尖正上方，胸部在大腿中段的正上方。', '呼气时以胸部和髋部引领，收缩股四头肌，把身体抬回起始位置。', '按建议次数重复。', '换腿重复动作。'],
  'YOpen_Palm_Kettlebell_Clean': ['把一个壶铃放在双脚之间，蹬伸双腿和髋部，把壶铃向肩部方向翻举。', '壶铃上升时松开手，让它翻转，使壶身落进你的手掌中。', '把壶铃向前方抛出，用双手接住手柄，放回起始位置并重复。'],
  'YOverhead_Cable_Curl': ['先在绳索机两侧各设定一个合适的重量；注意：两侧选择的重量必须相同。', '调整两侧滑轮的高度，确保它们高于你的肩膀。', '站在两侧滑轮中间，用反手（掌心朝上）抓住两侧把手，手臂完全伸直并与地面平行，双脚与肩同宽，身体与把手对齐居中，这就是起始姿势。', '呼气时缓慢收缩两侧肱二头肌，直到前臂与肱二头肌相互靠近。', '吸气时把前臂放回起始位置；注意：动作过程中除前臂外，整个身体保持不动。', '按训练计划规定的次数重复。'],
  'YOverhead_Lat': ['坐直在地面上，搭档站在身后；单臂竖直上举，屈肘让手尽力触向背部，搭档握住你的肱三头肌和手腕，这就是起始姿势。', '试着把上臂拉向体侧，搭档则用力阻止你完成这个动作。', '10至20秒后放松手臂，让搭档轻轻按压肱三头肌进一步拉伸背阔肌，保持10至20秒后换边。'],
  'YOverhead_Slam': ['双手持药球，双脚与肩同宽站立，这就是起始姿势。', '先做反向预备动作，把药球举过头顶并充分伸展身体。', '反向发力，把药球全力砸向正前方地面。', '用双手接住弹起的球并重复动作。'],
  'YOverhead_Squat': ['先把杠铃放在身前地面，双脚站距宽于肩。', '屈膝，用掌心朝向自己的正握抓住杠铃，双手握距宽于肩，摆好位置后把杠铃提起放到胸前。', '把杠铃移到头顶上方略靠后，确保手臂完全伸直，全程抬头、保持背部挺直，收紧肩胛骨，这就是起始姿势。', '吸气时屈膝缓慢下蹲，直到大腿与地面平行；提示：动作中保持背部挺直以避免受伤，手臂全程保持在头顶上方伸直。', '呼气时用脚和腿部力量把重量推回起始位置。', '按建议次数重复。'],
  'YOverhead_Stretch': ['直立站好，十指相扣，掌心向上打开，向上伸直手臂时保持肩膀下沉。', '为了充分拉伸躯干，向下收尾骨并稳住躯干，拉伸躯干前侧和后侧的肌肉。'],
  'YOverhead_Triceps': ['坐直在地面上，搭档站在身后；单臂竖直上举，屈肘让手尽力触向背部，搭档握住你的肘部和手腕，这就是起始姿势。', '试着把手臂伸直伸向空中，搭档则用力阻止你完成这个动作。', '10至20秒后放松手臂，让搭档轻轻按压手腕进一步拉伸肱三头肌，保持10至20秒后换边。'],
  'YPallof_Press_With_Rotation': ['把标准把手装到龙门架上，把绳索调到肩部高度。', '侧身对着绳索，单手抓住把手，远离龙门架站到约一臂的距离，让绳索承受配重张力，伸出的手臂与绳索保持一条直线。', '双脚与髋同宽站立，把绳索拉向胸口，用另一只手也抓住把手，此时双手都在把手上。', '面朝前方，把绳索从胸前推出，核心收紧发力。', '保持髋部朝前不动，躯干向远离滑轮的一侧转体，直到完成四分之一圈。', '保持身体姿势稳定、手臂伸直，缓慢而有控制地回到中立位置，双臂在身前伸展。', '在侧向张力持续激活核心的状态下，把双手拉回胸前，再立刻向外推至完全伸展的位置，这就完成一次。', '重复至力竭。', '然后调整站位，在另一侧重复同样的动作。'],
  'YPalmsDown_Dumbbell_Wrist_Curl_Over_A_Bench': ['先把两只哑铃放在平凳的一侧。', '双膝跪地，身体面向平凳。', '用正握（掌心向下）抓住两只哑铃，把前臂放在平凳上，手腕悬出凳边。', '呼气的同时向上弯举手腕。', '吸气时缓慢把手腕放回起始位置。', '做这个动作时只有手腕需要活动，前臂应保持固定。', '按建议次数重复。'],
  'YPalmsDown_Wrist_Curl_Over_A_Bench': ['先把一根杠铃放在平凳的一侧。', '双膝跪地，身体面向平凳。', '用正握（掌心向下）抓住杠铃，把前臂放在平凳上，手腕悬出凳边。', '呼气的同时向上弯举手腕。', '吸气时缓慢把手腕放回起始位置。', '做这个动作时只有手腕需要活动，前臂应保持固定。', '按建议次数重复。'],
  'YPalmsUp_Barbell_Wrist_Curl_Over_A_Bench': ['先把一根杠铃放在平凳的一侧。', '双膝跪地，身体面向平凳。', '用反握（掌心向上）抓住杠铃，把前臂放在平凳上，手腕悬出凳边。', '呼气的同时向上弯举手腕。', '吸气时缓慢把手腕放回起始位置。', '做这个动作时只有手腕需要活动，前臂应保持固定。', '按建议次数重复。'],
  'YPalmsUp_Dumbbell_Wrist_Curl_Over_A_Bench': ['先把两只哑铃放在平凳的一侧。', '双膝跪地，身体面向平凳。', '用反握（掌心向上）抓住两只哑铃，把前臂放在平凳上，手腕悬出凳边。', '呼气的同时向上弯举手腕。', '吸气时缓慢把手腕放回起始位置，确保在这个阶段吸气。', '做这个动作时只有手腕需要活动，前臂应保持固定。', '按建议次数重复。'],
  'YParallel_Bar_Dip': ['站在双杠中间，双手各握一根杠，轻轻跳起撑到手臂锁定的起始姿势。', '屈肘下放身体，直到手臂弯曲超过90度，下放过程中避免摆动并保持良好姿态。', '伸展肘部反向发力，把自己推回起始位置。', '按目标次数重复。'],
  'YPeronealsSMR': ['侧卧，用前臂和放在小腿外侧的泡沫轴支撑身体重量，另一条腿可以搭在上面，也可以交叉放在身前，这就是起始姿势。', '抬起髋部离地，从膝盖下方到脚踝上方来回滚动小腿侧面，在紧张点停留10至30秒，另一条腿重复。'],
  'YPhysioball_Hip_Bridge': ['仰躺在瑜伽球上，上背部靠在球上、髋部悬空，双脚平踩地面，间距与髋同宽或更宽，这就是起始姿势。', '用臀大肌和腘绳肌伸展髋部，把髋部向上顶起成桥。', '在动作顶端停顿，然后回到起始位置。'],
  'YPin_Presses': ['铁架卧推去掉了卧推的离心阶段，用来发展启动力量，还能让你针对性地训练特定的活动幅度。', '把卧推凳放进深蹲架，把安全杆设在你想要的行程位置（可以是锁定位，也可以离胸口几厘米），把杠铃放到安全杆上做好准备。', '仰卧在凳上，让杠铃位于正常卧推时杠铃落点的正上方，双脚收向身体、拱起背部，借杠铃分担部分体重，把肩部抬离凳面并后收肩胛骨，用双脚把斜方肌压向凳面，整个动作保持身体的紧绷姿势。', '可以采用标准卧推握距，或用肩宽握距来侧重肱三头肌；杠铃、手腕和肘部全程保持一条直线，集中注意力用力握杠，想象要把杠铃掰断。', '用最大的力量向上推起杠铃，肘部在锁定前始终保持贴近身体。', '把杠铃放回安全杆上，停顿后再开始下一次。'],
  'YPiriformisSMR': ['臀部坐在泡沫轴上，屈膝，把一条腿架到另一条腿上，脚踝放在膝盖上方，这就是起始姿势。', '把重心移到架腿一侧，在臀部上来回滚动，直到上臀肌感到紧张，可以用一只手把弯曲的膝盖拉向胸口来加深拉伸，保持10至30秒后换边。'],
  'YPlate_Pinch': ['拿两片宽边杠铃片，光滑面朝外合在一起。', '用四指扣住外侧片的边缘、拇指抵住另一侧，把两片杠铃片夹在一起，这就是起始姿势。', '用手指和拇指用力捏住杠铃片，坚持尽可能长的时间。', '按训练计划规定的组数重复。', '换手重复动作。'],
  'YPlate_Twist': ['仰卧在地面或瑜伽垫上，双腿完全伸直、上半身立起，双手微屈、在腹部前方握住杠铃片的两侧。', '缓慢把双腿在脚踝处交叉并抬离地面，膝盖微微弯曲；提示：上半身稍微后仰有助于在转动时保持平衡，这就是起始姿势。', '把杠铃片转向左侧并用它触碰地面，动作过程中呼气。', '吸气回到起始位置，然后向身体右侧重复动作；提示：全程使用缓慢可控的动作，猛甩会伤到背部。', '按建议次数重复。'],
  'YPlatform_Hamstring_Slides': ['这个动作需要木地板或类似光滑的地面；仰卧、双腿伸直，在脚跟下垫一条毛巾或轻重量片，这就是起始姿势。', '屈膝开始动作，另一条腿保持伸直。', '继续让脚跟在地面上滑向身体。', '膝盖完全屈曲后反向动作，回到起始位置。'],
  'YPlie_Dumbbell_Squat': ['双手托住一只哑铃的底部直立站好，双脚站距宽于肩，膝盖微屈。', '脚尖朝外；注意：动作过程中手臂保持不动，这就是起始姿势。', '缓慢屈膝下蹲，直到大腿与地面平行，这个离心阶段记得吸气。', '呼气时主要用脚跟发力，把身体推回起始位置。', '按建议次数重复。'],
  'YPlyo_Kettlebell_Pushups': ['把壶铃放在地面上，摆成俯卧撑姿势，脚尖撑地，一只手撑地、另一只手扶住壶铃，手臂伸直，这就是起始姿势。', '保持背部挺直，尽量向下俯身。', '快速有力地反向发力，撑起身子换到壶铃另一侧，同时交换双手的位置，继续下俯并来回重复动作。'],
  'YPower_Clean_from_Blocks': ['杠铃架在合适高度的垫木上，握距略宽于双腿；沉髋、重心落在脚跟，背部挺直、目视前方、挺胸，肩部略在杠铃前方，这就是起始姿势。', '用脚跟蹬地、伸展膝盖开始第一次发力，背部角度保持不变、手臂保持伸直，杠铃接近大腿中部时开始伸展髋部。', '以跳跃动作伸展髋、膝、踝加速，利用速度把杠铃向上带动，不需要用手臂主动拉拽来加速；第二次发力结束时，身体应完全伸展、微微后仰，手臂仍然伸直。', '达到完全伸展后，猛烈耸肩并屈臂、肘部向上向外，进入第三次发力；在伸展的最高点，把自己拉向杠铃下方，让杠铃能落在肩上，同时把肘部转到杠铃下方，杠铃应架在送出的肩膀上，轻轻触碰喉部、双手放松。', '立刻用脚跟蹬地站起，保持躯干直立、肘部抬起，直到完全站直，然后把重量放回垫木上，完成一次动作。'],
  'YPower_Jerk': ['杠铃架在肩前站立，开始预蹲；双脚位于髋部正下方，屈膝时髋部不要后移，只下蹲一点点，然后尽可能有力地反向发力。', '用脚跟蹬地，制造尽可能大的速度和力量，杠铃离开肩部时记得把头部让开。', '双脚离地的瞬间，必须尽快把脚落到接杠位置；在双脚没有踩住地面的短暂时间里，向上推杠的力会把身体向下带，双脚应移到略宽的位置、膝盖微屈。', '手臂在头顶锁定，接住杠铃。', '站回直立位置。'],
  'YPower_Partials': ['躯干挺直站立，双手各持一只哑铃、手臂伸直垂下，肘部贴近躯干。', '掌心朝向身体，双脚约与肩同宽，这就是起始姿势。', '保持手臂伸直、躯干固定，呼气时把哑铃向两侧举起，直到约与肩同高。', '感受一秒收缩，然后吸气缓慢把哑铃放回起始位置；提示：举起和下放时保持掌心向下、小指略高，这样能把压力主要集中在肩部。', '按建议次数重复。'],
  'YPower_Snatch': ['杠铃加好片放在地面，杠铃靠近或贴着胫骨，采用宽握距；双脚位于髋部正下方、按需外展，沉髋、挺胸、目视前方，肩部略在杠铃前方，这就是起始姿势。', '以前脚掌发力蹬地开始第一次发力，把杠铃从地面拉起，杠铃越过膝盖前背部角度保持不变。', '伸展髋、膝、踝进入第二次发力，尽可能快地向上带动杠铃，杠铃应贴近身体；在伸展最高点耸肩，让肘部向两侧弯曲。', '双脚移到略宽于髋的接杠位置时，把自己拉到杠铃下方，同时把杠铃举过头顶；在半蹲位接住杠铃，继续把杠铃举到头顶上方，在头顶锁定接住。', '保持杠铃在头顶，站回直立位置。'],
  'YPower_Snatch_from_Blocks': ['杠铃架在合适高度的垫木或架子上，采用宽握距，双脚位于髋部正下方、按需外展；沉髋、挺胸、目视前方，肩部略在杠铃前方、肘部向外打开，这就是起始姿势。', '以前脚掌发力蹬地开始第一次发力，把杠铃从垫木上拉起。', '伸展髋、膝、踝进入第二次发力，尽可能快地向上带动杠铃，杠铃应贴近身体；在伸展最高点耸肩，让肘部向两侧弯曲。', '双脚移动到接杠位置时，用力把自己拉到杠铃下方，同时把杠铃举过头顶；双脚移到髋部外侧略宽的位置、按需外展，在全蹲位置接住杠铃，手臂在头顶完全伸直。', '保持杠铃位于脚跟前方、抬头挺胸，用脚跟蹬地站起，然后小心地把重量放回垫木上。'],
  'YPower_Stairs': ['上坡负重走这个动作是把负重在楼梯上逐级向上搬运，训练时可以用轮胎或箱子代替。', '先用双手抓住重物，双脚站宽、抬头挺胸，用脚跟蹬地，伸展膝盖和髋部把重物从地面提起。', '身体后仰，试着把重物甩到通常约40至45厘米（16-18英寸）高的台阶上，可以用腿部辅助把重物推上台阶。', '重复3至5次，然后换更重的重量，尽可能快地继续。'],
  'YPreacher_Curl': ['做这个动作需要托臂凳和曲杆杠铃；握住曲杆的内侧窄距位置（最好让搭档递给你，或者从多数托臂凳前部自带的杠铃架上取），掌心朝前，由于杠铃形状，双手会微微内倾。', '上臂贴住托臂凳垫、胸部抵住垫子，在肩同高位置握住曲杆杠铃，这就是起始姿势。', '吸气时缓慢下放杠铃，直到上臂伸直、肱二头肌完全拉伸。', '呼气时用肱二头肌把杠铃弯举起来，直到肌肉完全收缩、杠铃与肩同高，用力挤压肱二头肌并保持一秒。', '按建议次数重复。'],
  'YPreacher_Hammer_Dumbbell_Curl': ['双手各握一只哑铃，掌心相对（中立握姿），把两侧上臂放在托臂凳上。', '吸气时缓慢下放哑铃，直到上臂伸直、肱二头肌完全拉伸。', '呼气时用肱二头肌把哑铃弯举起来，直到肌肉完全收缩、哑铃与肩同高。', '在收缩位置用力挤压肱二头肌一秒，按建议次数重复。'],
  'YPress_SitUp': ['先仰卧在凳上，杠铃放在胸口，双腿固定在腹肌凳的脚托上，这就是起始姿势。', '吸气时收紧腹部和臀部，同时像做仰卧起坐一样卷起躯干，呼气时把杠铃推举到头顶上方；提示：做这个动作时用手臂把杠铃推出，但仍要把注意力放在腹部肌肉上。', '把上半身放回起始位置，同时把杠铃收回到躯干上，下放身体时记得吸气。', '按建议次数重复。'],
  'YProne_Manual_Hamstring': ['这个动作需要一位搭档；俯卧、双腿伸直，搭档把手放在你的脚跟上。', '开始屈膝把腿向上卷起，搭档应提供阻力，从轻开始、随着动作进行逐渐加压，并与搭档沟通以确定合适的阻力大小。', '在顶端停顿，回到起始位置的整个过程搭档都施加反向阻力。'],
  'YProwler_Sprint': ['把雪橇放在合适的地面上，装上合适的重量，雪橇的阻力应足以让你用力，但不要太重而明显拖慢速度。', '这个动作可以使用直立把手或低位把手；双手握住把手、手臂伸直，身体前倾靠在雪橇上。', '保持良好姿态，用短促交替的步伐蹬地前进，在短距离内尽可能快地移动。'],
  'YPull_Through': ['站在低位滑轮前方几步远的位置，滑轮上装好绳头或把手；背对器械、跨立在绳索两侧，双脚分开宽站距。', '开始动作时屈髋、双手尽可能远地从双腿之间向后伸，膝盖保持微屈；保持手臂伸直，伸展髋部站直身体，避免用肩膀向上发力，所有动作都应来自髋部。'],
  'YPullups': ['用规定的握法、掌心朝前抓住引体向上杠；握距说明：宽握时双手间距宽于肩，中握时与肩同宽，窄握时窄于肩。', '双手在选定的握距下伸直握住杠铃后，躯干向后仰约30度，同时下背部呈自然弧度、挺胸，这就是起始姿势。', '把肩部和上臂向下向后拉，把躯干拉起直到上胸触杠，这个阶段呼气；提示：达到完全收缩位置后集中挤压背部肌肉，上半身在空间中保持稳定、只有手臂在动，前臂除了握杠不做其他工作。', '在收缩位置保持一秒后，开始吸气并缓慢下放躯干，直到手臂完全伸直、背阔肌完全拉伸。', '按规定的次数重复动作。'],
  'YPushUp_Wide': ['双手宽距撑地，脚尖和双手支撑身体成平板姿势，肘部伸直、身体笔直，不要让髋部下塌，这就是起始姿势。', '开始让肘部弯曲，吸气时把胸部下放到接近地面。', '用胸肌发力、伸直肘部把上半身推回起始位置，这一步呼气。', '在收缩位置停顿后，按规定的次数重复动作。'],
  'YPushUps__Close_Triceps_Position': ['俯卧在地面上，双手间距窄于肩宽，用手臂撑起躯干。', '吸气时下放身体，直到胸部几乎触地。', '用肱三头肌和部分胸肌发力，把上半身推回起始位置并收紧胸部，这一步呼气。', '在收缩位置停顿一秒后，按规定的次数重复动作。'],
  'YPushUps_With_Feet_Elevated': ['俯卧在地面上，双手间距约90厘米（36英寸），用手臂撑起躯干。', '把脚尖搭在平凳上，让身体抬高；提示：平凳越高，动作难度和阻力越大。', '吸气时下放身体，直到胸部几乎触地。', '用胸肌发力，把上半身推回起始位置并收紧胸部，这一步呼气。', '在收缩位置停顿一秒后，按规定的次数重复动作。'],
  'YPushUps_With_Feet_On_An_Exercise_Ball': ['俯卧在地面上，双手间距约90厘米（36英寸），用手臂撑起躯干。', '把脚尖搭在瑜伽球上，让身体抬高。', '吸气时下放身体，直到胸部几乎触地。', '用胸肌发力，把上半身推回起始位置并收紧胸部，这一步呼气。', '在收缩位置停顿一秒后，按规定的次数重复动作。'],
  'YPush_Press__Behind_the_Neck': ['站姿,杠铃架在颈后肩部,先做预蹲。双脚位于髋部正下方,屈膝但髋部不要后移,只下蹲一点点,然后尽可能有力地反向起身。脚跟发力蹬地,产生尽可能大的速度和力量,让杠铃沿垂直轨迹上升。', '利用产生的动量,伸展手臂将杠铃推举过头顶。', '回到起始姿势,用双腿吸收冲击。'],
  'YPushups': ['俯卧在地面上,双手分开约36英寸(约91厘米),手臂伸直将躯干撑起。', '接着吸气,身体下放,直到胸部几乎触地。', '呼气,收紧胸部,将上身推回起始姿势。', '在顶端收缩位短暂停顿后,再次下放身体,按所需次数重复。'],
  'YPushups_Close_and_Wide_Hand_Positions': ['俯卧在地面上,身体挺直,脚尖着地,宽距时双手分开大于肩宽,窄距时双手距离小于肩宽。确保手臂伸直将躯干撑起。', '吸气,身体下放,直到胸部几乎触地。', '用胸大肌发力将上身推回起始姿势并收紧胸部,此步骤呼气。', '在收缩位停顿一秒后,按规定次数重复动作。'],
  'YPyramid': ['先将躯干向前滚上瑜伽球,让髋部落在球顶,成为身体的最高点。', '双手和双脚撑地,手臂和腿可以微屈或伸直,取决于球的大小、你的柔韧性和肢体长度。这也有助于发展躯干和肩部的稳定力量。'],
  'YQuad_Stretch': ['侧卧,用腰带、绳子或弹力带套在上方脚的脚踝处。屈膝并伸展髋部,试着用脚去触碰臀部,双手拉住带子。这就是起始姿势。', '带子搭在肩上或举过头顶,轻轻拉动以加大股四头肌的拉伸感。保持10-20秒,然后换边。'],
  'YQuadricepsSMR': ['俯卧在地面上,用双手或前臂支撑体重。将泡沫轴垫在一条腿的股四头肌下方,脚离地。尽量放松这条腿。这就是起始姿势。', '在可承受的范围内尽量把体重压到待放松的腿上,在泡沫轴上从膝盖上方滚到髋部下方,在紧张点停留10-30秒。换边。'],
  'YQuick_Leap': ['这个动作需要一个跳箱。', '面向跳箱站立,距箱边1-2英尺(约30-60厘米)。', '利用髋部发力,跳到箱子上,双腿落地。确保屈膝、全脚掌着地。', '落地后立即全身充分伸展,双臂摆过头顶爆发跳离箱子。用双腿吸收落地冲击。'],
  'YRack_Delivery': ['这个练习用于训练把杠铃送到肩部架位。开始时以稻草人姿势持杠:上臂与地面平行,前臂向下垂。采用钩握,手指包住拇指。', '开始时让手肘绕着杠铃转动,把杠铃送到肩上。手肘前移时放松握力。肩部应前伸,为杠铃提供架子,杠铃应轻触喉部。', '杠铃必须始终贴近身体,因为重量较大时任何距离都会导致不必要的碰撞。当动作变得更顺畅时,可以在进一步进阶前增加速度和重量。'],
  'YRack_Pull_with_Bands': ['在力量架中架好杠铃,放在保险杆上。保险杆设在目标位置:略低于膝盖、略高于膝盖或大腿中部。把弹力带固定在架底,或用哑铃压住。另一端挂到杠铃上。可能需要把弹力带绕短以提供张力。', '以标准硬拉姿势站到杠铃前。双脚应在髋部正下方,握距与肩同宽,背部弓起,髋部后坐以启动腘绳肌。由于重量通常很大,可以用正反握、钩握或用助力带辅助握杠。', '目视前方,伸展髋部和膝盖,把重量向上向后拉至锁定。完成动作时记得把肩膀向后收。把杠铃放回保险杆并重复。'],
  'YRack_Pulls': ['在力量架中架好杠铃,放在保险杆上。保险杆设在目标位置:略低于膝盖、略高于膝盖或大腿中部。以标准硬拉姿势站到杠铃前。双脚应在髋部正下方,握距与肩同宽,背部弓起,髋部后坐以启动腘绳肌。由于重量通常很大,可以用正反握、钩握或用助力带辅助握杠。', '目视前方,伸展髋部和膝盖,把重量向上向后拉至锁定。完成动作时记得把肩膀向后收。', '把杠铃放回保险杆并重复。'],
  'YRear_Leg_Raises': ['在训练垫上双手双膝撑地。头部目视前方,屈膝使腘绳肌与小腿之间呈90度角。这就是起始姿势。', '将一条腿向上向后伸展,膝盖和髋部都应伸展。重复5-10次,然后换边。'],
  'YRecumbent_Bike': ['开始时坐上卧式健身车,把座椅调到适合你的高度。', '从菜单中选择想要的选项。可能需要先踩踏板才能开机。可以用手动模式,也可以选择程序。通常可以输入年龄和体重来估算运动消耗的卡路里。整个锻炼过程中可以改变阻力大小。手柄可以用来监测心率,帮助你保持合适的强度。', '卧式健身车方便、有心血管锻炼效果,且比其他运动冲击更小。一个150磅(约68公斤)的人以中等速度骑行30分钟大约消耗230卡路里,而跑步可消耗450卡路里或更多。'],
  'YReturn_Push_from_Stance': ['这个练习需要一名搭档。', '以运动姿态的2点或3点支撑姿势开始。', '听到信号后,移动到接住搭档传球的位置。', '双手接住药球,立即扔回给搭档。', '可以通过跑不同路线来调整这个练习。'],
  'YReverse_Band_Bench_Press': ['在力量架内放一张卧推凳,把杠铃调到正确高度。先把弹力带固定在带钉或架顶。确保自己处于弹力带正下方。另一端挂到杠铃上。', '躺在凳上,双脚收拢在身下,拱起下背。借杠铃支撑体重,把肩抬离凳面并向后收,夹紧肩胛骨。用双脚把斜方肌推向凳面。整个动作中保持这个紧绷的身体姿态。无论握多宽,手都应覆盖杠铃上的刻度环。', '把杠铃从架上取出,不要前伸肩部。专注于握紧杠铃并试着把它向两边掰开。把杠铃下放到下胸或上腹位置。杠铃、手腕和手肘应始终保持一条直线。', '杠铃触到躯干时停顿,然后尽可能用力把杠推起。手肘应收在身侧直到锁定。'],
  'YReverse_Band_Box_Squat': ['在力量架内开始,身后放一个高度合适的箱子。把弹力带固定在带钉上或系在架顶,确保深蹲时弹力带位于杠铃正上方。另一端挂到杠上。', '先站到杠下,把杠放在肩后。夹紧肩胛骨,手肘向前转,试着把杠铃在肩上压弯。把杠从架上取下,下背保持紧绷弓起,后退站好。双脚站宽更侧重背部、臀大肌、内收肌和腘绳肌,站窄更侧重股四头肌。头部保持目视前方。', '保持背部、肩部和核心紧绷,膝盖和臀部向外打开开始下蹲。髋部后坐,直到坐到箱子上。理想情况下,小腿应垂直于地面。坐到箱上时停顿,放松髋屈肌。绝不要借箱子弹起。', '保持重心在脚跟,双脚和膝盖向外推,头部引领发力从箱上蹬起。继续上升,从头到脚保持紧绷。小心地把杠铃放回架上。'],
  'YReverse_Band_Deadlift': ['在力量架中架好杠铃。把弹力带固定在架顶,可以用带钉或架体本身。把弹力带另一端挂到杠铃上。', '走到杠铃前,让杠铃位于双脚正上方。双脚约与髋同宽。屈髋以肩宽握距握杠,让肩胛骨前伸。较重的组通常用正握或正反握。', '双脚和握姿就位后,深吸一口气,然后下放髋部、屈膝,直到小腿触到杠铃。头部目视前方,挺胸,背部弓起,开始用脚跟发力把重量向上拉起。', '杠铃过膝后,用力向后拉杠,同时夹紧肩胛骨,髋部向前顶向杠铃。', '屈髋下放杠铃,引导它回到地面。'],
  'YReverse_Band_Power_Squat': ['在力量架内开始,保险杆和杠铃调到合适高度。装好片后,把弹力带固定在架顶,用带钉或架体本身。另一端挂到杠铃上。', '先站到杠下,把杠放在肩后。夹紧肩胛骨,手肘向前转,试着把杠铃在肩上压弯。把杠从架上取下,下背保持紧绷弓起,后退站好。双脚站宽,更侧重背部、臀大肌、内收肌和腘绳肌。', '头部保持目视前方。背部、肩部和核心紧绷,膝盖和臀部向外打开开始下蹲。髋部尽量向后坐。理想情况下,小腿应垂直于地面。杠位较低时需要更大的躯干前倾,让杠铃保持在脚跟正上方。继续下蹲直到低于平行,即髋部褶皱与膝盖顶部齐平。', '保持重心在脚跟,双脚和膝盖向外推,头部引领发力向上站起。继续上升,从头到脚保持紧绷,直到回到起始姿势。'],
  'YReverse_Band_Sumo_Deadlift': ['在力量架内把装好片的杠铃放在地面上。把弹力带固定在架顶,用带钉或架体本身。另一端挂到杠铃上。', '走到杠铃前,让杠铃穿过双脚中线。双脚站得很宽,靠近卡箍。屈髋握杠。双臂应在肩部正下方、双腿内侧,可以用正握、正反握或钩握。放松肩部,这实际上能拉长你的手臂。', '吸一口气,然后下放髋部,头部目视前方、挺胸。双脚蹬地,把双脚向外撑开,重心落在脚掌后半部。伸展髋部和膝盖。', '杠铃过膝后,身体后倾,把髋部顶向杠铃,同时夹紧肩胛骨。', '屈髋,控制住重量回到地面。'],
  'YReverse_Barbell_Curl': ['身体站直,以肩宽握距持杠,手肘贴近躯干。手掌应朝下(正握)。这就是起始姿势。', '保持上臂固定,呼气的同时收缩肱二头肌弯举杠铃。只有前臂应该移动。继续弯举直到肱二头肌完全收缩、杠铃到肩部高度。挤压肌肉,在收缩位保持一秒。', '吸气,慢慢把杠铃放回起始姿势。', '按建议的次数重复。'],
  'YReverse_Barbell_Preacher_Curls': ['用肩宽、掌心朝下(正握)的握法握住曲杆。', '把双臂上臂放在托臂凳上,手臂伸直。这就是起始姿势。', '呼气时,用肱二头肌把重量弯举起来,直到肱二头肌完全收缩、杠铃到肩部高度。在收缩位用力挤压肱二头肌一秒。', '吸气,慢慢下放杠铃,直到上臂伸直、肱二头肌充分拉伸。', '按建议的次数重复。'],
  'YReverse_Cable_Curl': ['身体站直,用正握(掌心朝下)、肩宽的握法握住连接低位滑轮的杠铃附件。确保手肘贴近躯干。这就是起始姿势。', '保持上臂固定,呼气的同时收缩肱二头肌弯举杠铃。只有前臂应该移动。继续弯举直到肱二头肌完全收缩、杠铃到肩部高度。挤压肌肉,在收缩位保持一秒。', '吸气,慢慢把杠铃放回起始姿势。', '按建议的次数重复。'],
  'YReverse_Flyes': ['开始时俯卧在上斜凳上,胸部和腹部贴住斜板。双手各持一只哑铃,掌心相对(中立握)。', '双臂向前伸直,与凳面角度垂直。双腿保持固定,前脚掌用力压地。这就是起始姿势。', '保持手肘微屈,呼气的同时将哑铃沿弧线向两侧打开。提示:试着夹紧肩胛骨,以获得最佳锻炼效果。', '手臂应抬起直到与地面平行。', '感受收缩,吸气,慢慢把哑铃放回起始姿势。', '按建议的次数重复。'],
  'YReverse_Flyes_With_External_Rotation': ['开始时俯卧在30度角的上斜凳上,胸部和腹部贴住斜板。', '双手各持一只哑铃,掌心朝下对着地面。双臂应在身前,与凳面角度垂直。提示:手肘应有微屈。双腿保持固定,前脚掌用力压地(脚跟不应触地)。这就是起始姿势。', '保持手肘微屈,呼气的同时将哑铃沿弧线向两侧打开。', '举起哑铃时,手腕应外旋90度,从掌心朝下(正握)转为掌心相对(中立握)。提示:试着夹紧肩胛骨,以获得最佳锻炼效果。', '手臂应抬起直到与头部齐平。', '感受收缩,吸气,慢慢把哑铃放回起始姿势。', '按建议的次数重复。'],
  'YReverse_Grip_BentOver_Rows': ['身体站直,用反握(掌心朝上)握住杠铃。', '膝盖微屈,从腰部俯身向前,保持背部挺直,直到躯干几乎与地面平行。提示:保持抬头。杠铃应垂在正前方,双臂垂直于地面和躯干。这就是起始姿势。', '保持躯干固定,呼气时提起杠铃,手肘贴近身体,前臂除了握杠外不用力。在顶端收缩位,挤压背部肌肉并保持一秒。', '吸气,慢慢把杠铃放回起始姿势。', '按建议的次数重复。'],
  'YReverse_Machine_Flyes': ['调整手柄,让它们完全位于最后方。选择合适的重量,调整座椅高度使手柄与肩同高。双手掌心朝内握住手柄。这就是起始姿势。', '以半圆形轨迹把双手向两侧后方拉开,收缩三角肌后束。', '整个动作中手臂保持微屈,所有动作都发生在肩关节。', '在动作后方停顿,慢慢把重量放回起始姿势。'],
  'YReverse_Plate_Curls': ['开始时站直,双手握住一片杠铃片,手臂完全伸直。采用正握(掌心朝下),手指扣住杠铃片的粗糙面,拇指扣住光滑面。注意:为获得最佳效果,在11点和1点方向握住杠铃片。', '双脚与肩同宽,杠铃片应在大腿根部附近。这就是起始姿势。', '呼气,缓慢向上弯举杠铃片,保持手肘内收、上臂固定,直到肱二头肌与前臂相触。此时杠铃片应与躯干对齐。', '感受收缩一秒,吸气,开始把重量放回起始姿势。', '按建议的次数重复。'],
  'YReverse_Triceps_Bench_Press': ['仰卧在平凳上。用窄距反握(约肩宽)把杠铃从架上取下,手臂伸直锁定,将杠铃垂直举在身前。这就是起始姿势。', '吸气,缓慢下放,直到感觉到杠铃触到胸中部。提示:与普通卧推不同,要让手肘始终贴近躯干,以最大化肱三头肌的参与。', '停顿一秒后,呼气,用肱三头肌发力把杠铃推回起始姿势。在收缩位锁定手臂,保持一秒,然后再次缓慢下放。提示:下放时间应至少是推起时间的两倍。', '按规定次数重复动作。', '完成后,把杠铃放回架上。'],
  'YRhomboidsSMR': ['仰卧在地面上。把泡沫轴垫在上背部下方,双臂在胸前交叉,肩部前伸。这就是起始姿势。', '髋部抬离地面,把体重压到泡沫轴上。一次向一侧转移重心,在中背和上背来回滚动。在紧张点停留10-30秒。'],
  'YRickshaw_Carry': ['把框架放到起点,装上合适的重量。站在框架中央,握住手柄,脚跟发力蹬地将框架提起。确保挺胸、抬头、背部挺直。', '立即开始以快速、受控的小步快走。保持挺胸、目视前方,确保持续呼吸。到达终点后把框架放回地面。'],
  'YRickshaw_Deadlift': ['给框架装上想要的重量。站在两个手柄正中。双脚约与髋同宽。屈髋握住手柄,让肩胛骨前伸。', '双脚和握姿就位后,深吸一口气,然后下放髋部、屈膝。头部目视前方,挺胸、背部弓起,开始用脚跟发力把重量向上拉起。重量升起时,夹紧肩胛骨,同时髋部向前顶。', '屈髋下放重量,引导它回到地面。'],
  'YRocket_Jump': ['以放松站姿开始,双脚与肩同宽,双臂贴近身体。', '开始时半蹲,然后以尽可能大的力量向上爆发跳起。', '全身充分伸展,尽量向上伸展到头顶上方。落地时用双腿吸收冲击。'],
  'YRocking_Standing_Calf_Raise': ['出于安全考虑,这个动作最好在深蹲架内进行。首先把杠铃架到最适合你身高的高度。选好高度并装好片后,站到杠下,把杠铃放在肩后(颈部稍下方)。', '双臂在两侧扶住杠铃,先用腿发力把它从架上推起,同时挺直躯干。', '离开深蹲架,采用与肩同宽的中等站距,脚尖微微外展。始终保持抬头,低头会让你失去平衡。同时保持背部挺直,膝盖微屈,绝不锁死。这就是起始姿势。', '呼气,尽可能高地伸展脚踝,收缩小腿肌肉,提起脚跟。确保膝盖始终保持不动。任何时候都不应有屈膝(除了定位时的那一点微屈)。在开始下放前,在收缩位保持一秒。', '吸气,弯曲脚踝下放脚跟,直到小腿充分拉伸,慢慢回到起始姿势。', '呼气,收缩小腿前侧的胫骨肌,抬起脚尖。', '保持一秒,吸气,把脚尖放回地面。', '按建议的次数重复。'],
  'YRocky_PullUps_Pulldowns': ['掌心朝前,用宽握距抓住引体向上杠。', '双臂伸直在身前握住杠铃、保持所选握距,躯干后倾约30度,同时下背形成弧度、挺胸。这就是起始姿势。', '把肩膀和上臂向下向后拉,将躯干拉起,直到杠铃触到上胸。这一阶段呼气。提示:到达完全收缩位时,专注于挤压背部肌肉。上身应在空间中保持稳定,只有手臂在动。前臂除了握杠外不做任何其他工作。', '在收缩位保持一秒后,吸气,慢慢把躯干放回起始姿势,直到手臂完全伸直、背阔肌充分拉伸。', '现在重复上述动作,只是这次上升时躯干保持挺直,杠铃触到颈后而不是上胸。提示:头部微微前倾,这样能帮助你正确完成这部分动作。', '回到起始姿势后,按计划规定的次数重复这个练习。'],
  'YRomanian_Deadlift': ['把杠铃放在身前地面上,用略宽于肩的正握(掌心朝下)握住。提示:根据使用的重量,可能需要护腕,也可能需要垫高平台以获得更好的活动范围。', '膝盖微屈,保持小腿垂直、髋部后坐、背部挺直。这就是起始姿势。', '始终保持背部和手臂完全挺直,呼气,用髋部发力提起杠铃。提示:动作不应过快,而应平稳受控。', '完全站直后,把髋部向后推来下放杠铃,膝盖只微屈,不像深蹲那样。提示:动作开始时深吸一口气并挺胸。下放时屏住呼吸,完成动作时呼气。', '按建议的次数重复。'],
  'YRomanian_Deadlift_from_Deficit': ['站立,手持杠铃垂在身前,手臂伸直。可以站在垫高平台上以加大活动范围。', '先微屈膝盖,然后屈髋,臀部尽可能向后移,躯干尽可能下放(以柔韧性为限)。背部应始终保持完全伸展,杠铃应始终贴着腿。如果做得正确,腘绳肌应有强烈的牵拉感。', '反向动作回到起始姿势。'],
  'YRope_Crunch': ['跪在装有绳索附件的绳索器械前1-2英尺(约30-60厘米)处。', '选好合适的重量后,双手举过头顶抓住绳索。起始姿势中躯干应保持直立。', '开始时屈曲脊柱,把绳索向下拉的同时试着让肋骨靠近双腿。', '在动作底部停顿,然后慢慢回到起始姿势。', '这个动作可以加转体或向一侧做,以刺激腹斜肌。'],
  'YRope_Jumping': ['双手各握跳绳的一端。把绳放在身后地面上。抬起双臂把绳从头顶甩到身前。绳子落地时跳过去。找到一个可以保持的稳定甩绳节奏。可以用不同的速度和技巧来增加变化。', '跳绳刺激有趣、考验协调性,而且需要大量能量。一个150磅(约68公斤)的人跳绳30分钟大约消耗350卡路里,而跑步消耗超过450卡路里。'],
  'YRope_StraightArm_Pulldown': ['把绳索挂到高位滑轮上,选好重量。距滑轮几英尺站立,双脚前后错开,双手握住绳索。从髋部前倾,保持背部挺直,双臂在身前向上伸直。这就是起始姿势。', '保持手臂伸直,伸展肩部,把绳索下拉到大腿处。', '在动作底部停顿,挤压背阔肌。', '回到起始姿势,不要让配重完全落到片堆上。'],
  'YRound_The_World_Shoulder_Stretch': ['双腿并拢站直,手持一根健身棒或扫帚杆。', '在髋部后方以宽于肩的握距握住杆。掌心朝下,拇指朝外。', '慢慢把手臂从脑后向上抬起。如果抬不动,不要硬来。'],
  'YRowing_Stationary': ['开始时坐上划船机。确保脚跟舒服地抵在脚踏底部,绑带系紧。如有需要,选择想用的程序。坐直,从髋部向前俯身。', '使用划船机时动作分三个阶段。第一阶段是身体前移:膝盖弯曲贴近胸口,上身微微前倾但保持良好姿态。接着蹬脚踏、伸直双腿,同时把双手拉向上腹部,并向后挤压肩膀。为避免背部拉伤,主要用腿部和髋部肌肉发力。', '回程阶段只需伸直手臂、屈膝,身体再次前移,过渡回第一阶段。'],
  'YRunners_Stretch': ['最容易的进入方式是:先站起来,一条腿向后伸,慢慢把躯干下放到地面。', '保持前脚脚跟贴地(如果抬起来了,把另一条腿再往后挪)。', '双手放在前腿两侧。要加深拉伸效果,可以把臀部向上推向天花板,再逐渐放回地面。这样会拉伸后腿的髋屈肌,以及前腿的腘绳肌和臀部。'],
  'YRunning_Treadmill': ['开始时踏上跑步机,从菜单中选择想要的选项。多数跑步机有手动设置,也可以选择跑步程序。通常可以输入年龄和体重来估算运动消耗的卡路里。可以调整坡度来改变训练强度。', '跑步机方便、有心血管锻炼效果,而且通常比户外跑的冲击小。一个150磅(约68公斤)的人以每小时8英里跑30分钟消耗超过450卡路里。跑步时保持正确姿态,只在必要时扶扶手,例如下机或查看心率时。'],
  'YSandbag_Load': ['装载沙袋或其他物件时,先把器械放在距装载平台一段距离处,通常50英尺(约15米)。', '先提起沙袋。沙袋非常难抓,提起方式因沙袋而异。尽量环抱它,伸展髋部和膝盖把它提得很高。通常不允许扛上肩。', '尽可能快地移动到平台,伸展髋、膝、踝把它尽可能举高,装载到平台上,确保它不会掉下来。', '回到起点取下一个沙袋,重复直到完成该项目。'],
  'YScissor_Kick': ['开始时仰卧,背部贴地(可选:垫训练垫)。双臂向两侧完全伸直,掌心朝下。注意:整个过程中手臂应保持不动。', '膝盖微屈,抬起双腿,让脚跟离地约6英寸(约15厘米)。这就是起始姿势。', '左腿抬到约45度角,同时右腿下放,直到脚跟离地约2-3英寸(约5-8厘米)。', '交换动作:抬起右腿,放下左腿。做这个动作时记得呼吸。', '按建议的次数重复。'],
  'YScissors_Jump': ['摆出箭步蹲姿势:一脚在前、膝盖弯曲,后膝几乎触地。', '确保前膝位于脚掌中线正上方。双腿同时伸展,尽可能高地跳起,摆动双臂借力。', '跳到最高点时交换双腿位置,前腿移到后面,后腿移到前面。', '落地时以箭步蹲姿势用双腿吸收冲击,然后重复。'],
  'YSeated_Band_Hamstring_Curl': ['把弹力带固定在贴近地面的位置,在距它几英尺处放一张长凳。', '坐在凳上,把弹力带套在脚踝后方,从双腿伸直开始。这就是起始姿势。', '屈膝,把双脚拉向长凳。可能需要微微后仰,以免双脚碰到地面。', '动作完成时停顿,然后慢慢回到起始姿势。'],
  'YSeated_Barbell_Military_Press': ['坐在军事推举凳上,杠铃放在头后。可以让保护者把杠铃递给你(这样对肩袖更友好),或者自己用正握(掌心朝前)小心地取杠。提示:握距应宽于肩,杠铃下放时前臂与上臂之间应呈90度角。', '以正确的握距取杠后,锁定手臂把杠举过头顶。保持在大约肩部高度、头部稍前方。这就是起始姿势。', '吸气,慢慢把杠下放到锁骨处。', '呼气,把杠推回起始姿势。', '按建议的次数重复。'],
  'YSeated_Barbell_Twist': ['开始时坐在平凳末端,杠铃放在大腿上。双脚应与肩同宽。', '掌心朝下握住杠铃,双手间距宽于肩。把杠铃举过头顶,直到手臂完全伸直。', '把杠铃下放到头后,直到它贴住颈根。这就是起始姿势。', '双脚和头部保持不动,腰部向两侧转动,让腹斜肌感受到收缩。只转到腰部能承受的幅度。过度拉伸或转动太远可能导致受伤。提示:用缓慢受控的动作。', '向一侧转体时呼气,回到起始姿势时吸气。', '按建议的次数重复。'],
  'YSeated_BentOver_OneArm_Dumbbell_Triceps_Extension': ['坐在平凳末端,单手持哑铃,采用中立握(掌心朝向自己)。', '膝盖微屈,从腰部俯身向前,保持背部挺直,直到躯干几乎与地面平行。保持抬头。', '持哑铃的上臂应贴近躯干并与躯干对齐(抬起直到与地面平行,前臂朝下,双手握铃)。提示:前臂与上臂之间应有90度角。这就是起始姿势。', '保持上臂固定,呼气,用肱三头肌发力抬起重量,直到前臂与地面平行、整条手臂伸直。和许多手臂练习一样,只有前臂在动。', '顶端收缩一秒后,吸气,慢慢把哑铃放回起始姿势。', '按规定次数重复动作。', '换手臂,重复练习。'],
  'YSeated_BentOver_Rear_Delt_Raise': ['在平凳前方放两只哑铃,铃片朝前。', '坐在凳端,双腿并拢,哑铃在小腿后方。', '保持背部挺直,从腰部俯身去拿哑铃。拿起时掌心应相对。这就是起始姿势。', '保持躯干前倾固定、手肘微屈,呼气,把哑铃向正侧方抬起,直到双臂与地面平行。(注意:避免摆动躯干或把手臂向后带,应向两侧打开。)', '顶端收缩一秒后,慢慢把哑铃放回起始姿势。', '按建议的次数重复。'],
  'YSeated_BentOver_TwoArm_Dumbbell_Triceps_Extension': ['坐在平凳末端,双臂各持一只哑铃,采用中立握(掌心朝向自己)。', '膝盖微屈,从腰部俯身向前,保持背部挺直,直到躯干几乎与地面平行。保持抬头。', '持铃的上臂应贴近躯干并与躯干对齐(抬起直到与地面平行,前臂朝下,双手握铃)。提示:前臂与上臂之间应有90度角。这就是起始姿势。', '保持上臂固定,呼气,用肱三头肌发力抬起重量,直到前臂与地面平行、整条手臂伸直。和许多手臂练习一样,只有前臂在动。', '顶端收缩一秒后,吸气,慢慢把哑铃放回起始姿势。', '按规定次数重复动作。'],
  'YSeated_Biceps': ['坐在地面上,屈膝,搭档站在你身后。双臂向后伸直,掌心相对。搭档会握住你的手腕。这就是起始姿势。', '试着屈肘发力,搭档则防止手臂产生任何实际移动。', '10-20秒后,放松手臂,搭档轻轻把你的手腕向上拉,拉伸肱二头肌。一定要让搭档知道拉伸到什么程度合适,以防受伤或过度拉伸。'],
  'YSeated_Cable_Rows': ['这个练习需要一台带V形把手的低位滑轮划船器。注意:V形把手让你可以采用掌心相对的中立握。要进入起始姿势,先坐上器械,双脚踩在前方踏板或横杆上,确保膝盖微屈、没有锁死。', '保持背部自然对齐,俯身抓住V形把手。', '手臂伸直向后拉,直到躯干与双腿成90度角。背部应微弓,挺胸。把杠握在身前时,背阔肌应有明显的拉伸感。这就是该练习的起始姿势。', '保持躯干固定,手臂贴近躯干向后拉,直到触到腹部。做这个动作时呼气。此时应用力挤压背部肌肉。保持这个收缩一秒,吸气,慢慢回到起始位置。', '按建议的次数重复。'],
  'YSeated_Cable_Shoulder_Press': ['把重量调到合适水平,坐下,握住手柄。上臂与身体约成90度,抬头挺胸。手肘也应弯到约90度。这就是起始姿势。', '开始时伸展手肘,把两个手柄在头顶上方推到一起。', '顶端停顿后,把手柄放回起始姿势。确保绳索保持张力。', '也可以让背部离开靠垫,交替手臂来做这个动作。'],
  'YSeated_Calf_Raise': ['坐在器械上,脚趾踩在踏板的较低位置,脚跟悬出踏板外。按照本章开头的内容选择脚尖朝向(朝前、朝内或朝外)。', '把大腿前侧放到压腿垫下,垫子需要根据大腿高度调整。现在把手放在压腿垫上,防止它向前滑。', '用脚跟向上顶起压杆,松开安全杆。这就是起始姿势。', '弯曲脚踝慢慢下放脚跟,直到小腿充分拉伸。做这个动作时吸气。', '呼气,尽可能高地伸展脚踝,收缩小腿,提起脚跟。顶端收缩保持一秒。', '按建议的次数重复。'],
  'YSeated_Calf_Stretch': ['在训练垫上坐直。', '屈起一条腿,把脚放在地面上以稳定躯干。', '伸直另一条腿,勾脚踝。', '用弹力带、毛巾,或者够得到的话直接用手,把脚趾拉向自己。保持10-20秒,然后换边。'],
  'YSeated_CloseGrip_Concentration_Barbell_Curl': ['坐在平凳上,杠铃或曲杆放在身前两腿之间。双腿分开、屈膝,双脚踩地。', '用手拿起杠铃,把上臂后侧放在大腿内侧上方(距膝前约3.5英寸处)。这个练习需要窄于肩宽的反握。提示:手臂应完全伸直,杠铃应高于地面。这就是起始姿势。', '保持上臂固定,呼气,收缩肱二头肌向前上方弯举。只有前臂应该移动。继续弯举直到肱二头肌完全收缩、杠铃到肩部高度。挤压肱二头肌,在收缩位保持一秒。', '吸气,慢慢把杠铃放回起始姿势。提示:任何时刻都要避免摆动动作。', '按建议的次数重复。'],
  'YSeated_Dumbbell_Inner_Biceps_Curl': ['坐在平凳末端,双手各持一只哑铃,手臂自然下垂。手肘应贴近躯干。', '旋转手掌,让掌心朝内呈中立位。这就是起始姿势。', '保持上臂固定,把哑铃向外向上弯举,举起时手掌向外转,前臂与三角肌外侧保持一条线。提示:', '只有前臂应该移动。继续弯举直到肱二头肌完全收缩、哑铃到肩部高度。挤压肱二头肌,在收缩位保持一秒。', '吸气,慢慢把哑铃放回起始姿势。下放哑铃时记得旋转手臂,以便回到中立握。', '按建议的次数重复。'],
  'YSeated_Dumbbell_PalmsDown_Wrist_Curl': ['先把两只哑铃放在平凳前方的地面上。', '坐在平凳边缘,双腿约与肩同宽。确保双脚踩在地面上。', '用双手拿起两只哑铃,让前臂贴在大腿上,掌心朝下。手腕应悬在大腿边缘外。', '呼气,向上弯举手腕。', '吸气,慢慢把手腕放回起始姿势。确保动作的这一阶段吸气。提示:前臂应保持不动,做这个练习只需要手腕活动。', '按建议的次数重复。', '完成后,把哑铃放回地面。'],
  'YSeated_Dumbbell_PalmsUp_Wrist_Curl': ['先把两只哑铃放在平凳前方的地面上。', '坐在平凳边缘,双腿约与肩同宽。确保双脚踩在地面上。', '用双手拿起两只哑铃,让前臂贴在大腿上,掌心朝上。手腕应悬在大腿边缘外。', '呼气,向上弯举手腕。', '吸气,慢慢把手腕放回起始姿势。确保动作的这一阶段吸气。提示:前臂应保持不动,做这个练习只需要手腕活动。', '按建议的次数重复。', '完成后,把哑铃放回地面。'],
  'YSeated_Dumbbell_Press': ['拿起两只哑铃,坐在军事推举凳或带靠背的多功能凳上,把哑铃竖立放在大腿上。', '用大腿依次把哑铃借力翻起到两侧肩部高度。', '旋转手腕,让掌心朝前。这就是起始姿势。', '呼气,把哑铃向上推起,直到顶端两只哑铃相触。', '停顿一秒后,吸气,慢慢回到起始姿势。', '按建议的次数重复。'],
  'YSeated_Flat_Bench_Leg_PullIn': ['坐在凳上,双腿在身前伸直、略低于水平,双手扶住凳边。躯干应向后倾约45度。这就是起始姿势。', '把膝盖收向身体,同时躯干向膝盖靠近。做这个动作时呼气。', '停顿一秒后,吸气,回到起始姿势。', '按建议的次数重复。'],
  'YSeated_Floor_Hamstring_Stretch': ['坐在垫上,右腿在身前伸直,左腿屈膝,脚掌抵住右大腿内侧。', '从髋部向前俯身,伸手去够脚踝,直到腘绳肌有拉伸感。保持15秒,然后换另一侧重复。'],
  'YSeated_Front_Deltoid': ['坐直在地面上,屈腿,搭档站在你身后。双臂向两侧伸直,掌心朝下。试着把手臂尽可能向后移,搭档握住你的手腕。这就是起始姿势。', '保持手肘伸直,试着把手臂向前移,搭档轻轻限制你,10-20秒内不产生实际移动。', '现在放松肌肉,让搭档轻轻加大肩部和胸部的拉伸。保持10-20秒。'],
  'YSeated_Glute': ['坐姿屈膝,把一只脚踝搭在对侧膝盖上。搭档会站在你身后。现在身体前倾,搭档用手顶住你的肩膀。这就是起始姿势。', '试着向后推躯干10-20秒,搭档防止你的躯干产生任何实际移动。', '现在放松肌肉,搭档轻轻向前推你的躯干,加大拉伸,持续10-20秒。'],
  'YSeated_Good_Mornings': ['在力量架中放一个箱子。保险杆设到合适高度。先站到杠下,把杠放在肩后,不要压在斜方肌上。夹紧肩胛骨,手肘向前转,试着把杠铃在肩上压弯。', '把杠从架上取下,下背保持紧绷弓起。头部保持目视前方。背部、肩部和核心紧绷,膝盖和臀部向外打开开始下蹲。髋部后坐,直到坐到箱子上。这就是起始姿势。', '保持杠铃稳定,在髋部尽可能向前俯身。如果把保险杆设在与地面平行的位置,失败时你不仅有保护,而且知道该在哪里停。', '在保险杆上方稍作停顿,反向动作,直到躯干直立。'],
  'YSeated_Hamstring': ['坐姿双腿伸直,搭档站在你身后。现在身体前倾,搭档用手顶住你的肩膀。这就是起始姿势。', '试着向后推躯干10-20秒,搭档防止你的躯干产生任何实际移动。', '现在放松肌肉,搭档轻轻向前推你的躯干,加大拉伸,持续10-20秒。'],
  'YSeated_Hamstring_and_Calf_Stretch': ['用腰带、绳子或弹力带套住一只脚。坐下,双腿伸直。这就是起始姿势。', '微微前倾,拉动带子把脚趾向后拉。保持这个姿势10-20秒,然后用另一条腿重复。'],
  'YSeated_Head_Harness_Neck_Resistance': ['把颈部挂带放在平凳末端的地面上。选好重量后,坐在平凳末端,双脚间距宽于肩,脚尖朝外。', '慢慢把躯干前移,直到几乎与地面平行。用双手把头套牢靠地戴在头上。提示:确保重量片仍放在地面上,以免颈部受力。现在双手抓住重量,同时把躯干抬回几乎垂直于地面的位置。注意:做这个练习时头部和躯干需微微前倾。', '现在把双手放在膝盖上。这就是起始姿势。', '吸气,慢慢低头,直到下巴触到胸上部。', '呼气,把颈部带回起始姿势。', '按建议的次数重复。'],
  'YSeated_Leg_Tucks': ['坐在凳上,双腿在身前伸直、略低于水平,双手扶住凳边。躯干应向后倾约45度。这就是起始姿势。', '把膝盖收向身体,同时躯干向膝盖靠近。做这个动作时呼气。', '停顿一秒后,吸气,回到起始姿势。', '按建议的次数重复。'],
  'YSeated_OneArm_Dumbbell_PalmsDown_Wrist_Curl': ['坐在平凳上,右手持一只哑铃。', '双脚平踩地面,间距略宽于肩。', '身体前倾,把右前臂放在右大腿上方,掌心朝下。提示:确保手背搭在膝盖上。这就是起始姿势。', '紧紧握住哑铃,尽可能向下放低。做这个动作时吸气。', '呼气,收缩前臂,尽可能高地弯举哑铃。在再次下放前保持收缩一秒。提示:唯一的活动应发生在手腕处。', '按建议的次数完成,换手臂重复动作。'],
  'YSeated_OneArm_Dumbbell_PalmsUp_Wrist_Curl': ['坐在平凳上,右手持一只哑铃。', '双脚平踩地面,间距略宽于肩。', '身体前倾,把右前臂放在右大腿上方,掌心朝上。提示:确保手腕正面搭在膝盖上。这就是起始姿势。', '紧紧握住哑铃,尽可能向下放低。做这个动作时吸气。', '呼气,收缩前臂,尽可能高地弯举哑铃。在再次下放前保持收缩一秒。提示:唯一的活动应发生在手腕处。', '按建议的次数完成,换手臂重复动作。'],
  'YSeated_Onearm_Cable_Pulley_Rows': ['要进入起始姿势,先坐上器械,双脚踩在前方踏板或横杆上,确保膝盖微屈、没有锁死。', '保持背部自然对齐,俯身用左臂以掌心朝下的握法抓住单把手附件。', '手臂伸直向后拉,直到躯干与双腿成90度角。背部应微弓,挺胸。把杠握在身前时,背阔肌应有明显的拉伸感。右臂可以放在腰侧。这就是该练习的起始姿势。', '保持躯干固定,手臂贴近躯干向后拉,同时旋转手腕,等手到腹部时转为中立位(掌心朝向躯干)。做这个动作时呼气。此时应用力挤压背部肌肉。', '保持这个收缩一秒,吸气,慢慢回到起始位置。提示:回到起始姿势时记得旋转手腕,让掌心重新朝下。', '按建议的次数重复,然后用右手做同样的动作。'],
  'YSeated_Overhead_Stretch': ['在训练垫上坐直。', '双脚脚掌相对,脚放在髋部前方6-8英寸(约15-20厘米)处。', '一只手放在身旁的地面上,另一只手放在头后。', '向天花板抬起手肘,同时躯干向另一侧倾斜。保持10-20秒,然后换边。'],
  'YSeated_PalmUp_Barbell_Wrist_Curl': ['双手掌心朝上握住杠铃,双手间距约与肩同宽。', '双脚平踩地面,间距略宽于肩。', '身体前倾,把前臂放在大腿上方,掌心朝上。提示:确保手腕正面搭在膝盖上。这就是起始姿势。', '吸气,紧紧握住杠铃,尽可能向下放低。', '呼气,屈曲前臂,尽可能高地弯举杠铃。顶端保持收缩一秒。提示:只有手腕应该移动。'],
  'YSeated_PalmsDown_Barbell_Wrist_Curl': ['双手掌心朝下握住杠铃,双手间距约与肩同宽。', '双脚平踩地面,间距略宽于肩。', '身体前倾,把前臂放在大腿上方,掌心朝下。提示:确保手背搭在膝盖上。这就是起始姿势。', '吸气,紧紧握住杠铃,尽可能向下放低。', '呼气,屈曲前臂,尽可能高地弯举杠铃。顶端保持收缩一秒。提示:只有手腕应该移动。'],
  'YSeated_Side_Lateral_Raise': ['拿起两只哑铃,坐在平凳末端,双脚稳稳踩地。掌心朝内握住哑铃,手臂伸直垂在身体两侧。这就是起始姿势。', '保持躯干固定(不要摆动),手肘微屈、双手微微前倾(像往杯子里倒水一样),把哑铃向两侧举起。继续向上直到手臂与地面平行。做这个动作时呼气,顶端停顿一秒。', '吸气,慢慢把哑铃放回起始姿势。', '按建议的次数重复。'],
  'YSeated_Triceps_Press': ['坐在有靠背的凳上,双手握住一只哑铃,举过头顶、手臂伸直。提示:更好的做法是让别人递给你,尤其是哑铃很重的时候。重量应落在掌心,拇指环绕。掌心应朝内。这就是起始姿势。', '保持上臂贴近头部(手肘内收)并垂直于地面,以半圆形轨迹把重量下放到头后,直到前臂触到肱二头肌。提示:上臂应保持不动,只有前臂移动。做这一步时吸气。', '用肱三头肌发力把哑铃举回起始姿势。做这一步时呼气。', '按建议的次数重复。'],
  'YSeated_TwoArm_PalmsUp_LowPulley_Wrist_Curl': ['在装有杠铃或曲杆附件的低位滑轮器械前放一张长凳。', '把长凳挪到合适距离,使你把把手拉到大腿上方时,配重片被拉起、绳索产生张力。', '现在双手掌心朝上,以肩宽握距握住把手。', '后退坐到凳上,双脚约与肩同宽,稳稳踩地。', '身体前倾,把前臂放在大腿上,手背搭在膝盖上方。这就是起始姿势。', '吸气,紧紧握住杠铃,尽可能向下放低。', '呼气,收缩前臂,尽可能高地弯举杠铃。提示:只有手腕应该移动,前臂不动。', '顶端收缩一秒后,吸气回到起始姿势。', '按建议的次数重复。'],
  'YSeeSaw_Press_Alternating_Side_Press': ['双手各持一只哑铃,身体站直。', '把哑铃翻举(提起)到胸/肩高度,然后旋转手腕,让掌心朝向你,就像准备做阿诺德推举一样。这就是起始姿势。', '现在开始把左臂向头顶伸展,同时旋转手腕,上升时掌心朝前。举起重量时手肘也应打开。同时,身体要从髋部向对侧弯曲。提示:如果动作做得正确,看起来就像你试着用左臂去够身体右上方的什么东西。做这个动作时呼气。', '到达顶端位置后吸气。然后,重量完全伸展过头顶、身体向右侧弯曲时,开始向左侧做动作。', '按建议的次数重复。'],
  'YShotgun_Row': ['在低位绳索上挂一个单把手。', '选好合适的重量后,后退几英尺,采用前后分开的大跨步站姿。手臂应伸直,肩部前伸。这就是起始姿势。', '通过后收肩部、屈肘来完成动作。拉动时旋后手腕,随着动作进行把掌心转向上方。', '短暂停顿后,回到起始姿势。'],
  'YShoulder_Circles': ['肩膀放松,手臂自然垂在身侧(若坐着可放在腿上),轻轻向前、向上、向后、向下转动肩膀。', '反向转动。这个练习可以交替肩膀做,也可以两肩同时做。'],
  'YShoulder_Press__With_Bands': ['开始时踩住弹力带,使张力从手臂伸直处开始。抓住手柄,把它们提到两侧肩部高度。', '旋转手腕,让掌心朝前。手肘应弯曲,上臂和前臂与躯干对齐。这就是起始姿势。', '呼气,把手柄向上推举,直到手臂在头顶完全伸直。'],
  'YShoulder_Raise': ['手臂放松垂在身侧,把肩膀向上耸向耳朵,然后放下来。'],
  'YShoulder_Stretch': ['左臂横过身体伸向右侧,保持伸直。'],
  'YSide_HopSprint': ['站在锥桶或栏架的一侧。', '开始这个训练:侧向跳过障碍物,落地后反弹跳回起点。', '以最快速度按规定的次数跳跃,最后一次落地后冲刺一小段距离来完成这个训练。'],
  'YSide_Lateral_Raise': ['拿起两只哑铃,躯干挺直站立,哑铃垂在身侧、手臂伸直,掌心朝向自己。这就是起始姿势。', '保持躯干固定(不要摆动),手肘微屈、双手微微前倾(像往杯子里倒水一样),把哑铃向两侧举起。继续向上直到手臂与地面平行。做这个动作时呼气,顶端停顿一秒。', '吸气,慢慢把哑铃放回起始姿势。', '按建议的次数重复。'],
  'YSide_Laterals_to_Front_Raise': ['站立姿势,双手各持一只哑铃垂在身侧。这就是起始姿势。', '保持手肘微屈,把哑铃从正前方抬起至肩部高度,避免任何摆动或借力。', '在动作顶端,保持手臂伸直,把哑铃移到身前。', '用受控的动作下放哑铃。', '下一次重复时,先把哑铃在身前抬到肩部高度,再把哑铃向两侧移动。', '把哑铃放回起始姿势。'],
  'YSide_Leg_Raises': ['站在椅子旁边,可以扶着椅子作支撑。单腿站立。这就是起始姿势。', '保持腿伸直,尽可能向侧上方抬起,然后摆回下方,让它交叉过另一条腿。', '重复这个摆动动作5-10次,并逐渐加大活动幅度。'],
  'YSide_Lying_Groin_Stretch': ['先右侧卧，右膝在身前弯曲以稳定躯干。', '头枕在右手或右肩上；左腿上抬，用手托住膝盖后方（较容易）或脚部（较困难）。', '将左膝拉向左侧肩膀，同时把脚或膝盖向下压向地面；想加强拉伸可伸直左腿，然后换边。'],
  'YSide_Neck_Stretch': ['肩膀放松开始，轻轻将头向肩部倾斜。', '用手在头部一侧轻轻施压，辅助拉伸。'],
  'YSide_Standing_Long_Jump': ['双脚与髋同宽、呈运动站姿站立，抬头挺胸，膝髋微屈，此为起始姿势。', '身体向右倾斜，通过髋、膝、踝发力伸展跳向空中，双臂摆动引领动作，尽可能向右跳远。', '保持面向同一方向落地，双脚与髋同宽，用下肢缓冲落地的冲击。'],
  'YSide_To_Side_Chins': ['掌心朝前、宽握握住引体向上杆。', '双臂在身前伸直、宽握横杠，躯干向后倾约30度，同时下背部弓出弧度、挺胸，此为起始姿势。', '向左倾斜，将肩膀和上臂向下向后收，拉起躯干直到横杠几乎触到上胸，此阶段呼气；提示：到达完全收缩位置时集中挤压背部肌肉，上躯干在空间中应保持稳定（不要摆动），只有手臂移动，前臂除握杠外不做任何其他工作。', '收缩一秒钟后，吸气回到起始姿势。', '现在向右倾斜，将肩膀和上臂向下向后收，拉起躯干直到横杠几乎触到上胸，此阶段呼气；提示：到达完全收缩位置时集中挤压背部肌肉，上躯干在空间中应保持稳定，只有手臂移动，前臂除握杠外不做任何其他工作。', '收缩一秒钟后，吸气回到起始姿势。', '重复第3至第6步，直到每侧完成规定的次数。'],
  'YSide_Wrist_Pull': ['这个拉伸站立时效果最好；左臂交叉过身体中线，右手在髋部高度握住左手腕，以左臂弯曲的姿势开始拉伸。', '如图慢慢伸直、拉动并抬起手臂至肩部高度；应感觉拉伸源自背部而非肩部，不要过度拉扯肩关节，然后换边。'],
  'YSide_to_Side_Box_Shuffle': ['站在箱子一侧，左脚踩在箱子中间。', '开始时跳起越过箱子到另一侧，右脚落在箱顶、左脚落在地面，摆动双臂辅助移动。', '继续在箱子两侧来回交叉跳。'],
  'YSingleArm_Cable_Crossover': ['先把滑轮调到高位，选好阻力，双手各握一个手柄。', '向前迈步站到两个滑轮前方，双臂在身前伸直、双手在身前合拢；前倾时抬头挺胸，双脚前后分立，此为起始姿势。', '左臂保持不动，右臂向侧方展开，肘部保持微屈；右臂应大致与肩同高、与身体垂直。', '将手臂拉回起始位置，让手回到身体中线。', '在起始姿势保持一秒钟，然后在另一侧重复；按规定的次数继续来回交替。'],
  'YSingleArm_Linear_Jammer': ['把杠铃装进地雷管或在角落固定牢固，加载合适的重量。', '将杠铃从地面抬起，用单手或双手送到肩上，采用宽站距，此为起始姿势。', '伸展肘部把重量向上推起开始动作；动作要爆发有力，充分伸展髋和膝以产生最大力量。', '回到起始姿势。'],
  'YSingleCone_Sprint_Drill': ['这个练习训练快速步法；需要一只锥桶；开始时站在锥桶旁，一臂在后、一臂在前。', '双脚尽可能快地碎步点地，双臂摆动配合；围着锥桶绕圈，膝盖抬高，步频猛烈。', '绕锥桶三圈后休息。'],
  'YSingleLeg_High_Box_Squat': ['在深蹲架里放一只箱子，在箱子上方固定好弹力带或绳索。', '站在箱子前面，踏上箱子至完全站立，另一条腿保持悬空；抓住弹力带保持平衡。', '同一条腿继续反复踏上踏下，然后换到另一侧。'],
  'YSingleLeg_Hop_Progression': ['在身前摆一排锥桶；放松站立，单腿保持平衡，另一条腿的膝盖抬起，此为起始姿势。', '单腿向前跳，用同一条腿起跳和落地越过锥桶。', '利用预蹲反弹动作，从一个锥桶跳到下一个。', '跳到尽头后转身，换另一条腿跳回来。'],
  'YSingleLeg_Lateral_Hop': ['站在锥桶或栏架一侧；进入起始姿势时单腿站立、膝盖微屈。', '开始时先做一个预蹲反弹，侧向跳过锥桶。', '用起跳腿落地，并立即从该腿反弹，跳回起始位置。', '继续来回侧跳。'],
  'YSingleLeg_Leg_Extension': ['坐上器械并调整到合适位置：垫子应抵住小腿下部但不要接触脚踝；调整座椅使转轴与膝盖对齐；选择适合自己的重量。', '保持良好体态，单腿完全伸直，在动作顶端停顿。', '不要让配重完全停顿，回到起始姿势，保持肌肉张力。', '重复至规定的次数。'],
  'YSingleLeg_Stride_Jump': ['站在箱子一侧，内侧脚踩在箱顶靠近边缘处。', '开始时双臂向上摆动，同时上方的腿发力蹬箱，尽可能向上跳起，另一侧膝盖向上顶。', '落在起始时的位置，用内侧腿缓冲冲击。'],
  'YSingle_Dumbbell_Raise': ['宽站距站立，双手握住哑铃的头部而不是手柄；手臂伸直垂于腰间，此为起始姿势。', '手臂保持伸直，将重量举到肩部以上；整个动作中躯干和髋部保持不动。', '回到起始姿势，按建议次数重复。'],
  'YSingle_Leg_Butt_Kick': ['开始时单腿站立，另一侧膝盖弯曲抬起，此为起始姿势。', '利用预蹲反弹，伸展支撑腿的髋、膝、踝向上起跳。', '立即屈膝，用起跳腿的脚跟尽量去碰臀部。', '将腿收回到髋部下方半屈位置落地；整个练习中另一条腿应基本保持原位置。'],
  'YSingle_Leg_Pushoff': ['站在地面上，一只脚踩在箱子上，脚跟靠近箱子边缘。', '用踩箱的脚蹬离，通过伸展髋和膝尽量获得最大高度。', '同一只脚落在箱顶，另一只脚回到起始位置。'],
  'YSitUp': ['躺在地面上，双脚勾在固定物下或让同伴压住双脚；膝盖弯曲。', '双手放在头后，十指交叉扣紧，此为起始姿势。', '抬起上体，与大腿形成想象中的V形；此阶段呼气。', '感到收缩一秒钟后，吸气将上体放回起始姿势。', '按建议次数重复。'],
  'YSit_Squats': ['双脚与肩同宽站立，此为起始姿势。', '屈膝屈髋开始动作，臀部向后坐。', '继续下蹲到中途、仍高于平行的位置，然后迅速反转动作回到起始姿势；重复5-10次。'],
  'YSkating': ['轮滑是一项有趣的活动，能有效改善心肺耐力和肌肉耐力，需要较好的平衡与协调能力；必须先学习包括转弯和刹车在内的基础技巧，并佩戴护具避免受伤。', '可以用舒适的速度连续滑30分钟；想要心肺挑战，可做间歇滑行——每5分钟快速滑2分钟，用剩下3分钟恢复；体重约150磅的人在舒适速度下滑行30分钟约消耗175卡路里，与快走相当。'],
  'YSled_Drag__Harness': ['开始时给雪橇加载目标重量并系好牵引带；可以用手柄拉动、使用背带，或将牵引带系在负重腰带上。', '无论向前还是向后拉，都朝移动方向倾斜身体，通过伸展髋和膝前进。'],
  'YSled_Overhead_Backward_Walk': ['用绳索或链条给雪橇装上双手柄，加载较轻的重量。', '面对雪橇后退，直到绳索有张力；双手在头顶正上方伸直，肘部伸展，此为起始姿势。', '保持双臂举过头顶向后走，避免突然的动作。'],
  'YSled_Overhead_Triceps_Extension': ['用链条或绳索给雪橇装上双手柄，加载适当的重量。', '背对雪橇走开，直到绳索有张力；双手并拢举过头顶，掌心相对；肘部朝上并弯曲，此为起始姿势。', '伸展肘部使手臂伸直；确保大臂保持原位以孤立肱三头肌。', '完全伸直后向前迈步拉紧绳索以消除松弛；双脚可前后分立以增加稳定。'],
  'YSled_Push': ['给推式雪橇加载目标重量。', '呈运动姿态，双臂完全伸直握住手柄，身体前倾靠在雪橇上；尽可能快地推动雪橇，重点伸展髋和膝以强化后链肌群。'],
  'YSled_Reverse_Flye': ['用绳索或链条给雪橇装上双手柄，加载较轻的重量。', '面对雪橇后退到绳索有张力；双手在腰高位置、手臂伸直握住两个手柄，膝盖微屈、抬头挺胸，此为起始姿势。', '肘部不弯曲，将手柄向上并向两侧拉开，做带外旋的反向飞鸟；动作中掌心朝前。', '回到起始姿势，后退几步拉紧绳索以消除松弛。'],
  'YSled_Row': ['用绳索或链条给雪橇装上双手柄，加载适当的重量；面对雪橇后退，直到绳索有张力。', '双手各握一个手柄，膝盖微屈、抬头挺胸，手臂伸直开始动作。', '开始动作时屈肘并后收肩胛骨，将雪橇拉向自己。', '后退一两步让绳索有张力，然后重复。'],
  'YSledgehammer_Swings': ['这个练习需要轮胎和大锤；站在轮胎前约两英尺处，前后分立站稳，握紧大锤。', '如果你是右撇子，左手握在锤柄底部，右手握在靠近锤头的位置。', '挥锤向上时右手滑向锤头，向下砸时右手滑下与左手会合；尽全力砸向轮胎，并控制大锤从轮胎上反弹的幅度。', '换另一侧重复。'],
  'YSmith_Incline_Shoulder_Raise': ['在史密斯机下方放上斜凳；把杠铃调到躺下时手臂几乎完全伸直能够到的高度；选好重量后躺在斜凳上，确保肩膀正好在杠铃正下方。', '用与肩同宽的正握（掌心朝前）握法将杠铃从架上取下，肘部微屈、直举于身体上方，此为起始姿势。', '呼气，将杠铃向上举起直到手臂完全伸直；注意：收缩应集中在肩部。', '停顿一秒钟后，吸气将杠铃放回起始姿势。', '按规定的次数重复该动作。', '完成后将杠铃放回架子。'],
  'YSmith_Machine_Behind_the_Back_Shrug': ['杠铃调到大腿高度，加载适当的重量。', '站在杠铃后方，用与肩同宽的正握握法握住杠铃并解锁；身体站直、抬头挺胸、手臂伸直，此为起始姿势。', '双肩笔直向上耸起开始动作；动作过程中手臂和手腕不要弯曲。', '短暂停顿后将重量放回起始姿势。', '重复至规定的次数，然后合上挂钩把重量挂回架上。'],
  'YSmith_Machine_Bench_Press': ['在史密斯机下方放平凳；把杠铃调到躺下时手臂几乎完全伸直能够到的高度；选好重量后躺在平凳上，用宽于肩的正握握法解锁杠铃，手臂锁定、直举于身体上方，此为起始姿势。', '吸气，缓慢下放直到感觉到杠铃触到胸部中间。', '停顿一秒钟后，呼气用胸肌发力将杠铃推回起始姿势；在收缩位置锁定手臂，保持一秒钟再开始缓慢下放；提示：下放时间至少应是上推时间的两倍。', '按规定的次数重复该动作。', '完成后将杠铃锁回架子。'],
  'YSmith_Machine_Bent_Over_Row': ['把史密斯机上的杠铃调到膝盖下方约2英寸的高度。', '膝盖微屈，从腰部前倾躯干、背部保持平直，直到躯干几乎与地面平行；提示：保持抬头。', '现在用正握握法抓住杠铃并从史密斯机架上解锁；让杠铃垂直悬垂在身前，手臂伸直、与地面和躯干垂直，此为起始姿势。', '躯干保持不动，呼气拉起杠铃，肘部贴近身体，前臂除握杠外不用力；在顶部收缩位置挤压背部肌肉并保持一秒钟。', '吸气，慢慢将重量放回起始姿势。', '按建议次数重复。'],
  'YSmith_Machine_Calf_Raise': ['在史密斯机杠铃下方放一块垫木或杠铃片；把杠铃调到最符合你身高的位置；选定高度并加载后，用前脚掌踩上垫片，把杠铃放在肩后。', '双手掌心朝前握住杠铃，转动杠铃将其解锁，此为起始姿势。', '用前脚掌发力将脚跟抬到尽可能高，顶部收缩时绷紧小腿；膝盖保持伸展；保持收缩一秒钟后再开始下放。', '吸气，慢慢放下脚跟回到起始姿势。', '按建议次数重复。'],
  'YSmith_Machine_CloseGrip_Bench_Press': ['在史密斯机下方放平凳；把杠铃调到躺下时手臂几乎完全伸直能够到的高度；选好重量后躺在平凳上，用约与肩同宽的窄距正握（掌心朝前）握法解锁杠铃，手臂锁定、直举于身体上方，此为起始姿势。', '吸气，缓慢下放直到感觉到杠铃触到胸部中间；提示：与常规卧推不同，全程让肘部贴近躯干，以最大化肱三头肌的参与。', '停顿一秒钟后，呼气用肱三头肌发力将杠铃推回起始姿势；在收缩位置锁定手臂，保持一秒钟再开始缓慢下放；提示：下放时间至少应是上推时间的两倍。', '按规定的次数重复该动作。', '完成后将杠铃锁回架子。'],
  'YSmith_Machine_Decline_Press': ['在架子里放好下斜凳，使杠铃位于胸部上方；加载适当的重量并坐上凳子。', '转动杠铃将其解锁，完全伸展手臂；背部微微反弓、肩胛骨后收，此为起始姿势。', '屈臂将杠铃下放到胸部开始动作。', '短暂停顿后，伸展手臂将重量推回起始姿势。', '完成规定次数后，转动杠铃把重量挂回架上。'],
  'YSmith_Machine_Hang_Power_Clean': ['把杠铃调到膝盖高度并加载适当的重量。', '在宽于肩的位置用正握握法抓住杠铃并解开机器的锁扣；抬头挺胸、手臂完全伸直；肘部朝外、肩膀后展下沉；髋部后坐，把张力加载到腘绳肌，此为起始姿势。', '爆发式伸展髋和膝开始动作，加速冲向杠铃；这一阶段确保手臂保持伸直。', '完全伸展后，再次屈髋屈膝，降低接杠位置。', '此时让手臂弯曲，肘部绕杠转动，把杠铃接到肩上。', '伸展髋和膝站起，杠铃架在肩上完成动作。'],
  'YSmith_Machine_Hip_Raise': ['在架子里放好凳子并加载适当的重量；躺在凳上，脚底抵住杠铃；解锁杠铃并伸直双腿；可能需要用手辅助；为增加稳定可抓住史密斯机两侧，此为起始姿势。', '通过旋转骨盆、弯曲脊柱开始动作，把髋部从凳子上抬起；整个动作中膝盖保持微屈。', '短暂停顿后，将髋部放回凳面。', '重复至规定的次数。'],
  'YSmith_Machine_Incline_Bench_Press': ['在史密斯机下方放上斜凳；把杠铃调到躺下时手臂几乎完全伸直能够到的高度；选好重量后躺在斜凳上，确保上胸与杠铃对齐；用宽于肩的正握（掌心朝前）握法解锁杠铃，手臂锁定、直举于身体上方，此为起始姿势。', '吸气，缓慢下放直到感觉到杠铃触到上胸。', '停顿一秒钟后，呼气用胸肌发力将杠铃推回起始姿势；在收缩位置锁定手臂，保持一秒钟再开始缓慢下放；提示：下放时间至少应是上推时间的两倍。', '按规定的次数重复该动作。', '完成后将杠铃放回架子。'],
  'YSmith_Machine_Leg_Press': ['把史密斯机杠铃调到离地面几英尺的位置，确保搁在安全架上；加载适当重量后躺到杠铃下方，双脚中部踩在杠铃上、膝盖收向胸口，此为起始姿势。', '双脚发力推动杠铃向上、伸展髋和膝开始动作；不要把膝盖锁死。', '在动作顶端短暂停顿后回到起始姿势。'],
  'YSmith_Machine_OneArm_Upright_Row': ['杠铃调到大腿高度，加载适当的重量。', '宽握杠铃并解锁，另一只手离开杠铃；抬头挺胸站直，手臂伸直，此为起始姿势。', '屈肘、肘部朝外抬起大臂开始动作，直到大臂与地面平行。', '短暂停顿后将重量放回起始姿势。', '重复至规定的次数，然后合上挂钩把重量挂回架上。'],
  'YSmith_Machine_Overhead_Shoulder_Press': ['开始时在史密斯机下方放平凳（最好带靠背）；调整杠铃高度，使坐在平凳上时手臂几乎完全伸直才能碰到杠铃。', '高度调好后，坐在杠铃稍靠后的位置，使鼻尖到杠铃成一条想象中的直线；双脚固定；掌心朝前抓住杠铃、解锁并举起，使手臂完全伸直，此为起始姿势。', '吸气，慢慢将杠铃下放到与下巴齐平。', '然后呼气，用肩部力量将杠铃推回起始姿势。', '按建议次数重复。'],
  'YSmith_Machine_Pistol_Squat': ['开始时先把杠铃调到最符合你身高的位置；站到杠下，把杠铃横放在肩后。', '双手掌心朝前握住杠铃，解锁后伸展双腿将它抬离架子。', '一只脚向前迈出约12英寸到杠铃前方；另一条腿向前伸直并悬空；始终目视前方，脊柱保持中立或轻微反弓，此为起始姿势。', '保持良好体态，屈膝屈髋下蹲，下到柔韧性允许的最低位置。', '在底部短暂停顿后，用脚跟发力、伸展膝和髋回到起始姿势。'],
  'YSmith_Machine_Reverse_Calf_Raises': ['调整史密斯机杠铃到适合你的身高，并在杠铃正下方对齐一个抬高的平台。', '站在平台上，脚跟固定在平台顶部，前脚掌伸出平台外；脚尖朝前，双脚与肩同宽。', '保持脚的位置不变，把肩膀置于杠铃下方，伸展髋和膝把杠铃顶起直到躯干直立；膝盖保持微屈，绝不锁死，此为起始姿势；提示：背上的杠铃只用于保持平衡。', '呼气，尽可能高地伸展脚趾并绷紧小腿，抬起前脚掌；确保膝盖全程保持静止，任何时刻都不弯曲；保持收缩一秒钟后再开始下放。', '吸气，放下前脚掌和脚趾，慢慢回到起始姿势。', '按建议次数重复。'],
  'YSmith_Machine_Squat': ['开始时先把杠铃调到最符合你身高的高度；选定高度并加载后，站到杠下，把肩后（颈稍下方）横在杠上。', '双手在两侧握住杠铃（掌心朝前），解锁后先用腿部发力、同时挺直躯干，把杠铃抬离架子。', '用与肩同宽的中等站距调整双腿位置，脚尖微微外展；全程抬头、背部保持挺直，此为起始姿势；注：这里使用针对全面发展型的中等站距，你也可以选择脚位章节中讨论的三种站距中的任意一种。', '保持挺直姿势、抬头，屈膝慢慢下放杠铃；继续下放直到大腿与小腿的夹角略小于90度（即大腿低于与地面平行的位置）；此阶段吸气；提示：如果动作正确，膝盖前方应与脚尖成一条想象中的垂直直线；如果膝盖超过这条线（超过脚尖），就是在给膝盖施加不当压力，动作不正确。', '呼气，主要用脚跟蹬地，同时重新伸直双腿，把杠铃推回起始姿势。', '按建议次数重复。'],
  'YSmith_Machine_StiffLegged_Deadlift': ['开始时把史密斯机杠铃调到约大腿中部的高度；选定高度并加载后，用与肩同宽的正握（掌心朝前）握法抓住杠铃；如果重量较大，可能需要护腕。', '手臂完全伸直、背部挺直把杠铃提起；躯干直立，双脚与肩同宽或更窄；膝盖微屈，此为起始姿势。', '膝盖保持不动，背部挺直、从腰部前屈，把杠铃下放到脚尖上方；像要捡地上的东西一样继续前移，直到腘绳肌有拉伸感；此阶段呼气。', '一感觉到腘绳肌拉伸，就伸展髋部和腰部，把躯干重新挺直回到起始姿势；此阶段吸气。', '按建议次数重复。'],
  'YSmith_Machine_Upright_Row': ['开始时把史密斯机杠铃调到约大腿中部的高度；选定高度并加载后，用与肩同宽的正握（掌心朝前）握法抓住杠铃；如果重量较大，可能需要护腕。', '把杠铃提起并完全伸直手臂，背部挺直；肘部微屈，此为起始姿势。', '呼气，用肩部侧束发力将杠铃上提；上移时杠铃贴近身体；继续提起直到几乎触到下巴；提示：肘部应带动动作，上提时肘部始终高于前臂；同时保持躯干静止，在动作顶端停顿一秒钟。', '慢慢将杠铃放回起始姿势；此阶段吸气。', '按建议次数重复。'],
  'YSnatch': ['双脚与肩同宽站立，杠铃横放在脚尖与脚掌连接处的正上方。', '掌心朝下的握法，屈膝、背部保持平直，用宽于肩的握距抓住杠铃；髋部下沉，身体像要坐到椅子上一样下降，此为起始姿势。', '双脚像踩在移动平台上一样蹬地，同时开始把杠铃贴近双腿向上拉起。', '杠铃到达大腿中部时，双腿蹬地，爆发式伸展身体到完全伸直。', '耸起肩膀向后收，同时把杠铃向上带起，肘部向两侧抬起并尽量长时间保持肘部高于杠铃。', '在杠铃升到足够高、可以控制的高度时，用一个快速有力的动作把身体钻到杠下，锁住手臂、将杠铃举过头顶，同时进入深蹲姿势。', '最后从深蹲中站起完成举重；结束时双脚应在一条线上，手臂完全伸直，把杠铃举在头顶。'],
  'YSnatch_Balance': ['双脚呈发力站姿开始，杠铃架在肩后，双手用宽距抓握握法。', '膝盖快速预蹲再蹬起，把杠铃向上弹起，同时猛力把身体钻到杠下，双脚切换成接杠站姿。', '在深蹲接近底部的位置接住杠铃，手臂在头顶锁定；躯干保持竖直，髋部下沉到双腿之间。', '继续下蹲到全蹲深度，然后站起；小心放下重量。'],
  'YSnatch_Deadlift': ['抓举硬拉强化抓举的第一段拉力；开始时宽握横杠、杠铃放在举重台上；双脚在髋部正下方，脚尖外展；下蹲靠近杠铃，背部保持绝对伸展、目视前方。', '用脚跟发力蹬地、抬高髋部开始动作；杠铃通过膝盖前，背部角度保持不变。', '此时髋部前顶、身体后仰；然后反向动作，将杠铃放回台面。'],
  'YSnatch_Shrug': ['宽握开始，杠铃悬垂于大腿中部位置；可用勾握或正握；背部挺直，身体微微前倾。', '把肩膀耸向耳侧；虽然这个练习通常可以加载比抓举更重的重量，但要避免过载到动作变慢的程度。'],
  'YSnatch_from_Blocks': ['把加载好的杠铃放在目标高度的箱子或架上；宽握横杠；双脚在髋部正下方，根据需要脚尖外展；髋部下沉、挺胸、目视前方；肩膀在杠铃稍前方、肘部朝外，此为起始姿势。', '从前脚掌前部发力蹬地开始第一段拉力，把杠铃从箱子上提起。', '通过伸展髋、膝、踝过渡到第二段拉力，尽可能快地把杠铃向上带；杠铃贴近身体；在完全伸展的顶点耸肩，让肘部向两侧弯曲。', '双脚切入接杠站姿的同时，在把杠铃举过头顶的过程中猛力把身体拉向杠下；双脚应移到髋部外侧、按需外展；身体尽量低、手臂在头顶完全伸直接杠。', '保持杠铃位于脚跟前方连线上、抬头挺胸，用脚跟蹬地站起；小心把重量放回箱子上。'],
  'YSpeed_Band_Overhead_Triceps': ['这个练习需要把弹力带固定在地面；我们用了上斜凳，把弹力带固定在凳脚上，站在凳上进行；也可以改为踩住弹力带进行。', '开始时把弹力带拉到头后，用正握握住、肘部抬高，此为起始姿势。', '伸展肘部使手臂伸直，确保大臂保持原位。', '停顿后回到起始姿势。'],
  'YSpeed_Box_Squat': ['把弹力带系在杠铃两端并牢固地固定在地面附近；可能需要收短弹力带以获得足够的张力。', '使用合适高度的箱子；加载一个仍有训练难度但不会牺牲速度的重量，通常为单次最大重量的50%-70%。', '把杠铃放在上背，肩胛骨后收、背部反弓，从头到脚保持紧绷，此为起始姿势。', '出杠后站到箱子前方，髋部后坐坐到箱子上，确保下放受控、不要砸到箱面。', '短暂停顿后，爆发式离箱，伸展髋和膝。'],
  'YSpeed_Squats': ['这个练习最好在深蹲架内进行以保证安全；开始时先把杠铃调到最符合你身高的高度；选定高度并加载后，站到杠下，把肩后（颈稍下方）横在杠上。', '双手在两侧握住杠铃，先用腿部发力、同时挺直躯干，把杠铃抬离架子。', '离开架子，用与肩同宽的中等站距调整双腿位置，脚尖微微外展；全程抬头（低头会失去平衡）、背部保持挺直，此为起始姿势；注：这里使用针对全面发展型的中等站距，你也可以选择脚位章节中讨论的三种站距中的任意一种。', '保持挺直姿势、抬头，屈膝下放杠铃；继续下放直到大腿与小腿的夹角略小于90度（即大腿低于与地面平行的位置）；此阶段吸气；提示：如果动作正确，膝盖前方应与脚尖成一条想象中的垂直直线；如果膝盖超过这条线（超过脚尖），就是在给膝盖施加不当压力，动作不正确。', '呼气，主要用脚跟蹬地，重新伸直双腿时尽可能快地回到起始姿势，但不要借助惯性；注：应尽可能快地完成，但不能破坏标准动作、也不能借助惯性。', '按建议次数重复。'],
  'YSpider_Crawl': ['俯卧在地面开始；用手和脚趾支撑体重，双脚并拢、身体挺直；手臂弯曲成90度，此为起始姿势。', '抬起一只脚离地开始动作；外旋这条腿，把膝盖带向肘部，尽可能向前。', '把这条腿放回起始位置，换另一侧重复。'],
  'YSpider_Curl': ['先把杠铃放在牧师凳通常坐人的那部分上；确保杠铃对准放稳、保持平衡不会掉下来。', '移到牧师凳的前侧（手臂通常搁置的那一面），身体呈45度倾斜躺靠，躯干和腹部贴住牧师凳前侧。', '确保双脚（尤其是脚趾）稳稳踩在地面，把大臂放在牧师凳内侧的垫子上。', '用反握（掌心朝上）握法、约与肩同宽或略窄的间距抓住杠铃。', '慢慢向上举起杠铃并呼气；挤压肱二头肌，在收缩位置保持一秒钟。', '吸气，慢慢把杠铃放回起始姿势。', '按建议次数重复。'],
  'YSpinal_Stretch': ['坐在椅子上，背部挺直、双脚踩实地面。', '双手在头后交叉相扣，肘部打开、下巴内收。', '上体向一侧转体，尽力转到约3次的程度；然后前倾并转动躯干，让肘部够向膝盖内侧的地面。', '回到直立姿势，换另一侧重复。'],
  'YSplit_Clean': ['杠铃放在地面、贴近小腿，在双腿外侧用正握握法握住；髋部下沉、重心放在脚跟，背部挺直、目视前方、挺胸，肩膀在杠铃稍前方，此为起始姿势。', '脚跟发力蹬地、伸展膝盖开始第一段拉力；背部角度保持不变、手臂保持伸直；继续受控地把重量带过膝盖上方。', '接下来是第二段拉力，翻举加速的主要来源；杠铃接近大腿中部时开始伸展髋部；像起跳一样通过伸展髋、膝、踝加速，利用速度把杠铃向上带；不需要主动用手臂拉来加速；第二段拉力结束时身体应完全伸展、微微后仰，手臂仍保持伸直。', '达到完全伸展后，通过猛烈耸肩和屈臂、肘部向上向外，过渡到第三段拉力；在伸展顶点猛力把身体拉向下方，同时肘部绕杠转动。', '双脚前后分开接杠——一只脚猛力向前、一只脚向后；杠铃应架在伸展的肩上，轻触喉部、双手放松；继续下蹲到底部位置，这有助于后续站起。', '立即用脚跟发力蹬地站起，躯干保持直立、肘部抬高；站起时双脚并拢。'],
  'YSplit_Jerk': ['重量架在肩前站立，从预蹲开始；双脚在髋部正下方，屈膝但髋部不后移。', '只下蹲一点点，然后尽可能有力地反向蹬起；主要用脚跟发力产生尽可能大的速度和力量，杠铃离肩时确保头让开；脚离地的这一刻，必须尽快把双脚切换到接杠站姿。', '在双脚没有主动蹬地的短暂瞬间，向上推杠的力会把人向下压；双脚应切换到分腿站姿——一只脚在前、一只脚在后，膝盖半屈；手臂在头顶锁死接杠。', '回到站立姿势，双脚并拢。'],
  'YSplit_Jump': ['呈箭步蹲姿势：一只脚在前、膝盖弯曲，后膝几乎触地。', '确保前膝位于脚的中线上方。', '双腿伸展发力，尽可能向上跳，摆动双臂获得上升动力。', '跳起时双脚并拢，落地时再移回起始位置。', '回到起始姿势缓冲冲击。'],
  'YSplit_Snatch': ['加载好的杠铃放在地面开始；杠铃应贴近或触到小腿，宽握横杠；双脚在髋部正下方、按需外展；髋部下沉、挺胸、目视前方；肩膀在杠铃稍前方，此为起始姿势。', '从前脚掌前部发力蹬地开始第一段拉力，把杠铃从地面提起；杠铃通过膝盖前，背部角度保持不变。', '通过伸展髋、膝、踝过渡到第二段拉力，尽可能快地把杠铃向上带；杠铃贴近身体；在伸展顶点耸肩，让肘部向两侧弯曲。', '双脚切入接杠站姿的同时，在把杠铃举过头顶的过程中猛力把身体拉向杠下；双脚应猛力切换成分腿站姿——一只脚向前、一只脚向后；身体尽量低、手臂在头顶完全伸直接杠。', '保持杠铃位于脚跟前方连线上、抬头挺胸，用脚跟蹬地站起，双脚并拢。', '小心把重量放回地面。'],
  'YSplit_Squat_with_Dumbbells': ['呈前后分立站姿，后脚垫高、前脚在前。', '双手各持一只哑铃垂于体侧，此为起始姿势。', '屈膝屈髋下蹲开始动作；全程保持良好体态，前膝与脚保持一条直线。', '在动作底部用脚跟发力，伸展膝和髋回到起始姿势。'],
  'YSquat_with_Bands': ['把弹力带套在杠铃套筒上，固定到弹力带挂点、深蹲架或哑铃上，使其张力合适。', '站到杠下，把杠横在肩后；夹紧肩胛骨、肘部向前转，试着把杠在肩上掰弯；出杠时下背部收紧成弓，后退站好；双脚站宽，更侧重背部、臀大肌、内收肌和腘绳肌；目视前方。', '背部、肩部和核心保持紧绷，膝盖和臀部向外推开开始下蹲；髋部尽可能向后坐；理想情况下小腿应与地面垂直；杠位越低，躯干前倾越多才能保持杠在脚跟上方；继续下蹲直到低于平行（即髋部褶皱与膝盖顶端平齐）。', '重心保持在脚跟，双脚和膝盖向外推，头部引领动作向上蹬起；继续上升，从头到脚保持紧绷，直到回到起始姿势。'],
  'YSquat_with_Chains': ['设置链条：先把引导链绕过杠铃套筒；重链应用弹簧扣连接；调整引导链长度，使动作顶端仍有几节链环落在地面。', '站到杠下，把杠横在肩后；夹紧肩胛骨、肘部向前转，试着把杠在肩上掰弯；出杠时下背部收紧成弓，后退站好；双脚站宽，更侧重背部、臀大肌、内收肌和腘绳肌；目视前方。', '背部、肩部和核心保持紧绷，膝盖和臀部向外推开开始下蹲；髋部尽可能向后坐；理想情况下小腿应与地面垂直；杠位越低，躯干前倾越多才能保持杠在脚跟上方；继续下蹲直到低于平行（即髋部褶皱与膝盖顶端平齐）。', '重心保持在脚跟，双脚和膝盖向外推，头部引领动作向上蹬起；继续上升，从头到脚保持紧绷，直到回到起始姿势。'],
  'YSquat_with_Plate_Movers': ['开始时先把杠铃调到略低于肩部的高度；在深蹲架后方几英尺的地面放一片杠铃片；加载后站到杠下，把肩后横在杠上。', '双手握住杠铃，先用腿部发力、同时挺直躯干，把杠铃抬离架子。', '离开架子，采用宽站距、脚尖微微外展，一只脚踩在杠铃片上；全程抬头，此为起始姿势。', '屈膝屈髋缓慢下放杠铃；继续下放直到大腿与小腿的夹角略小于90度。', '呼气，伸展髋和膝，用脚跟蹬地推起杠铃。', '在动作顶端侧向迈步，把双脚并拢到杠铃片的另一侧。', '用内侧脚推动杠铃片，让它沿地面滑向你刚才站的位置。', '把内侧脚踩回杠铃片上，以宽站距开始下一次重复。'],
  'YSquats__With_Bands': ['开始时确保弹力带在身体左右两侧均匀分开；用双手抓住弹力带两侧，双脚踩在弹力带中间；双脚与肩同宽。', '握住弹力带时两侧高度应一致；本练习采用正握（掌心朝前），手柄应位于脸旁，此为起始姿势。', '呼气，慢慢屈膝下蹲，直到大腿与地面平行。', '呼气，用脚跟发力把身体推回起始姿势。', '按建议次数重复。'],
  'YStairmaster': ['开始时踏上台阶机，从菜单中选择想要的选项；可选择手动模式，也可选择程序模式；通常可以输入年龄和体重来估算运动中的热量消耗。', '按固定节奏上下踩动双腿，把踏板踩下去但不要踩到地面；建议扶稳扶手以免摔倒；扶手还可监测心率，帮助你保持在合适的强度。', '台阶机便捷、有心血管益处，冲击通常比户外跑步小；但通常比其他有氧器械累得多；体重约150磅的人在30分钟内通常可消耗超过300卡路里，而走路约消耗175卡路里。'],
  'YStanding_Alternating_Dumbbell_Press': ['双手各持一只哑铃站立；把哑铃举到肩部，掌心朝前、肘部朝外，此为起始姿势。', '伸出一臂把哑铃垂直向上推起，另一只手保持原位；动作过程中不要侧倾或甩动重量。', '短暂停顿后回到起始姿势。', '换另一侧重复，继续交替进行。'],
  'YStanding_Barbell_Calf_Raise': ['这个练习最好在深蹲架内进行以保证安全；开始时先把杠铃调到最符合你身高的高度；选定高度并加载后，站到杠下，把杠铃放在肩后（颈稍下方）。', '双手在两侧握住杠铃，先用腿部发力、同时挺直躯干，把杠铃抬离架子。', '离开架子，用与肩同宽的中等站距调整双腿位置，脚尖微微外展；全程抬头（低头会失去平衡）、背部保持挺直；膝盖保持微屈，绝不锁死，此为起始姿势；提示：为获得更大的活动范围，也可把前脚掌踩在木块上，但这种方式需要更好的平衡和稳固的木块。', '呼气，尽可能高地伸展脚踝并绷紧小腿，抬起脚跟；确保膝盖全程保持静止，任何时刻都不弯曲；保持收缩一秒钟后再开始下放。', '吸气，弯曲脚踝放下脚跟，直到小腿被充分拉伸，慢慢回到起始姿势。', '按建议次数重复。'],
  'YStanding_Barbell_Press_Behind_Neck': ['这个练习最好在深蹲架内进行，便于取杠；开始时先把杠铃调到最符合你身高的高度；选定高度并加载后，站到杠下，把肩后（颈稍下方）横在杠上。', '双手在两侧握住杠铃，先用腿部发力、同时挺直躯干，把杠铃抬离架子。', '离开架子，用与肩同宽的中等站距调整双腿位置，脚尖微微外展；练习过程中背部保持挺直，此为起始姿势。', '呼气，完全伸直双臂把杠铃举过头顶。', '保持收缩一秒钟，吸气将杠铃放回起始姿势。', '按建议次数重复。'],
  'YStanding_BentOver_OneArm_Dumbbell_Triceps_Extension': ['单手持哑铃、掌心朝向躯干，膝盖微屈，从腰部前倾躯干、背部保持平直，直到躯干几乎与地面平行；确保保持抬头。', '大臂贴近躯干并与地面平行，前臂指向地面、手握住重量；提示：前臂与大臂之间应为90度角，此为起始姿势。', '大臂保持不动，呼气用肱三头肌发力举起重量，直到前臂与地面平行、整条手臂伸直；和许多手臂动作一样，只有前臂移动。', '顶部收缩一秒钟后，吸气慢慢将哑铃放回起始姿势。', '按规定的次数重复该动作。', '换另一只手臂重复该练习。'],
  'YStanding_BentOver_TwoArm_Dumbbell_Triceps_Extension': ['双手各持一只哑铃、掌心朝向躯干，膝盖微屈，从腰部前倾躯干、背部保持平直，直到躯干几乎与地面平行；确保保持抬头；大臂贴近躯干并与地面平行，前臂指向地面、手握住重量；提示：前臂与大臂之间应为90度角，此为起始姿势。', '大臂保持不动，呼气用肱三头肌发力举起重量，直到前臂与地面平行、双臂完全伸直；和许多手臂动作一样，只有前臂移动。', '顶部收缩一秒钟后，吸气慢慢将哑铃放回起始姿势。', '按规定的次数重复该动作。'],
  'YStanding_Biceps_Cable_Curl': ['躯干直立站立，握住连接低位滑轮的弯举杆；与肩同宽握杆、肘部贴近躯干；掌心朝上（反握），此为起始姿势。', '大臂保持不动，呼气收缩肱二头肌弯举重量；只有前臂移动；继续弯举直到肱二头肌完全收缩、杠铃到肩部高度；挤压肌肉，在收缩位置保持一秒钟。', '吸气，慢慢将弯举杆放回起始姿势。', '按建议次数重复。'],
  'YStanding_Biceps_Stretch': ['双手在背后交握、掌心相对，伸直手臂后旋转，使掌心朝下。', '向上抬起手臂并保持，直到肱二头肌有拉伸感。'],
  'YStanding_Bradford_Press': ['把加载好的杠铃放上架子、置于肩部高度；用与肩同宽的正握握法，杠铃架在肩前，此为起始姿势。', '伸展肘部把杠铃推过头顶开始动作；杠铃移到头后时避免锁死肘部。', '把杠铃下放到头后，直到肘部成直角。', '伸展肘部把杠铃重新举回头顶。', '把杠铃下放回起始姿势。', '按这种方式交替，直到完成规定的次数。'],
  'YStanding_Cable_Chest_Press': ['把双滑轮调到胸部高度并选择适当的重量；站在绳索前方一两英尺处，双手各握一个手柄；双脚可前后分立以增加稳定。', '大臂呈90度角、肩胛骨并拢，此为起始姿势。', '身体其余部位保持不动，伸展肘部向前推出手柄，并在身前将双手合拢。', '在动作顶端停顿，回到起始姿势。'],
  'YStanding_Cable_Lift': ['在拉力架上装一个标准手柄，把绳索调到最低滑轮位置。', '侧身对着绳索，单手抓住手柄并远离拉力架；应站在离滑轮约一臂远的位置，让配重的张力拉紧绳索；伸出的手臂应与绳索对齐。', '双脚与肩同宽，下蹲用双手抓住手柄；手臂仍保持完全伸直。', '一个连贯动作把手柄向上拉过身体，直到双臂在头顶完全伸直。', '保持背部挺直、手臂贴近身体，转动后脚并伸直双腿，以获得完整的活动范围。', '收回手臂再收回身体，缓慢受控地回到中立姿势。', '重复到力竭。', '然后重新站位，在另一侧重复同样的动作序列。'],
  'YStanding_Cable_Wood_Chop': ['在拉力架上装一个标准手柄，把绳索调到最高滑轮位置。', '侧身对着绳索，单手抓住手柄并远离拉力架；应站在离滑轮约一臂远的位置，让配重的张力拉紧绳索；伸出的手臂应与绳索对齐。', '双脚与肩同宽，另一只手向上伸出，双手一起抓住手柄；手臂仍保持完全伸直。', '一个连贯动作把手柄向下拉过身体到前膝旁边，同时转动躯干。', '保持背部和手臂伸直、核心收紧，转动后脚并屈膝，以获得完整的活动范围。', '保持站姿和伸直的手臂，缓慢受控地回到中立姿势。', '重复到力竭。', '然后重新站位，在另一侧重复同样的动作序列。'],
  'YStanding_Calf_Raises': ['调整提踵机的垫杆，使其适合你的身高。', '把肩膀放在垫子下方，脚尖朝前（或使用章节开头介绍的另外两种姿势）；前脚掌固定在提踵块顶部，脚跟伸出块外；伸展髋和膝把垫杆顶起，直到躯干直立；膝盖保持微屈，绝不锁死；脚尖按章节开头所述朝前、朝外或朝内，此为起始姿势。', '呼气，尽可能高地伸展脚踝并绷紧小腿，抬起脚跟；确保膝盖全程保持静止，任何时刻都不弯曲；保持收缩一秒钟后再开始下放。', '吸气，弯曲脚踝放下脚跟，直到小腿被充分拉伸，慢慢回到起始姿势。', '按建议次数重复。'],
  'YStanding_Concentration_Curl': ['工作手持哑铃，身体前倾；工作臂垂直于地面悬垂、肘部朝外，此为起始姿势。', '大臂保持不动，屈肘弯举重量；在动作顶端收缩肱二头肌并停顿。', '把哑铃放回起始姿势。', '按规定的次数重复该动作。'],
  'YStanding_Dumbbell_Calf_Raise': ['躯干直立站立，双手各持一只哑铃垂于体侧；前脚掌踩在一块稳固的木板上（约2-3英寸高），脚跟伸出板外触地，此为起始姿势。', '脚尖朝前（均衡刺激各部位）、朝内（侧重外侧头）或朝外（侧重内侧头），呼气收缩小腿肌群，把脚跟抬离地面；顶部收缩保持一秒钟。', '吸气，慢慢放下脚跟回到起始姿势。', '按建议次数重复。'],
  'YStanding_Dumbbell_Press': ['双脚与肩同宽站立，双手各持一只哑铃；把哑铃举到头部高度，肘部张开约90度，此为起始姿势。', '保持严格技术、不用腿部借力也不后仰，伸展肘部将两只哑铃一起举到头顶正上方。', '停顿后慢慢回到起始姿势。'],
  'YStanding_Dumbbell_Reverse_Curl': ['开始时身体直立，双手各持一只哑铃，采用正握（掌心朝下）；手臂完全伸直、双脚与肩同宽，此为起始姿势。', '大臂保持不动，呼气收缩肱二头肌弯举重量；只有前臂移动；继续弯举直到肱二头肌完全收缩、哑铃到肩部高度；挤压肌肉，在收缩位置保持一秒钟。', '吸气，慢慢将哑铃放回起始姿势。', '按建议次数重复。'],
  'YStanding_Dumbbell_StraightArm_Front_Delt_Raise_Above_Head': ['双手持哑铃置于大腿前，掌心朝向大腿。', '手臂保持伸直、肘部微屈但锁定，此为起始姿势。', '呼气，以半圆弧轨迹将哑铃举过头顶、举至手臂长度。', '吸气，沿相同轨迹慢慢回到起始姿势。', '按建议次数重复。'],
  'YStanding_Dumbbell_Triceps_Extension': ['开始时站立，双手一起握住一只哑铃；双脚约与肩同宽；慢慢用双手举起哑铃过头，直到双臂完全伸直。', '重量应搁在掌心、拇指环绕；掌心朝上对着天花板，此为起始姿势。', '大臂贴近头部、肘部向内且垂直于地面，以半圆弧轨迹将重量下放到头后，直到前臂触到肱二头肌；提示：大臂保持不动，只有前臂移动；此阶段吸气。', '用肱三头肌发力将哑铃举回起始姿势；此阶段呼气。', '按建议次数重复。'],
  'YStanding_Dumbbell_Upright_Row': ['双手各持一只哑铃，采用略窄于肩的正握（掌心朝前）握法；哑铃搁在大腿上方；手臂伸直、肘部微屈，背部挺直，此为起始姿势。', '呼气，用肩部侧束发力上提哑铃；上移时哑铃贴近身体、肘部带动动作；继续提起直到几乎触到下巴；提示：肘部应带动动作，上提时肘部始终高于前臂；同时保持躯干静止，在动作顶端停顿一秒钟。', '慢慢将哑铃放回起始姿势；此阶段吸气。', '按建议次数重复。'],
  'YStanding_Elevated_Quad_Stretch': ['开始时站立，背部距长凳或台阶约两到三英尺。', '一条腿向后抬起，把脚放在台阶上——脚背或前脚掌均可，选最舒服的方式。', '支撑腿膝盖微屈，不要让该膝盖超过脚尖，然后换边。'],
  'YStanding_Front_Barbell_Raise_Over_Head': ['开始时身体直立、手持杠铃；掌心朝下，采用窄于肩的握距。', '双脚与肩同宽，肘部微屈，此为起始姿势。', '呼气，把杠铃向上举到头顶正上方；每次重复都要保持肘部微屈。', '感到收缩后，吸气将杠铃放回起始姿势。', '按建议次数重复。'],
  'YStanding_Gastrocnemius_Calf_Stretch': ['右脚跟踩在台阶上、膝盖伸直，身体前倾，用右手抓住右脚趾；左膝微屈、背部挺直。', '用左腿支撑体重，左手放在左大腿上。', '把右脚趾拉向膝盖方向，直到小腿有拉伸感。'],
  'YStanding_Hamstring_and_Calf_Stretch': ['先把腰带、弹力带或绳索绕在一只脚上；站立时把这只脚迈向前方。', '后腿弯曲，前腿保持伸直；抬起前脚的脚趾离开地面并向前倾身。', '用腰带拉动脚背，加大小腿的拉伸；保持10-20秒，然后换另一只脚重复。'],
  'YStanding_Hip_Circles': ['单腿站立，扶住一个竖直的支撑物。', '将悬空腿的膝盖抬至90度，此为起始姿势。', '尽量打开髋部，尝试用膝盖画一个大圆。', '缓慢完成若干次重复，然后换另一侧重复。'],
  'YStanding_Hip_Flexors': ['站直身体，脊柱保持竖直，左脚略在右脚前方。', '双膝弯曲，将右髋前压的同时抬起后脚跟离地。不过这个姿势难以获得充分深度的拉伸，因为很难在站立的同时放松髋屈肌，然后换另一侧重复。'],
  'YStanding_InnerBiceps_Curl': ['站姿，双手各持一只哑铃垂于体侧，肘部贴近躯干，双脚与肩同宽。', '转动手掌使掌心相对，呈中立握姿，此为起始姿势。', '上臂保持不动，呼气时收缩肱二头肌将重量向外弯举，手腕随之转动，当重量完全举起时变为掌心向上的旋后握姿。', '只有前臂应该移动，继续动作直到肱二头肌完全收缩、哑铃到达肩部高度。提示：保持前臂与三角肌外侧对齐。', '用力收紧肱二头肌，在收缩位置保持一秒钟。', '吸气时缓慢将哑铃放回起始位置，下放重量时记得转动手腕，回到中立握姿。', '按建议次数重复。'],
  'YStanding_Leg_Curl': ['调整器械压杆高度，身体前倾约30-45度俯卧（倾斜姿势更有利于腘绳肌发力），压杆垫放在右腿后侧（小腿下方几英寸处），右腿前侧贴住器械垫。', '保持躯干前倾，确保腿部完全伸展，握住器械两侧把手，脚尖朝前，此为起始姿势。', '呼气时将右腿尽可能向上弯举，大腿不要离开垫子，到达完全收缩位置后保持一秒钟。', '吸气时将腿放回起始位置，按建议次数重复。', '现在换左腿做同样的动作。'],
  'YStanding_Long_Jump': ['这个训练最好在沙地或其他柔软的落地面上进行，确保能够测量距离，双脚与肩同宽半蹲站立。', '利用大幅摆臂和腿部的预蹲反冲，尽可能向前跳远。', '落地时尽量让双脚落在身前，双腿尽可能向前伸展够远。', '测量落点到起点的距离，并记录成绩。'],
  'YStanding_LowPulley_Deltoid_Raise': ['站在低位滑轮划船器的右侧，左手横过身体，用正握（掌心向下）抓住低位滑轮上的单个把手，手臂自然放在身前，右手扶住器械以获得更好的支撑和平衡。', '确保背部挺直，双脚与肩同宽，此为起始姿势。', '呼气时左手横过身体向外抬起，直到举至肩部高度。', '在顶部感受收缩一秒钟，然后吸气开始缓慢将把手放回起始位置。', '按建议次数重复。', '换另一只手臂重复该动作。'],
  'YStanding_LowPulley_OneArm_Triceps_Extension': ['在低位滑轮器械旁用左臂抓住单个把手，转身背对器械，手臂完全伸直让把手位于体侧；然后用双手将把手举到头顶正上方，掌心朝前，上臂保持完全竖直（与地面垂直），右手扶住左肘帮助稳定，此为起始姿势。', '上臂贴近头部（肘部内收）并与地面垂直，以半圆弧轨迹将阻力降到头后，直到前臂碰到肱二头肌。提示：上臂保持不动，只有前臂移动，做这一步时吸气。', '用肱三头肌发力将单个把手举回起始位置，做这一步时呼气。', '按建议次数重复。', '换另一只手臂重复该动作。'],
  'YStanding_Military_Press': ['先把杠铃放在深蹲架上约胸部高度，选好重量后用正握（掌心向前）抓住杠铃，握距要宽于肩宽。', '膝盖微屈，将杠铃放在锁骨上，保持杠铃贴着胸部将其抬起，后退一步，双脚与肩同宽站立。', '以正确的握距拿起杠铃后，锁定手臂将杠铃举过头顶，保持在肩部高度并略在头前，此为起始姿势。', '吸气时缓慢将杠铃下放到锁骨位置。', '呼气时将杠铃举回起始位置。', '按建议次数重复。'],
  'YStanding_Olympic_Plate_Hand_Squeeze': ['开始时站直，双手用中立握姿（掌心相对）捏住杠铃片边缘，手臂伸直垂于体侧，双脚与肩同宽，此为起始姿势。', '下放杠铃片直到手指几乎伸直但还能握住重量，下放时吸气。', '呼气时收紧手指，将杠铃片提回起始位置。', '按计划中建议的次数重复。'],
  'YStanding_OneArm_Cable_Curl': ['在低位滑轮器械旁抓住单个把手，确保离器械足够远，让手臂承托重量。', '确保上臂固定不动，与地面垂直，肘部内收，掌心向前，另一只不发力手扶住腰部以保持平衡，此为起始姿势。', '上臂保持不动，呼气时缓慢将单个把手向上弯举，直到前臂碰到肱二头肌。提示：只有前臂应该移动。', '挤压肱二头肌保持收缩位置，然后吸气将单个把手放回起始位置。', '按建议次数重复。', '做这个动作时换另一只手臂进行。'],
  'YStanding_OneArm_Dumbbell_Curl_Over_Incline_Bench': ['站在上斜凳背面，就像要给别人做保护一样，单手持一只哑铃，用旋后握姿（掌心向上）将其横放在上斜凳上。', '不发力手扶在上斜凳的角部或侧面，胸部贴住斜凳顶端，双脚宽站距踩实地面，此为起始姿势。', '上臂保持不动，呼气时收缩肱二头肌将哑铃向上弯举，只有前臂移动；继续动作直到肱二头肌完全收缩、哑铃到达肩部高度，保持收缩位置一秒钟。', '吸气时缓慢将哑铃放回起始位置。', '按建议次数重复。', '做这个动作时换另一只手臂进行。'],
  'YStanding_OneArm_Dumbbell_Triceps_Extension': ['开始时站立，单手持一只哑铃，双脚约与肩同宽，然后将持铃手臂完全伸直举过头顶。提示：小指朝向天花板，掌心朝前，哑铃应在头顶上方。', '此为起始姿势。', '上臂贴近头部（肘部内收）并与地面垂直，以半圆弧轨迹将阻力降到头后，直到前臂碰到肱二头肌。提示：上臂保持不动，只有前臂移动，做这一步时吸气。', '用肱三头肌发力将哑铃举回起始位置，做这一步时呼气。', '按建议次数重复。', '换另一只手臂重复该动作。'],
  'YStanding_Overhead_Barbell_Triceps_Extension': ['开始时站立，用正握（掌心向前）握住杠铃或曲杆杠铃，双手间距窄于肩宽，双脚约与肩同宽。', '将杠铃举过头顶直到手臂完全伸直，肘部内收，此为起始姿势。', '上臂贴近头部、肘部内收并与地面垂直，以半圆弧轨迹将阻力降到头后，直到前臂碰到肱二头肌。提示：上臂保持不动，只有前臂移动，做这一步时吸气。', '用肱三头肌发力将杠铃举回起始位置，做这一步时呼气。', '按建议次数重复。'],
  'YStanding_PalmIn_OneArm_Dumbbell_Press': ['单手持一只哑铃，用中立握姿将手臂向侧面完全伸直，另一只手臂扶住上斜凳保持平衡。', '双脚与肩同宽，缓慢将哑铃举起直到手臂呈90度角。注意：前臂应与地面垂直，整个动作过程中保持中立握姿。', '缓慢将哑铃举起直到手臂完全伸直，此为起始姿势。', '吸气时下放重量，直到手臂再次呈90度角。', '感受收缩一秒钟，然后呼气将重量提回起始位置。记得扶住上斜凳并保持双脚位置以维持平衡。', '按建议次数重复。', '换另一只手臂重复该动作。'],
  'YStanding_PalmsIn_Dumbbell_Press': ['双手各持一只哑铃，用中立握姿将手臂向两侧完全伸直，双脚与肩同宽，缓慢将哑铃举起直到双臂呈90度角。注意：前臂应与地面垂直，此为起始姿势。', '整个动作过程中保持中立握姿，缓慢将哑铃举起直到手臂完全伸直。', '吸气时下放重量，直到手臂再次呈90度角。', '按建议次数重复。'],
  'YStanding_PalmsUp_Barbell_Behind_The_Back_Wrist_Curl': ['开始时站直，用正握（掌心朝后、背离臀部）将杠铃举在臀部后方、手臂伸直，双手与肩同宽。', '目视前方，双脚与肩同宽，此为起始姿势。', '呼气时以半圆弧轨迹向天花板方向弯屈手腕，缓慢将杠铃抬起。注意：这个动作中手腕应是唯一移动的身体部位。', '保持收缩一秒钟，然后吸气将杠铃放回起始位置。', '按建议次数重复。', '完成后屈膝将杠铃放回深蹲架或地面。提示：最方便的做法是从深蹲架上取放，或让搭档递给你。'],
  'YStanding_Rope_Crunch': ['将绳索挂在高位滑轮上，选择合适的重量。', '背对绳索塔架站立，双手将绳索拉过肩部，固定在胸前上部，此为起始姿势。', '屈曲脊柱发力，将重量尽可能向下卷压。', '在顶峰收缩处保持片刻，然后回到起始位置。'],
  'YStanding_Soleus_And_Achilles_Stretch': ['双脚与髋同宽站立，一只脚略微在前。', '双膝弯曲，保持后脚跟贴地，换另一侧重复。'],
  'YStanding_Toe_Touches': ['站立时身体前后留出空间。', '保持双腿伸直，从腰部弯曲，直到能放松地让上半身自然垂在身前，手臂和双手自然下垂，保持10到20秒。'],
  'YStanding_Towel_Triceps_Extension': ['开始时站立，双手握住毛巾一端，双臂完全伸直举过头顶，肘部内收、手臂与地面垂直、掌心相对，双脚与肩同宽，此为起始姿势。', '与搭档沟通，让他/她抓住毛巾另一端施加阻力；上臂贴近头部（肘部内收）并与地面垂直，以半圆弧轨迹将阻力降到头后，直到前臂碰到肱二头肌。提示：上臂保持不动，只有前臂移动，做这一步时吸气。', '用肱三头肌发力将毛巾举回起始位置，做这一步时呼气。', '按建议次数重复。'],
  'YStanding_TwoArm_Overhead_Throw': ['双脚与肩同宽站立，双手抱住药球，开始时膝盖微屈、身体后仰，将药球充分引到头部后方。', '屈髋发力，用全身力量将球猛烈向前抛出。', '药球可以抛给搭档或抛向墙壁，在弹回时接住。'],
  'YStar_Jump': ['以放松姿势开始，双脚与肩同宽，手臂贴近身体。', '启动动作时半蹲，然后尽可能高地爆发跳起，身体完全伸展，双腿和双臂向外张开。', '落地时将四肢收拢，用双腿缓冲冲击。'],
  'YStepup_with_Knee_Raise': ['双脚并拢，面向合适高度的跳箱或踏板站立，此为起始姿势。', '开始动作时左脚踩上踏板顶端，通过前腿伸髋伸膝站上跳箱，左脚站上后弯曲右侧膝盖和髋部，将右膝尽可能抬高。', '反向动作走下跳箱，然后换另一条腿重复整个流程。'],
  'YStep_Mill': ['开始时踏上台阶机，从菜单中选择所需模式，可以选手动设置或选择一个训练程序，通常可输入年龄和体重来估算运动消耗的热量；爬台阶时小心不要绊倒，建议始终握住扶手以防摔倒。', '台阶机方便、有益心肺，冲击通常比户外跑步小，燃脂效率却相近；它通常比其他有氧器械难度更大，一个150磅（约68公斤）的人30分钟可消耗超过300卡路里，而步行大约只消耗175卡路里。'],
  'YStiffLegged_Barbell_Deadlift': ['用正握（掌心向下）抓住杠铃，如果重量较大，可能需要佩戴护腕。', '躯干挺直，双脚与肩同宽或略窄站立，膝盖微微弯曲，此为起始姿势。', '膝盖保持不动，背部挺直，屈髋将杠铃下放到脚面上方，像要从地上捡东西一样继续前移，直到腘绳肌感到拉伸，做这个动作时吸气。', '伸髋将躯干重新挺直，回到起始位置，做这个动作时呼气。', '按建议次数重复。'],
  'YStiffLegged_Dumbbell_Deadlift': ['双手各持一只哑铃，手臂伸直垂于体侧。', '躯干挺直，双脚与肩同宽或略窄站立，膝盖微微弯曲，此为起始姿势。', '膝盖保持不动，背部挺直，屈髋将哑铃下放到脚面上方，像要从地上捡东西一样继续前移，直到腘绳肌感到拉伸，做这个动作时呼气。', '伸展髋部和腰部将躯干重新挺直，回到起始位置，做这个动作时吸气。', '按建议次数重复。'],
  'YStiff_Leg_Barbell_Good_Morning': ['出于安全考虑，这个动作最好在深蹲架内进行；先把杠铃放到与身高匹配的架位上，选好高度并装好重量后，走到杠铃下方，将肩部后方（略低于颈部）横跨在杠铃上。', '双臂在两侧扶住杠铃，先蹬腿发力同时挺直躯干，将杠铃从架上抬起。', '离开深蹲架，双脚采用与肩同宽的中等站距；始终保持抬头，低头会失去平衡，同时保持背部挺直，此为起始姿势。', '双腿保持不动，吸气时屈髋使躯干前倾，直到躯干与地面平行。', '呼气时抬起躯干回到起始位置，将杠铃举起。', '按建议次数重复。'],
  'YStomach_Vacuum': ['开始时站直，双脚与肩同宽，双手叉腰，此为起始姿势。', '缓慢尽量深吸气，然后尽可能呼气，同时尽量收腹并保持这个姿势，试着想象肚脐贴向脊柱。', '一次等长收缩约20秒，在保持的20秒内尽量正常呼吸，然后吸气让腹部回到起始状态。', '熟练后尝试将动作保持超过20秒。提示：可以逐步延长到40至60秒。', '按建议组数重复。'],
  'YStraightArm_Dumbbell_Pullover': ['将一只哑铃竖立在平凳上。', '确保哑铃稳稳放在凳子顶端，身体与长凳垂直躺下（躯干横跨凳子呈十字形），只有肩部躺在凳面上，臀部低于凳面，双腿弯曲、双脚踩实地面，头部也悬在凳外。', '双手握住哑铃，手臂伸直举在胸部正上方，双掌抵住哑铃一侧的下端，此为起始姿势。 注意：务必确保动作使用的哑铃牢固，配重片松动的哑铃可能散架砸到脸上。', '保持手臂伸直，吸气时以弧线轨迹将重量缓慢降到头后，直到胸部感到拉伸。', '此时沿下放时的弧线轨迹将哑铃带回起始位置，做这个动作时呼气。', '在起始位置保持重量一秒钟，按规定的次数重复动作。'],
  'YStraight_Bar_Bench_Mid_Rows': ['将装好重量的杠铃放在长凳一端，站在杠铃后方的凳面上，用中等握距正握抓杠，臀部后移、挺胸，保持脊柱中立，此为起始姿势。', '后收肩胛骨、屈肘将杠铃拉向躯干，动作要有控制，不要猛拉。', '短暂停顿后缓慢将杠铃放回起始位置，确保完全下放到位。'],
  'YStraight_Raises_on_Incline_Bench': ['将一根杠铃放在上斜凳头部后方的地面上。', '俯卧在长凳上，用正握握姿、保持手臂伸直将杠铃从地面拿起，让杠铃自然垂直下垂，此为起始姿势。', '开始时保持手臂伸直，将杠铃举向头部前方。', '回到起始位置。'],
  'YStride_Jump_Crossover': ['站在跳箱侧面，内侧脚踩在箱子上，靠近边缘。', '开始动作时双臂向上摆动，同时踩箱腿发力蹬起，尽可能向上跳高，并尝试将另一侧膝盖向上顶。', '落到跳箱另一侧、与起始相反的方位，原本踩箱的脚现在落地，另一只脚踩上箱子。', '重复动作，跳回另一侧。'],
  'YSumo_Deadlift': ['先把装好重量的杠铃放在地面，站近杠铃让杠铃经过双脚中部；双脚站得非常宽，靠近卡箍；屈髋下腰抓杠，手臂位于肩部正下方、两腿内侧，可采用正握、正反握或锁握；放松肩部，这样实际上能延长手臂。', '吸一口气，然后下沉臀部，抬头目视前方、挺胸；双脚向两侧蹬地发力，重心落在脚掌后半部，伸髋伸膝起身。', '杠铃通过膝盖时，身体后倾、髋部顶向杠铃，同时收紧肩胛骨。', '屈髋将重量放回地面，下放过程中控制好重量。'],
  'YSumo_Deadlift_with_Bands': ['用短弹力带做硬拉时，开始前直接把弹力带套在杠铃上，然后踩进弹力带完成预备姿势；确保弹力带位于脚掌后半部下方的位置，正是你蹬地发力的位置。', '先把装好重量的杠铃放在地面，站近杠铃让杠铃经过双脚中部；双脚站得非常宽，靠近卡箍；屈髋下腰抓杠，手臂位于肩部正下方、两腿内侧，可采用正握、正反握或锁握。', '吸一口气，然后下沉臀部，抬头目视前方、挺胸；双脚向两侧蹬地发力，重心落在脚掌后半部，伸髋伸膝起身。', '杠铃通过膝盖时，身体后倾、髋部顶向杠铃，同时收紧肩胛骨。', '屈髋将重量放回地面，下放过程中控制好重量。'],
  'YSumo_Deadlift_with_Chains': ['可以把链条挂在杠铃套筒上，或直接把链条中部搭在杠铃上，这样上拉时重量增加更明显；尽量让链条两端远离杠铃片，以免下放重量时碰到它们。', '先把装好重量的杠铃放在地面，站近杠铃让杠铃经过双脚中部；双脚站得非常宽，靠近卡箍；屈髋下腰抓杠，手臂位于肩部正下方、两腿内侧，可采用正握、正反握或锁握；放松肩部，这样实际上能延长手臂。', '吸一口气，然后下沉臀部，抬头目视前方、挺胸；双脚向两侧蹬地发力，重心落在脚掌后半部，伸髋伸膝起身。', '杠铃通过膝盖时，身体后倾、髋部顶向杠铃，同时收紧肩胛骨。', '屈髋将重量放回地面，下放过程中控制好重量。'],
  'YSupine_Chest_Throw': ['在没有搭档或足够结实的墙壁时，这个训练非常适合做胸前传球；仰卧在地面上，双膝弯曲。', '开始时将球放在胸前，双手从下方托住。', '爆发向上，伸展手肘将球笔直向上方尽可能高地抛出。', '球落下时用双手接住。'],
  'YSupine_OneArm_Overhead_Throw': ['仰卧在地面，双膝弯曲，单手托球，手臂完全伸到头后，此为起始姿势。', '从肩部启动发力，坐起的同时将球向正前方抛出，争取最远距离。', '球可以抛给搭档，也可以砸墙反弹。'],
  'YSupine_TwoArm_Overhead_Throw': ['仰卧在地面，双膝弯曲。', '双手抱球，手臂完全伸到头后，此为起始姿势。', '从肩部启动发力，坐起的同时将球向正前方抛出，争取最远距离。', '球可以抛给搭档，也可以砸墙反弹。'],
  'YSuspended_Fallout': ['调整悬挂带，让把手的高度合适，低于腰部。', '站立并握住把手，身体前倾靠向悬挂带，进入倾斜俯卧撑姿势，此为起始姿势。', '保持手臂伸直，进一步向悬挂带前倾，让身体更接近地面，肩部充分伸展，手臂举过头顶上方。', '保持脊柱中立、身体其余部分绷直，肩部是唯一允许活动的关节。', '在顶峰收缩处停顿片刻，然后回到起始位置。'],
  'YSvend_Press': ['以站立姿势开始。', '双手将两片轻重量杠铃片对压在一起，贴近胸前保持，让胸肌产生等长收缩，手指指向前方，此为起始姿势。', '用双掌夹紧杠铃片，以受控的动作将手臂向正前方伸直推出。', '在动作顶端停顿片刻，然后缓慢回到起始位置。'],
  'YTBar_Row_with_Handle': ['将杠铃一端插进地雷管装置或墙角固定住，防止移动，在你这一端装上合适的重量。', '跨站在杠铃上方，把双D形划船把手套在杠铃上、靠近卡箍的位置，用髋和腿发力站起来。', '采用宽站距，臀部后移、挺胸，手臂伸直，此为起始姿势。', '后收肩胛骨、屈肘将重量拉向上腹部，动作过程中不要猛拉重量或借力。', '短暂停顿后回到起始位置。'],
  'YTate_Press': ['仰卧在平凳上，双手各持一只哑铃放在大腿上方，掌心相对。', '借助大腿把哑铃顶起，逐臂翻举哑铃，使其在身前呈肩宽持握；注意：持铃于身前时，双臂间距要宽于肩宽，采用正握（掌心向前），让肘部向外张开，此为起始姿势。', '上臂保持不动，吸气时以半圆弧轨迹将哑铃向内下方移动，直到碰到上胸；全程完全控制哑铃，上臂不要移动，也不要把哑铃停在胸口休息。', '呼气时用肱三头肌以相反的半圆弧轨迹将哑铃推起，上推时尽量让两只哑铃保持靠近；在收缩位置锁定手臂保持一秒钟，然后再次缓慢下放。提示：下放时间至少应是上推时间的两倍。', '按训练计划规定的次数重复动作。'],
  'YThe_Straddle': ['以坐姿挺直身体开始，将双腿在身前伸开成V形。', '双手撑地，尽可能向前俯身，保持10到20秒。'],
  'YThigh_Abductor': ['开始时坐在外展器械上，选择自己适应的重量，双腿位置调整好后握住两侧把手，整个上半身（腰部以上）保持固定，此为起始姿势。', '呼气时用双腿缓慢向外推压器械，让双腿相互远离。', '感受收缩一秒钟，然后吸气将双腿移回起始位置。注意：保持上半身固定，以防受伤。', '按建议次数重复。'],
  'YThigh_Adductor': ['开始时坐在内收器械上，选择自己适应的重量，双腿在器械腿垫上放好后握住两侧把手，整个上半身（腰部以上）保持固定，此为起始姿势。', '呼气时用双腿缓慢向内推压器械，让双腿相互靠拢。', '感受收缩一秒钟，然后吸气将双腿移回起始位置。注意：保持上半身固定，避免快速猛拉的动作，以防受伤。', '按建议次数重复。'],
  'YToe_Touchers': ['开始时仰卧在地板或训练垫上，背部贴地，双臂放在身体两侧，掌心向下。', '双腿并拢，缓慢将双腿抬起，直到几乎与地面垂直，膝盖略微弯曲，双脚与地面平行。', '移动双臂，使其与地面呈45度角完全伸直，此为起始姿势。', '下背部保持贴地，缓慢抬起躯干，用手尝试触碰脚尖，做这部分动作时记得呼气。', '吸气时缓慢将躯干和手臂放回起始位置，记得保持手臂伸直、指向脚尖方向。', '按建议次数重复。'],
  'YTorso_Rotation': ['站立挺直，双手抱住瑜伽球，伸直手臂让球位于正前方，此为起始姿势。', '将躯干转向一侧，转动时眼睛始终看着球，然后再向相反方向转回，重复10到20次。'],
  'YTrail_Running_Walking': ['越野跑或徒步几乎立刻就能让血液流动加快、心跳加速，务必穿好鞋；上坡时用小腿和臀部肌肉把身体拉上去，下坡时膝盖、关节和脚踝承受大部分冲击；下坡行走时迈小步、保持膝盖弯曲以减小冲击，并放慢速度防止摔倒。', '一个150磅（约68公斤）的人上坡步行30分钟可消耗超过200卡路里，而平地消耗175卡路里；如果越野跑，150磅的人30分钟可消耗远超500卡路里。'],
  'YTricep_Dumbbell_Kickback': ['双手各持一只哑铃，掌心朝向躯干；背部挺直、膝盖微屈，从腰部前倾，躯干几乎与地面平行，保持抬头；上臂贴近躯干并与地面平行，前臂持铃指向地面，前臂与上臂之间呈90度角，此为起始姿势。', '上臂保持不动，呼气并用肱三头肌发力将重量向后抬起，直到手臂完全伸直，专注于移动前臂。', '在顶部收缩处短暂停顿后，吸气缓慢将哑铃放回起始位置。', '按规定的次数重复动作。'],
  'YTricep_Side_Stretch': ['将右臂横过身体、越过左肩，用左手拉住右肘，直到肱三头肌感到拉伸，然后换另一侧手臂重复。'],
  'YTriceps_Overhead_Extension_with_Rope': ['将绳索挂到低位滑轮上，选好合适重量后双手抓住绳索，背对滑轮架。', '双手置于头后，肘部笔直朝上；肘部从屈曲状态开始，可以采用前后分腿站姿并轻轻向远离器械的方向倾斜，以增强稳定性，此为起始姿势。', '做动作时上臂保持位置，伸展手肘，将双手举过头顶。', '在动作顶部收紧肱三头肌，然后缓慢将重量放回起始位置。'],
  'YTriceps_Pushdown': ['将直杆或弯杆挂到高位滑轮上，用与肩同宽的正握（掌心向下）抓握。', '身体直立，躯干挺直并微微前倾，上臂贴近身体并与地面垂直，前臂握杆指向上方的滑轮，此为起始姿势。', '用肱三头肌发力将横杆下压，直到碰到大腿前侧、手臂完全伸直并与地面垂直；上臂始终贴住躯干保持不动，只有前臂移动，做这个动作时呼气。', '在收缩位置保持一秒钟后，缓慢将横杆提回起始位置，做这一步时吸气。', '按建议次数重复。'],
  'YTriceps_Pushdown__Rope_Attachment': ['将绳索附件挂到高位滑轮上，用中立握姿（掌心相对）抓握。', '身体直立，躯干挺直并微微前倾，上臂贴近身体并与地面垂直，前臂握绳、掌心相对，指向上方的滑轮，此为起始姿势。', '用肱三头肌发力将绳索下压，同时把绳索两端分别压向大腿外侧；动作结束时手臂完全伸直并与地面垂直；上臂始终贴住躯干保持不动，只有前臂移动，做这个动作时呼气。', '在收缩位置保持一秒钟后，缓慢将绳索提回起始位置，做这一步时吸气。', '按建议次数重复。'],
  'YTriceps_Pushdown__VBar_Attachment': ['将V形杆挂到高位滑轮上，用与肩同宽的正握（掌心向下）抓握。', '身体直立，躯干挺直并微微前倾，上臂贴近身体并与地面垂直，前臂握杆指向上方的滑轮，拇指位置高于小指，此为起始姿势。', '用肱三头肌发力将横杆下压，直到碰到大腿前侧、手臂完全伸直并与地面垂直；上臂始终贴住躯干保持不动，只有前臂移动，做这个动作时呼气。', '在收缩位置保持一秒钟后，缓慢将V形杆提回起始位置，做这一步时吸气。', '按建议次数重复。'],
  'YTwoArm_Dumbbell_Preacher_Curl': ['双手各持一只哑铃，将上臂放在托臂凳或上斜凳上，哑铃在肩宽位置持握，此为起始姿势。', '吸气时缓慢下放哑铃，直到上臂伸直、肱二头肌完全拉伸。', '呼气时用肱二头肌将重量弯举上来，直到肱二头肌完全收缩、哑铃到达肩部高度。', '在收缩位置用力挤压肱二头肌一秒钟，按建议次数重复。'],
  'YTwoArm_Kettlebell_Clean': ['将两只壶铃放在双脚之间，臀部后推、目视前方，摆出起始姿势。', '伸展腿部和髋部，将壶铃提拉至肩部完成翻举，同时转动手腕。', '将壶铃放回起始位置并重复。'],
  'YTwoArm_Kettlebell_Jerk': ['先将两只壶铃翻举至肩部：伸展腿部和髋部将壶铃摆向肩部，同时转动手腕让掌心朝前；下蹲几英寸后迅速反向发力，将两只壶铃推过头顶；初次发力后立即再次下蹲，让身体钻到壶铃下方；壶铃锁定后站直身体，完成动作。'],
  'YTwoArm_Kettlebell_Military_Press': ['先将两只壶铃翻举至肩部：伸展腿部和髋部将壶铃摆向肩部，同时转动手腕让掌心朝前。', '将壶铃向上向外推举；壶铃经过头部时身体前倾靠近重量，让壶铃架在头后；务必收紧背阔肌、臀部和腹部以增加稳定性。'],
  'YTwoArm_Kettlebell_Row': ['将两只壶铃放在脚前，膝盖微屈，俯身时臀部尽可能向后撅，摆出起始姿势。', '抓住两只壶铃，后收肩胛骨、屈肘将壶铃拉向腹部，保持背部挺直，下放后重复。'],
  'YUnderhand_Cable_Pulldowns': ['坐在高位下拉器械上，顶部滑轮挂着宽杆，根据身高调整器械膝垫，这些垫子可以防止身体被横杆的阻力拉起。', '用掌心朝向躯体的反握（旋后握姿）抓住下拉横杆，双手间距要窄于肩宽。', '双臂在身前伸直、按所选握距握住横杆，躯干后倾约30度，同时下背部微弓、挺胸，此为起始姿势。', '呼气时肩部下沉后收、带动上臂将横杆下拉，直到碰到上胸。提示：到达完全收缩位置后集中精力挤压背部肌群，肘部贴近身体；将横杆拉向身体时上躯干保持不动，只有手臂移动，前臂除了握住横杆外不做其他工作。', '在收缩位置保持一秒钟后，吸气缓慢将横杆放回起始位置，此时手臂完全伸直、背阔肌充分拉伸。', '按规定的次数重复动作。'],
  'YUpper_BackLeg_Grab': ['坐姿时身体前倾，双臂从大腿下方环抱双腿。', '膝盖并拢、双腿伸直，让胸部向膝盖靠近；也可以在抱腿的同时让背部远离膝盖，从而拉伸中背部。'],
  'YUpright_Barbell_Row': ['用略窄于肩宽的正握抓住杠铃，杠铃停在大腿上方，手臂伸直、手肘微屈，背部挺直，此为起始姿势。', '呼气时用肩部侧束发力提起杠铃，将肘部向上并向两侧抬起；上提时让杠铃贴近身体，一直提到接近下巴的位置。提示：肘部应该主导动作，且始终高于前臂；记得保持躯干固定，在动作顶端停顿一秒钟。', '缓慢将杠铃放回起始位置，做这一部分动作时吸气。', '按建议次数重复。'],
  'YUpright_Cable_Row': ['用略窄于肩宽的正握（掌心朝向大腿）抓住连接低位滑轮的直杆附件，横杆停在大腿上方，手臂伸直、手肘微屈，背部挺直，此为起始姿势。', '呼气时用肩部侧束发力提起绳索横杆；上移时让横杆贴近身体，一直提到接近下巴的位置。提示：肘部应该主导动作，上提时肘部始终高于前臂；同时保持躯干固定，在动作顶端停顿一秒钟。', '缓慢将横杆放回起始位置，做这一部分动作时吸气。', '按建议次数重复。'],
  'YUpright_Row__With_Bands': ['开始时踩住弹力带，使手臂下垂时刚好产生张力；用略窄于肩宽的正握（掌心朝向大腿）抓住把手，把手停在大腿上方，手臂伸直、手肘微屈，背部挺直，此为起始姿势。', '呼气时用肩部侧束发力提起把手；上移时让把手贴近身体，一直提到接近下巴的位置。提示：肘部应该主导动作，上提时肘部始终高于前臂；同时保持躯干固定，在动作顶端停顿一秒钟。', '缓慢将把手放回起始位置，做这一部分动作时吸气。', '按建议次数重复。'],
  'YUpward_Stretch': ['双手在头顶正上方伸直，掌心相触。', '保持背部挺直，缓慢将双手向上、向后推。'],
  'YVBar_Pulldown': ['坐在高位下拉器械上，顶部滑轮挂着V形杆。', '根据身高调整器械膝垫，这些垫子可以防止身体被横杆的阻力拉起。', '用掌心相对的握姿（中立握）抓住V形杆，挺胸并微微后仰（约30度）以更好地激活背阔肌，此为起始姿势。', '用背阔肌发力下拉横杆，同时收紧肩胛骨，一直拉到胸部几乎碰到V形杆，呼气完成动作。提示：整个动作过程中保持躯干固定。', '在收缩位置保持一秒钟后，吸气缓慢将横杆放回起始位置。', '按规定的次数重复。'],
  'YVBar_Pullup': ['先把V形杆的中部搭在引体向上杆中间（假设你用的引体向上架没有中立握把手），V形杆的把手朝下，这样就能借助把手悬垂在引体向上杆上。', 'V形杆放稳后，从两侧握住把手悬垂起来，挺胸并微微后仰以更好地激活背阔肌，此为起始姿势。', '用背阔肌发力拉起躯干，同时头部微微后仰，以免撞到横杆；一直拉到胸部几乎碰到V形杆，呼气完成动作。', '在收缩位置保持一秒钟后，吸气缓慢将身体放回起始位置。', '按规定的次数重复。'],
  'YVertical_Swing': ['双手握住哑铃，让它垂在两腿之间、手臂伸直，保持背部挺直、抬头。', '屈髋并微屈膝盖，将哑铃向两腿之间摆动。', '通过伸展髋、膝、踝强力反转动作，推动身体向上，将哑铃摆过头顶。', '落地时用双腿缓冲冲击，下一次重复前将哑铃拉回躯干前。'],
  'YWalking_Treadmill': ['开始时踏上跑步机，从菜单中选择所需模式；大多数跑步机有手动设置，也可以选择训练程序；通常可输入年龄和体重来估算运动消耗的热量，还可以调整坡度来改变训练强度。', '跑步机方便、有益心肺，冲击通常比户外行走小；行走时应保持中速到快速，而不是悠闲散步；作为低强度运动，行走消耗的热量不如某些其他运动，但仍有很大益处；一个150磅（约68公斤）的人以每小时4英里行走30分钟约消耗175卡路里，而以两倍速度跑步则消耗450卡路里；行走时保持正确姿态，只在必要时（如下机或测量心率时）扶住扶手。'],
  'YWeighted_Ball_Hyperextension': ['开始时俯卧在瑜伽球上，躯干贴着球面并与地面平行，前脚掌踩地帮助保持平衡，将一片负重杠铃片放在下巴下方或颈后，此为起始姿势。', '通过屈曲腰部和下背部缓慢抬起躯干，做这个动作时记得呼气。', '让下背部保持收缩一秒钟，然后吸气将躯干放回起始位置。', '按计划中建议的次数重复。'],
  'YWeighted_Ball_Side_Bend': ['开始时侧卧在瑜伽球上，躯干左侧（腰部、髋部和肩部）贴着球面。', '双脚踩地，双腿交叉垂挂在球侧；右手持一片负重杠铃片放在头部正右侧。提示：确保杠铃片的光滑面贴着头部。', '左臂横放在躯干上，手掌贴住腹斜肌，左前臂与上臂之间呈直角，此为起始姿势。', '呼气时向侧方屈曲腰部，将躯干一侧抬起。', '保持收缩一秒钟，然后吸气缓慢将身体放回起始位置。', '按建议次数重复。', '换另一侧重复该动作。'],
  'YWeighted_Crunches': ['仰卧平躺，双脚平放在地面或搭在凳上，膝盖弯曲呈90度角。', '将负重抱在胸前，或伸直手臂举在躯干上方，此为起始姿势。', '呼气并缓慢将肩部卷离地面，肩部离地约4英寸（约10厘米），下背部保持贴地。', '在动作顶端收紧腹部并短暂停顿。', '然后吸气缓慢将身体放回起始位置。'],
  'YWeighted_Jump_Squat': ['将一根轻负荷杠铃横放在肩部后方，也可以用负重背心、沙袋或其他类型的阻力来做这个动作。', '重量要足够轻，不能明显拖慢你的速度；双脚略宽于肩，抬头挺胸，此为起始姿势。', '利用预蹲的反向动作半蹲，然后立即反向爆发离地，充分伸展髋、膝、踝；跳跃全程保持良好姿态。', '回到地面时用双腿缓冲冲击。'],
  'YWeighted_Pull_Ups': ['将负重挂到双杠腰带上并系好，掌心向前抓住引体向上杆；中握距时双手与肩同宽，双臂在身前伸直，按所选握距握住横杆。', '躯干后倾约30度，下背部微弓并挺胸，此为起始姿势。', '呼气并拉起躯干，直到头部高过双手；到达顶部收缩位置时，集中精力将肩胛骨向后向下收紧。', '在顶部收缩位置短暂停留后，吸气缓慢将躯干放回起始位置，手臂伸直、背阔肌充分拉伸。'],
  'YWeighted_SitUps__With_Bands': ['先把弹力带绑在下斜凳底座上，把手朝向下斜凳内侧，这样躺下时两只手都能够到。', '将双腿伸进下斜凳固定好；然后双手去抓弹力带，用正握（掌心向前）抓住把手，放在锁骨附近并转动手腕变为中立握姿（掌心朝向躯干）。注意：整个动作过程中手臂保持不动，此为起始姿势。', '呼气时将躯干向上卷起，直到上半身与地面垂直；保持收缩一秒钟，然后吸气将上半身放回起始位置。', '按建议次数重复。'],
  'YWideGrip_Barbell_Bench_Press': ['仰卧在平凳上，双脚踩实地面；采用宽握正握（掌心向前），每只手比肩宽再向外约3英寸（约7.6厘米），将杠铃从架上取下，锁定手臂举在身体正上方；杠铃与躯干和地面垂直，此为起始姿势。', '吸气时缓慢下放，直到感觉到杠铃触到胸部中间。', '停顿一秒钟后，呼气用胸部肌肉将杠铃推回起始位置；在收缩位置锁定手臂并挤压胸肌，保持一秒钟后再开始缓慢下放。提示：下放时间至少应是上推时间的两倍。', '按规定的次数重复动作。'],
  'YWideGrip_Decline_Barbell_Bench_Press': ['仰卧在下斜凳上，双脚在凳前端固定牢；采用宽握正握（掌心向前），每只手比肩宽再向外约3英寸（约7.6厘米），将杠铃从架上取下，锁定手臂举在身体正上方；杠铃与躯干和地面垂直，此为起始姿势。', '吸气时缓慢下放，直到感觉到杠铃触到胸部下部。', '停顿一秒钟后，呼气用胸部肌肉将杠铃推回起始位置；在收缩位置锁定手臂并挤压胸肌，保持一秒钟后再开始缓慢下放。提示：下放时间至少应是上推时间的两倍。', '按规定的次数重复动作。'],
  'YWideGrip_Decline_Barbell_Pullover': ['仰卧在下斜凳上，双腿固定牢；用正握（掌心向外）去够头后的杠铃，这个动作要采用宽于肩宽的握距；用双臂缓慢将杠铃从地面提起。', '位置调整到位后，手臂应完全伸直并与地面垂直，此为起始姿势。', '开始以半圆弧轨迹将杠铃向后下方移动，就像要把它放到地上，但要在手臂与地面平行时停下。提示：全程保持手臂完全伸直，动作只发生在肩关节，做这一部分动作时吸气。', '呼气时将杠铃拉起，回到起始位置，全程记住保持对杠铃的完全控制。', '按训练计划规定的次数重复动作。', '完成一组后，缓慢将杠铃下放到与头部齐平，然后松手。'],
  'YWideGrip_Pulldown_Behind_The_Neck': ['坐在高位下拉器械上，顶部滑轮挂着宽杆；确保根据身高调整器械膝垫，这些垫子可以防止身体被横杆的阻力拉起。', '掌心向前，按规定的握距抓住横杆。握距说明：宽握时双手间距大于肩宽，中握时与肩同宽，窄握时小于肩宽。', '双臂在身前伸直、按所选握距握住横杆，躯干和头部向前；想象从横杆中心到颈后有一条假想线，此为起始姿势。', '呼气时肩部下沉后收、带动上臂将横杆下拉，直到碰到颈后。提示：到达完全收缩位置后集中精力挤压背部肌群；上躯干保持不动，只有手臂移动；前臂除了握住横杆外不做其他工作，因此不要试图用前臂把杆拉下来。', '在收缩位置收紧肩胛骨保持一秒钟，然后缓慢将横杆放回起始位置，此时手臂完全伸直、背阔肌充分拉伸，这一部分动作时吸气。', '按规定的次数重复动作。'],
  'YWideGrip_Standing_Barbell_Curl': ['躯干挺直站立，握住杠铃宽握的外侧位置，掌心朝前，肘部贴近躯干，此为起始姿势。', '上臂保持不动，呼气时收缩肱二头肌将重量向前弯举。提示：只有前臂应该移动。', '继续动作直到肱二头肌完全收缩、横杆到达肩部高度；在收缩位置保持一秒钟，用力挤压肱二头肌。', '吸气时缓慢将横杆放回起始位置。', '按建议次数重复。'],
  'YWide_Stance_Barbell_Squat': ['出于安全考虑，这个动作最好在深蹲架内进行；先把杠铃放到与身高匹配的架位上，选好高度并装好重量后，走到杠铃下方，将肩部后方（略低于颈部）横跨在杠铃上。', '双臂在两侧扶住杠铃，先蹬腿发力同时挺直躯干，将杠铃从架上抬起。', '离开深蹲架，双脚采用宽于肩宽的站距，脚尖微微外展；始终保持抬头，低头会失去平衡，同时保持背部挺直，此为起始姿势。', '保持抬头、身体挺直的姿态，屈膝缓慢下放杠铃；一直下蹲到大腿与小腿之间的夹角略小于90度（即大腿低于与地面平行的位置），做这一部分动作时吸气。提示：如果动作正确，膝盖前侧应与脚尖形成一条垂直向前的假想直线，如果膝盖越过这条假想线（超过脚尖），说明膝盖承受了过大压力，动作有误。', '呼气时用脚跟蹬地，重新伸直双腿，将杠铃抬起并回到起始位置。', '按建议次数重复。'],
  'YWide_Stance_Stiff_Legs': ['先把装好重量的杠铃放在地面，采用宽站距，屈髋下腰抓杠；臀部尽可能向后坐，双腿几乎伸直；保持背部挺直、抬头挺胸，此为起始姿势。', '启动动作时髋部发力前顶，手臂自然下垂伸直；直到身体完全站直，然后缓慢将重量放回起始位置；后续重复时，重量不必触地。'],
  'YWindmills': ['仰卧，双臂向两侧伸展、双腿伸直，此为起始姿势。', '抬起一条腿，快速横越过身体，尝试让脚触到另一侧手附近的地面。', '回到起始位置，换另一条腿重复，交替进行10到20次。'],
  'YWorlds_Greatest_Stretch': ['这是分三部分的拉伸：先向前弓步，前脚平踩地面、后脚脚尖着地；双膝弯曲下蹲，直到后膝几乎触地；保持躯干直立，保持此姿势10到20秒。', '然后，将与前腿同侧的手臂撑到地面，肘部靠近脚边；另一只手撑地，与领先腿平行，在拉伸的这一阶段帮助支撑身体。', '10到20秒后，双手放在前脚两侧；前脚脚尖抬离地面，伸直腿部，必要时可重新调整后腿位置；保持10到20秒，然后换另一侧重复整套动作。'],
  'YWrist_Roller': ['开始时站直，用正握（掌心向下）抓住腕部滚轮，双脚与肩同宽。', '缓慢抬起双臂，直到完全伸直、与地面平行地举在身前。注意：确保绳子没有缠在滚轮上；除前臂外全身保持固定，此为起始姿势。', '一次转动一只手腕做向上卷动，让绳子绕上滚轮，把重量提到横杆处。', '重量到达横杆后，反向转动手腕向下放绳，缓慢将重量放回起始位置。', '按计划中规定的次数重复。'],
  'YWrist_Rotations_with_Straight_Bar': ['双手握住杠铃，掌心向下，双手间距约与肩同宽，此为起始姿势。', '双手交替进行，像卷报纸一样伸展手腕完成动作，持续左右交替直到力竭。', '反向屈曲手腕、向相反方向卷动，继续交替动作直到力竭。'],
  'YYoke_Walk': ['轭式行走通常用专门的轭式器械进行，但有时也会用冰箱或其他重物替代。', '先把器械架在肩部后方，目视前方、背部微微拱起，用脚跟蹬地发力将轭架抬起。', '用小步快走尽可能快地前进；可以扶住轭架两侧立柱帮助稳定位置；以最快速度走完规定距离，通常是75到100英尺（约23到30米）。'],
  'YZercher_Squats': ['出于安全考虑，这个动作最好在深蹲架内进行；先把杠铃放到与身高匹配的架位，合适的高度应在腰部以上、胸部以下；选好高度并装好重量后，双手交扣，将杠铃架在前臂与上臂之间的手臂上。', '将杠铃抬起，让它停在前臂上方；如果持杠正确，看起来就像双臂交叉而杠铃横在手臂上。', '离开深蹲架，双脚采用与肩同宽的中等站距，脚尖微微外展；始终保持抬头，低头会失去平衡，同时保持背部挺直，此为起始姿势（注：这里我们使用上文描述的中等站距，它针对整体发展；你也可以从脚站位部分讨论的三种站距中任选一种）。', '保持抬头、身体挺直的姿态，屈膝下放杠铃；一直下蹲到大腿与小腿之间的夹角略小于90度（即大腿低于与地面平行的位置），做这一部分动作时吸气。提示：如果动作正确，膝盖前侧应与脚尖形成一条垂直向前的假想直线，如果膝盖越过这条假想线（超过脚尖），说明膝盖承受了过大压力，动作有误。', '呼气时主要用前脚掌蹬地，重新伸直双腿，将杠铃抬起并回到起始位置。', '按建议次数重复。'],
  'YZottman_Preacher_Curl': ['双手各持一只哑铃，将上臂放在托臂凳或上斜凳上；哑铃举在肩部高度，肘部弯曲，掌心向下握住哑铃，此为起始姿势。', '吸气时保持掌心向下，缓慢下放哑铃，直到上臂伸直、肱二头肌完全拉伸。', '到达动作底部后转动手腕，让掌心朝上。', '呼气时用肱二头肌将重量弯举上来，直到完全收缩、哑铃到达肩部高度；再次提醒，要确保完全收缩，需要让小指高于拇指。', '在收缩位置用力挤压肱二头肌一秒钟，然后转动手腕让掌心重新朝下。', '按建议次数重复。'],
};
